-- BEGIN AETHER MODULE: blatant/LongJump.lua --
run(function()
    local Value
    local CameraDir
    local LimitItems
    local ChangeDir
    local LongJumpBypass
    local BypassBoost
    local start
    local JumpTick, JumpSpeed, Direction = tick(), 0
    local jumpWasActive = false
	local function horizontalDirection(direction)
		local flat = direction and Vector3.new(direction.X, 0, direction.Z) or Vector3.zero
		if flat.Magnitude > 0.001 then return flat.Unit end
		local look = entitylib.isAlive and entitylib.character.RootPart.CFrame.LookVector or Vector3.zAxis
		flat = Vector3.new(look.X, 0, look.Z)
		return flat.Magnitude > 0.001 and flat.Unit or Vector3.zAxis
	end
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function launchProjectile(item, pos, proj, speed, dir)
        if not pos then return end

        pos = pos - dir * 0.1
        local shootPosition = (CFrame.lookAlong(pos, Vector3.new(0, -speed, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
        switchItem(item.tool, 0)
        task.wait(0.1)
        bedwars.ProjectileController:createLocalProjectile(bedwars.ProjectileMeta[proj], proj, proj, shootPosition.Position, '', shootPosition.LookVector * speed, {drawDurationSeconds = 1})
        if projectileRemote:InvokeServer(item.tool, proj, proj, shootPosition.Position, pos, shootPosition.LookVector * speed, httpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
			local itemMeta = bedwars.ItemMeta[item.itemType]
			local source = itemMeta and itemMeta.projectileSource
			local shoot = source and type(source.launchSound) == 'table' and #source.launchSound > 0 and source.launchSound or nil
			shoot = shoot and shoot[math.random(1, #shoot)] or nil
            if shoot then
                bedwars.SoundManager:playSound(shoot)
            end
        end
    end

    local LongJumpMethods = {
        cannon = function(_, pos, dir)
            pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
            local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
            bedwars.placeBlock(rounded, 'cannon', false)

            task.delay(0, function()
                local block, blockpos = getPlacedBlock(rounded)
                if block and block.Name == 'cannon' and (entitylib.character.RootPart.Position - block.Position).Magnitude < 20 then
                    local breaktype = bedwars.ItemMeta[block.Name].block.breakType
                    local tool = getBreakTool(breaktype)
                    if tool then
                        switchItem(tool.tool)
                    end

                    bedwars.Client:Get(remotes.CannonAim):SendToServer({
                        cannonBlockPos = blockpos,
                        lookVector = dir
                    })

                    local broken = 0.1
                    if bedwars.BlockController:calculateBlockDamage(lplr, {blockPosition = blockpos}) < block:GetAttribute('Health') then
                        broken = 0.4
                        bedwars.breakBlock(block, true, true)
                    end

                    task.delay(broken, function()
                        for _ = 1, 3 do
                            local call = bedwars.Client:Get(remotes.CannonLaunch):CallServer({cannonBlockPos = blockpos})
                            if call then
                                bedwars.breakBlock(block, true, true)
                                JumpSpeed = 5.25 * Value.Value
                                JumpTick = tick() + 2.3
								Direction = horizontalDirection(dir)
                                break
                            end
                            task.wait(0.1)
                        end
                    end)
                end
            end)
        end,
        cat = function(_, _, dir)
            LongJump:Clean(vapeEvents.CatPounce.Event:Connect(function()
                JumpSpeed = 4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
                entitylib.character.RootPart.Velocity = Vector3.zero
            end))

            -- The pounce has to be timed off the frame the game actually leaps, and the only
            -- way to know that is the controller itself. This used to be fired by AutoKit's cat
            -- routine, so cat LongJumps silently did nothing unless that module happened to be
            -- on with the cat toggle ticked; the hook lives here now and is put back on cleanup.
            if bedwars.CatController and typeof(bedwars.CatController.leap) == 'function' then
                local controller = bedwars.CatController
                local original = controller.leap
                local hook
                hook = function(...)
                    vapeEvents.CatPounce:Fire()
                    return original(...)
                end
                controller.leap = hook
                LongJump:Clean(function()
                    if controller.leap == hook then
                        controller.leap = original
                    end
                end)
            end

            if not bedwars.AbilityController:canUseAbility('CAT_POUNCE') then
                repeat task.wait() until bedwars.AbilityController:canUseAbility('CAT_POUNCE') or not LongJump.Enabled
            end

            if bedwars.AbilityController:canUseAbility('CAT_POUNCE') and LongJump.Enabled then
                bedwars.AbilityController:useAbility('CAT_POUNCE')
            end
        end,
        fireball = function(item, pos, dir)
            launchProjectile(item, pos, 'fireball', 60, dir)
        end,
        grappling_hook = function(item, pos, dir)
            launchProjectile(item, pos, 'grappling_hook_projectile', 140, dir)
        end,
        jadeHammer = function(item, _, dir)
            local jade = AetherMatchRuntime and AetherMatchRuntime.Jade
            if jade then
                local result = jade:ActivateForTraversal('LongJump', dir, function()
                    return not LongJump.Enabled
                end)
                if not result.confirmed or not LongJump.Enabled then return end
                JumpSpeed = 1.4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
                return
            end

            local ability = getJadeAbility(item)
            if not bedwars.AbilityController:canUseAbility(ability) then
                repeat
                    task.wait()
                    ability = getJadeAbility(item)
                until bedwars.AbilityController:canUseAbility(ability) or not LongJump.Enabled
            end
            if bedwars.AbilityController:canUseAbility(ability) and LongJump.Enabled then
                if not activateJadeTool(item) then bedwars.AbilityController:useAbility(ability) end
                local deadline = tick() + 0.75
                repeat
                    task.wait()
                until not bedwars.AbilityController:canUseAbility(ability) or tick() >= deadline or not LongJump.Enabled
                if not LongJump.Enabled or bedwars.AbilityController:canUseAbility(ability) then return end
                JumpSpeed = 1.4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
            end
        end,
        tnt = function(item, pos, dir)
            pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
            local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
            start = Vector3.new(rounded.X, start.Y, rounded.Z) + (dir * (item.itemType == 'pirate_gunpowder_barrel' and 2.6 or 0.2))
            bedwars.placeBlock(rounded, item.itemType, false)
        end,
        wood_dao = function(item, pos, dir)
            if (lplr.Character:GetAttribute('CanDashNext') or 0) > workspace:GetServerTimeNow() or not bedwars.AbilityController:canUseAbility('dash') then
                repeat task.wait() until (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') or not LongJump.Enabled
            end

            if LongJump.Enabled then
                bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                switchItem(item.tool, 0.1)
                replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
                    direction = dir,
                    origin = pos,
                    weapon = item.itemType
                })
                JumpSpeed = 4.5 * Value.Value
                JumpTick = tick() + 2.4
				Direction = horizontalDirection(dir)
            end
        end
    }
    for _, v in {'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'} do
        LongJumpMethods[v] = LongJumpMethods.wood_dao
    end
    for _, hammer in jadeHammerNames do
        LongJumpMethods[hammer] = LongJumpMethods.jadeHammer
    end
    LongJumpMethods.void_axe = LongJumpMethods.jadeHammer
    LongJumpMethods.siege_tnt = LongJumpMethods.tnt
    LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt

	local function heldLongJumpMethod()
		local hand = store.hand
		local tool = hand and hand.tool
		if not tool then return nil end
		local raw = hand.itemType or tool.Name
		local normalized = tostring(raw):lower():gsub('[%s%-]+', '_')
		local method = LongJumpMethods[raw] or LongJumpMethods[normalized]
		local jadeName = isJadeHammerName(normalized)
		if jadeName then method = LongJumpMethods.jadeHammer end
		if not method then return nil end
		local item = getItem(raw) or getItem(normalized)
		if jadeName and AetherMatchRuntime and AetherMatchRuntime.Jade then
			item = AetherMatchRuntime.Jade:GetBestHammer() or item
		end
		item = item or {itemType = normalized, tool = tool, amount = hand.amount or 1}
		return method, item, normalized
	end

    LongJump = vape.Categories.Blatant:CreateModule({
        Name = 'LongJump',
        Function = function(callback)
            frictionTable.LongJump = callback or nil
            updateVelocity()
            if callback then
                -- Limit to items: only engage from a long-jump item you're HOLDING. Without one
                -- the driver below would hold you frozen in place waiting for a jump that can never
                -- come (the module's idle state pins your velocity), so turn straight back off.
				if LimitItems and LimitItems.Enabled and not heldLongJumpMethod() then
                    frictionTable.LongJump = nil
                    updateVelocity()
                    notif('LongJump', 'Hold a long-jump item to use it (Limit to items is on).', 4)
                    return task.spawn(function() if LongJump.Enabled then LongJump:Toggle() end end)
                end
                LongJump:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
                    -- Limit to items: the knockback (Heatseeker) boost isn't item-driven, so skip it.
                    if LimitItems and LimitItems.Enabled then return end
                    if damageTable.entityInstance == lplr.Character and damageTable.fromEntity == lplr.Character and (not damageTable.knockbackMultiplier or not damageTable.knockbackMultiplier.disabled) then
                        local knockbackBoost = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
                            vertical = 0,
                            horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 1)
                        }).Magnitude * 1.1

                        if knockbackBoost >= JumpSpeed then
                            local pos = damageTable.fromPosition and Vector3.new(damageTable.fromPosition.X, damageTable.fromPosition.Y, damageTable.fromPosition.Z) or damageTable.fromEntity and damageTable.fromEntity.PrimaryPart.Position
                            if not pos then return end
                            local vec = (entitylib.character.RootPart.Position - pos)
                            JumpSpeed = knockbackBoost
                            JumpTick = tick() + 2.5
                            Direction = Vector3.new(vec.X, 0, vec.Z).Unit
                        end
                    end
                end))
                LongJump:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(dataTable)
                    if dataTable.hookFunction == 'PLAYER_IN_TRANSIT' then
                        local vec = entitylib.character.RootPart.CFrame.LookVector
                        JumpSpeed = 2.5 * Value.Value
                        JumpTick = tick() + 2.5
                        Direction = Vector3.new(vec.X, 0, vec.Z).Unit
                    end
                end))

                start = entitylib.isAlive and entitylib.character.RootPart.Position or nil
                LongJump:Clean(runService.PreSimulation:Connect(function(dt)
                    local root = entitylib.isAlive and entitylib.character.RootPart or nil

                    if root and isnetworkowner(root) then
                        if JumpTick > tick() then
                            if not jumpWasActive then
                                jumpWasActive = true
                                longJumpActivation:Fire(root.AssemblyLinearVelocity)
                            end
                            -- Change direction mid-air: while the boost is running, steer it with
                            -- your movement keys (or where the camera looks) instead of riding the
                            -- fixed line it launched on. MoveDirection is already camera-relative, so
                            -- W/A/S/D bends the boost; with no keys down it holds its current heading.
                            if ChangeDir and ChangeDir.Enabled and Direction then
                                local steer = entitylib.character.Humanoid.MoveDirection
                                steer = Vector3.new(steer.X, 0, steer.Z)
                                if steer.Magnitude < 0.1 and CameraDir and CameraDir.Enabled then
                                    local look = gameCamera.CFrame.LookVector
                                    steer = Vector3.new(look.X, 0, look.Z)
                                end
                                if steer.Magnitude > 0.1 then
                                    Direction = steer.Unit
                                end
                            end
                            root.AssemblyLinearVelocity = Direction * (getSpeed() + ((JumpTick - tick()) > 1.1 and JumpSpeed or 0)) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                            if entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air and not start then
                                root.AssemblyLinearVelocity += Vector3.new(0, dt * (workspace.Gravity - 23), 0)
                            else
                                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 15, root.AssemblyLinearVelocity.Z)
                            end
                            start = nil
                        else
                            jumpWasActive = false
                            if start then
                                root.CFrame = CFrame.lookAlong(start, root.CFrame.LookVector)
                            end
                            root.AssemblyLinearVelocity = Vector3.zero
                            JumpSpeed = 0
                        end
                    else
                        start = nil
                    end
                end))

				local heldMethod, heldItem = heldLongJumpMethod()
				if heldMethod then
					task.spawn(heldMethod, heldItem, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
                    return
                end

                -- Limit to items: a held item was already required above, so never fall through to
                -- the inventory/kit scan (which is what would otherwise fire a kit-based jump).
                if LimitItems and LimitItems.Enabled then return end

                for i, v in LongJumpMethods do
                    local item = getItem(i)
                    if item or store.equippedKit == i then
                        task.spawn(v, item, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
                        break
                    end
                end
            else
                JumpTick = tick()
                jumpWasActive = false
                Direction = nil
                JumpSpeed = 0
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Lets you jump farther'
    })
    Value = LongJump:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 37,
        Default = 37,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    CameraDir = LongJump:CreateToggle({
        Name = 'Camera Direction'
    })
    LimitItems = LongJump:CreateToggle({
        Name = 'Limit to items',
        Tooltip = 'Only long-jumps from a held item. Without one LongJump turns itself back off instead of freezing you'
    })
    ChangeDir = LongJump:CreateToggle({
        Name = 'Change direction mid-air',
        Tooltip = 'Steer the boost with your movement keys instead of flying in a straight line'
    })

    local api = {
        Module = LongJump,
        Methods = LongJumpMethods,
        GetHeldMethod = heldLongJumpMethod,
        GetJumpTick = function() return JumpTick end
    }
    shared.AetherLongJumpRuntime = api
    vape:Clean(function() if shared.AetherLongJumpRuntime == api then shared.AetherLongJumpRuntime = nil end end)
end)
-- END AETHER MODULE: blatant/LongJump.lua --

-- BEGIN AETHER MODULE: blatant/NoFallDamage.lua --
run(function()
    local NoFall
    local Mode
    local MinVelocity
    local BlockClutch
    local TelepearlClutch
    local DaoClutch
    local JadeHammerClutch
    local VoidAxeClutch
    local HealthCheck
    local CvDamage
    local Zephyr
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    -- Deliberately left on the default collision group - see groundBelow.
    local plainCheck = RaycastParams.new()
    plainCheck.RespectCanCollide = true
    plainCheck.FilterType = Enum.RaycastFilterType.Exclude
    local usedPearl = false
    local lastLegitUse = 0
    local clutchBusyUntil = 0
    local lastBlockPlace = 0
    local lastZephyrJump = 0
    local fallAnchorY
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local daoItems = {'wood_dao', 'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'}

    local function validCharacter()
        if not entitylib.isAlive then return end
        local character = entitylib.character
        local root = character.RootPart or character.HumanoidRootPart
        local humanoid = character.Humanoid
        if root and humanoid and humanoid.Health > 0 then
            return character, root, humanoid
        end
    end

    local function updateRay(root)
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        rayCheck.CollisionGroup = root.CollisionGroup
    end

    local function getGround(root, character, distance)
        updateRay(root)
        local hipHeight = character.HipHeight or (character.Humanoid and character.Humanoid.HipHeight) or 2
        local castDistance = -(distance + hipHeight + (root.Size.Y * 0.5))
        return workspace:Blockcast(root.CFrame, Vector3.new(3, 3, 3), Vector3.new(0, castDistance, 0), rayCheck)
    end

    -- Height of the floor below us, by three independent methods.
    --
    -- A cast that comes back empty is the single failure that stops TP mode dead: with no floor
    -- to aim at it does nothing at all, which is exactly what "TP doesn't teleport" looks like
    -- from the outside. So an empty result is never taken at face value here.
    --
    --   1. The box cast, tolerant of thin blocks and of ledges a thin ray slips past. This is the
    --      shipped script's own method, on the character's collision group.
    --   2. A plain long ray on the DEFAULT collision group. If the character sits in a group that
    --      does not collide with the map, (1) passes straight through the world and finds nothing
    --      while this still sees it.
    --   3. The block engine's own store, walked cell by cell down the column we are over. On a
    --      BedWars map the floor is nearly always a placed block, and a data lookup cannot be
    --      defeated by a collision group, a CanQuery flag or a filter at all.
    local function groundBelow(root, character)
        local ground = getGround(root, character, 1500)
        if ground then return ground.Position.Y end

        plainCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        local ray = workspace:Raycast(root.Position, Vector3.new(0, -3000, 0), plainCheck)
        if ray then return ray.Position.Y end

        local success, blockY = pcall(function()
            local origin = root.Position
            for step = 1, 200 do
                local below = Vector3.new(origin.X, origin.Y - (step * 3), origin.Z)
                if getPlacedBlock(below) then
                    -- Top face of the block we found, which is what we would stand on.
                    return (bedwars.BlockController:getBlockPosition(below).Y * 3) + 1.5
                end
            end
            return nil
        end)
        return success and blockY or nil
    end

    -- The distance from the root's centre down to the floor we stand on. entitylib already folds
    -- half the root part into HipHeight, so adding it again (as this used to) put every floor
    -- estimate a stud out.
    local function standClearance(root, character)
        local humanoid = character.Humanoid
        return character.HipHeight or ((humanoid and humanoid.HipHeight or 2) + (root.Size.Y * 0.5))
    end

    -- The fall that has built up: the fastest we have been moving downwards since we were last on
    -- the ground. This, not the speed at any one instant, is what a fall is worth - a drop that
    -- has already reached 200 studs a second is a lethal fall even on the frame it happens to be
    -- reading -3 because it clipped something. Every mode below decides off this one number.
    local trackedFall = 0

    local function updateTrackedFall(root, humanoid)
        if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
            trackedFall = 0
        else
            trackedFall = math.min(trackedFall, root.AssemblyLinearVelocity.Y)
        end
        return trackedFall
    end

    -- TP mode. BedWars charges for the landing you report, so the way to clear a long drop is to
    -- end it early: cast straight down, put the character on the floor it was heading for anyway
    -- and take the touchdown there with no speed left on it.
    --
    -- The old version teleported down for a couple of frames and then teleported back UP to
    -- "resume" the fall from where it would have got to. Moving upwards that fast is exactly what
    -- the server's movement check rejects, so every touch was rubber-banded straight back to
    -- where it started and the mode looked like it never teleported at all. A drop to the ground
    -- is a move the server is already expecting, so this one lands.
	local clearRegisteredFall
	local function tpNoFall(root, character)
        local groundY = groundBelow(root, character)
        if not groundY then return false end

        local floorY = groundY + standClearance(root, character)
        local drop = root.Position.Y - floorY
        -- Below the floor we found (inside a block, or it read a ceiling): leave it alone.
        if drop <= 1 then return false end

        local velocity = root.AssemblyLinearVelocity
		local landed = root.CFrame - Vector3.new(0, drop, 0)
		-- Pivot the complete character, not only its root. Moving a single part can
		-- be overwritten by the humanoid assembly before replication sees it.
		character:PivotTo(landed)
        -- Keep the horizontal travel so the landing spot is the one the fall was heading for,
        -- and arrive with nothing vertical left for the game to charge for. Dropping to the
        -- floor is a move the server is already expecting from someone who is falling, which is
        -- why this replicates where the old build's teleport back UP was always rejected.
        root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        -- The fall is over as far as we are concerned. Without this the next pass would still be
        -- holding the old speed and would fire again before the humanoid has registered the
        -- landing, which is what turns one teleport into a burst of them.
		trackedFall = 0
		clearRegisteredFall(-1)
		return true
    end

    local function restoreTool(oldTool)
        if oldTool and oldTool.tool then
            task.delay(0.18, function()
                switchItem(oldTool.tool)
                local oldHotbar = getHotbar(oldTool.tool)
                if oldHotbar then hotbarSwitch(oldHotbar) end
            end)
        end
    end

    local function firePearl(root, spot, pearl)
        if usedPearl or not pearl or not projectileRemote or not projectileRemote.InvokeServer then return end
        local meta = bedwars.ProjectileMeta.telepearl
        if not meta then return end

        local calc = prediction.SolveTrajectory(root.Position, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0)
        if not calc then return end

        local oldTool = store.hand
        local hotbar = getHotbar(pearl.tool)
        switchItem(pearl.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.03)

        local direction = CFrame.lookAt(root.Position, calc).LookVector * meta.launchVelocity
        local success = pcall(function()
            bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', root.Position, nil, direction, {drawDurationSeconds = 1})
            projectileRemote:InvokeServer(pearl.tool, 'telepearl', 'telepearl', root.Position, root.Position, direction, httpService:GenerateGUID(true), {
                drawDurationSeconds = 1,
                shotId = httpService:GenerateGUID(false)
            }, workspace:GetServerTimeNow() - 0.045)
        end)
        restoreTool(oldTool)
        if success then
            usedPearl = true
            return true
        end
    end

    local function blockClutch(root)
        if tick() - lastBlockPlace < 0.08 then return end
        local wool, amount = getWool()
        if not wool or (amount or 0) < 1 then return end

        lastBlockPlace = tick()
        local placePosition = bedwars.BlockController:getBlockPosition(root.Position - Vector3.new(0, 4, 0)) * 3
        fallAnchorY = root.Position.Y
        if not getPlacedBlock(placePosition) and bedwars.placeBlock(placePosition, wool) then
            return true
        end
    end

    local function isFallFatal(root, humanoid, ground)
        if not HealthCheck or not HealthCheck.Enabled then return true end
        if not ground then return true end

        local health = (lplr.Character and lplr.Character:GetAttribute('Health')) or humanoid.Health
        local fallBlocks = math.max(0, ((fallAnchorY or root.Position.Y) - ground.Position.Y) / 3)
        local estimatedDamage = math.max(0, fallBlocks - 6) * 5
        return estimatedDamage >= health
    end

    local function abilityClutch(item, ability, callback)
        if not item then return end
        local oldTool = store.hand
        local hotbar = getHotbar(item.tool)
        switchItem(item.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.05)
        callback(item, ability)
        restoreTool(oldTool)
        return true
    end

    local function useToolAbility(ability, data)
        local success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, newproxy(true), data)
        end)
        if success and result ~= false then return true end

        success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, data)
        end)
        if success and result ~= false then return true end

        pcall(function()
            bedwars.Client:Get(remotes.UseAbility).instance:FireServer(ability, data)
        end)
        return true
    end

    local function jadeClutch(root)
        local item
        for _, hammer in jadeHammerNames do
            item = getItem(hammer)
            if item then break end
        end
        if not item then return end
        local ability = item.itemType..'_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function voidClutch(root)
        local item = getItem('void_axe')
        if not item then return end
        local ability = item.itemType..'_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function daoClutch(root)
        for _, itemName in daoItems do
            local item = getItem(itemName)
            if item and (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') then
                return abilityClutch(item, 'dash', function(dao)
                    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                    replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
                        direction = Vector3.new(root.CFrame.LookVector.X, -0.05, root.CFrame.LookVector.Z).Unit,
                        origin = root.Position,
                        weapon = dao.itemType
                    })
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
                end)
            end
        end
    end

    local function toolClutch(root)
        if DaoClutch and DaoClutch.Enabled and daoClutch(root) then return true end
        if JadeHammerClutch and JadeHammerClutch.Enabled and jadeClutch(root) then return true end
        if VoidAxeClutch and VoidAxeClutch.Enabled and voidClutch(root) then return true end
    end

    local function shouldToolClutch(root, humanoid, groundDistance)
        if not groundDistance or groundDistance == math.huge then return false end
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)
        if verticalSpeed <= 0 then return false end

        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        return remainingDistance <= 4.5 or (remainingDistance / verticalSpeed) <= 0.16
    end

    local function telepearlClutch(root, ground, groundDistance)
        if usedPearl or not TelepearlClutch or not TelepearlClutch.Enabled then return end
        local pearl = getItem('telepearl')
        return pearl and ground and firePearl(root, ground.Position + Vector3.new(0, 3, 0), pearl)
    end

    local function legitClutch(root, humanoid, ground)
        local now = tick()
        if now < clutchBusyUntil or now - lastLegitUse < 0.06 then return end
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            return
        end

        local groundDistance = ground and (root.Position.Y - ground.Position.Y) or math.huge
        fallAnchorY = fallAnchorY or root.Position.Y
        lastLegitUse = now

        if not isFallFatal(root, humanoid, ground) then return end

        if BlockClutch and BlockClutch.Enabled and groundDistance > 21 and (fallAnchorY - root.Position.Y) >= 15 then
            if blockClutch(root) then
                clutchBusyUntil = tick() + 0.08
                return true
            end
        end

        if root.AssemblyLinearVelocity.Y > -(MinVelocity and MinVelocity.Value or 60) then return end

        if TelepearlClutch and TelepearlClutch.Enabled and telepearlClutch(root, ground, groundDistance) then
            clutchBusyUntil = tick() + 0.65
            return true
        end

        if ground and shouldToolClutch(root, humanoid, groundDistance) and toolClutch(root) then
            clutchBusyUntil = tick() + 0.65
            return true
        end
    end

    -- Best-effort Zephyr kit detection. This is never a hard requirement: it
    -- returns true/false when the kit can be read and nil when it cannot, so
    -- callers can treat "unknown" as "go ahead anyway" and never break.
    local function hasZephyrKit()
        local success, result = pcall(function()
            local kit = store.equippedKit
            if kit == nil or kit == '' then
                kit = lplr:GetAttribute('PlayingAsKit')
            end
            if kit == nil then return nil end
            -- The Zephyr kit is internally named "WindWalker" (bedwars.WindWalkerController),
            -- so matching only the string 'zephyr' failed for everyone actually using the kit
            -- and made this clutch never fire. Accept both names.
            local name = string.lower(tostring(kit))
            return name:find('zephyr') ~= nil or name:find('wind') ~= nil
        end)
        if not success then return nil end
        return result
    end

    local zephyrFired = false
    local function zephyrClutch(root, humanoid, ground)
        local now = tick()
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            zephyrFired = false
            return
        end

        fallAnchorY = fallAnchorY or root.Position.Y
        -- Fire at most once per fall; retriggering while the Jump flag is still
        -- latched is what caused the extra, unwanted hops after landing.
        if zephyrFired or now - lastZephyrJump < 0.3 then return end
        if not ground or not isFallFatal(root, humanoid, ground) then return end

        -- Detection is a soft gate only: skip the jump when we positively know
        -- the wrong kit is equipped, but proceed on failure or an unknown kit.
        if hasZephyrKit() == false then return end

        local groundDistance = root.Position.Y - ground.Position.Y
        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)

        -- Short falls never deal damage in BedWars (~6 blocks of grace), so a
        -- jump there is pure noise even though isFallFatal passes with the
        -- health check disabled. Require a fall that can actually hurt.
        local totalFall = math.max(fallAnchorY - root.Position.Y, 0) + remainingDistance
        if totalFall < 20 then return end

        -- Jump the instant before ground contact so the fall resets on landing.
        if remainingDistance <= 3.5 or (verticalSpeed > 0 and (remainingDistance / verticalSpeed) <= 0.09) then
            lastZephyrJump = now
            zephyrFired = true
            pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                humanoid.Jump = true
            end)
            -- Release the latched Jump flag so the humanoid does not queue a
            -- second, unwanted jump for the frame after it lands.
            task.delay(0.2, function()
                pcall(function()
                    if humanoid.Parent then
                        humanoid.Jump = false
                    end
                end)
            end)
            return true
        end
    end

    -- Blatant. Nothing physical happens here at all: the character falls at full speed, lands
    -- where and when it would have, and no velocity, position or humanoid state is ever touched.
    -- The only thing that changes is what the server has on its books for the fall.
    --
    -- BedWars settles fall damage off the ground-hit event the client sends it. While descending,
    -- replay the same GroundHit payload used by the game exploit so the fall is continuously
    -- settled and cleared before the real landing arrives.
    --
    -- The cadence is the mechanism, not a detail. One packet and then silence leaves the fall
    -- free to build straight back up before touchdown, which is why this is deliberately NOT
    -- rate limited - it fires on every pass of the module's poll for as long as the fall is
    -- dangerous, so at the moment of landing the server has at most one tick of drop recorded.
    -- An earlier build here rate limited it to one send every 120ms and that is precisely the
    -- kind of "tidying" that stops it working.
    --
    -- Every physical variant of this has now been tried and none of them hold: cancelling the
    -- registered velocity, bleeding the impact off in the last frames, capping the fall speed
    -- and giving the distance back. They all lose the same race against the landing frame, or
    -- lean on a field the game does not have. This one does not race anything - it is simply
    -- keeping the server's record of the fall empty the whole way down.
    local groundHit
    local groundHitBlock

    local function resolveGroundHit()
        if groundHit and groundHitBlock then return groundHit end
        local success, remote, block = pcall(function()
            local managed = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged
            return managed.GroundHit, workspace.Map.Worlds.tr_Range.Blocks:GetChildren()[222]
        end)
        groundHit = success and remote or nil
        groundHitBlock = success and block or nil
        return groundHit
    end
    task.spawn(resolveGroundHit)

	clearRegisteredFall = function()
        local remote = resolveGroundHit()
        if not remote or not groundHitBlock then return false end
		local success = pcall(function()
			remote:FireServer(
                groundHitBlock,
                Vector3.new(-10.598394393921, -35.038021087646, -16.960966110229),
                1785564031.154
            )
        end)
        return success
    end

    local cvStateConnections = {}
    local modeGeneration = 0

    local function restoreCvStateConnections()
        for _, connection in cvStateConnections do
            pcall(function()
                if connection.Enable then connection:Enable() end
            end)
        end
        table.clear(cvStateConnections)
    end

    local function disableCvStateConnections(humanoid)
        restoreCvStateConnections()
        if not humanoid or type(getconnections) ~= 'function' then return end
        local ok, connections = pcall(getconnections, humanoid.StateChanged)
        if not ok or type(connections) ~= 'table' then return end
        for _, connection in connections do
            if connection and connection.Disable then
                local disabled = pcall(connection.Disable, connection)
                if disabled then table.insert(cvStateConnections, connection) end
            end
        end
    end

    local function startCvBlatant(generation)
        if entitylib.isAlive then
            disableCvStateConnections(entitylib.character.Humanoid)
        end

        local trackedVelocity = 0
        local groundHit
        pcall(function()
            groundHit = bedwars.Handler:Get('GroundHit')
        end)

        NoFall:Clean(runService.PostSimulation:Connect(function()
            if generation ~= modeGeneration or not NoFall.Enabled or Mode.Value ~= 'Blatant' then return end
            if not entitylib.isAlive or store.matchState ~= 1 or store.infinitefly then return end

            local root = entitylib.character.RootPart
            local humanoid = entitylib.character.Humanoid
            local velocity = root.Velocity
            if trackedVelocity < -(45 + ((CvDamage and CvDamage.Value or 0) * 0.75)) then
                -- cv behaviour: briefly report a landed state, preserve the fall's previous
                -- velocity, and settle the GroundHit record immediately.
                root.Velocity = Vector3.new(0, 2.5, 0)
                humanoid:ChangeState(Enum.HumanoidStateType.Landed)
                runService.PreRender:Wait()
                if generation == modeGeneration and NoFall.Enabled and Mode.Value == 'Blatant' and root.Parent then
                    root.Velocity = velocity
                    if groundHit then
                        pcall(groundHit.Fire, groundHit, 'SendToServer', nil, Vector3.new(0, trackedVelocity, 0), workspace:GetServerTimeNow())
                    end
                end
            end
            trackedVelocity = velocity.Y
        end))

        NoFall:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
            if generation ~= modeGeneration or not NoFall.Enabled or Mode.Value ~= 'Blatant' then return end
            task.defer(function()
                if generation == modeGeneration and NoFall.Enabled and Mode.Value == 'Blatant' then
                    disableCvStateConnections(ent.Humanoid)
                end
            end)
        end))
    end

    local function setSettingsVisible()
        local legit = Mode and Mode.Value == 'Legit'
        if CvDamage and CvDamage.Object then CvDamage.Object.Visible = not legit end
        if MinVelocity and MinVelocity.Object then MinVelocity.Object.Visible = legit end
        if HealthCheck and HealthCheck.Object then HealthCheck.Object.Visible = legit end
        for _, option in {BlockClutch, TelepearlClutch, DaoClutch, JadeHammerClutch, VoidAxeClutch, Zephyr} do
            if option and option.Object then option.Object.Visible = legit end
        end
    end

    NoFall = vape.Categories.Blatant:CreateModule({
        Name = 'NoFallDamage',
        Function = function(callback)
            modeGeneration += 1
            local generation = modeGeneration

            if callback then
                restoreCvStateConnections()
                if Mode.Value == 'Blatant' then
                    startCvBlatant(generation)
                end

                repeat
                    local waitDelay = 0.1
                    local character, root, humanoid = validCharacter()
                    if character then
                        updateTrackedFall(root, humanoid)
                        if humanoid.FloorMaterial ~= Enum.Material.Air then
                            usedPearl = false
                        elseif Mode.Value == 'Legit' then
                            local ground = getGround(root, character, HealthCheck and HealthCheck.Enabled and 300 or 30)
                            local zephyred = false
                            if Zephyr and Zephyr.Enabled then
                                zephyred = zephyrClutch(root, humanoid, ground)
                                if zephyred then waitDelay = 0.05 end
                            end
                            if not zephyred then legitClutch(root, humanoid, ground) end
                        end
                    end
                    task.wait(waitDelay)
                until not NoFall.Enabled or generation ~= modeGeneration
            else
                restoreCvStateConnections()
                usedPearl = false
                lastLegitUse = 0
                clutchBusyUntil = 0
                lastBlockPlace = 0
                lastZephyrJump = 0
                zephyrFired = false
                fallAnchorY = nil
                trackedFall = 0
            end
        end,
        Tooltip = 'Prevents fall damage'
    })
	Mode = NoFall:CreateDropdown({
		Name = 'Mode',
		List = {'Blatant', 'Legit'},
        Function = function()
            setSettingsVisible()
            if NoFall.Enabled then
                NoFall:Toggle()
                NoFall:Toggle()
            end
        end,
		Tooltip = 'Blatant - completely cancels/reduces fall damage\nLegit - clutches using semi-legit means'
    })
    CvDamage = NoFall:CreateSlider({
        Name = 'Damage',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%',
        Tooltip = 'How much % of fall damage to take'
    })
    MinVelocity = NoFall:CreateSlider({
        Name = 'Minimum Velocity',
        Min = 35,
        Max = 120,
        Default = 60,
        Tooltip = 'How fast the drop has to be before Legit uses a clutch'
    })
    BlockClutch = NoFall:CreateToggle({
        Name = 'Blocks',
        Default = true,
        Tooltip = 'Places blocks directly beneath you while falling'
    })
    HealthCheck = NoFall:CreateToggle({
        Name = 'Health check',
        Tooltip = 'Only clutches when the estimated fall damage would be lethal'
    })
    Zephyr = NoFall:CreateToggle({
        Name = 'Zephyr',
        Tooltip = 'Jumps before landing with Zephyr'
    })
    TelepearlClutch = NoFall:CreateToggle({
        Name = 'Telepearl',
        Default = true,
        Tooltip = 'Throws a telepearl to nearby safe ground'
    })
    DaoClutch = NoFall:CreateToggle({
        Name = 'Dao',
        Default = true
    })
    JadeHammerClutch = NoFall:CreateToggle({
        Name = 'Jade Hammer',
        Default = true
    })
    VoidAxeClutch = NoFall:CreateToggle({
        Name = 'Void Axe',
        Default = true
    })

    setSettingsVisible()
end)
-- END AETHER MODULE: blatant/NoFallDamage.lua --

-- BEGIN AETHER MODULE: blatant/NoSlowdown.lua --
run(function()
    local old

    vape.Categories.Blatant:CreateModule({
        Name = 'NoSlowdown',
        Function = function(callback)
            local modifier = bedwars.SprintController:getMovementStatusModifier()
            if callback then
                old = modifier.addModifier
                modifier.addModifier = function(self, tab)
                    if tab.moveSpeedMultiplier then
                        tab.moveSpeedMultiplier = math.max(tab.moveSpeedMultiplier, 1)
                    end
                    return old(self, tab)
                end

                for i in modifier.modifiers do
                    if (i.moveSpeedMultiplier or 1) < 1 then
                        modifier:removeModifier(i)
                    end
                end
            else
                modifier.addModifier = old
                old = nil
            end
        end,
        Tooltip = 'Prevents slowing down when using items'
    })
end)
-- END AETHER MODULE: blatant/NoSlowdown.lua --

-- BEGIN AETHER MODULE: blatant/PlayerAttach.lua --
run(function()
    local PlayerAttach
    local Range
    local Targets

    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    PlayerAttach = vape.Categories.Blatant:CreateModule({
        Name = 'PlayerAttach',
        Tooltip = 'Attachs you to the nearest target',
        Function = function(call)
            if call then
                repeat
                    if entitylib.isAlive then
                        local plr = entitylib.AllPosition({
                            Range = Range.Value,
                            Wallcheck = Targets.Walls.Enabled or nil,
                            Part = 'RootPart',
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Limit = 1,
                            Sort = function(a, b)
                                return a.Entity.Health < b.Entity.Health
                            end
                        })[1]
                        if plr then
                            rayCheck.FilterDescendantsInstances = {plr.RootPart.Parent, lplr.Character}

                            entitylib.character.RootPart.AssemblyLinearVelocity = Vector3.new(0, entitylib.character.RootPart.Size.Y / 2 + entitylib.character.Humanoid.HipHeight + 0.25 * 3, 0)
                            entitylib.character.RootPart.CFrame = plr.RootPart.CFrame + (not workspace:Raycast(plr.RootPart.Position, plr.RootPart.CFrame.LookVector, rayCheck) and (plr.RootPart.CFrame.LookVector * 1.4) or Vector3.zero)
                        end
                    end
                    task.wait()
                until not PlayerAttach.Enabled
            end
        end
    })

    Targets = PlayerAttach:CreateTargets({
        Players = true,
        NPCs = true
    })

    Range = PlayerAttach:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 35,
        Default = 23,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end
    })
end)
-- END AETHER MODULE: blatant/PlayerAttach.lua --

-- BEGIN AETHER MODULE: blatant/ProjectileAimbot.lua --
run(function()
	local Blacklist
	local TargetPart
	local Targets
	local Sort
	local FOV
	local AutoCharge
	local Aim = {}
	local OtherProjectiles
	local MaxAccuracy
	local maxAccuracyScale = 1
	local maxAccuracyGeneration = 0
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	rayCheck.FilterDescendantsInstances = {workspace:FindFirstChild('Map')}
	local launchHook

	local function resolveProjectileAimbotPart(ent, requested, projectileType)
		local character = ent and ent.Character
		local root = ent and (ent.RootPart or ent.HumanoidRootPart) or character and character.PrimaryPart
		if not character then return root end
		local function first(...)
			for index = 1, select('#', ...) do
				local partName = select(index, ...)
				local part = partName and character:FindFirstChild(partName)
				if part and part:IsA('BasePart') then return part end
			end
			return root
		end
		if requested == 'Dynamic' then
			requested = tostring(projectileType or ''):lower():find('headhunter', 1, true) and 'Head' or 'RootPart'
		end
		if requested == 'Head' then return first('Head') end
		if requested == 'Torso' then return first('UpperTorso', 'Torso', 'LowerTorso') end
		if requested == 'Left arm' then return first('LeftHand', 'LeftLowerArm', 'LeftUpperArm', 'Left Arm') end
		if requested == 'Right arm' then return first('RightHand', 'RightLowerArm', 'RightUpperArm', 'Right Arm') end
		if requested == 'Left leg' then return first('LeftFoot', 'LeftLowerLeg', 'LeftUpperLeg', 'Left Leg') end
		if requested == 'Right leg' then return first('RightFoot', 'RightLowerLeg', 'RightUpperLeg', 'Right Leg') end
		if requested == 'Random' then
			local available = {first('Head'), first('UpperTorso', 'Torso'), first('LeftHand', 'Left Arm'), first('RightHand', 'Right Arm'), first('LeftFoot', 'Left Leg'), first('RightFoot', 'Right Leg')}
			local filtered = {}
			for _, part in available do if part and part ~= root then table.insert(filtered, part) end end
			return #filtered > 0 and filtered[math.random(1, #filtered)] or root
		end
		return root
	end

	local ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		Function = function(callback)
			if callback then
				if vape.Modules.SilentAim and vape.Modules.SilentAim.Enabled then vape.Modules.SilentAim:Toggle() end
				launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileAimbot', 12, function(nextLaunch, ...)
					local launch = nextLaunch(...)
					local projmeta, worldmeta = select(2, ...), select(3, ...)
					if type(launch) ~= 'table' or typeof(launch.positionFrom) ~= 'Vector3'
						or typeof(launch.initialVelocity) ~= 'Vector3' or not projmeta then return launch end
					local projectileType = tostring(projmeta.projectile or '')
					if projectileType == '' or ((not OtherProjectiles.Enabled) and not projectileType:find('arrow')) then return launch end
					local blacklistName = (projectileType == 'glue_trap' or projectileType == 'glue_projectile') and 'gloop' or projectileType
					if table.find(Blacklist.ListEnabled or {}, blacklistName) then return launch end

					local origin = launch.positionFrom
					local plr = entitylib.EntityMouse({
						Part = 'RootPart',
						Range = FOV.Value,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled,
						Origin = origin,
						Sort = sortmethods[Sort.Value]
					})
					if plr then
						local targetPart = resolveProjectileAimbotPart(plr, TargetPart.Value, projectileType)
						if not targetPart or not targetPart.Parent then return launch end
						local ok, meta = pcall(projmeta.getProjectileMeta, projmeta)
						meta = ok and meta or bedwars.ProjectileMeta[projectileType]
						if type(meta) ~= 'table' then return launch end
						local lifetime = (worldmeta and meta.predictionLifetimeSec or meta.lifetimeSec or 3)
						local gravity = launch.gravitationalAcceleration or ((meta.gravitationalAcceleration or 196.2) * (projmeta.gravityMultiplier or 1))
						local fullSpeed = tonumber(meta.launchVelocity) or launch.initialVelocity.Magnitude
						local speed = (AutoCharge.Enabled or not Aim.Enabled) and fullSpeed or launch.initialVelocity.Magnitude
						local solution = solveBedwarsProjectile(origin, speed, gravity, plr, targetPart.Position, {
							Lifetime = lifetime,
							PredictionScale = maxAccuracyScale,
							Stationary = projectileType == 'telepearl',
							RaycastParams = rayCheck
						})
						if solution then
							store.hitchance.ProjectileAimbot = {Value = getHitChance(plr, (targetPart.Position - origin).Magnitude / math.max(speed, 1)), Clock = tick()}
							targetinfo.Targets[plr] = tick() + 1
							launch.initialVelocity = solution.Velocity
							launch.positionFrom = origin
							launch.deltaT = lifetime
							launch.gravitationalAcceleration = gravity
							if AutoCharge.Enabled then launch.drawDurationSeconds = 5 end
						end
					end
					return launch
				end)
				ProjectileAimbot:Clean(function()
					if launchHook then launchHook(); launchHook = nil end
				end)
			elseif launchHook then
				launchHook()
				launchHook = nil
			end
		end,
		Tooltip = 'Silently adjusts your aim towards the enemy'
	})
	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})
	local methods = {'Distance', 'Damage'}
	for _, i in sortlist do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Distance'
	})
	TargetPart = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic'}
	})
	MaxAccuracy = ProjectileAimbot:CreateToggle({
		Name = 'Max accuracy',
		Tooltip = 'Changes prediction based on ping to give you the most accurate shots',
		Function = function(callback)
			maxAccuracyGeneration += 1
			local generation = maxAccuracyGeneration
			if callback then
				MaxAccuracy:Clean(task.spawn(function()
					repeat
						maxAccuracyScale = math.clamp(1 - lplr:GetNetworkPing(), 0.1, 1)
						task.wait(1)
					until not MaxAccuracy.Enabled or generation ~= maxAccuracyGeneration
				end))
			else
				maxAccuracyScale = 1
			end
		end
	})
	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = 'Auto Charge',
		Function = function(callback)
			if Aim.Object then
				Aim.Object.Visible = callback
			end
		end,
		Default = true,
		Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage'
	})
	Aim = ProjectileAimbot:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Changes your trajectory to match charge percentage.'
	})
	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true
	})
	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})
end)
-- END AETHER MODULE: blatant/ProjectileAimbot.lua --

-- BEGIN AETHER MODULE: blatant/ProjectileAura.lua --
run(function()
	local ProjectileAura
	local Targets
	local FireRate
	local Range
	local Part
	local List
	local UseSophia
	local UseWhim
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	local projectileRemote
	local FireDelays = {}
	local generation = 0

	local function resolveProjectileAuraPart(ent, requested, projectileType)
		local character = ent and ent.Character
		local root = ent and (ent.RootPart or ent.HumanoidRootPart) or character and character.PrimaryPart
		if not character then return root end
		local function first(...)
			for index = 1, select('#', ...) do
				local partName = select(index, ...)
				local part = partName and character:FindFirstChild(partName)
				if part and part:IsA('BasePart') then return part end
			end
			return root
		end
		if requested == 'Dynamic' then
			requested = tostring(projectileType or ''):lower():find('headhunter', 1, true) and 'Head' or 'RootPart'
		end
		if requested == 'Head' then return first('Head') end
		if requested == 'Torso' then return first('UpperTorso', 'Torso', 'LowerTorso') end
		if requested == 'Left arm' then return first('LeftHand', 'LeftLowerArm', 'LeftUpperArm', 'Left Arm') end
		if requested == 'Right arm' then return first('RightHand', 'RightLowerArm', 'RightUpperArm', 'Right Arm') end
		if requested == 'Left leg' then return first('LeftFoot', 'LeftLowerLeg', 'LeftUpperLeg', 'Left Leg') end
		if requested == 'Right leg' then return first('RightFoot', 'RightLowerLeg', 'RightUpperLeg', 'Right Leg') end
		if requested == 'Random' then
			local available = {first('Head'), first('UpperTorso', 'Torso'), first('LeftHand', 'Left Arm'), first('RightHand', 'Right Arm'), first('LeftFoot', 'Left Leg'), first('RightFoot', 'Right Leg')}
			local filtered = {}
			for _, part in available do if part and part ~= root then table.insert(filtered, part) end end
			return #filtered > 0 and filtered[math.random(1, #filtered)] or root
		end
		return root
	end

	local function getProjectileRemote()
		if projectileRemote and type(projectileRemote.InvokeServer) == 'function' then return projectileRemote end
		local ok, remote = pcall(function()
			local handler = bedwars.Handler:Get('ProjectileFire')
			return handler and handler.Remote and handler.Remote.instance
		end)
		if not ok or not remote then
			ok, remote = pcall(function() return bedwars.Client:Get(remotes.FireProjectile).instance end)
		end
		if ok and remote and type(remote.InvokeServer) == 'function' then projectileRemote = remote end
		return projectileRemote
	end

	ProjectileAura = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAura',
		Function = function(callback)
			generation += 1
			if not callback then return end
			local token = generation
			repeat
				if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.3 and entitylib.isAlive then
					local ent = entitylib.EntityPosition({
						Part = 'RootPart',
						Range = Range.Value,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled
					})
					local remote = ent and getProjectileRemote()
					if ent and ent.RootPart and remote then
						local rootPosition = entitylib.character.RootPart.Position
						for _, data in getProjectiles(List.ListEnabled, UseSophia.Enabled, UseWhim.Enabled) do
							if token ~= generation or not ProjectileAura.Enabled then break end
							local item, ammo, projectile, source, meta = unpack(data)
							local now = workspace:GetServerTimeNow()
							local aimPart = resolveProjectileAuraPart(ent, Part.Value, projectile)
							if not aimPart then continue end
							if item.tool and item.tool.Parent and (FireDelays[item.itemType] or 0) <= now then
								rayCheck.FilterDescendantsInstances = {lplr.Character, ent.Character, gameCamera}
								local speed = meta.launchVelocity
								local first = solveBedwarsProjectile(rootPosition, speed, meta.gravitationalAcceleration, ent, aimPart.Position, {
									RaycastParams = rayCheck,
									Lifetime = meta.lifetimeSec or 3
								})
								local shootPosition = first and projectileLaunchOrigin(rootPosition, first.Velocity)
								local solution = shootPosition and solveBedwarsProjectile(shootPosition, speed, meta.gravitationalAcceleration, ent, aimPart.Position, {
									RaycastParams = rayCheck,
									Lifetime = meta.lifetimeSec or 3
								})
								if solution then
									store.hitchance.ProjectileAura = {Value = getHitChance(ent, (aimPart.Position - shootPosition).Magnitude / math.max(speed, 1)), Clock = tick()}
									switchItem(item.tool, 0)
									FireDelays[item.itemType] = now + (source.fireDelaySec or 0) + FireRate:GetRandomValue()
									task.spawn(function()
										if token ~= generation or not ProjectileAura.Enabled or not item.tool.Parent then return end
										local velocity = solution.Velocity
										local id = httpService:GenerateGUID(true)
										local draw = {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}
										pcall(bedwars.ProjectileController.createLocalProjectile, bedwars.ProjectileController, meta, ammo, projectile, shootPosition, id, velocity, draw)
										local ok, result = pcall(remote.InvokeServer, remote, item.tool, ammo, projectile, shootPosition, rootPosition, velocity, id, draw, workspace:GetServerTimeNow() - 0.045)
										if token ~= generation or not ProjectileAura.Enabled then return end
										if ok and result ~= false then
											store.lastProjectileFire = workspace:GetServerTimeNow()
											targetinfo.Targets[ent] = tick() + 1
											prediction.trackShot(ent.RootPart)
											local sounds = source.launchSound
											local sound = type(sounds) == 'table' and #sounds > 0 and sounds[math.random(1, #sounds)] or nil
											if sound then pcall(bedwars.SoundManager.playSound, bedwars.SoundManager, sound) end
										else
											FireDelays[item.itemType] = workspace:GetServerTimeNow()
										end
									end)
									task.wait(FireRate:GetRandomValue())
								end
							end
						end
					end
				end
				task.wait(0.03)
			until not ProjectileAura.Enabled or token ~= generation
		end,
		Tooltip = 'Shoots people around you'
	})
	Targets = ProjectileAura:CreateTargets({
		Players = true,
		Walls = true
	})
	Part = ProjectileAura:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic'},
		Default = 'Dynamic',
		Tooltip = 'Dynamic uses Head for headhunters and the body/root for other projectiles'
	})
	List = ProjectileAura:CreateTextList({
		Name = 'Projectiles',
		Default = {'arrow', 'snowball'}
	})
	UseSophia = ProjectileAura:CreateToggle({
		Name = 'Use sophia',
		Tooltip = 'Also shoots sophia\'s frost staff, swapping it out of mist mode on its own'
	})
	UseWhim = ProjectileAura:CreateToggle({
		Name = 'Use whim',
		Tooltip = 'Also casts whim\'s magic book, follows whatever element you have cycled'
	})
	FireRate = ProjectileAura:CreateTwoSlider({
		Name = 'Fire Rate',
		Min = 0,
		Max = 1,
		DefaultMin = 0.05,
		DefaultMax = 0.12,
		Decimal = 100
	})
	Range = ProjectileAura:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 50,
		Default = 50,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
end)
-- END AETHER MODULE: blatant/ProjectileAura.lua --

-- BEGIN AETHER MODULE: blatant/ProjectileDodger.lua --
run(function()
    local ProjectileDodger
    local Range
    local Strength
    local Mode
    local TeleportDistance
    local EdgeCheck
    local projectiles = {}
    local projectileHistory = {}
    local dodgedProjectiles = {}
    local dodgeUntil, dodgeDirection = 0, Vector3.zero
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    -- Projectiles replicate as Models parented directly to workspace, tagged with 'ProjectileShooter'.
    local function projectilePart(obj)
        return obj:IsA('BasePart') and obj or obj.PrimaryPart
    end

    local function isProjectile(obj)
        local shooter = obj:GetAttribute('ProjectileShooter')
        if shooter == nil or shooter == lplr.UserId then return false end
        return projectilePart(obj) ~= nil
    end

    -- Keep the last good velocity so freshly spawned projectiles (which report a
    -- zero AssemblyLinearVelocity for a frame or two) are still dodged in time.
    local function getProjectileVelocity(obj, part)
        local now = os.clock()
        local history = projectileHistory[obj]
        local assembly = part.AssemblyLinearVelocity
        local velocity
        if assembly.Magnitude > 1 then
            velocity = assembly
        elseif history and (now - history.Time) > 1e-4 then
            velocity = (part.Position - history.Position) / (now - history.Time)
        end
        if (not velocity or velocity.Magnitude <= 2) and history and history.Velocity then
            velocity = history.Velocity
        end
        velocity = velocity or Vector3.zero
        projectileHistory[obj] = {Position = part.Position, Time = now, Velocity = velocity.Magnitude > 2 and velocity or (history and history.Velocity)}
        return velocity
    end

    local function safeDirection(root, dir)
        if dir ~= dir or dir.Magnitude <= 0 then
            dir = root.CFrame.RightVector
        end
        dir = Vector3.new(dir.X, 0, dir.Z)
        dir = dir.Magnitude > 0 and dir.Unit or root.CFrame.RightVector
        if not EdgeCheck.Enabled then return dir end
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
        local rightSafe = workspace:Raycast(root.Position + (dir * 6), Vector3.new(0, -16, 0), rayCheck)
        if rightSafe then return dir end
        local left = -dir
        local leftSafe = workspace:Raycast(root.Position + (left * 6), Vector3.new(0, -16, 0), rayCheck)
        return leftSafe and left or dir
    end

    local function teleportDodge(root, side)
        local distance = TeleportDistance.Value * 3 -- slider is in blocks; BedWars blocks are 3 studs
        local options = {side, -side}
        for _, direction in options do
            local target = root.Position + (direction * distance)
            if not EdgeCheck.Enabled or workspace:Raycast(target + Vector3.new(0, 2, 0), Vector3.new(0, -12, 0), rayCheck) then
                root.CFrame = CFrame.new(target, target + root.CFrame.LookVector)
                root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                return true
            end
        end
        return false
    end

    -- Evaluates the threat along the projectile's real (gravity-aware) arc. A straight-line
    -- closest-approach reports a large miss for an arcing arrow until it is nearly on top of
    -- you, which is what made the sidestep fire too late; sampling the parabola catches it
    -- with time to spare.
    local function incomingDirection(obj, root, range)
        local part = obj.Parent and projectilePart(obj)
        if not part then return end
        local origin = part.Position
        local rootPos = root.Position
        if (origin - rootPos).Magnitude > math.max(range, 70) then return end
        local velocity = getProjectileVelocity(obj, part)
        if velocity.Magnitude < 2 then return end
        local toLocal = rootPos - origin
        if toLocal.Magnitude <= 0 then return end
        local closingSpeed = velocity:Dot(toLocal.Unit)
        if closingSpeed <= 0 then return end

        local meta = bedwars.ProjectileMeta[obj.Name]
        local grav = meta and meta.gravitationalAcceleration or workspace.Gravity
        local horizon = math.clamp((toLocal.Magnitude / closingSpeed) * 1.3, 0.05, 1.4)
        local miss, timeToHit = math.huge, horizon
        for i = 0, 16 do
            local t = horizon * i / 16
            local pos = origin + velocity * t - Vector3.new(0, 0.5 * grav * t * t, 0)
            local d = (pos - rootPos).Magnitude
            if d < miss then
                miss = d
                timeToHit = t
            end
        end
        if miss < 12 then
            return safeDirection(root, velocity.Unit:Cross(Vector3.yAxis)), timeToHit
        end
    end

    ProjectileDodger = vape.Categories.Blatant:CreateModule({
        Name = 'ProjectileDodger',
        Function = function(callback)
            if callback then
                table.clear(projectiles)
                table.clear(projectileHistory)
                table.clear(dodgedProjectiles)
                for _, obj in workspace:GetChildren() do
                    if isProjectile(obj) then projectiles[obj] = true end
                end
                ProjectileDodger:Clean(workspace.ChildAdded:Connect(function(obj)
                    task.delay(0, function()
                        if obj.Parent and isProjectile(obj) then projectiles[obj] = true end
                    end)
                end))

                -- Legit mode moves the real hitbox with a smooth, frame-rate-independent CFrame
                -- nudge every physics step. Setting AssemblyLinearVelocity alone does nothing here
                -- because the Humanoid movement controller overwrites it each step, which is why
                -- Legit mode previously appeared to do nothing at all.
                ProjectileDodger:Clean(runService.PostSimulation:Connect(function(dt)
                    if Mode.Value ~= 'Legit' or tick() >= dodgeUntil or dodgeDirection.Magnitude <= 0 then return end
                    if not entitylib.isAlive then return end
                    local root = entitylib.character.RootPart
                    if not root then return end
                    -- CFrame stepping only: also writing a full-strength velocity each
                    -- frame fought the humanoid controller and doubled the effective
                    -- speed, which is what made the sidestep overshoot and rubber-band.
                    local step = math.clamp(Strength.Value, 10, 80) * dt
                    local delta = Vector3.new(dodgeDirection.X * step, 0, dodgeDirection.Z * step)
                    -- Per-frame edge guard. The one-shot check at commit time only
                    -- probed 6 studs out, so a long Legit slide kept moving past the
                    -- last ground and walked the player off the edge even with Edge
                    -- Check on. Re-probe the ground directly beneath the *next*
                    -- position every frame and stop the slide the moment it would
                    -- leave a supported block.
                    if EdgeCheck.Enabled then
                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
                        local nextPos = root.Position + delta
                        if not workspace:Raycast(nextPos + Vector3.new(0, 2, 0), Vector3.new(0, -(entitylib.character.HipHeight + 5), 0), rayCheck) then
                            dodgeUntil = 0
                            return
                        end
                    end
                    root.CFrame = root.CFrame + delta
                end))

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        -- While a dodge is in progress just wait it out; the PostSimulation stepper
                        -- above carries out the Legit movement, and Teleport already fired instantly.
                        if tick() >= dodgeUntil then
                            local best, bestTime, bestObj = nil, math.huge, nil
                            for obj in projectiles do
                                if not obj.Parent then
                                    projectiles[obj] = nil
                                    projectileHistory[obj] = nil
                                    continue
                                end
                                local side, timeToHit = incomingDirection(obj, root, Range.Value)
                                if side and (timeToHit or 1.25) < bestTime and (not dodgedProjectiles[obj] or tick() - dodgedProjectiles[obj] > 1.5) then
                                    best, bestTime, bestObj = side, timeToHit or 1.25, obj
                                end
                            end
                            -- Only commit once the hit is imminent. Dodging the moment a
                            -- threat appears (sometimes >1s early) let the player drift
                            -- back into the arc while the per-projectile lockout blocked a
                            -- second dodge - the main source of "dodged but still got hit".
                            local ping = 0
                            pcall(function() ping = lplr:GetNetworkPing() end)
                            -- Teleport is instant and can't overshoot back into the arc, so it
                            -- commits earlier and covers a fuller round-trip than the Legit slide.
                            -- Reacting too late here was what let fast arrows land in TP mode.
                            local reactionWindow = Mode.Value == 'Teleport'
                                and math.min(ping * 1.4 + 0.45, 0.9)
                                or math.min(ping + 0.45, 0.6)
                            if best and bestTime <= reactionWindow then
                                dodgeDirection = best
                                if Mode.Value == 'Teleport' then
                                    -- Only flag the projectile as handled once the teleport actually
                                    -- fires. Previously it was flagged unconditionally, so a blocked
                                    -- teleport (edge check) locked the arrow out for 1.5s and let it hit.
                                    if teleportDodge(root, best) then
                                        dodgedProjectiles[bestObj] = tick()
                                        -- brief lockout so a burst of arrows can't chain-teleport the player away
                                        dodgeUntil = tick() + math.clamp(bestTime, 0.12, 0.35)
                                    end
                                else
                                    dodgedProjectiles[bestObj] = tick()
                                    dodgeUntil = tick() + math.clamp(bestTime + 0.15, 0.25, 0.6)
                                end
                            end
                        end
                    end
                    task.wait()
                until not ProjectileDodger.Enabled
            else
                table.clear(projectiles)
                table.clear(projectileHistory)
                table.clear(dodgedProjectiles)
                dodgeUntil = 0
                dodgeDirection = Vector3.zero
            end
        end,
        Tooltip = 'Dodges incoming projectiles without stepping off edges'
    })
    Range = ProjectileDodger:CreateSlider({Name = 'Range', Min = 10, Max = 80, Default = 45, Suffix = 'studs'})
    Mode = ProjectileDodger:CreateDropdown({Name = 'Mode', List = {'Teleport', 'Legit'}, Default = 'Teleport', Function = function(val)
        pcall(function()
            TeleportDistance.Object.Visible = val == 'Teleport'
            Strength.Object.Visible = val == 'Legit'
        end)
    end})
    TeleportDistance = ProjectileDodger:CreateSlider({Name = 'Teleport Distance', Min = 1, Max = 2, Default = 2, Decimal = 1, Suffix = ' blocks'})
    Strength = ProjectileDodger:CreateSlider({Name = 'Dodge Strength', Min = 10, Max = 80, Default = 38, Suffix = 'studs', Visible = false})
    EdgeCheck = ProjectileDodger:CreateToggle({Name = 'Edge Check', Default = true})
end)
-- END AETHER MODULE: blatant/ProjectileDodger.lua --

-- BEGIN AETHER MODULE: blatant/RecoveryTP.lua --
run(function()
    local RecoveryTP
    local HealthThreshold
    local TeleportHeight
    local GroundTime
    local PlayerCheck
    local groundedSince = 0
	local trackedCharacter
	local recovered = false

	local function validCharacter()
		local character = entitylib.character
		if not entitylib.isAlive or not character or not character.Character or not character.Character.Parent then return end
		local humanoid, root = character.Humanoid, character.RootPart
		if not humanoid or humanoid.Health <= 0 or not root or not root.Parent then return end
		return character, humanoid, root
	end

	local function playerNearby(origin)
		local list = type(entitylib.List) == 'table' and entitylib.List or {}
		for _, ent in list do
			local root = ent and ent.RootPart
			local player = ent and ent.Player
			if player and player ~= lplr and player.Parent == playersService and root and root.Parent
				and (not ent.Health or ent.Health > 0) and (root.Position - origin).Magnitude <= 50 then
				return true
			end
		end
		return false
	end

    RecoveryTP = vape.Categories.Blatant:CreateModule({
        Name = 'RecoveryTP',
        Function = function(callback)
			groundedSince, trackedCharacter, recovered = 0, nil, false
			if not callback then return end
			RecoveryTP:Clean(lplr.CharacterAdded:Connect(function(character)
				trackedCharacter, groundedSince, recovered = character, 0, false
			end))
            RecoveryTP:Clean(runService.PostSimulation:Connect(function()
				if not RecoveryTP.Enabled then return end
				local character, humanoid, root = validCharacter()
				if not character then groundedSince, recovered = 0, false return end
				if trackedCharacter ~= character.Character then
					trackedCharacter, groundedSince, recovered = character.Character, 0, false
				end
				if humanoid.Health >= HealthThreshold.Value then groundedSince, recovered = 0, false return end
				if recovered then return end
				local ownsRoot = false
				pcall(function() ownsRoot = isnetworkowner(root) end)
				if not ownsRoot then groundedSince = 0 return end
				if PlayerCheck.Enabled and not playerNearby(root.Position) then groundedSince = 0 return end
				if humanoid.FloorMaterial == Enum.Material.Air then groundedSince = 0 return end
                local now = tick()
                if groundedSince == 0 then groundedSince = now return end
				if now - groundedSince < GroundTime.Value then return end
				groundedSince, recovered = 0, true
				root.CFrame = CFrame.new(root.Position.X, TeleportHeight.Value, root.Position.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
            end))
        end,
        Tooltip = 'Teleports you to a safe height when your health is critical'
    })
    HealthThreshold = RecoveryTP:CreateSlider({Name = 'Health threshold', Min = 1, Max = 99, Default = 35, Suffix = ' HP'})
    TeleportHeight = RecoveryTP:CreateSlider({Name = 'Safe height', Min = 80, Max = 300, Default = 180, Suffix = ' studs'})
    GroundTime = RecoveryTP:CreateSlider({Name = 'Ground time', Min = 0.1, Max = 3, Default = 0.5, Decimal = 100, Suffix = ' seconds'})
    PlayerCheck = RecoveryTP:CreateToggle({
        Name = 'Player check',
        Tooltip = 'Only teleports while a player is within 50 studs'
    })
end)
-- END AETHER MODULE: blatant/RecoveryTP.lua --

-- BEGIN AETHER MODULE: blatant/Speed.lua --
run(function()
	local Speed
    local Mode
    local Value
    local WallCheck
    local AutoJump
    local AlwaysJump
    local KrystalKit, KrystalSpeed
    local SigridKit, SigridSpeed
    local GrimKit, GrimSpeed
    local ZephyrKit, ZephyrSpeed

    local function kitMovementSpeed(fallback)
        if not entitylib.isAlive then return fallback end
        local equipped = store.equippedKit
        if equipped == nil or equipped == '' then equipped = lplr:GetAttribute('PlayingAsKit') or lplr:GetAttribute('PlayingAsKits') end
        local kit = string.lower(tostring(equipped or ''))
        local char = lplr.Character
        local function has(words)
            for _, word in words do if kit:find(word, 1, true) then return true end end
            return false
        end
        if KrystalKit.Enabled and has({'glacial_skater', 'ice_skater', 'glacier', 'krystal'}) then return KrystalSpeed.Value end
        local riding = lplr:GetAttribute('ElkKitMounted') or lplr:GetAttribute('SigridMounted')
            or (char and (char:GetAttribute('ElkKitMounted') or char:GetAttribute('SigridMounted') or char:FindFirstChild('ElkMount', true)))
        if SigridKit.Enabled and has({'elk_master', 'elk', 'rider', 'sigrid'}) and riding then return SigridSpeed.Value end
        local soul = char and (char:GetAttribute('GrimReaperChannel') or char:GetAttribute('SoulForm') or char:GetAttribute('GrimReaperGhost') or char:FindFirstChild('GrimReaperChannel', true))
        if GrimKit.Enabled and has({'grim_reaper', 'grim', 'soul'}) and soul then return GrimSpeed.Value end
        local stacks = tonumber(lplr:GetAttribute('WindWalkerStacks') or lplr:GetAttribute('WindWalkerStack') or lplr:GetAttribute('WindStacks')
            or (char and (char:GetAttribute('WindWalkerStacks') or char:GetAttribute('WindWalkerStack') or char:GetAttribute('WindStacks'))) or 0) or 0
        if ZephyrKit.Enabled and has({'wind_walker', 'zephyr', 'wind'}) and stacks >= 1 then return ZephyrSpeed.Value end
        return fallback
    end
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    Speed = vape.Categories.Blatant:CreateModule({
        Name = 'Speed',
        Function = function(callback)
            frictionTable.Speed = callback or nil
            updateVelocity()
            pcall(function()
                debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, callback and 'constantSpeedMultiplier' or 'moveSpeedMultiplier')
            end)

            if callback then
                Speed:Clean(runService.PreSimulation:Connect(function(dt)
                    bedwars.StatefulEntityKnockbackController.lastImpulseTime = callback and math.huge or time()
                    if entitylib.isAlive then
                        if not (Fly and Fly.Enabled) and not (LongJump and LongJump.Enabled) then
                            local movementSpeed = kitMovementSpeed(Value.Value)
                            bedwars.SprintController:setSpeed(Mode.Value == 'CFrame' and 20 or movementSpeed)
                            if Mode.Value == 'CFrame' then
                                local state = entitylib.character.Humanoid:GetState()
                                if state == Enum.HumanoidStateType.Climbing then return end

                                local root, velo = entitylib.character.RootPart, getSpeed()
                                local moveDirection = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
                                local destination = (moveDirection * math.max(movementSpeed - velo, 0) * dt)

                                if WallCheck.Enabled and destination.Magnitude > 1e-4 then
                                    rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
                                    rayCheck.CollisionGroup = root.CollisionGroup
                                    -- The probe has to reach past the BODY, not just past the step.
                                    -- The step itself is only what the CFrame push adds on top of
                                    -- normal movement - a few hundredths of a stud at 60fps - so a
                                    -- ray that length, cast from the middle of the root, ended
                                    -- inside the player and never saw the wall a stud in front of
                                    -- them. Nothing was ever subtracted, the push went straight
                                    -- into the block every frame, and pressed against a surface
                                    -- while falling that is exactly the clip through it.
                                    local skin = (math.max(root.Size.X, root.Size.Z) / 2) + 0.4
                                    local half = root.Size.Y / 2
                                    -- Two passes: the first takes out the component into whatever
                                    -- we are pressed against, the second catches the corner that
                                    -- the resulting slide runs into.
                                    for _ = 1, 2 do
                                        local step = destination.Magnitude
                                        if step <= 1e-4 then break end
                                        local probe = destination.Unit * (step + skin)
                                        local ray
                                        -- Waist, then shoulders, then shins: a block edge level
                                        -- with only one of them still counts as a wall.
                                        for _, height in {0, half * 0.8, -half * 0.8} do
                                            ray = workspace:Raycast(root.Position + Vector3.new(0, height, 0), probe, rayCheck)
                                            if ray then break end
                                        end
                                        if not ray then break end
                                        -- Drop the part of the step that goes into the wall and keep
                                        -- the rest, so pressing into a surface slides along it rather
                                        -- than through it.
                                        local into = destination:Dot(ray.Normal)
                                        if into >= 0 then break end
                                        destination -= ray.Normal * into
                                    end
                                end

                                root.CFrame += destination
								-- CFrame mode contributes only its missing horizontal speed. Do not
								-- replace physics velocity: doing so erased dao/kit impulses and made
								-- contact with a wall behave like a downward wall slide.
				local current = root.AssemblyLinearVelocity
				local requested = moveDirection * velo
				local currentHorizontal = Vector3.new(current.X, 0, current.Z)
				if currentHorizontal.Magnitude < requested.Magnitude then
									root.AssemblyLinearVelocity = Vector3.new(requested.X, current.Y, requested.Z)
								end
                                if AutoJump.Enabled and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and moveDirection ~= Vector3.zero and (Attacking or AlwaysJump.Enabled) then
                                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                                end
                            end
                        end
                    end
                end))
            else
                bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Increases your movement with various methods'
    })
    Mode = Speed:CreateDropdown({
        Name = 'Method',
        List = {'Bedwars', 'CFrame'},
        Default = 'CFrame'
    })
    Value = Speed:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    KrystalKit = Speed:CreateToggle({Name = 'Krystal', Function = function(callback) if KrystalSpeed and KrystalSpeed.Object then KrystalSpeed.Object.Visible = callback end end})
    KrystalSpeed = Speed:CreateSlider({Name = 'Krystal Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    SigridKit = Speed:CreateToggle({Name = 'Sigrid', Function = function(callback) if SigridSpeed and SigridSpeed.Object then SigridSpeed.Object.Visible = callback end end})
    SigridSpeed = Speed:CreateSlider({Name = 'Sigrid Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    GrimKit = Speed:CreateToggle({Name = 'Grim Reaper', Function = function(callback) if GrimSpeed and GrimSpeed.Object then GrimSpeed.Object.Visible = callback end end})
    GrimSpeed = Speed:CreateSlider({Name = 'Grim Reaper Speed', Min = 1, Max = 80, Default = 37, Suffix = ' studs/s', Darker = true, Visible = false})
    ZephyrKit = Speed:CreateToggle({Name = 'Zephyr', Function = function(callback) if ZephyrSpeed and ZephyrSpeed.Object then ZephyrSpeed.Object.Visible = callback end end})
    ZephyrSpeed = Speed:CreateSlider({Name = 'Zephyr Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    WallCheck = Speed:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    AutoJump = Speed:CreateToggle({
        Name = 'AutoJump',
        Function = function(callback)
            AlwaysJump.Object.Visible = callback
        end
    })
    AlwaysJump = Speed:CreateToggle({
        Name = 'Always Jump',
        Visible = false,
        Darker = true
    })
end)
-- END AETHER MODULE: blatant/Speed.lua --

-- BEGIN AETHER MODULE: blatant/Spider.lua --
run(function()
	local Spider
	local SpiderShift = false
    local Mode
    local Animation
    local Value
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local Active, Truss, Loaded

    local climbAnimation = Instance.new('Animation')
    climbAnimation.AnimationId = 'rbxassetid://11344417710'

    Spider = vape.Categories.Blatant:CreateModule({
	Name = 'Spider',
	Function = function(callback)
		if callback then
			if Truss then
				Truss.Parent = gameCamera
			end

			Spider:Clean(runService.PreSimulation:Connect(function(dt)
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					local chars = { gameCamera, lplr.Character, Truss }
					for _, v in entitylib.List do
						table.insert(chars, v.Character)
					end
					SpiderShift = inputService:IsKeyDown(Enum.KeyCode.LeftShift)
					rayCheck.FilterDescendantsInstances = chars
					rayCheck.CollisionGroup = root.CollisionGroup

                        local dir, stop = entitylib.character.Humanoid.MoveDirection, false
                        if dir.Magnitude <= 0 then
                            dir, stop = root.CFrame.LookVector, true
                        end
                        local vec = dir * 2.5
                        local ray = workspace:Raycast(
                            root.Position - Vector3.new(0, entitylib.character.HipHeight - 0.5, 0),
                            vec,
                            rayCheck
                        )
                        if Active then
                            if not Loaded and Animation.Enabled then
                                Loaded = entitylib.character.Humanoid:LoadAnimation(climbAnimation)
                                Loaded:Play()
                            end
                            if Loaded then
                                Loaded:AdjustSpeed((not stop) and 2 or 0)
                            end
                            -- Only cancel downward velocity while actively climbing (to stop
                            -- overshoot once we reach the top). When there is no movement input
                            -- (stop) we must NOT zero the Y velocity, otherwise the player just
                            -- hovers/slides down the wall very slowly while stuck in the falling
                            -- animation. Letting gravity through makes idle descent feel normal.
                            if not ray and not stop then
                                root.Velocity = Vector3.new(root.Velocity.X, 0, root.Velocity.Z)
                            end
                        end

                        Active = ray
                        if Active and ray.Normal.Y == 0 and not stop then
                            if not (vape.Modules.Phase and vape.Modules.Phase.Enabled) or not SpiderShift then
                                if Animation.Enabled then
                                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
                                end

                                root.Velocity *= Vector3.new(1, 0, 1)
                                if Mode.Value == 'CFrame' then
                                    root.CFrame += Vector3.new(0, Value.Value * dt, 0)
                                elseif Mode.Value == 'Impulse' then
                                    root:ApplyImpulse(Vector3.new(0, Value.Value, 0) * root.AssemblyMass)
                                else
                                    root.Velocity += Vector3.new(0, Value.Value, 0)
                                end
                            end
                        elseif not Active then
                            if Loaded then
                                Loaded:Stop()
                            end
                            Loaded = nil
                        end
                    else
                        if Loaded then
                            Loaded:Stop()
                        end
                        Loaded = nil
				end
			end))
		else
			if Truss then
				Truss.Parent = nil
			end
                if Loaded then
                    Loaded:Stop()
                end
                Loaded = nil
			SpiderShift = false
		end
	end,
	Tooltip = 'Lets you climb up walls. (Hold shift to use Phase over spider)',
    })
    Mode = Spider:CreateDropdown({
	Name = 'Mode',
	List = {'Velocity', 'Impulse', 'CFrame'},
	Function = function(val)
		Value.Object.Visible = val ~= 'Part'
            if Truss then
			Truss:Destroy()
			Truss = nil
		end
		if val == 'Part' then
			Truss = Instance.new('TrussPart')
			Truss.Size = Vector3.new(2, 2, 2)
			Truss.Transparency = 1
			Truss.Anchored = true
			Truss.Parent = Spider.Enabled and gameCamera or nil
		end
	end,
	Tooltip = 'Velocity - smooth boost up\nCFrame - moves you up\nPart - a climbable part in front of you',
    })
    Value = Spider:CreateSlider({
	Name = 'Speed',
	Min = 0,
	Max = 100,
	Default = 30,
	Darker = true,
	Suffix = function(val)
		return val == 1 and 'stud' or 'studs'
	end,
    })
    Animation = Spider:CreateToggle({
        Name = 'Use bedwars climbing',
        Tooltip = 'Makes you look like you are climbing with a kit (e.g. Yamini)'
    })
end)
-- END AETHER MODULE: blatant/Spider.lua --

-- BEGIN AETHER MODULE: blatant/TPAura.lua --
run(function()
    local TPAura
    local Targets
    local Range
    local TeleportRange
    local Delay
    local DodgeAttacks
    local Mode
    local HoldTime
    local SwitchAfter
    local StructureCheck
    local rand = Random.new()
    local overlapParams = OverlapParams.new()
    overlapParams.FilterType = Enum.RaycastFilterType.Exclude

    local function isValidTarget(ent)
        return ent and ent.RootPart and ent.RootPart.Parent and ent.RootPart.AssemblyLinearVelocity.Y > -35
    end

    local function isClearPosition(position, targetPosition)
        local path = position - targetPosition
        if path.Magnitude > 0.1 and workspace:Raycast(targetPosition + Vector3.new(0, 2.5, 0), path.Unit * math.max(path.Magnitude - 1.5, 0), store.blockRaycast) then return false end
        if workspace:Raycast(position, Vector3.new(0, entitylib.character.HipHeight + 3, 0), store.blockRaycast) then return false end

        overlapParams.FilterDescendantsInstances = {lplr.Character, gameCamera}
        local boxSize = Vector3.new(3.2, entitylib.character.HipHeight + 4, 3.2)
        local boxCFrame = CFrame.new(position + Vector3.new(0, boxSize.Y / 2 - 1.5, 0))
        for _, part in workspace:GetPartBoundsInBox(boxCFrame, boxSize, overlapParams) do
            if part.CanCollide and part.Transparency < 0.95 and not part:IsDescendantOf(lplr.Character) then
                return false
            end
        end
        return true
    end

    local function getGroundPosition(raw, targetPosition)
        local ground = workspace:Raycast(raw + Vector3.new(0, 16, 0), Vector3.new(0, -36, 0), store.blockRaycast)
        if not ground or math.abs(ground.Position.Y - targetPosition.Y) > 5 then return end
        local position = Vector3.new(raw.X, ground.Position.Y + entitylib.character.HipHeight + 2.5, raw.Z)
        -- Structure Check: reject spots that sit under a roof/bridge (something solid
        -- within ~12 studs overhead) so we never teleport into an enclosed pocket.
        if StructureCheck and StructureCheck.Enabled then
            if workspace:Raycast(position + Vector3.new(0, entitylib.character.HipHeight + 1, 0), Vector3.new(0, 12, 0), store.blockRaycast) then
                return
            end
        end
        return isClearPosition(position, targetPosition) and position or nil
    end

    -- Runtime state for target locking / switching.
    local lockedTarget, lockedUntil, lastSwitch, switchIndex = nil, 0, 0, 0

    -- Scanning: every targetable enemy inside Target Range, nearest first. Reuses
    -- entitylib.AllPosition so team filtering, vulnerability and the Walls line-of-sight
    -- option behave exactly like the rest of the combat modules.
    local function scanTargets(origin)
        return entitylib.AllPosition({
            Origin = origin,
            Range = Range.Value,
            Players = Targets.Players.Enabled,
            NPCs = Targets.NPCs.Enabled,
            Wallcheck = Targets.Walls.Enabled or nil,
            Part = 'RootPart',
            Sort = sortmethods.Distance
        })
    end

    -- Teleport placement: prefer the spot behind the target (Dodge attacks), otherwise
    -- sweep a ring around them for the first clear, ground-backed, unobstructed slot.
    local function findTeleportPosition(ent)
        local root = ent.RootPart
        local targetPosition = root.Position
        local radius = TeleportRange.Value
        local position
        if DodgeAttacks.Enabled then
            position = getGroundPosition(targetPosition - (root.CFrame.LookVector * radius), targetPosition)
        end
        for i = 1, 16 do
            if position then break end
            local angle = ((i / 16) * math.pi * 2) + rand:NextNumber(-0.15, 0.15)
            local distance = rand:NextNumber(math.max(2.5, radius - 1.5), radius)
            position = getGroundPosition(targetPosition + Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance), targetPosition)
        end
        return position, targetPosition
    end

    TPAura = vape.Categories.Blatant:CreateModule({
        Name = 'TPAura',
        Function = function(callback)
            if callback then
                lockedTarget, lockedUntil, lastSwitch, switchIndex = nil, 0, 0, 0
                local homePosition
                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        -- Anchor the target search and every range gate to a stable
                        -- "home" position instead of the live root. The old code measured
                        -- range from wherever the last teleport left you (right on top of
                        -- an enemy), so each teleport quietly stretched the effective reach
                        -- far past the Target Range you set and let TP Aura chain across the
                        -- map. Home freezes while a valid target is being engaged and only
                        -- re-samples to your real position once you have nothing to fight.
                        local engaging = lockedTarget and isValidTarget(lockedTarget)
                            and (lockedTarget.RootPart.Position - (homePosition or root.Position)).Magnitude <= Range.Value
                        if not engaging or not homePosition then
                            homePosition = root.Position
                        end
                        local origin = homePosition
                        local targets = scanTargets(origin)
                        local target

                        if Mode.Value == 'Switch' then
                            -- Rotate to the next target every Switch Delay seconds, or
                            -- immediately if the current one died / left range.
                            local stillValid = lockedTarget and isValidTarget(lockedTarget) and (lockedTarget.RootPart.Position - origin).Magnitude <= Range.Value
                            if not stillValid or (tick() - lastSwitch) >= SwitchAfter.Value then
                                if #targets > 0 then
                                    switchIndex = (switchIndex % #targets) + 1
                                    target = targets[switchIndex]
                                    lockedTarget, lastSwitch = target, tick()
                                end
                            else
                                target = lockedTarget
                            end
                        else
                            -- Single: stick with one target until Hold Time elapses or it
                            -- becomes invalid, then re-acquire the nearest.
                            local stillValid = lockedTarget and isValidTarget(lockedTarget) and (lockedTarget.RootPart.Position - origin).Magnitude <= Range.Value
                            if stillValid and tick() < lockedUntil then
                                target = lockedTarget
                            else
                                target = targets[1]
                                lockedTarget = target
                                lockedUntil = tick() + HoldTime.Value
                            end
                        end

                        if target and isValidTarget(target) then
                            local targetRoot = target.RootPart
                            -- Only teleport when actually out of reach, or (with Dodge
                            -- attacks) when we are no longer behind the target. Skipping the
                            -- teleport while already in position removes the constant
                            -- micro-teleport jitter around a target.
                            local flat = (root.Position - targetRoot.Position) * Vector3.new(1, 0, 1)
                            local distance = (targetRoot.Position - root.Position).Magnitude
                            local behindOk = true
                            if DodgeAttacks.Enabled and flat.Magnitude > 0.5 then
                                behindOk = targetRoot.CFrame.LookVector:Dot(flat.Unit) > 0.15
                            end
                            if distance > TeleportRange.Value + 1.5 or not behindOk then
                                local position, targetPosition = findTeleportPosition(target)
                                if position then
                                    -- Face the target on a level plane so we don't tilt.
                                    root.CFrame = CFrame.lookAt(position, Vector3.new(targetPosition.X, position.Y, targetPosition.Z))
                                    root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                                end
                            end
                        end
                    end
                    task.wait(Delay.Value)
                until not TPAura.Enabled
            else
                lockedTarget = nil
            end
        end,
        Tooltip = 'Teleports around targets and faces them. Single locks one, Switch rotates between them'
    })
    Targets = TPAura:CreateTargets({Players = true, NPCs = true})
    Mode = TPAura:CreateDropdown({Name = 'Mode', List = {'Single', 'Switch'}, Default = 'Single'})
    Range = TPAura:CreateSlider({Name = 'Target Range', Min = 6, Max = 40, Default = 22, Suffix = 'studs'})
    TeleportRange = TPAura:CreateSlider({Name = 'Teleport Range', Min = 3, Max = 10, Default = 6, Decimal = 10, Suffix = 'studs'})
    Delay = TPAura:CreateSlider({Name = 'Teleport Delay', Min = 0.15, Max = 1, Default = 0.35, Decimal = 100, Suffix = 'seconds'})
    HoldTime = TPAura:CreateSlider({Name = 'Single Hold Time', Min = 0.5, Max = 8, Default = 3, Decimal = 10, Suffix = 'seconds'})
    SwitchAfter = TPAura:CreateSlider({Name = 'Switch Delay', Min = 0.35, Max = 4, Default = 1.25, Decimal = 100, Suffix = 'seconds'})
    StructureCheck = TPAura:CreateToggle({Name = 'Structure Check', Tooltip = 'Rejects teleport spots on roofs, bridges, or tall structures above the target', Default = true})
    DodgeAttacks = TPAura:CreateToggle({
        Name = 'Dodge attacks',
        Tooltip = 'Prioritizes teleporting behind where targets are facing'
    })
end)
-- END AETHER MODULE: blatant/TPAura.lua --

-- BEGIN AETHER MODULE: combat/AimAssist.lua --
run(function()
    local AimAssist
    local AimMode
    local Mode
    local Targets
    local Sort
    local AimPart
    local AimSpeed
    local Shake
    local Distance
    local AngleSlider
    local StrafeIncrease
    local BlockBreak
    local KillauraTarget
    local ClickAim
    local Mouse
    local Limit

    local function ease(t)
	return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local cache = {}
    local function getMousePosition()
	if inputService.TouchEnabled then
		return gameCamera.ViewportSize / 2
	end
	return inputService.GetMouseLocation(inputService)
    end

    local function getAim(ent)
	if AimPart.Value == 'Closest' then
		if not cache[ent.Character] then
			cache[ent.Character] = ent.Character:GetChildren()
		end
		local localPosition, magnitude, part = getMousePosition(), 9e9, nil
		for _, v in cache[ent.Character] do
			if v and v.Parent and v:IsA('BasePart') then
				local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)

				if vis then
					local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude

					if mag < magnitude then
						magnitude = mag
						part = v
					end
				end
			end
		end
		if part then
			return part.Position
		end
	end
	return ent.RootPart.Position
    end

    local started, lasttarget = 0, nil
    local aimfuncs = {
	Simple = function(localcframe, ent, fps)
		local rng = Random.new()
		local speed = (AimSpeed.Value + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 0))

		return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
	end,
	Adaptive = function(localcframe, ent, fps)
		local prog, rng = ease(math.min(tick() - started, 1)), Random.new()
		local speed = (AimSpeed.Value * 0.1 * prog) + (1 - prog) + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 5)
		return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
	end
    }

    local function GetTarget()
	if lasttarget then
		local localPosition = entitylib.character.RootPart.Position
		if not lasttarget or not lasttarget.RootPart or not lasttarget.Humanoid or not lasttarget.Humanoid.Health or lasttarget.Humanoid.Health <= 0 then
			return false
		end
		if (localPosition - lasttarget.RootPart.Position).Magnitude > Distance.Value then
			return false
		end
		if Targets.Walls.Enabled and entitylib.Wallcheck(localPosition, lasttarget.RootPart.Position, Targets.Walls.Enabled) then
			return false
		end
		return lasttarget
	end

	return false
    end

    local function getAttackData()
	if Mouse.Enabled and not inputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.15 then
		return false
	end
	if ClickAim.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3 then
		return false
	end
	if BlockBreak.Enabled and (tick() - store.lastHit) < 0.3 then
		return false
	end
	if Limit.Enabled and store.hand.toolType ~= 'sword' then
		return false
	end

	if (tick() - started) > 1 or not lasttarget or not lasttarget.Parent or not lasttarget.Humanoid or lasttarget.Humanoid.Health <= 0 then
		local ent = GetTarget() or KillauraTarget.Enabled and store.KillauraTarget or entitylib.EntityPosition({
			Range = Distance.Value,
			Part = 'RootPart',
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value],
		})
		if ent then
			started = tick()
		end
		lasttarget = ent
	end
	return lasttarget
    end

    AimAssist = vape.Categories.Combat:CreateModule({
	Name = 'AimAssist',
	Function = function(callback)
		if callback then
			local rotate = 0

			AimAssist:Clean(runService.PostSimulation:Connect(function(dt)
				if entitylib.isAlive then
					entitylib.character.Humanoid.AutoRotate = tick() > rotate

					local ent = getAttackData()
					if ent then
						local root = entitylib.character.RootPart
						local delta = (ent.RootPart.Position - root.Position)
						local localfacing = root.CFrame.LookVector * Vector3.new(1, 0, 1)
						local angle = math.acos(localfacing:Dot((delta * Vector3.new(1, 0, 1)).Unit))
						if angle >= (math.rad(AngleSlider.Value) / 2) then
							return
						end
						targetinfo.Targets[ent] = tick() + 1

						local cframe, speed = aimfuncs[Mode.Value](gameCamera.CFrame, ent, dt)
						if AimMode.Value == 'First person' or AimMode.Value == 'Dynamic' and entitylib.character.Head.LocalTransparencyModifier == 1 then
							gameCamera.CFrame = cframe
						elseif AimMode.Value == 'Third person' or AimMode.Value == 'Dynamic' and entitylib.character.Head.LocalTransparencyModifier ~= 1 then
							cframe, speed = aimfuncs[Mode.Value](root.CFrame, ent, dt)
							entitylib.character.Humanoid.AutoRotate = false
							root.CFrame = CFrame.lookAlong(root.Position, cframe.LookVector * Vector3.new(1, 0, 1))
							rotate = tick() + 0.1
						elseif AimMode.Value == 'Mouse' then
							local viewport = gameCamera:WorldToViewportPoint(cframe.Position)
							local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * (speed / 15)
							mousemoverel(pos.X, pos.Y)
						end
					end
				end
			end))
		end
	end,
	Tooltip = 'Smoothly aims to closest valid target with sword'
    })
    Targets = AimAssist:CreateTargets({
	Players = true,
	Walls = true,
    })
    local modes = {}
    for i in aimfuncs do
	table.insert(modes, i)
    end
    AimMode = AimAssist:CreateDropdown({
	Name = 'Aim perspective',
	Tooltip = 'First person - camera\nThird person - turns your character\nMouse - moves your mouse\nDynamic - whichever you are in',
	List = {'First person', 'Third person', 'Mouse', 'Dynamic'},
	Default = 'First person'
    })
    Mode = AimAssist:CreateDropdown({
	Name = 'Mode',
	List = modes,
	Tooltip = 'Simple - Smooth aiming\nAdaptive - Advanced tracking with adaptive behavior',
	Default = modes[1],
    })
    local methods = {'Damage', 'Distance'}
    for _, i in sortlist do
	if not table.find(methods, i) then
		table.insert(methods, i)
	end
    end
    ClickAim = AimAssist:CreateToggle({
	Name = 'Click aim',
	Default = true,
    })
    Mouse = AimAssist:CreateToggle({Name = 'Require mouse down'})
    StrafeIncrease = AimAssist:CreateToggle({Name = 'Strafe increase'})
    BlockBreak = AimAssist:CreateToggle({Name = 'Check block break'})
    KillauraTarget = AimAssist:CreateToggle({Name = 'Use killaura target'})
    AimSpeed = AimAssist:CreateSlider({
	Name = 'Aim speed',
	Min = 1,
	Max = 20,
	Default = 6,
    })
    Distance = AimAssist:CreateSlider({
	Name = 'Distance',
	Min = 1,
	Max = 30,
	Default = 30,
	Suffix = function(val)
		return val == 1 and 'stud' or 'studs'
	end,
    })
    Shake = AimAssist:CreateSlider({
	Name = 'Shake',
	Min = 0,
	Max = 100,
	Default = 0,
	Tooltip = 'Adds random jitter to simulate human aim',
    })
    AngleSlider = AimAssist:CreateSlider({
	Name = 'Max angle',
	Min = 1,
	Max = 360,
	Default = 70,
    })
    Limit = AimAssist:CreateToggle({
	Name = 'Limit to items',
	Tooltip = 'Only attacks when sword is held',
    })
    Sort = AimAssist:CreateDropdown({
	Name = 'Target mode',
	List = methods,
	Default = 'Angle',
    })
    AimPart = AimAssist:CreateDropdown({
	Name = 'Target area',
	List = {'Center', 'Closest'},
	Default = 'Center',
    })
end)
-- END AETHER MODULE: combat/AimAssist.lua --

-- BEGIN AETHER MODULE: combat/AutoClicker.lua --
run(function()
	local AutoClicker
	local CPS
	local BlockCPS = {}
	local Attacks
	local Blocks
	local Wool
	local Thread
	local heldInputs = {}
	local bridgeInputs = {}

	local function stopInput(source)
		heldInputs[source] = nil
		bridgeInputs[source] = nil
		if not next(heldInputs) and Thread then
			task.cancel(Thread)
			Thread = nil
		end
	end

	local function AutoClick(source, autoBridge)
		heldInputs[source] = true
		bridgeInputs[source] = autoBridge or nil
		if Thread then
			return
		end

		Thread = task.delay(1 / (store.hand.toolType == 'block' and BlockCPS or CPS).GetRandomValue(), function()
			repeat
				if not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
					local blockPlacer = bedwars.BlockPlacementController.blockPlacer
					if store.hand.toolType == 'block' and Blocks.Enabled and (not Wool.Enabled or store.hand.tool.Name:find('wool_')) and blockPlacer then
						if (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= ((1 / 12) * 0.5) then
							if next(bridgeInputs) and blockPlacer.autoBridge then
								blockPlacer:autoBridge(workspace:GetServerTimeNow() - bedwars.KnockbackController:getLastKnockbackTime() >= 0.2)
							else
								local mouseinfo = blockPlacer.clientManager:getBlockSelector():getMouseInfo(0)
								if mouseinfo and mouseinfo.placementPosition == mouseinfo.placementPosition then
									task.spawn(blockPlacer.placeBlock, blockPlacer, mouseinfo.placementPosition)
								end
							end
						end
					elseif store.hand.toolType == 'sword' and Attacks.Enabled then
						bedwars.SwordController:swingSwordAtMouse()
					end
				end

				task.wait(1 / (store.hand.toolType == 'block' and BlockCPS or CPS).GetRandomValue())
			until not AutoClicker.Enabled or not next(heldInputs)
			Thread = nil
		end)
	end

	AutoClicker = vape.Categories.Combat:CreateModule({
		Name = 'AutoClicker',
		Function = function(callback)
			if callback then
				AutoClicker:Clean(inputService.InputBegan:Connect(function(input, processed)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						AutoClick(input, false)
					elseif input.UserInputType == Enum.UserInputType.Touch then
						-- World touches use the selector's suggested placement exactly like desktop.
						-- Gui buttons are handled below so camera/menu touches cannot start clicking.
						local overButton = false
						for _, object in guiService:GetGuiObjectsAtPosition(input.Position.X, input.Position.Y) do
							if object:IsA('GuiButton') then overButton = true; break end
						end
						if not processed and not overButton then AutoClick(input, false) end
					end
				end))

				AutoClicker:Clean(inputService.InputEnded:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						stopInput(input)
					end
				end))

				if inputService.TouchEnabled then
					local hooked = {}
					local function hookButton(button)
						if hooked[button] or not button:IsA('GuiButton') then return end
						local name = button.Name:lower()
						local label = button:IsA('TextButton') and button.Text:lower() or ''
						local relevant = tonumber(button.Name) ~= nil or name:find('attack', 1, true) or name:find('place', 1, true)
							or name:find('build', 1, true) or name:find('block', 1, true) or label:find('build', 1, true)
						if not relevant then return end
						hooked[button] = true
						local autoBridge = tonumber(button.Name) ~= nil or name:find('build', 1, true) ~= nil
							or name:find('bridge', 1, true) ~= nil or label:find('build', 1, true) ~= nil
						AutoClicker:Clean(button.MouseButton1Down:Connect(function() AutoClick(button, autoBridge) end))
						AutoClicker:Clean(button.MouseButton1Up:Connect(function()
							stopInput(button)
						end))
						AutoClicker:Clean(button.InputEnded:Connect(function(input)
							if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then stopInput(button) end
						end))
						AutoClicker:Clean(button.AncestryChanged:Connect(function(_, parent)
							if not parent then stopInput(button) end
						end))
					end
					task.spawn(function()
						local mobileUI = lplr.PlayerGui:WaitForChild('MobileUI', 20)
						if not mobileUI or not AutoClicker.Enabled then return end
						for _, button in mobileUI:GetDescendants() do hookButton(button) end
						AutoClicker:Clean(mobileUI.DescendantAdded:Connect(hookButton))
					end)
				end
			else
				table.clear(heldInputs)
				table.clear(bridgeInputs)
				if Thread then
					task.cancel(Thread)
					Thread = nil
				end
			end
		end,
		Tooltip = 'Hold attack button to automatically click'
	})
	Attacks = AutoClicker:CreateToggle({
		Name = 'Attack',
		Default = true,
		Function = function(callback)
			if CPS and CPS.Object then
				CPS.Object.Visible = callback
			end
		end,
		Tooltip = 'Automatically attacks while the mouse button is held'
	})
	CPS = AutoClicker:CreateTwoSlider({
		Name = 'CPS',
		Min = 1,
		Max = 9,
		DefaultMin = 7,
		DefaultMax = 7
	})
	Blocks = AutoClicker:CreateToggle({
		Name = 'Place Blocks',
		Default = true,
		Function = function(callback)
			if BlockCPS.Object then
				BlockCPS.Object.Visible = callback
			end
			if Wool and Wool.Object then Wool.Object.Visible = callback end
		end
	})
	Wool = AutoClicker:CreateToggle({Name = 'Wool only', Tooltip = 'Only places while wool is held.', Darker = true})
	BlockCPS = AutoClicker:CreateTwoSlider({
		Name = 'Block CPS',
		Min = 1,
		Max = 12,
		DefaultMin = 12,
		DefaultMax = 12,
		Darker = true
	})
end)
-- END AETHER MODULE: combat/AutoClicker.lua --

-- BEGIN AETHER MODULE: combat/BowAssist.lua --
run(function()
    local BowAssist
    local Targets
    local Sort
    local Shake
    local Speed
    local Angle
    local FOV
    local AimPart
    local Distance
    local Smoothness
    local Clear
    local Blacklist
    local Mouse
    local ThirdPerson
    local Projectiles
    local aimRandom = Random.new()

    local function ease(t)
	return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local function findAim(localcframe, predicted, fps, started, offset)
	local prog, rng = ease(math.min((tick() - started) / (1 / (Speed.Value * 0.5)), 1)), aimRandom
	local speed = (Speed.Value / Smoothness.Value) * prog

	return localcframe:Lerp(CFrame.lookAt(localcframe.p, predicted + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, offset + ((rng:NextNumber() - 0.5) * Shake.Value * fps), (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
    end

    local launchHook
    local lasttarget, started = nil, 0
    local function getAttackData()
	if not entitylib.isAlive then
		return false
	end
	if Mouse.Enabled and not inputService:IsMouseButtonPressed(0) then
		return false
	end
	if not store.hand.tool or not bedwars.ItemMeta[store.hand.tool.Name].projectileSource and store.hand.toolType ~= 'bow' then
		return false
	end
	if Blacklist.Enabled and table.find(Projectiles.ListEnabled, store.hand.tool.Name == 'glue_trap' and 'gloop' or store.hand.tool.Name) then
		return false
	end

	if (tick() - started) > 1 or not lasttarget or not lasttarget.Parent or not lasttarget.Humanoid or lasttarget.Humanoid.Health <= 0 then
		local ent = entitylib.EntityMouse({
			Origin = entitylib.character.RootPart.Position,
			Range = FOV.Value,
			Part = AimPart.Value,
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value],
		})
		if ent and (ent.RootPart.Position - entitylib.character.RootPart.Position).Magnitude > Distance.Value then ent = nil end
		if ent then
			started = tick()
		end
		lasttarget = ent
	end
	return lasttarget
    end

    local rayCheck = RaycastParams.new()

    BowAssist = vape.Categories.Combat:CreateModule({
	Name = 'BowAssist',
	Function = function(callback)
		if callback then
			local multi, predicted = 0, nil
			local lastpredicted = 0
			local lastent, found, update = nil, 0, 0

			launchHook = bedwars.ProjectileLaunchHook:Add('BowAssist', 10, function(nextLaunch, ...)
				local res = nextLaunch(...)
				local projmeta = select(2, ...)
				multi = projmeta and (projmeta.velocityMultiplier + 2) or 0
				if projmeta and tick() - update < 0.1 and lastent and lastent.RootPart then
					local meta = projmeta:getProjectileMeta()
					local gravity = (meta.gravitationalAcceleration or 196.2) * projmeta.gravityMultiplier
					local calc = prediction.SolveTrajectory(entitylib.character.RootPart.Position, (meta.launchVelocity or 100) * (1 - lplr:GetNetworkPing()), gravity, lastent.RootPart.Position, lastent.RootPart.Velocity, workspace.Gravity, entitylib.character.HipHeight, nil, rayCheck)
					predicted = calc
					lastpredicted = tick()
				else
					predicted = nil
				end
				return res
			end)

			BowAssist:Clean(runService.PostSimulation:Connect(function(dt)
				local ent = getAttackData()
				if ent then
					local delta = (ent.RootPart.Position - entitylib.character.RootPart.Position)
					local localfacing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
					local angle = math.acos(localfacing:Dot((delta * Vector3.new(1, 0, 1)).Unit))
					if angle >= (math.rad(Angle.Value) / 2) then
						return
					end
					if ent ~= lastent then
						found = tick()
					end
					lastent = ent
					update = tick()
					if tick() - lastpredicted < 0.1 then
						targetinfo.Targets[ent] = tick() + 1
						local aimPosition = predicted or ent[AimPart.Value].Position
						if Clear.Enabled then
							rayCheck.FilterDescendantsInstances = {lplr.Character, ent.Character, gameCamera}
							if workspace:Raycast(gameCamera.CFrame.Position, aimPosition - gameCamera.CFrame.Position, rayCheck) then return end
						end
						local cframe, speed = findAim(gameCamera.CFrame, aimPosition, dt, found, multi + ((entitylib.character.RootPart.Position.Y - ent.RootPart.Position.Y) / 7))
						if inputService.MouseEnabled and entitylib.character.Head.LocalTransparencyModifier == 1 then
							gameCamera.CFrame = cframe
						elseif ThirdPerson.Enabled and inputService.MouseEnabled then
							local viewport = gameCamera:WorldToViewportPoint(aimPosition)
							local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * (speed / 15)
							mousemoverel(pos.X, pos.Y)
						end
					end
				end
			end))
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
        Tooltip = 'Smoothly aims your projectile trajectory to the target'
    })

    Targets = BowAssist:CreateTargets({
	Players = true,
	Walls = true,
    })
    local methods = {'Damage', 'Distance'}
    for _, i in sortlist do
	if not table.find(methods, i) then
		table.insert(methods, i)
	end
    end
    Sort = BowAssist:CreateDropdown({
	Name = 'Target mode',
	List = methods,
	Default = 'Angle',
    })
    AimPart = BowAssist:CreateDropdown({Name = 'Part', List = {'RootPart', 'Head'}})
    Distance = BowAssist:CreateSlider({Name = 'Distance', Min = 1, Max = 300, Default = 200, Suffix = ' studs'})
    Speed = BowAssist:CreateSlider({
	Name = 'Aim speed',
	Min = 1,
	Max = 20,
	Default = 7,
	Suffix = 'sp/s',
	Tooltip = 'How fast you will aim per second',
    })
    Smoothness = BowAssist:CreateSlider({Name = 'Smoothness', Min = 1, Max = 20, Default = 2, Decimal = 10, Tooltip = 'Divides aim speed to soften camera movement.'})
    Angle = BowAssist:CreateSlider({
	Name = 'Max angle',
	Min = 1,
	Max = 360,
	Default = 120,
    })
    Shake = BowAssist:CreateSlider({
	Name = 'Shake',
	Min = 1,
	Max = 100,
	Default = 5,
	Tooltip = 'Jitters your screen, Simulating human aim',
    })
    FOV = BowAssist:CreateSlider({
	Name = 'FOV',
	Min = 1,
	Max = 1000,
	Default = 200,
    })
    Mouse = BowAssist:CreateToggle({
	Name = 'Require mouse down',
	Default = inputService.KeyboardEnabled,
    })
    ThirdPerson = BowAssist:CreateToggle({
	Name = 'Use mouse aim',
	Tooltip = 'Aims using the mouse if you are on third person',
	Default = true,
    })
    Blacklist = BowAssist:CreateToggle({
	Name = 'Use blacklist',
	Default = true,
	Function = function(callback)
		if Projectiles then
			Projectiles.Object.Visible = callback
		end
	end,
	Tooltip = 'Doesn\'t bow-assist if your holding one of the blacklisted projectiles',
    })
    Projectiles = BowAssist:CreateTextList({
	Name = 'Blacklisted',
	Default = { 'fireball', 'telepearl', 'gloop' },
	Darker = true,
    })
    Clear = BowAssist:CreateToggle({Name = 'Clear shot only', Default = true, Tooltip = 'Stops assisting when the aim path is obstructed.'})
end)
-- END AETHER MODULE: combat/BowAssist.lua --

-- BEGIN AETHER MODULE: combat/HitregAdjuster.lua --
if canDebug then
run(function()
	local HitregAdjuster, Hitreg
	local firstConnection, restoreConnection

	HitregAdjuster = vape.Categories.Combat:CreateModule({
		Name = 'HitregAdjuster',
		Function = function(enabled)
			if not enabled then return end
			local sync = bedwars.SyncEvents and bedwars.SyncEvents.SwordSwing
			if not sync then
				notif('HitregAdjuster', 'Sword swing events are unavailable.', 5, 'warning')
				HitregAdjuster:Toggle()
				return
			end
			local original
			firstConnection = sync:setPriority(150):connect(function(event)
				original = event.attackSpeed
				event.attackSpeed = 10 / math.max(Hitreg.Value - 1, 1)
			end)
			restoreConnection = sync:setPriority(300):connect(function(event)
				if original ~= nil then event.attackSpeed = original end
			end)
			HitregAdjuster:Clean(function()
				if firstConnection then firstConnection:Destroy(); firstConnection = nil end
				if restoreConnection then restoreConnection:Destroy(); restoreConnection = nil end
			end)
		end,
		Tooltip = 'Adjusts manual and AutoClicker sword swing spacing without changing Killaura timing.'
	})
	Hitreg = HitregAdjuster:CreateSlider({Name = 'Hitreg', Min = 1, Max = 36, Default = 35, Suffix = ' hits / 10s'})
end)
end
-- END AETHER MODULE: combat/HitregAdjuster.lua --

-- BEGIN AETHER MODULE: combat/NoClickDelay.lua --
run(function()
	local NoClickDelay
	local SwingLock
	local Drill
	local old, olddrill, oldlock
	
	NoClickDelay = vape.Categories.Combat:CreateModule({
		Name = 'NoClickDelay',
		Function = function(callback)
			if callback then
				old = bedwars.SwordController.isClickingTooFast
				bedwars.SwordController.isClickingTooFast = function(self)
					self.lastSwing = tick()
					return false
				end
	
				if SwingLock.Enabled then
					oldlock = bedwars.SwordController.getSwordSwingDisabled
					bedwars.SwordController.getSwordSwingDisabled = function()
						return false
					end
				end
	
				if Drill.Enabled then
					olddrill = bedwars.DrillTabletController.isClickingTooFast
					bedwars.DrillTabletController.isClickingTooFast = function()
						return false
					end
				end
			else
				bedwars.SwordController.isClickingTooFast = old
	
				if oldlock then
					bedwars.SwordController.getSwordSwingDisabled = oldlock
					oldlock = nil
				end
	
				if olddrill then
					bedwars.DrillTabletController.isClickingTooFast = olddrill
					olddrill = nil
				end
			end
		end,
		Tooltip = 'Removes the 9 clicks a second cap the client puts on swinging'
	})
	SwingLock = NoClickDelay:CreateToggle({
		Name = 'Swing lock',
		Function = function()
			if NoClickDelay.Enabled then
				NoClickDelay:Toggle()
				NoClickDelay:Toggle()
			end
		end,
		Tooltip = 'Also lets you swing while a kit ability has swinging turned off, like sigrid on her elk'
	})
	Drill = NoClickDelay:CreateToggle({
		Name = 'Drill',
		Function = function()
			if NoClickDelay.Enabled then
				NoClickDelay:Toggle()
				NoClickDelay:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Removes the same cap on the drill tablet'
	})
end)
-- END AETHER MODULE: combat/NoClickDelay.lua --

-- BEGIN AETHER MODULE: combat/Reach.lua --
run(function()
    if canDebug then




run(function()
	local BlockReach
		local BlockRange
		local BreakReach
		local BreakRange
		local SwordReach
		local SwordRange

		local old

		Reach = vape.Categories.Combat:CreateModule({
			Name = 'Reach',
			Tooltip = 'Allows you to place, attack, and break further',
			Function = function(callback)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4
				if callback then
					old = bedwars.BlockSelector.getMouseInfo
					bedwars.BlockSelector.getMouseInfo = function(...)
						local Self, Select, Args = ...
						if not Args then
							Args = {}
						end
						if Select == 0 then
							Args.range = BlockReach.Enabled and BlockRange.Value or 24
						elseif Select == 1 then
							Args.range = BreakReach.Enabled and BreakRange.Value or 18
						end
						return old(Self, Select, Args)
					end
				else
					bedwars.BlockSelector.getMouseInfo = old
					old = nil
				end
			end,
		})
		SwordReach = Reach:CreateToggle({
			Name = 'Sword Reach',
			Default = true,
			Function = function(callback)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and callback and SwordRange.Value + 2 or 14.4
				pcall(function()
					SwordRange.Object.Visible = callback
				end)
			end,
