run(function()
    local AutoBank
    local Whitelist
    local DisplayResources
    local Mode
    local ChestRange
    local Withdraw
    local BeforeDeath
    local HPThreshold
    local BeforeDeathWhitelist
    local UI

    -- Drops we made and are currently holding out of the world.
    local droppedItems = {}
    -- itemType -> when we may next try to drop it. A stack the server refuses would otherwise
    -- be re-dropped ten times a second for the rest of the match.
    local dropCooldowns = {}
    -- Tools with an in-flight DropItem request and drops with an in-flight pickup request.
    -- The main loop runs faster than either remote can respond, so these guards prevent the
    -- same stack being banked or restored more than once.
    local pendingDrops = {}
    local pendingReclaims = {}
    -- Drops being returned must no longer be held at BANK_ORIGIN. Without a separate release
    -- state, PreRender moved them back into the sky on the very next frame, racing the pickup
    -- remote and making retrieval depend on lucky timing.
    local releasingDrops = {}
    local displayEntries = {}
    -- A danger state is one trip below the configured health threshold.  It is deliberately
    -- separate from the normal banking loop: a low-health player can remain in danger for a
    -- while and must not re-send ChestGiveItem requests every update.
    local dangerTriggered = false
    local dangerCharacter
    local beforeDeathDepositing = false
    local chestDepositBusy = false
	local dangerConnections = {}
	local evaluateDanger

    -- Keep the stash inside the local character's simulation radius. Parking drops at a fixed
    -- Y=100000 eventually hands their network ownership back to the server; after that, changing
    -- CFrame only moves the client's copy and PickupItem rejects it as still being out of range.
    -- Following the player a few hundred studs overhead remains unreachable while preserving the
    -- ownership needed to bring the server-authoritative drop back down later.
    local BANK_HEIGHT = 120
    local BANK_SPACING = 4
    local BANK_COLUMNS = 8

    local function untrackDrop(drop)
        releasingDrops[drop] = nil
        pendingReclaims[drop] = nil
        local index = table.find(droppedItems, drop)
        if index then
            table.remove(droppedItems, index)
        end
    end

    -- Bring one drop back to the head and ask for it. PickupItem only transfers one item from a
    -- stacked drop per request, so keep requesting until the server removes the emptied drop.
    local function reclaim(drop)
        if not drop or not drop.Parent then
            untrackDrop(drop)
            return
        end
        if not entitylib.isAlive then return end

        releasingDrops[drop] = true
        -- Keep moving the drop to the player even while a previous pickup request is pending.
        -- This matters during disable cleanup, when the PreRender skybox holder is disconnected.
        drop.Velocity = Vector3.zero
        drop.CFrame = entitylib.character.Head.CFrame
        if pendingReclaims[drop] then return end
        pendingReclaims[drop] = true

		local ok = pcall(function()
			-- Use the same stable handler path as cv.  The generated Client remote
			-- changes shape between BedWars builds, which made reclaim silently stop.
			bedwars.Handler:Get('PickupItemDrop'):Fire('CallServerAsync', {itemDrop = drop}):andThen(function(success)
                pendingReclaims[drop] = nil
                if not drop.Parent then
                    untrackDrop(drop)
                elseif AutoBank.Enabled then
                    -- A false response can simply mean the server has not observed the move
                    -- from the sky yet. Keep the drop at the player and retry; stacked drops
                    -- also require more than one successful pickup request.
                    task.delay(success and 0.03 or 0.1, reclaim, drop)
                end
            end, function()
                pendingReclaims[drop] = nil
                if AutoBank.Enabled and drop.Parent then
                    task.delay(0.1, reclaim, drop)
                end
            end)
        end)
        if not ok then
            pendingReclaims[drop] = nil
            if AutoBank.Enabled and drop.Parent then
                task.delay(0.1, reclaim, drop)
            end
        end
    end

    -- True while standing at a shop NPC, which is the cue to hand the stash back.
    local function atShop()
        if not entitylib.isAlive then return false end
        local opened = false
        pcall(function()
            opened = bedwars.AppController:isAppOpen('BedwarsItemShopApp') or bedwars.AppController:isAppOpen('TeamUpgradeApp')
        end)
        if opened then return true end
        local position = entitylib.character.RootPart.Position
        for _, npc in store.shop do
            local root = npc.RootPart
            if root and root.Parent and (root.Position - position).Magnitude <= 30 then
                return true
            end
        end
        return false
    end

    ------------------------------------------------------------------------------------------
    -- Chest mode
    ------------------------------------------------------------------------------------------

    local function inventoryRemotes()
        return bedwars.Client:GetNamespace('Inventory')
    end

    -- The folder our banked items actually live in. This is always the deposit target, whichever
    -- world object we happen to be stood at - so being next to somebody else's chest can never
    -- put our resources into theirs.
    local function ownPersonalFolder()
        local inventories = replicatedStorage:FindFirstChild('Inventories')
        return inventories and inventories:FindFirstChild(lplr.Name .. '_personal') or nil
    end

    local function chestPart(chest)
        return chest:IsA('Model') and chest.PrimaryPart or (chest:IsA('BasePart') and chest) or nil
    end

    -- Are we close enough to a personal chest for a deposit to look like one? The chest is only
    -- the proximity gate here, not the destination, which is what keeps this honest: no remote
    -- goes out until we are genuinely stood at one, exactly as a player has to be.
    local function atPersonalChest()
        if not entitylib.isAlive then return false end
        local opened = false
        pcall(function()
            opened = bedwars.AppController:isAppOpen('ChestApp')
        end)
        if opened then return true end
        local position = entitylib.character.RootPart.Position
        for _, chest in collectionService:GetTagged('personal-chest') do
            local part = chestPart(chest)
            if part and part.Parent and (part.Position - position).Magnitude <= ChestRange.Value then
                return true
            end
        end
        return false
    end

    -- What is sitting in the chest, by item type, for the hotbar display.
    local function chestTotals(folder)
        local totals = {}
        if not folder then return totals end
        for _, entry in folder:GetChildren() do
            totals[entry.Name] = (totals[entry.Name] or 0) + (entry:GetAttribute('Amount') or 1)
        end
        return totals
    end

    -- Put the whitelisted stacks in. SetObservedChest is what the client sends when the chest UI
    -- opens and what the server checks the deposit against, so it brackets the deposits rather
    -- than being sent per item.
    local function depositToChest(folder, allowedItems)
        if chestDepositBusy then return false end
        allowedItems = allowedItems or Whitelist.ListEnabled
        local wanted = {}
        for _, item in store.inventory.inventory.items do
            local name = item.itemType or (item.tool and item.tool.Name)
            if name and item.tool and table.find(allowedItems, name) and (dropCooldowns[name] or 0) < os.clock() then
                table.insert(wanted, {Name = name, Tool = item.tool})
            end
        end
        if #wanted == 0 then return false end

        chestDepositBusy = true
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(folder)
        end)
        for _, entry in wanted do
            if not AutoBank.Enabled then break end
            local ok, given = pcall(function()
                return inventoryRemotes():Get('ChestGiveItem'):CallServer(folder, entry.Tool)
            end)
            if not ok or not given then
                -- Refused - a full chest, or a stack the server will not take. Back off rather
                -- than asking again ten times a second for the rest of the match.
                dropCooldowns[entry.Name] = os.clock() + 5
            end
        end
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(nil)
        end)
        chestDepositBusy = false
        return true
    end

    local function currentHealthPercent()
        local character = lplr.Character
        if not character then return nil end
        -- BedWars keeps the authoritative health values as character attributes. Fall back to
        -- Humanoid values for transitions while those attributes are being recreated on respawn.
        local health = character:GetAttribute('Health')
        local maximum = character:GetAttribute('MaxHealth')
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if type(health) ~= 'number' then health = humanoid and humanoid.Health end
        if type(maximum) ~= 'number' or maximum <= 0 then maximum = humanoid and humanoid.MaxHealth end
        if type(health) ~= 'number' or type(maximum) ~= 'number' or maximum <= 0 then return nil end
        return math.clamp((health / maximum) * 100, 0, 100)
    end

	local function queueEmergencyDrop(item, token, bankPosition, bankCharacter)
		local name, tool = item and (item.itemType or (item.tool and item.tool.Name)), item and item.tool
		if not name or not tool or pendingDrops[tool] or (dropCooldowns[name] or 0) >= os.clock() then return false end
		pendingDrops[tool] = true
		local amount = item.amount
		-- Do not task.cancel a coroutine blocked inside the remote call: the server may already
		-- have dropped the stack. The generation check owns the late reply and immediately
		-- reclaims it after a disable/respawn instead of abandoning it in the world.
		task.spawn(function()
			local ok, drop = pcall(function()
				local handler = bedwars.Handler and bedwars.Handler:Get('DropItem')
				if not handler then error('DropItem remote unavailable') end
				return handler:Fire('CallServer', {item = tool, amount = amount})
			end)
			pendingDrops[tool] = nil
			if not ok or not drop or not drop.Parent then
				dropCooldowns[name] = os.clock() + 1
				return
			end
			if not table.find(droppedItems, drop) then
				table.insert(droppedItems, drop)
				drop:ClearAllChildren()
				drop.AncestryChanged:Once(function() untrackDrop(drop) end)
			end
			if typeof(bankPosition) == 'Vector3' and drop.Parent then
				pcall(function()
					drop.Velocity = Vector3.zero
					drop.CFrame = CFrame.new(bankPosition + Vector3.new(0, BANK_HEIGHT, 0))
				end)
			end
			if not AutoBank.Enabled or AutoBank.Generation ~= token or lplr.Character ~= bankCharacter then reclaim(drop) end
		end)
		return true
	end

    local function bankBeforeDeath()
        if beforeDeathDepositing or not AutoBank.Enabled or not BeforeDeath.Enabled then return end
        beforeDeathDepositing = true
		local token = AutoBank.Generation
		local bankCharacter = lplr.Character
		local character = entitylib.character
		local root = character and character.RootPart
		local bankPosition = root and root.Position
		local deposited = false
		if Mode.Value == 'Chest' and not chestDepositBusy then
			local folder = entitylib.isAlive and ownPersonalFolder() or nil
			if folder and atPersonalChest() then
				deposited = depositToChest(folder, BeforeDeathWhitelist.ListEnabled)
			end
		end
		-- A lethal hit does not leave time to walk to a chest. If the legit chest path is not
		-- available, immediately use the module's existing drop-and-hold bank for the selected
		-- stacks. Every request is guarded by the current module generation so late replies cannot
		-- re-apply state after a toggle or respawn.
		if not deposited then
			local inventory = store.inventory and store.inventory.inventory
			for _, item in type(inventory) == 'table' and inventory.items or {} do
				local name = item.itemType or (item.tool and item.tool.Name)
				if name and table.find(BeforeDeathWhitelist.ListEnabled, name) then
					queueEmergencyDrop(item, token, bankPosition, bankCharacter)
				end
			end
		end
		beforeDeathDepositing = false
    end

	local function disconnectDangerConnections()
		for _, connection in dangerConnections do pcall(function() connection:Disconnect() end) end
		table.clear(dangerConnections)
	end

	local function bindDangerCharacter(character)
		disconnectDangerConnections()
		dangerCharacter, dangerTriggered = character, false
		if not character then return end
		evaluateDanger = function()
			if not AutoBank.Enabled or not BeforeDeath.Enabled or lplr.Character ~= character then return end
			local percent = currentHealthPercent()
			if not percent then return end
			if percent <= HPThreshold.Value then
				if not dangerTriggered then dangerTriggered = true; bankBeforeDeath() end
			elseif percent >= math.min(100, HPThreshold.Value + 5) then
				dangerTriggered = false
			end
		end
		for _, attribute in {'Health', 'MaxHealth'} do
			table.insert(dangerConnections, character:GetAttributeChangedSignal(attribute):Connect(evaluateDanger))
		end
		local humanoid = character:FindFirstChildOfClass('Humanoid')
		if humanoid then
			table.insert(dangerConnections, humanoid.HealthChanged:Connect(evaluateDanger))
			table.insert(dangerConnections, humanoid:GetPropertyChangedSignal('MaxHealth'):Connect(evaluateDanger))
		end
		evaluateDanger()
	end

    -- Take matching stacks back out. ChestGetItem transfers one item per call rather than the
    -- Accessory's entire Amount, so issue one request for every item that was counted.
    local function withdrawFromChest(folder, itemType)
        local contents = folder:GetChildren()
        if #contents == 0 then return end

        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(folder)
        end)
        local requestBudget = 8
        for _, entry in contents do
            if not AutoBank.Enabled then break end
            if entry:IsA('Accessory') and table.find(Whitelist.ListEnabled, entry.Name)
                and (not itemType or entry.Name == itemType) then
                local amount = math.max(entry:GetAttribute('Amount') or 1, 1)
                for _ = 1, amount do
                    if not AutoBank.Enabled or not entry.Parent or requestBudget <= 0 then break end
                    pcall(function()
                        inventoryRemotes():Get('ChestGetItem'):CallServer(folder, entry)
                    end)
                    requestBudget -= 1
                end
            end
            if requestBudget <= 0 then break end
        end
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(nil)
        end)
    end

    local function addDisplayEntry(itemType)
        local icon = Instance.new('ImageButton')
        icon.Name = itemType
        icon.Image = bedwars.getIcon({itemType = itemType}, true)
        icon.Size = UDim2.fromOffset(32, 32)
        icon.BackgroundTransparency = 1
        icon.LayoutOrder = #UI:GetChildren()
        icon.Parent = UI
        local amount = Instance.new('TextLabel')
        amount.Name = 'Amount'
        amount.Size = UDim2.fromScale(1, 1)
        amount.BackgroundTransparency = 1
        amount.Text = ''
        amount.TextColor3 = Color3.new(1, 1, 1)
        amount.TextSize = 16
        amount.TextStrokeTransparency = 0.3
        amount.Font = Enum.Font.Arial
        amount.Parent = icon
        displayEntries[itemType] = amount
        icon.Activated:Connect(function()
            -- cv storage is always a held item drop, so a resource icon returns
            -- that matching drop directly instead of branching into Chest mode.
            for _, drop in table.clone(droppedItems) do
                if drop.Name == itemType then reclaim(drop) end
            end
        end)
    end

    AutoBank = vape.Categories.Inventory:CreateModule({
        Name = 'AutoBank',
        Function = function(callback)
            if callback then
                -- cv's AutoBank loop.  Keep the current display helper and the
                -- Before death hook, but use cv's direct drop/hold/reclaim flow
                -- rather than the alternate chest/banking implementation below.
                UI = Instance.new('Frame')
                UI.Size = UDim2.new(1, 0, 0, 32)
                UI.AnchorPoint = Vector2.new(0.5, 0)
                UI.Position = UDim2.new(0.5, 0, 0, -240)
                UI.BackgroundTransparency = 1
                UI.Visible = DisplayResources.Enabled
                UI.Parent = vape.gui
                AutoBank:Clean(UI)
                local layout = Instance.new('UIListLayout')
                layout.FillDirection = Enum.FillDirection.Horizontal
                layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                layout.SortOrder = Enum.SortOrder.LayoutOrder
                layout.Parent = UI

                table.clear(displayEntries)
                for _, itemType in Whitelist.ListEnabled do
                    addDisplayEntry(itemType)
                end

                local near = false
                local base = CFrame.new(1e3, 1e5, 1e3)
				local rows = Random.new():NextInteger(1, 20000)
				local holdAccumulator = 0
				AutoBank:Clean(runService.Heartbeat:Connect(function(delta)
					holdAccumulator += delta
					if holdAccumulator < 0.05 then return end
					holdAccumulator = 0
					local totals = {}
					for index, drop in droppedItems do
						if drop and drop.Parent then
							totals[drop.Name] = (totals[drop.Name] or 0) + (drop:GetAttribute('Amount') or 0)
							drop.Velocity = Vector3.zero
							if entitylib.isAlive then
								drop.CFrame = near and entitylib.character.Head.CFrame
									or base + Vector3.new((index % rows) * 1200, 0, math.floor(index / rows) * 1200)
							end
						else
							untrackDrop(drop)
						end
                    end
                    for itemType, label in displayEntries do
                        label.Text = tostring(totals[itemType] or 0)
                    end
                end))

				AutoBank:Clean(disconnectDangerConnections)
				AutoBank:Clean(lplr.CharacterAdded:Connect(bindDangerCharacter))
				bindDangerCharacter(lplr.Character)

                repeat
                    local hotbar = lplr.PlayerGui:FindFirstChild('hotbar')
                    local hotbarFrame = hotbar and hotbar:FindFirstChild('1')
                    hotbar = hotbarFrame and hotbarFrame:FindFirstChild('HotbarHealthbarContainer')
                    if hotbar then
                        UI.Position = UDim2.new(0.5, 0, 0, (hotbar.AbsolutePosition.Y + guiService:GetGuiInset().Y) - 60)
                    end

					if entitylib.isAlive and not atShop() then
						near = false
						local inventory = store.inventory and store.inventory.inventory
						for _, item in type(inventory) == 'table' and inventory.items or {} do
							local name = item.tool and item.tool.Name or item.itemType
							if name and item.tool and table.find(Whitelist.ListEnabled, name)
								and not pendingDrops[item.tool] and (dropCooldowns[name] or 0) < os.clock() then
								local token = AutoBank.Generation
								local bankCharacter = lplr.Character
								pendingDrops[item.tool] = true
								task.spawn(function()
									local ok, drop = pcall(function()
										return bedwars.Handler:Get('DropItem'):Fire('CallServer', {
											item = item.tool,
											amount = item.amount
										})
									end)
									pendingDrops[item.tool] = nil
									if not ok or not drop or not drop.Parent then
										dropCooldowns[name] = os.clock() + 5
									elseif not AutoBank.Enabled or AutoBank.Generation ~= token or lplr.Character ~= bankCharacter then
										reclaim(drop)
									elseif not table.find(droppedItems, drop) then
										table.insert(droppedItems, drop)
										drop:ClearAllChildren()
										drop.AncestryChanged:Once(function()
											untrackDrop(drop)
										end)
									end
								end)
							end
                        end
					elseif entitylib.isAlive then
						near = true
						for _, drop in droppedItems do
							if drop and drop.Parent then reclaim(drop) end
						end
					end
                    task.wait(0.1)
                until not AutoBank.Enabled
                return
            end

            if not callback then
                -- Give everything back rather than leaving it stranded in the sky. Bounded:
                -- drain what we can and stop, instead of spinning until the module is switched
                -- back on (which is what the reference build did, and never returned).
                local deadline = tick() + 3
                while #droppedItems > 0 and tick() < deadline and entitylib.isAlive do
                    for _, drop in table.clone(droppedItems) do
                        reclaim(drop)
                    end
                    task.wait(0.1)
                end
                -- Never forget a live drop that the server has not returned yet. If cleanup
                -- times out (for example while respawning), the next enable can restore it.
                for _, drop in table.clone(droppedItems) do
                    if not drop or not drop.Parent then untrackDrop(drop) end
                end
                table.clear(pendingDrops)
                table.clear(pendingReclaims)
                table.clear(releasingDrops)
                table.clear(dropCooldowns)
                table.clear(displayEntries)
                dangerTriggered, dangerCharacter, beforeDeathDepositing, chestDepositBusy = false, nil, false, false
                return
            end

        end,
        Tooltip = 'Stores resources somewhere safe, in your personal chest or held above the map until a shop'
    })

    Mode = AutoBank:CreateDropdown({
        Name = 'Mode',
        List = {'Skybox', 'Chest'},
        Default = 'Skybox',
        Visible = false,
        Tooltip = 'Skybox - holds the drops above the map until a shop\nChest - walks up and banks them like you would',
        Function = function()
            -- Reload rather than switching under the running loop: leaving Skybox has to hand
            -- the sky stash back first, which the disable path already does properly.
            if AutoBank.Enabled then
                AutoBank:Toggle()
                AutoBank:Toggle()
            end
            pcall(function()
                ChestRange.Object.Visible = Mode.Value == 'Chest'
                Withdraw.Object.Visible = Mode.Value == 'Chest'
            end)
        end
    })
    ChestRange = AutoBank:CreateSlider({
        Name = 'Chest range',
        Min = 1,
        Max = 30,
        Default = 20,
        Darker = true,
        Visible = false,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end,
        Tooltip = 'How close to your personal chest you have to be before anything is banked'
    })
    Withdraw = AutoBank:CreateToggle({
        Name = 'Withdraw at shop',
        Default = true,
        Darker = true,
        Visible = false,
        Tooltip = 'Empties the chest back into your inventory at a shop, so AutoBuy can spend what you banked'
    })
    BeforeDeath = AutoBank:CreateToggle({
        Name = 'Before death',
        Function = function(enabled)
            dangerTriggered, dangerCharacter, beforeDeathDepositing = false, nil, false
            if HPThreshold and HPThreshold.Object then HPThreshold.Object.Visible = enabled end
            if BeforeDeathWhitelist and BeforeDeathWhitelist.Object then BeforeDeathWhitelist.Object.Visible = enabled end
			if enabled and AutoBank.Enabled then bindDangerCharacter(lplr.Character) end
        end,
        Tooltip = 'Banks selected inventory items at your personal chest once when your health becomes dangerous'
    })
    HPThreshold = AutoBank:CreateSlider({
        Name = 'HP Threshold',
        Min = 1,
        Max = 99,
        Default = 25,
        Suffix = '%',
        Darker = true,
        Visible = false,
        Tooltip = 'Triggers the before-death deposit at or below this percentage of maximum health'
    })
    BeforeDeathWhitelist = AutoBank:CreateTextList({
        Name = 'Before death whitelist',
        Default = {'emerald', 'diamond', 'iron'},
        Darker = true,
        Visible = false,
        Tooltip = 'Only these item types are deposited by Before death'
    })
    Whitelist = AutoBank:CreateTextList({
        Name = 'Whitelist',
        Default = {'emerald', 'diamond', 'iron'},
        Function = function()
            if AutoBank.Enabled then
                AutoBank:Toggle()
                AutoBank:Toggle()
            end
        end
    })
    DisplayResources = AutoBank:CreateToggle({
        Name = 'Display resources',
        Default = true,
        Function = function(callback)
            if AutoBank.Enabled and UI then
                UI.Visible = callback
            end
        end
    })
end)
-- END AETHER MODULE: inventory/AutoBank.lua --

-- BEGIN AETHER MODULE: inventory/AutoBuy.lua --
run(function()
	local AutoBuy
	local Sword
	local Armor
	local Upgrades
	local TierCheck
	local BedwarsCheck
	local GUI
	local SmartCheck
	local ShopAnywhere
	local OpenShop
	local Custom = {}
	local CustomPost = {}
	local UpgradeToggles = {}
	local Functions, id = {}
	local Callbacks = {Custom, Functions, CustomPost}
	local npctick = tick()
	local purchaseRules = {}
	local rulesPath = 'aetherv2/profiles/autobuy-rules.json'
	local rulesWindow
	local lastShopPrompt, lastShopPromptAt

	local swords = {
		'wood_sword',
		'stone_sword',
		'iron_sword',
		'diamond_sword',
		'emerald_sword'
	}

	local armors = {
		'none',
		'leather_chestplate',
		'iron_chestplate',
		'diamond_chestplate',
		'emerald_chestplate'
	}

	local axes = {
		'none',
		'wood_axe',
		'stone_axe',
		'iron_axe',
		'diamond_axe'
	}

	local pickaxes = {
		'none',
		'wood_pickaxe',
		'stone_pickaxe',
		'iron_pickaxe',
		'diamond_pickaxe'
	}

	local function ruleAllows(itemType)
		local matched = false
		for _, rule in purchaseRules do
			if rule.Buy == itemType then
				matched = true
				local owned = getItem(rule.Condition) ~= nil
				if (rule.Operator == 'is owned' and owned) or (rule.Operator == 'is not owned' and not owned) then return true end
			end
		end
		return not matched
	end

	local function nearestItemShop()
		if not entitylib.isAlive then return nil end
		local root = entitylib.character.RootPart
		if not root then return nil end
		local closest, distance
		for _, entry in store.shop do
			if entry.Shop and entry.RootPart and entry.RootPart.Parent then
				local nextDistance = (entry.RootPart.Position - root.Position).Magnitude
				if not distance or nextDistance < distance then
					closest, distance = entry, nextDistance
				end
			end
		end
		return closest
	end

	local function shopPrompt(entry)
		local root = entry and entry.RootPart
		if not root or not root.Parent then return nil end
		return root:FindFirstChildWhichIsA('ProximityPrompt', true)
			or root.Parent:FindFirstChildWhichIsA('ProximityPrompt', true)
	end

	local function activateShop(entry)
		local prompt = shopPrompt(entry)
		local extender = ((getgenv and getgenv()) or _G).AetherInteractExtender
		if not prompt or type(extender) ~= 'table' or type(extender.Activate) ~= 'function' then
			return false, 'shop prompt unavailable'
		end
		if prompt == lastShopPrompt and tick() - lastShopPromptAt < 0.5 then return true end
		local ok, reason = extender.Activate(prompt)
		if ok then
			lastShopPrompt, lastShopPromptAt = prompt, tick()
		end
		return ok, reason
	end

	local function getShopNPC()
		local shop, items, upgrades, newid = nil, false, false, nil
		if entitylib.isAlive then
			local localPosition = entitylib.character.RootPart.Position
			for _, v in store.shop do
				if v.RootPart and v.RootPart.Parent and (v.RootPart.Position - localPosition).Magnitude <= 20 then
					shop = v.Upgrades or v.Shop or nil
					upgrades = upgrades or v.Upgrades
					items = items or v.Shop
					newid = v.Shop and v.Id or newid
				end
			end
		end
		-- The remote purchase path is only attempted from range by default. The optional
		-- anywhere mode must first open the shop through the shared InteractExtender API.
		if not shop and ShopAnywhere and ShopAnywhere.Enabled then
			local entry = nearestItemShop()
			if entry and activateShop(entry) then
				return entry.Upgrades or entry.Shop, entry.Shop ~= nil, entry.Upgrades ~= nil, entry.Shop and entry.Id or nil
			end
		end
		return shop, items, upgrades, newid
	end

	local function canBuy(item, currencytable, amount)
		amount = amount or 1
		if not currencytable[item.currency] then
			local currency = getItem(item.currency)
			currencytable[item.currency] = currency and currency.amount or 0
		end
		if item.ignoredByKit and table.find(item.ignoredByKit, store.equippedKit or '') then return false end
		if item.lockedByForge or item.disabled then return false end
		if item.require and item.require.teamUpgrade then
			if (bedwars.Store:getState().Bedwars.teamUpgrades[item.require.teamUpgrade.upgradeId] or -1) < item.require.teamUpgrade.lowestTierIndex then
				return false
			end
		end
		return currencytable[item.currency] >= (item.price * amount)
	end

	local function buyItem(item, currencytable)
		if not id then return end
		if #purchaseRules > 0 and not ruleAllows(item.itemType) then return end
		notif('AutoBuy', 'Bought '..bedwars.ItemMeta[item.itemType].displayName, 3)
		bedwars.Handler:Get('BedwarsPurchaseItem'):Fire('CallServerAsync', {
			shopItem = item,
			shopId = id
		}):andThen(function(suc)
			if suc then
				bedwars.SoundManager:playSound(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
				bedwars.Store:dispatch({
					type = 'BedwarsAddItemPurchased',
					itemType = item.itemType
				})
				bedwars.BedwarsShopController.alreadyPurchasedMap[item.itemType] = true
			end
		end)
		currencytable[item.currency] -= item.price
	end

	local function buyUpgrade(upgradeType, currencytable)
		if not Upgrades.Enabled then return end
		local upgrade = bedwars.TeamUpgradeMeta[upgradeType]
		local currentUpgrades = bedwars.Store:getState().Bedwars.teamUpgrades[lplr:GetAttribute('Team')] or {}
		local currentTier = (currentUpgrades[upgradeType] or 0) + 1
		local bought = false

		for i = currentTier, #upgrade.tiers do
			local tier = upgrade.tiers[i]
			if tier.availableOnlyInQueue and not table.find(tier.availableOnlyInQueue, store.queueType) then continue end

			if canBuy({currency = 'diamond', price = tier.cost}, currencytable) then
				notif('AutoBuy', 'Bought '..(upgrade.name == 'Armor' and 'Protection' or upgrade.name)..' '..i, 3)
				bedwars.Handler:Get('RequestPurchaseTeamUpgrade'):Fire('CallServerAsync', upgradeType)
				currencytable.diamond -= tier.cost
				bought = true
			else
				break
			end
		end

		return bought
	end

	local function buyTool(tool, tools, currencytable)
		local bought, buyable = false
		tool = tool and table.find(tools, tool.itemType) and table.find(tools, tool.itemType) + 1 or math.huge

		for i = tool, #tools do
			local v = bedwars.Shop.getShopItem(tools[i], lplr)
			if canBuy(v, currencytable) then
				if SmartCheck.Enabled and bedwars.ItemMeta[tools[i]].breakBlock and i > 2 then
					if Armor.Enabled then
						local currentarmor = store.inventory.inventory.armor[2]
						currentarmor = currentarmor and currentarmor ~= 'empty' and currentarmor.itemType or 'none'
						if (table.find(armors, currentarmor) or 3) < 3 then break end
					end
					if Sword.Enabled then
						if store.tools.sword and (table.find(swords, store.tools.sword.itemType) or 2) < 2 then break end
					end
				end
				bought = true
				buyable = v
			end
			if TierCheck.Enabled and v.nextTier then break end
		end

		if buyable then
			buyItem(buyable, currencytable)
		end

		return bought
	end

	local function saveRules()
		writefile(rulesPath, httpService:JSONEncode(purchaseRules))
	end

	local function openPreferences()
		if rulesWindow then rulesWindow:Destroy() end
		local root = vape.gui:FindFirstChild('ScaledGui') or vape.gui
		rulesWindow = Instance.new('Frame')
		rulesWindow.Name, rulesWindow.Size, rulesWindow.Position = 'PurchasePreferences', UDim2.fromOffset(460, 310), UDim2.new(0.5, -230, 0.5, -155)
		rulesWindow.BackgroundColor3, rulesWindow.Parent = uipallet.Main, root
		Instance.new('UICorner', rulesWindow).CornerRadius = UDim.new(0, 6)
		local title = Instance.new('TextLabel')
		title.Size, title.Position, title.BackgroundTransparency = UDim2.new(1, -60, 0, 38), UDim2.fromOffset(14, 0), 1
		title.Text, title.TextColor3, title.TextSize, title.TextXAlignment, title.FontFace, title.Parent = 'Purchase preferences', uipallet.Text, 14, Enum.TextXAlignment.Left, uipallet.FontSemiBold, rulesWindow
		local close = Instance.new('TextButton')
		close.Size, close.Position, close.BackgroundTransparency, close.Text, close.TextColor3, close.Parent = UDim2.fromOffset(34, 34), UDim2.new(1, -38, 0, 2), 1, '×', uipallet.Text, rulesWindow
		close.MouseButton1Click:Connect(function() rulesWindow:Destroy(); rulesWindow = nil end)
		local items = {'arrow', 'wool_white', 'fireball', 'telepearl', 'tnt'}
		local conditions = {'wood_axe', 'stone_axe', 'wood_pickaxe', 'iron_sword', 'leather_chestplate'}
		local operators = {'is owned', 'is not owned'}
		local draft = {Buy = items[1], Condition = conditions[1], Operator = operators[1]}
		local function token(x, width, values, key, prefix)
			local button = Instance.new('TextButton')
			button.Size, button.Position = UDim2.fromOffset(width, 28), UDim2.fromOffset(x, 46)
			button.BackgroundColor3, button.TextColor3, button.TextSize, button.FontFace, button.Parent = color.Light(uipallet.Main, 0.05), uipallet.Text, 11, uipallet.Font, rulesWindow
			Instance.new('UICorner', button).CornerRadius = UDim.new(0, 5)
			local index = 1
			local function update() button.Text = prefix..values[index]; draft[key] = values[index] end
			button.MouseButton1Click:Connect(function() index = index % #values + 1; update() end)
			update(); return button
		end
		token(14, 115, items, 'Buy', 'Buy '); token(137, 145, conditions, 'Condition', 'if '); token(290, 112, operators, 'Operator', '')
		local add = Instance.new('TextButton')
		add.Size, add.Position, add.BackgroundColor3, add.Text, add.TextColor3, add.Parent = UDim2.fromOffset(34, 28), UDim2.fromOffset(410, 46), Color3.fromRGB(120, 80, 180), '+', Color3.new(1, 1, 1), rulesWindow
		Instance.new('UICorner', add).CornerRadius = UDim.new(0, 5)
		local list = Instance.new('ScrollingFrame')
		list.Size, list.Position, list.BackgroundTransparency, list.ScrollBarThickness, list.Parent = UDim2.new(1, -28, 1, -94), UDim2.fromOffset(14, 86), 1, 2, rulesWindow
		local layout = Instance.new('UIListLayout'); layout.Padding, layout.Parent = UDim.new(0, 5), list
		local function render()
			for _, child in list:GetChildren() do if child:IsA('Frame') then child:Destroy() end end
			for index, rule in purchaseRules do
				local row = Instance.new('Frame'); row.Size, row.BackgroundColor3, row.Parent = UDim2.new(1, -4, 0, 34), color.Light(uipallet.Main, 0.03), list
				Instance.new('UICorner', row).CornerRadius = UDim.new(0, 5)
				local label = Instance.new('TextLabel'); label.Size, label.Position, label.BackgroundTransparency, label.Text = UDim2.new(1, -70, 1, 0), UDim2.fromOffset(9, 0), 1, 'Only buy '..rule.Buy..' if '..rule.Condition..' '..rule.Operator
				label.TextColor3, label.TextSize, label.TextXAlignment, label.FontFace, label.Parent = uipallet.Text, 11, Enum.TextXAlignment.Left, uipallet.Font, row
				for _, action in {{'↑', -58, function() if index > 1 then purchaseRules[index], purchaseRules[index - 1] = purchaseRules[index - 1], purchaseRules[index] end end}, {'×', -30, function() table.remove(purchaseRules, index) end}} do
					local button = Instance.new('TextButton'); button.Size, button.Position, button.BackgroundTransparency, button.Text, button.TextColor3, button.Parent = UDim2.fromOffset(26, 30), UDim2.new(1, action[2], 0, 2), 1, action[1], uipallet.Text, row
					button.MouseButton1Click:Connect(function() action[3](); saveRules(); render() end)
				end
			end
			list.CanvasSize = UDim2.fromOffset(0, #purchaseRules * 39)
		end
		add.MouseButton1Click:Connect(function()
			for _, rule in purchaseRules do if rule.Buy == draft.Buy and rule.Condition == draft.Condition and rule.Operator ~= draft.Operator then notif('AutoBuy', 'Contradictory rule', 4, 'alert'); return end end
			table.insert(purchaseRules, table.clone(draft)); saveRules(); render()
		end)
		render()
	end

	if isfile(rulesPath) then
		pcall(function()
			local decoded = httpService:JSONDecode(readfile(rulesPath))
			if type(decoded) ~= 'table' then return end
			local valid = {}
			for _, rule in decoded do
				if type(rule) == 'table' and type(rule.Buy) == 'string' and type(rule.Condition) == 'string'
					and table.find({'is owned', 'is not owned'}, rule.Operator) then table.insert(valid, rule) end
			end
			purchaseRules = valid
		end)
	end

	AutoBuy = vape.Categories.Inventory:CreateModule({
		Name = 'AutoBuy',
		Function = function(callback)
			if callback then
				repeat task.wait() until store.queueType ~= 'bedwars_test'
				if BedwarsCheck.Enabled and not store.queueType:find('bedwars') then return end

				local lastupgrades
				AutoBuy:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(function()
					-- Currency can arrive from a generator, a chest withdrawal, or a delayed
					-- pickup response. Always wake the buyer instead of only doing so when its
					-- current deadline happens to be more than a second away.
					npctick = math.min(npctick, tick())
				end))

				repeat
					local npc, shop, upgrades, newid = getShopNPC()
					id = newid
					if GUI.Enabled then
						if not (bedwars.AppController:isAppOpen('BedwarsItemShopApp') or bedwars.AppController:isAppOpen('TeamUpgradeApp')) then
							npc = nil
						end
					end

					if npc and lastupgrades ~= upgrades then
						npctick = tick()
						lastupgrades = upgrades
					end

					if npc and npctick <= tick() and store.matchState ~= 2 and store.shopLoaded then
						local currencytable = {}
						local waitcheck
						for _, tab in Callbacks do
							for _, callback in tab do
								if callback(currencytable, shop, upgrades) then
									waitcheck = true
								end
							end
						end
						-- Do not sleep forever when nothing is affordable. Inventory events are
						-- usually enough to wake us, but they can be coalesced or arrive before a
						-- chest transfer finishes. A cheap periodic retry makes shop entry and
						-- AutoBank hand-off deterministic without hammering purchase remotes.
						npctick = tick() + (waitcheck and 0.4 or 0.5)
					end

					task.wait(0.1)
				until not AutoBuy.Enabled
			else
				npctick = tick()
				if rulesWindow then rulesWindow:Destroy(); rulesWindow = nil end
			end
		end,
		Tooltip = 'Automatically buys items when you go near the shop'
	})

	AutoBuy:CreateButton({Name = 'Purchase preferences', Function = openPreferences})
	ShopAnywhere = AutoBuy:CreateToggle({
		Name = 'Shop anywhere',
		Tooltip = 'Uses InteractExtender to open the nearest item shop before buying'
	})
	Sword = AutoBuy:CreateToggle({
		Name = 'Buy Sword',
		Function = function(callback)
			npctick = tick()
			Functions[2] = callback and function(currencytable, shop)
				if not shop then return end

				if store.equippedKit == 'dasher' then
					swords = {
						[1] = 'wood_dao',
						[2] = 'stone_dao',
						[3] = 'iron_dao',
						[4] = 'diamond_dao',
						[5] = 'emerald_dao'
					}
				elseif store.equippedKit == 'ice_queen' then
					swords[5] = 'ice_sword'
				elseif store.equippedKit == 'ember' then
					swords[5] = 'infernal_saber'
				elseif store.equippedKit == 'lumen' then
					swords[5] = 'light_sword'
				end

				return buyTool(store.tools.sword, swords, currencytable)
			end or nil
		end
	})
	Armor = AutoBuy:CreateToggle({
		Name = 'Buy Armor',
		Function = function(callback)
			npctick = tick()
			Functions[1] = callback and function(currencytable, shop)
				if not shop then return end
				local currentarmor = store.inventory.inventory.armor[2] ~= 'empty' and store.inventory.inventory.armor[2] or getBestArmor(1)
				currentarmor = currentarmor and currentarmor.itemType or 'none'
				return buyTool({itemType = currentarmor}, armors, currencytable)
			end or nil
		end,
		Default = true
	})
	AutoBuy:CreateToggle({
		Name = 'Buy Axe',
		Function = function(callback)
			npctick = tick()
			Functions[3] = callback and function(currencytable, shop)
				if not shop then return end
				return buyTool(store.tools.wood or {itemType = 'none'}, axes, currencytable)
			end or nil
		end
	})
	AutoBuy:CreateToggle({
		Name = 'Buy Pickaxe',
		Function = function(callback)
			npctick = tick()
			Functions[4] = callback and function(currencytable, shop)
				if not shop then return end
				return buyTool(store.tools.stone, pickaxes, currencytable)
			end or nil
		end
	})
	Upgrades = AutoBuy:CreateToggle({
		Name = 'Buy Upgrades',
		Function = function(callback)
			for _, v in UpgradeToggles do
				v.Object.Visible = callback
			end
		end,
		Default = true
	})
	local count = 0
	for i, v in bedwars.TeamUpgradeMeta do
		local toggleCount = count
		table.insert(UpgradeToggles, AutoBuy:CreateToggle({
			Name = 'Buy '..(v.name == 'Armor' and 'Protection' or v.name),
			Function = function(callback)
				npctick = tick()
				Functions[5 + toggleCount + (v.name == 'Armor' and 20 or 0)] = callback and function(currencytable, shop, upgrades)
					if not upgrades then return end
					if v.disabledInQueue and table.find(v.disabledInQueue, store.queueType) then return end
					return buyUpgrade(i, currencytable)
				end or nil
			end,
			Darker = true,
			Default = (i == 'ARMOR' or i == 'DAMAGE')
		}))
		count += 1
	end
	TierCheck = AutoBuy:CreateToggle({Name = 'Tier Check'})
	BedwarsCheck = AutoBuy:CreateToggle({
		Name = 'Only Bedwars',
		Function = function()
			if AutoBuy.Enabled then
				AutoBuy:Toggle()
				AutoBuy:Toggle()
			end
		end,
		Default = true
	})
	GUI = AutoBuy:CreateToggle({Name = 'GUI check'})
	SmartCheck = AutoBuy:CreateToggle({
		Name = 'Smart check',
		Default = true,
		Tooltip = 'Buys iron armor before iron axe'
	})
	AutoBuy:CreateTextList({
		Name = 'Item',
		Placeholder = 'priority/item/amount/after',
		Function = function(list)
			table.clear(Custom)
			table.clear(CustomPost)
			for _, entry in list do
				local tab = entry:split('/')
				local ind = tonumber(tab[1])
				if ind then
					(tab[4] and CustomPost or Custom)[ind] = function(currencytable, shop)
						if not shop then return end

						local v = bedwars.Shop.getShopItem(tab[2], lplr)
						if v then
							local item = getItem(tab[2] == 'wool_white' and bedwars.Shop.getTeamWool(lplr:GetAttribute('Team')) or tab[2])
							item = (item and tonumber(tab[3]) - item.amount or tonumber(tab[3])) // v.amount
							if item > 0 and canBuy(v, currencytable, item) then
								for _ = 1, item do
									buyItem(v, currencytable)
								end
								return true
							end
						end
					end
				end
			end
		end
	})
	local shopApi = {activateShop = activateShop, nearestItemShop = nearestItemShop}
	shared.AetherShopRuntime = shopApi
	vape:Clean(function() if shared.AetherShopRuntime == shopApi then shared.AetherShopRuntime = nil end end)

end)
-- END AETHER MODULE: inventory/AutoBuy.lua --

-- BEGIN AETHER MODULE: inventory/AutoConsume.lua --
run(function()
    local AutoConsume
    local Health
    local SpeedPotion
    local Apple
    local ShieldPotion

    local function consumeCheck(attribute)
        if entitylib.isAlive then
            if SpeedPotion.Enabled and (not attribute or attribute == 'StatusEffect_speed') then
                local speedpotion = getItem('speed_potion')
                if speedpotion and (not lplr.Character:GetAttribute('StatusEffect_speed')) then
                    for _ = 1, 4 do
                        if bedwars.Client:Get(remotes.ConsumeItem):CallServer({item = speedpotion.tool}) then break end
                    end
                end
            end

            if Apple.Enabled and (not attribute or attribute:find('Health')) then
                if (lplr.Character:GetAttribute('Health') / lplr.Character:GetAttribute('MaxHealth')) <= (Health.Value / 100) then
                    local apple = getItem('orange') or (not lplr.Character:GetAttribute('StatusEffect_golden_apple') and getItem('golden_apple')) or getItem('apple')

                    if apple then
                        bedwars.Client:Get(remotes.ConsumeItem):CallServerAsync({
                            item = apple.tool
                        })
                    end
                end
            end

            if ShieldPotion.Enabled and (not attribute or attribute:find('Shield')) then
                if (lplr.Character:GetAttribute('Shield_POTION') or 0) == 0 then
                    local shield = getItem('big_shield') or getItem('mini_shield')

                    if shield then
                        bedwars.Client:Get(remotes.ConsumeItem):CallServerAsync({
                            item = shield.tool
                        })
                    end
                end
            end
        end
    end

    AutoConsume = vape.Categories.Inventory:CreateModule({
        Name = 'AutoConsume',
        Function = function(callback)
            if callback then
                AutoConsume:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(consumeCheck))
                AutoConsume:Clean(vapeEvents.AttributeChanged.Event:Connect(function(attribute)
                    if attribute:find('Shield') or attribute:find('Health') or attribute == 'StatusEffect_speed' then
                        consumeCheck(attribute)
                    end
                end))
                consumeCheck()
            end
        end,
        Tooltip = 'Automatically heals for you when health or shield is under threshold'
    })
    Health = AutoConsume:CreateSlider({
        Name = 'Health Percent',
        Min = 1,
        Max = 99,
        Default = 70,
        Suffix = '%'
    })
    SpeedPotion = AutoConsume:CreateToggle({
        Name = 'Speed Potions',
        Default = true
    })
    Apple = AutoConsume:CreateToggle({
        Name = 'Apple',
        Default = true
    })
    ShieldPotion = AutoConsume:CreateToggle({
        Name = 'Shield Potions',
        Default = true
    })
end)
-- END AETHER MODULE: inventory/AutoConsume.lua --

-- BEGIN AETHER MODULE: inventory/AutoEnchant.lua --
run(function()
	local category = vape.Categories.Inventory or vape.Categories.Utility or vape.Categories.World
	if not category or type(category.CreateModule) ~= 'function' then
		warn('[AetherV2] AutoEnchant could not find a module category')
		return
	end

	local AutoEnchant, Repair, Desired, MaximumRolls, Reserve, Interval
	local generation = 0
	local enchantNames = {}

	local function normalise(value)
		return tostring(value or ''):lower():gsub('[%s_%-]+', '')
	end

	local function displayName(key, meta)
		return tostring((type(meta) == 'table' and (meta.displayName or meta.name)) or key):gsub('_', ' ')
	end

	if type(bedwars.EnchantMeta) == 'table' then
		for key, meta in pairs(bedwars.EnchantMeta) do
			table.insert(enchantNames, displayName(key, meta))
		end
	end
	if #enchantNames == 0 then
		enchantNames = {'Critical Strike', 'Fire', 'Life Steal', 'Shield Gen', 'Static', 'Updraft', 'Wind'}
	end
	table.sort(enchantNames)

	local function diamonds()
		local item = getItem('diamond')
		return item and tonumber(item.amount) or 0
	end

	local function currentEnchant()
		local state
		pcall(function() state = bedwars.Store:getState() end)
		local value = type(state) == 'table' and state.Bedwars and state.Bedwars.enchant or nil
		value = value or lplr:GetAttribute('Enchant')
		if type(value) == 'table' then value = value.enchant or value.type or value.itemType end
		if value == nil or tostring(value) == '' or tostring(value):lower() == 'none' then return '' end
		return displayName(value, type(bedwars.EnchantMeta) == 'table' and bedwars.EnchantMeta[value] or nil)
	end

	local function hasDesired(value)
		return Desired and normalise(Desired.Value) == normalise(value)
	end

	local function findTable()
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return end
		local nearest, nearestDistance
		for _, object in pairs(store.enchant or {}) do
			if typeof(object) == 'Instance' and object.Parent then
				local ok, position = pcall(function()
					return object:IsA('Model') and object:GetPivot().Position or object.Position
				end)
				if ok and typeof(position) == 'Vector3' then
					local distance = (entitylib.character.RootPart.Position - position).Magnitude
					if not nearestDistance or distance < nearestDistance then nearest, nearestDistance = object, distance end
				end
			end
		end
		return nearest, nearestDistance
	end

	local function request(controllerNames, remoteNames, tableModel)
		local controller = bedwars.EnchantTableController or bedwars.EnchantController
		for _, name in ipairs(controllerNames) do
			if controller and type(controller[name]) == 'function' then
				local ok, result = pcall(controller[name], controller, tableModel)
				if ok and result ~= false then return true end
			end
		end
		for _, name in ipairs(remoteNames) do
			local ok = pcall(function()
				local handler = bedwars.Handler and bedwars.Handler:Get(name)
				if not handler then error('missing remote') end
				handler:Fire('CallServerAsync', tableModel)
			end)
			if ok then return true end
		end
		return false
	end

	AutoEnchant = category:CreateModule({
		Name = 'AutoEnchant',
		Tooltip = 'Rolls a nearby team enchant table until an accepted enchant is obtained.',
		Function = function(enabled)
			generation += 1
			if not enabled then return end
			local token = generation
			local worker = task.spawn(function()
				local rolls, character = 0, lplr.Character
				while AutoEnchant.Enabled and token == generation do
					if lplr.Character ~= character then
						character, rolls = lplr.Character, 0
					end
					local tableModel, distance = findTable()
					if not tableModel or not distance or distance > 18 then
						task.wait(0.25)
						continue
					end
					if hasDesired(currentEnchant()) then
						rolls = 0
						task.wait(0.25)
						continue
					end
					if rolls >= MaximumRolls.Value then
						notif('AutoEnchant', 'Maximum rolls reached without the selected enchant.', 5, 'warning')
						task.defer(function() if AutoEnchant.Enabled and token == generation then AutoEnchant:Toggle() end end)
						break
					end
					local broken = false
					pcall(function() broken = collectionService:HasTag(tableModel, 'broken-enchant-table') end)
					if broken then
						if not Repair.Enabled or diamonds() < Reserve.Value + 8 then task.wait(0.25); continue end
						if not request({'repairEnchantTable', 'repair'}, {'RepairEnchantTable', 'RepairEnchantTableRemote'}, tableModel) then
							task.wait(1)
							continue
						end
						task.wait(math.max(Interval.Value, 0.25))
						continue
					end
					local state
					pcall(function() state = bedwars.Store:getState() end)
					local bedwarsState = type(state) == 'table' and type(state.Bedwars) == 'table' and state.Bedwars or {}
					local gameState = type(state) == 'table' and type(state.Game) == 'table' and state.Game or {}
					local cost = tonumber(bedwarsState.enchantCost or gameState.enchantCost) or 2
					if diamonds() - cost < Reserve.Value then task.wait(0.25); continue end
					local before = currentEnchant()
					if not request({'purchaseEnchant', 'rollEnchant'}, {'PurchaseEnchant', 'RequestEnchant'}, tableModel) then
						task.wait(1)
						continue
					end
					rolls += 1
					local deadline = tick() + 4
					repeat task.wait() until not AutoEnchant.Enabled or token ~= generation or lplr.Character ~= character or currentEnchant() ~= before or tick() >= deadline
					if AutoEnchant.Enabled and token == generation and lplr.Character == character then
						task.wait(Interval.Value)
					end
				end
			end)
			AutoEnchant:Clean(worker)
		end
	})
	Desired = AutoEnchant:CreateDropdown({Name = 'Desired enchant', List = enchantNames, Default = enchantNames[1], Tooltip = 'Stops rolling as soon as this enchant is obtained.'})
	Repair = AutoEnchant:CreateToggle({Name = 'Repair enchant table', Default = true})
	MaximumRolls = AutoEnchant:CreateSlider({Name = 'Maximum rolls', Min = 1, Max = 50, Default = 10})
	Reserve = AutoEnchant:CreateSlider({Name = 'Resource reserve', Min = 0, Max = 32, Default = 0, Suffix = ' diamonds'})
	Interval = AutoEnchant:CreateSlider({Name = 'Request interval', Min = 0.25, Max = 2, Default = 0.6, Decimal = 100, Suffix = 's'})
end)
-- END AETHER MODULE: inventory/AutoEnchant.lua --

-- BEGIN AETHER MODULE: inventory/AutoFish.lua --
run(function()
	local AutoFish
	local Show
	local Blacklist
	local Minigame
	local CompleteDelay = {}
	local Cast
	local CastDelay = {}

	local old, newMinigame
	local function getBait()
		for _, v in workspace:GetChildren() do
			if v.Name == 'fisherman_bobber' and v:GetAttribute('ProjectileShooter') == lplr.UserId then
				return v
			end
		end
		return nil
	end

	local function castRod()
		local item = bedwars.FishingRodController:getHandItem()
		if item and not bedwars.FishingRodController.projectileHandler and bedwars.FishingRodController:canLaunch() then
			bedwars.FishingRodController:beginHolding(item, nil, bedwars.FishingRodController.aimingMaid, false)
			task.wait()
			bedwars.FishingRodController:releaseChargeInput(bedwars.FishingRodController.aimingMaid, function()
				return true
			end, nil)
		end
	end

	AutoFish = vape.Categories.Inventory:CreateModule({
		Name = 'AutoFish',
		Function = function(call)
			if call then
				old = bedwars.FishingMinigameController.startMinigame
				bedwars.FishingMinigameController.startMinigame = function(...)
	                if Minigame.Enabled then
	                    task.wait(CompleteDelay:GetRandomValue())
	                    return select(3, ...)({win = true})
	                end
	                return (old or bedwars.FishingMinigameController.startMinigame)(...)
				end

				AutoFish:Clean(bedwars.Handler:Get('FishFound').Remote:Connect(function(data)
					local reroll = #Blacklist.ListEnabled > 0
					for _, v in data.dropData.drops do
						local amount = tonumber(v.amount) or 0
						if Show.Enabled then
							local itemDisplay = bedwars.ItemMeta[v.itemType] and bedwars.ItemMeta[v.itemType].displayName or v.itemType
							notif('AutoFish', `You can get {amount} {itemDisplay:lower()}{amount >= 2 and 's' or ''} on ur next fish`, 20, 'info')
						end
						if not table.find(Blacklist.ListEnabled, v.itemType) then
							reroll = false
						end
					end

					if reroll and entitylib.isAlive then
						lplr.Character.Humanoid.Jump = true
					end
				end))
				repeat
					if entitylib.isAlive and Cast.Enabled and (store.hand.tool and store.hand.tool.Name == 'fishing_rod') then
						local ray = cloneref(lplr:GetMouse()).UnitRay
						if not getBait() and not workspace:Raycast(entitylib.character.Head.Position + (ray.Direction * 6), Vector3.new(0, -20, 0)) then
							task.wait(CastDelay:GetRandomValue())
							if AutoFish.Enabled then
								castRod()
							end
							task.wait(0.1)
						end
					end
					task.wait(0.1)
				until not AutoFish.Enabled
			elseif old then
	            bedwars.FishingMinigameController.startMinigame = old
	            old = nil
			end
		end,
		Tooltip = 'Automatically fishes with fishing rod'
	})

	Blacklist = AutoFish:CreateTextList({
		Name = 'Blacklisted loot',
		Default = {'iron'},
