-- BEGIN AETHER MODULE: kits/AutoFarmerCletus.lua --
run(function()
	local AutoFarmerCletus
	local Range
	local Delay
	local nextPickup = 0

	local crops = {
		carrot = true,
		carrot_seeds = true,
		melon = true,
		melon_seeds = true,
		watermelon = true,
		pumpkin = true,
		pumpkin_block = true,
		pumpkin_seeds = true
	}

	local Pickup = bedwars.Handler:Get('PickupItemDrop')

	AutoFarmerCletus = kits:CreateModule({
		Name = 'AutoFarmerCletus',
		Function = function(callback)
			if callback then
				nextPickup = 0

				repeat
					if entitylib.isAlive and store.equippedKit == 'farmer_cletus' and tick() >= nextPickup then
						local origin = entitylib.character.RootPart.Position
