	for _, effect in bedwars.ArmorTrimEffectType do
		table.insert(effects, effect)
	end
	table.sort(effects)
	
	local function clearTrim()
		for _, v in added do
			if v.Parent then
				v:Destroy()
			end
		end
		table.clear(added)
	end
	
	local function applyTrim()
		clearTrim()
		if not ArmorChanger.Enabled or not lplr.Character then return end
	
		local before = {}
		for _, v in lplr.Character:GetDescendants() do
			before[v] = true
		end
	
		bedwars.ArmorTrimController:attachArmorTrimEffects(lplr.Character, Trim.Value, Color.Value, Rank.Value - 1, Effect.Value)
	
		for _, v in lplr.Character:GetDescendants() do
			if not before[v] then
				table.insert(added, v)
			end
		end
	end
	
	ArmorChanger = vape.Categories.Render:CreateModule({
		Name = 'ArmorTrims',
		Function = function(callback)
			if callback then
				ArmorChanger:Clean(lplr.CharacterAdded:Connect(function()
					task.wait(1)
					applyTrim()
				end))
				ArmorChanger:Clean(clearTrim)
			end
			applyTrim()
		end,
		Tooltip = 'Puts an armor trim on yourself, only you can see it'
	})
	Trim = ArmorChanger:CreateDropdown({
		Name = 'Trim',
		List = trims,
		Function = function()
			if ArmorChanger.Enabled then
				applyTrim()
			end
		end
	})
	Color = ArmorChanger:CreateDropdown({
		Name = 'Color',
		List = colors,
		Function = function()
			if ArmorChanger.Enabled then
				applyTrim()
			end
		end
	})
	Effect = ArmorChanger:CreateDropdown({
		Name = 'Effect',
		List = effects,
		Function = function()
			if ArmorChanger.Enabled then
				applyTrim()
			end
		end
	})
	Rank = ArmorChanger:CreateSlider({
		Name = 'Tier',
		Min = 1,
		Max = 7,
		Default = 7,
		Function = function()
			if ArmorChanger.Enabled then
				applyTrim()
			end
		end,
		Tooltip = 'Higher tiers use the fancier version of the effect, 7 is nightmare'
	})
	
end)
-- END AETHER MODULE: render/ArmorTrims.lua --

-- BEGIN AETHER MODULE: render/Aura.lua --
run(function()
	local Aura
	local nimConnections = {}
	local nimFolder = nil
	local nimHighlight = nil
	local nimParts = {}
	local nimExtra = {}
	local nimH, nimS, nimV = 0.65, 1, 1
	local nimSpeed = 1.5
	local nimStyle = 'randomshi'
	local nimOrbCount = 8
	local nimMode = 'Solid'
	local nimOrbCountSlider = nil

	local function removeAura()
		for _, conn in nimConnections do
			pcall(function() conn:Disconnect() end)
		end
		table.clear(nimConnections)
		table.clear(nimParts)
		table.clear(nimExtra)
		if nimFolder then
			pcall(function() nimFolder:Destroy() end)
			nimFolder = nil
		end
		if nimHighlight then
			pcall(function() nimHighlight:Destroy() end)
			nimHighlight = nil
		end
	end

	local function makePart(size, shape)
		local p = Instance.new('Part')
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.Material = Enum.Material.Neon
		p.Size = size or Vector3.new(0.45, 0.45, 0.45)
		if shape then p.Shape = shape end
		p.Parent = nimFolder
		return p
	end

	local function makeHighlight(character, fillTrans)
		local hl = Instance.new('Highlight')
		hl.Adornee = character
		hl.OutlineTransparency = 0
		hl.FillTransparency = fillTrans or 0.78
		hl.OutlineColor = Color3.fromHSV(nimH, nimS, nimV)
		hl.FillColor = Color3.fromHSV(nimH, nimS, nimV)
		hl.Parent = nimFolder
		return hl
	end

	local setups = {
		['randomshi'] = function(character)
			nimHighlight = makeHighlight(character, 0.75)
