				fl:SetAttribute('RO', 0.6 + math.random() * 0.8)
				fl:SetAttribute('SP', 2.5 + math.random() * 3.5)
				fl:SetAttribute('YO', math.random() * 5)
				fl:SetAttribute('LN', 0.5 + math.random() * 1.1)
				table.insert(nimParts, fl)
			end
			for i = 1, 18 do
