-- BEGIN AETHER MODULE: render/HitAccuracy.lua --
run(function()
	local HitAccuracy
	local ShowColor
	local HideUnused
	local sources = {'ProjectileAura', 'ProjectileAimbot', 'SilentAim'}
	local rows = {}
	local holder
	
	local function addRow(name)
		local row = Instance.new('Frame')
		row.BackgroundTransparency = 1
		row.Name = name
		row.Size = UDim2.new(1, 0, 0, 20)
		row.Parent = holder
		local title = Instance.new('TextLabel')
		title.BackgroundTransparency = 1
		title.FontFace = uipallet.Font
		title.Position = UDim2.fromOffset(10, 0)
		title.Size = UDim2.new(1, -20, 1, 0)
		title.Text = name
		title.TextColor3 = Color3.new(1, 1, 1)
		title.TextSize = 14
		title.TextStrokeColor3 = Color3.new()
		title.TextStrokeTransparency = 0.8
		title.TextXAlignment = Enum.TextXAlignment.Left
		title.Parent = row
		local value = title:Clone()
		value.Name = 'Value'
		value.Text = '--'
		value.TextXAlignment = Enum.TextXAlignment.Right
		value.Parent = row
	
		rows[name] = {Object = row, Title = title, Value = value}
	end
	
	local function refresh()
		if vape.ThreadFix then
			setthreadidentity(8)
		end
	
		local shown = 0
		for _, v in sources do
			local chance = store.hitchance[v]
			local live = chance and (tick() - chance.Clock) < 2
			local row = rows[v]
			row.Object.Visible = live or not HideUnused.Enabled
	
			if row.Object.Visible then
				row.Object.Position = UDim2.fromOffset(0, 6 + (shown * 20))
				row.Value.Text = live and `{math.round(chance.Value * 100)}%` or '--'
				row.Value.TextColor3 = (live and ShowColor.Enabled) and Color3.fromHSV(chance.Value * 0.33, 0.75, 1) or Color3.new(1, 1, 1)
				shown += 1
			end
		end
	
		rows.Waiting.Object.Visible = shown == 0
		holder.Size = UDim2.fromOffset(190, 12 + (math.max(shown, 1) * 20))
	end
	
	HitAccuracy = vape:CreateOverlay({
		Name = 'Hit Accuracy',
		Icon = getcustomasset('aetherv2/assets/new/targetinfoicon.png'),
		Size = UDim2.fromOffset(18, 12),
		Position = UDim2.fromOffset(11, 14),
		Function = function(callback)
			if callback then
				repeat
					refresh()
					task.wait(0.05)
				until not HitAccuracy.Button or not HitAccuracy.Button.Enabled
			end
		end
	})
	HitAccuracy:CreateFont({
		Name = 'Font',
		Blacklist = 'Gotham',
		Function = function(val)
			for _, v in rows do
				v.Title.FontFace = val
				v.Value.FontFace = val
			end
		end
	})
	HideUnused = HitAccuracy:CreateToggle({
		Name = 'Hide unused',
		Function = function()
			if holder then
				refresh()
			end
		end,
		Default = true,
		Tooltip = 'Leaves out a module until it is actually aiming at someone'
	})
	ShowColor = HitAccuracy:CreateToggle({
		Name = 'Color the number',
		Default = true,
		Tooltip = 'Red through green as the chance climbs'
	})
	HitAccuracy:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(hue, sat, val, opacity)
			if holder then
				holder.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				holder.BackgroundTransparency = 1 - opacity
			end
		end
	})
	holder = Instance.new('Frame')
	holder.BackgroundColor3 = Color3.new()
	holder.BackgroundTransparency = 0.5
	holder.Size = UDim2.fromOffset(190, 32)
	holder.Parent = HitAccuracy.Children
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 5)
	corner.Parent = holder
	addBlur(holder)
	for _, v in sources do
		addRow(v)
	end
	addRow('Waiting')
	rows.Waiting.Object.Position = UDim2.fromOffset(0, 6)
	rows.Waiting.Title.Text = 'Hit chance'
	refresh()
	vape:Clean(HitAccuracy.Children:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
		if vape.ThreadFix then
			setthreadidentity(8)
		end
	
		local newside = HitAccuracy.Children.AbsolutePosition.X > (vape.gui.AbsoluteSize.X / 2)
		holder.AnchorPoint = Vector2.new(newside and 1 or 0, 0)
		holder.Position = UDim2.fromScale(newside and 1 or 0, 0)
	end))
end)
-- END AETHER MODULE: render/HitAccuracy.lua --

-- BEGIN AETHER MODULE: render/ItemESP.lua --
run(function()
    local ItemESP
    local Distance
    local Transparency
    local Scale
    local WhitelistOnly
    local Whitelist = {ListEnabled = {}, Object = nil}

    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local Reference, Strings, Sizes = {}, {}, {}

    local function Added(ent)
	local Name = bedwars.ItemMeta[ent.Name] and bedwars.ItemMeta[ent.Name].displayName or ent.Name
	if WhitelistOnly.Enabled and not table.find(Whitelist.ListEnabled, Name:lower()) then
		return
	end

	Strings[ent] = Name .. '%s'
	if Distance.Enabled then
		Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '.. Strings[ent]
	end

	local nametag = Instance.new('TextLabel')
	nametag.TextSize = 14 * Scale.Value
	nametag.Font = Enum.Font.Arial
	local size = getfontsize(removeTags(ent.Name), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
	nametag.Name = ent.Name
	nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
	nametag.AnchorPoint = Vector2.new(0.5, 1)
	nametag.BackgroundColor3 = Color3.new()
	nametag.BackgroundTransparency = 0.5
	nametag.BorderSizePixel = 0
	nametag.Visible = false
	local amount = ent:GetAttribute('Amount') or 1
	local suffix = amount >= 2 and ' x' .. tostring(amount) or ''
	nametag.Text = Distance.Enabled and string.format(Strings[ent], 0, suffix) or string.format(Strings[ent], suffix)
	nametag.TextColor3 = Color3.new(1, 1, 1)
	nametag.RichText = true
	nametag.Parent = Folder
	Reference[ent] = nametag
    end
    local function Updated(ent)
	if Reference[ent] then
		Reference[ent].TextSize = 14 * Scale.Value
		Reference[ent].BackgroundTransparency = Transparency.Value
	end
    end
    local function Removing(ent)
	if Reference[ent] then
		Reference[ent]:Destroy()
		Reference[ent] = nil
	end
    end

    ItemESP = vape.Categories.Render:CreateModule({
	Name = 'ItemESP',
	Function = function(call)
		if call then
			ItemESP:Clean(collectionService:GetInstanceAddedSignal('ItemDrop'):Connect(Added))
			ItemESP:Clean(collectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(Removing))
			ItemESP:Clean(runService.PreRender:Connect(function()
				for ent, nametag in Reference do
					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.Position + Vector3.new(0, 1, 0))
					nametag.Visible = headVis
					if not headVis then
						continue
					end

					local amount = ent:GetAttribute('Amount') or 1
					local mag = Distance.Enabled and entitylib.isAlive
						and math.floor((entitylib.character.RootPart.Position - ent.Position).Magnitude) or nil
					local cache = tostring(mag or '') .. ':' .. tostring(amount)
					if Sizes[ent] ~= cache then
						local suffix = amount >= 2 and ' x' .. tostring(amount) or ''
						nametag.Text = Distance.Enabled and string.format(Strings[ent], mag or 0, suffix)
							or string.format(Strings[ent], suffix)
						local size = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
						nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
						Sizes[ent] = cache
					end
					nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
				end
			end))

			for _, v in collectionService:GetTagged('ItemDrop') do
				Added(v)
			end
		else
			for i in Reference do
				Removing(i)
			end
		end
	end,
	Tooltip = 'Renders tags dropped items'
    })
    Distance = ItemESP:CreateToggle({
	Name = 'Distance',
	Tooltip = 'Shows the distance of the item',
	Function = function(callback)
		if ItemESP.Enabled then
			for ent in Reference do
				local Name = bedwars.ItemMeta[ent.Name] and bedwars.ItemMeta[ent.Name].displayName or ent.Name
				Strings[ent] = callback and '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '.. Strings[ent] or Name.. '%s'
			end
		end
	end
    })
    ItemESP:CreateToggle({
	Name = 'Group items',
	Tooltip = 'Group items into easier to read tags'
    })
    Transparency = ItemESP:CreateSlider({
	Name = 'Transparency',
	Function = function()
		if ItemESP.Enabled then
			for ent in Reference do
				Updated(ent)
			end
		end
	end,
	Default = 0.5,
	Min = 0,
	Max = 1,
	Decimal = 100
    })
    Scale = ItemESP:CreateSlider({
	Name = 'Scale',
	Default = 1,
	Min = 0.1,
	Max = 1.5,
	Decimal = 10,
	Function = function()
		if ItemESP.Enabled then
			for ent in Reference do
				Updated(ent)
			end
		end
	end
    })
    WhitelistOnly = ItemESP:CreateToggle({
	Name = 'Whitelist Only',
	Tooltip = 'Only renders whitelisted items',
	Function = function(call)
		if Whitelist.Object then
			Whitelist.Object.Visible = call

			if ItemESP.Enabled then
				ItemESP:Toggle()
				ItemESP:Toggle()
			end
		end
	end
    })
    Whitelist = ItemESP:CreateTextList({
	Name = 'Allowed items',
	Visible = false,
	Darker = true,
	Function = function()
		if ItemESP.Enabled then
			ItemESP:Toggle()
			ItemESP:Toggle()
		end
	end
    })
end)
-- END AETHER MODULE: render/ItemESP.lua --

-- BEGIN AETHER MODULE: render/LegacyAnimation.lua --
run(function()
    local LegacyAnimation
    local enabled = false
    local renderConnection = nil
    local lastSetValue = nil
    local CameraMode = { Value = 'Both' }

    local function ensureAttribute()
        local workspace = game:GetService("Workspace")
        if workspace:GetAttribute("RbxLegacyAnimationBlending") == nil then
            workspace:SetAttribute("RbxLegacyAnimationBlending", false)
        end
    end

    local function setLegacyAnimation(value)
        local workspace = game:GetService("Workspace")
        ensureAttribute()
        if lastSetValue ~= value then
            workspace:SetAttribute("RbxLegacyAnimationBlending", value)
            lastSetValue = value
        end
    end

    local function updateLegacyAnimation()
        if not enabled then
            setLegacyAnimation(false)
            return
        end

        local mode = 'Both'
        if CameraMode and CameraMode.Value then
            mode = CameraMode.Value
        end

        local inFirstPerson = isFirstPerson()

        local shouldEnable = false
        if mode == "Both" then
            shouldEnable = true
        elseif mode == "First Person" then
            shouldEnable = inFirstPerson
        elseif mode == "Third Person" then
            shouldEnable = not inFirstPerson
        end

        setLegacyAnimation(shouldEnable)
    end

    LegacyAnimation = vape.Categories.Render:CreateModule({
        Name = 'LegacyAnimation',
        Function = function(callback)
            enabled = callback

            if enabled then
                if not renderConnection then
                    renderConnection = game:GetService("RunService").RenderStepped:Connect(updateLegacyAnimation)
                end
                updateLegacyAnimation()
            else
                if renderConnection then
                    renderConnection:Disconnect()
                    renderConnection = nil
                end
                setLegacyAnimation(false)
            end
        end,
        Tooltip = 'turns on Roblox legacy animation blending'
    })

    CameraMode = LegacyAnimation:CreateDropdown({
        Name = 'Camera Mode',
        List = {'Both', 'First Person', 'Third Person'},
        Default = 'Both',
        Function = function(val)
            CameraMode.Value = val
            updateLegacyAnimation()
        end
    })
end)
-- END AETHER MODULE: render/LegacyAnimation.lua --

-- BEGIN AETHER MODULE: render/LootESP.lua --
run(function()
	local LootESP
	local IronToggle
	local DiamondToggle
	local EmeraldToggle
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local CollectionService = collectionService

	local lootTypes = {
		iron = {
			keywords = {'iron'},
			color = Color3.fromRGB(200, 200, 200),
			icon = 'iron',
			displayName = 'IRON'
		},
		diamond = {
			keywords = {'diamond'},
			color = Color3.fromRGB(85, 200, 255),
			icon = 'diamond',
			displayName = 'DIAMOND'
		},
		emerald = {
			keywords = {'emerald'},
			color = Color3.fromRGB(0, 255, 100),
			icon = 'emerald',
			displayName = 'EMERALD'
		}
	}

	local function getLootType(itemName)
		local nameLower = itemName:lower()
		for lootType, config in pairs(lootTypes) do
			for _, keyword in ipairs(config.keywords) do
				if nameLower:find(keyword, 1, true) then
					return lootType, config
				end
			end
		end
		return nil
	end

	local function isLootEnabled(lootType)
		if lootType == 'iron' then
			return IronToggle.Enabled
		elseif lootType == 'diamond' then
			return DiamondToggle.Enabled
		elseif lootType == 'emerald' then
			return EmeraldToggle.Enabled
		end
		return false
	end

	local function getProperIcon(lootType)
		local icon = bedwars.getIcon({itemType = lootType}, true)

		if not icon or icon == "" then
			return nil
		end

		return icon
	end

	local function Added(lootHandle, lootType, config)
		if not isLootEnabled(lootType) then return end
		if Reference[lootHandle] then return end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = lootType
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(40, 40)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = lootHandle

		local blur = addBlur(billboard)
		blur.Visible = true

		local iconImage = getProperIcon(config.icon)

		if iconImage then
			local image = Instance.new('ImageLabel')
			image.Size = UDim2.fromOffset(40, 40)
			image.Position = UDim2.fromScale(0.5, 0.5)
			image.AnchorPoint = Vector2.new(0.5, 0.5)
			image.BackgroundColor3 = Color3.new(0, 0, 0)
			image.BackgroundTransparency = 0.3
			image.BorderSizePixel = 0
			image.Image = iconImage
			image.Parent = billboard

			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = image
		else
			local frame = Instance.new('Frame')
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.new(0, 0, 0)
			frame.BackgroundTransparency = 0.3
			frame.BorderSizePixel = 0
			frame.Parent = billboard

			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = frame

			local textLabel = Instance.new('TextLabel')
			textLabel.Size = UDim2.fromScale(1, 1)
			textLabel.Position = UDim2.fromScale(0.5, 0.5)
			textLabel.AnchorPoint = Vector2.new(0.5, 0.5)
			textLabel.BackgroundTransparency = 1
			textLabel.Text = config.displayName
			textLabel.TextColor3 = config.color
			textLabel.TextScaled = true
			textLabel.Font = Enum.Font.GothamBold
			textLabel.TextStrokeTransparency = 0.5
			textLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			textLabel.Parent = frame
		end

		Reference[lootHandle] = billboard
	end

	local function Removed(lootHandle)
		if Reference[lootHandle] then
			Reference[lootHandle]:Destroy()
			Reference[lootHandle] = nil
		end
	end

	local function findExistingLoot()
		local tagged = CollectionService:GetTagged('ItemDrop')
		for _, drop in ipairs(tagged) do
			local handle = drop:FindFirstChild('Handle')
			if handle then
				local lootType, config = getLootType(drop.Name)
				if lootType and isLootEnabled(lootType) then
					if not Reference[handle] then
						Added(handle, lootType, config)
					end
				end
			end
		end
	end

	local function refreshLootType(lootType)
		if not LootESP.Enabled then return end

		local enabled = isLootEnabled(lootType)

		if not enabled then
			for handle, billboard in pairs(Reference) do
				if billboard.Name == lootType then
					billboard:Destroy()
					Reference[handle] = nil
				end
			end
		else
			local tagged = CollectionService:GetTagged('ItemDrop')
			for _, drop in ipairs(tagged) do
				local handle = drop:FindFirstChild('Handle')
				if handle then
					local dropLootType, config = getLootType(drop.Name)
					if dropLootType == lootType and not Reference[handle] then
						Added(handle, lootType, config)
					end
				end
			end
		end
	end

	LootESP = vape.Categories.Render:CreateModule({
		Name = 'LootESP',
		Function = function(callback)
			if callback then
				findExistingLoot()

				LootESP:Clean(CollectionService:GetInstanceAddedSignal('ItemDrop'):Connect(function(drop)
					if not LootESP.Enabled then return end

					task.defer(function()
						local handle = drop:FindFirstChild('Handle')
						if not handle then return end

						local lootType, config = getLootType(drop.Name)
						if lootType and isLootEnabled(lootType) then
							Added(handle, lootType, config)
						end
					end)
				end))

				LootESP:Clean(CollectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(function(drop)
					local handle = drop:FindFirstChild('Handle')
					if handle then
						Removed(handle)
					end
				end))

			else
				for handle, billboard in pairs(Reference) do
					billboard:Destroy()
				end
				table.clear(Reference)
			end
		end,
		Tooltip = 'esp for loot (iron, emerald, diamonds)'
	})

	IronToggle = LootESP:CreateToggle({
		Name = 'Iron',
		Function = function(callback)
			refreshLootType('iron')
		end,
		Default = true
	})

	DiamondToggle = LootESP:CreateToggle({
		Name = 'Diamond',
		Function = function(callback)
			refreshLootType('diamond')
		end,
		Default = true
	})

	EmeraldToggle = LootESP:CreateToggle({
		Name = 'Emerald',
		Function = function(callback)
			refreshLootType('emerald')
		end,
		Default = true
	})
end)
-- END AETHER MODULE: render/LootESP.lua --

-- BEGIN AETHER MODULE: render/NameTags.lua --
run(function()
    local NameTags
    local Targets
    local Color
    local Background
    local DisplayName
    local Health
    local Distance
    local Equipment
    local Rank
    local Enchant
    local DrawingToggle
    local Scale
    local FontOption
    local Teammates
    local DistanceCheck
    local DistanceLimit
    local Strings, Sizes, Reference = {}, {}, {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    local methodused

    local Added = {
	Normal = function(ent)
		if not Targets.Players.Enabled and ent.Player then
			return
		end
		if not Targets.NPCs.Enabled and ent.NPC then
			return
		end
		if Teammates.Enabled and not ent.Targetable and not ent.Friend then
			return
		end

		local nametag = Instance.new('TextLabel')
		Strings[ent] = ent.Player
				and whitelist:tag(ent.Player, true, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
			or ent.Character.Name

		if Health.Enabled then
			local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
			Strings[ent] = Strings[ent]
				.. ' <font color="rgb('
				.. tostring(math.floor(healthColor.R * 255))
				.. ','
				.. tostring(math.floor(healthColor.G * 255))
				.. ','
				.. tostring(math.floor(healthColor.B * 255))
				.. ')">'
				.. math.round(ent.Health)
				.. '</font>'
		end

		if Distance.Enabled then
			Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '
				.. Strings[ent]
		end

		if Equipment.Enabled then
			for i, v in {'Hand', 'Helmet', 'Chestplate', 'Boots', 'Kit'} do
				local Icon = Instance.new('ImageLabel')
				Icon.Name = v
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
				Icon.BackgroundTransparency = 1
				Icon.Image = ''
				Icon.Parent = nametag
			end
		end

		nametag.TextSize = 14 * Scale.Value
		nametag.FontFace = FontOption.Value
		local size =
			getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
		nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
		nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
		nametag.AnchorPoint = Vector2.new(0.5, 1)
		nametag.BackgroundColor3 = Color3.new()
		nametag.BackgroundTransparency = Background.Value
		nametag.BorderSizePixel = 0
		nametag.Visible = false
		nametag.Text = Strings[ent]
		nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		nametag.RichText = true
		nametag.Parent = Folder
		task.spawn(function()
			if Rank.Enabled and ent.Player then
				local Icon = Instance.new('ImageLabel')
				Icon.Name = 'RankIcon'
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(size.X + 10, -4)
				Icon.BackgroundTransparency = 1
				Icon.Image = store.rank[ent.Player]:async() and bedwars.RankMeta[store.rank[ent.Player]:async()].image
					or ''
				Icon.Parent = nametag
			end
		end)
		task.spawn(function()
			if Enchant.Enabled and ent.Player then
				local Icon = Instance.new('ImageLabel')
				Icon.Name = 'EnchantIcon'
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(-30, -4)
				Icon.BackgroundTransparency = 1
				Icon.Image = store.enchants[ent.Player]:async() or ''
				Icon.Parent = nametag
			end
		end)
		Reference[ent] = nametag
	end,
	Drawing = function(ent)
		if not Targets.Players.Enabled and ent.Player then
			return
		end
		if not Targets.NPCs.Enabled and ent.NPC then
			return
		end
		if Teammates.Enabled and not ent.Targetable and not ent.Friend then
			return
		end

		local nametag = {}
		nametag.BG = Drawing.new('Square')
		nametag.BG.Filled = true
		nametag.BG.Transparency = 1 - Background.Value
		nametag.BG.Color = Color3.new()
		nametag.BG.ZIndex = 1
		nametag.Text = Drawing.new('Text')
		nametag.Text.Size = 15 * Scale.Value
		nametag.Text.Font = 0
		nametag.Text.ZIndex = 2
		Strings[ent] = ent.Player
				and whitelist:tag(ent.Player, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
			or ent.Character.Name

		if Health.Enabled then
			Strings[ent] = Strings[ent] .. ' ' .. math.round(ent.Health)
		end

		if Distance.Enabled then
			Strings[ent] = '[%s] ' .. Strings[ent]
		end

		nametag.Text.Text = Strings[ent]
		nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
		Reference[ent] = nametag
	end,
    }

    local Removed = {
	Normal = function(ent)
		local v = Reference[ent]
		if v then
			Reference[ent] = nil
			Strings[ent] = nil
			Sizes[ent] = nil
			v:Destroy()
		end
	end,
	Drawing = function(ent)
		local v = Reference[ent]
		if v then
			Reference[ent] = nil
			Strings[ent] = nil
			Sizes[ent] = nil
			for _, obj in v do
				pcall(function()
					obj.Visible = false
					obj:Remove()
				end)
			end
		end
	end,
    }

    local Updated = {
	Normal = function(ent)
		local nametag = Reference[ent]
		if nametag then
			Sizes[ent] = nil
			Strings[ent] = ent.Player
					and whitelist:tag(ent.Player, true, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
				or ent.Character.Name

			if Health.Enabled then
				local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
				Strings[ent] = Strings[ent]
					.. ' <font color="rgb('
					.. tostring(math.floor(healthColor.R * 255))
					.. ','
					.. tostring(math.floor(healthColor.G * 255))
					.. ','
					.. tostring(math.floor(healthColor.B * 255))
					.. ')">'
					.. math.round(ent.Health)
					.. '</font>'
			end

			if Distance.Enabled then
				Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '
					.. Strings[ent]
			end

			if Equipment.Enabled and store.inventories[ent.Player] then
				local kit = ent.Player:GetAttribute('PlayingAsKit')
				local inventory = store.inventories[ent.Player]
				nametag.Hand.Image = bedwars.getIcon(inventory.hand or {itemType = ''}, true)
				nametag.Helmet.Image = bedwars.getIcon(inventory.armor[4] or {itemType = ''}, true)
				nametag.Chestplate.Image = bedwars.getIcon(inventory.armor[5] or {itemType = ''}, true)
				nametag.Boots.Image = bedwars.getIcon(inventory.armor[6] or {itemType = ''}, true)
				nametag.Kit.Image = kit and bedwars.BedwarsKitMeta[kit].renderImage or ''
			end

			if Enchant.Enabled and nametag:FindFirstChild('EnchantIcon') then
				nametag.EnchantIcon.Image = store.enchants[ent.Player]:async() or ''
			end

			local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.Text = Strings[ent]
		end
	end,
	Drawing = function(ent)
		local nametag = Reference[ent]
		if nametag then
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			Sizes[ent] = nil
			Strings[ent] = ent.Player
					and whitelist:tag(ent.Player, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
				or ent.Character.Name

			if Health.Enabled then
				Strings[ent] = Strings[ent] .. ' ' .. math.round(ent.Health)
			end

			if Distance.Enabled then
				Strings[ent] = '[%s] ' .. Strings[ent]
				nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
			else
				nametag.Text.Text = Strings[ent]
			end

			nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
			nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		end
	end,
    }

    local ColorFunc = {
	Normal = function(hue, sat, val)
		local color = Color3.fromHSV(hue, sat, val)
		for i, v in Reference do
			v.TextColor3 = entitylib.getEntityColor(i) or color
		end
	end,
	Drawing = function(hue, sat, val)
		local color = Color3.fromHSV(hue, sat, val)
		for i, v in Reference do
			v.Text.Color = entitylib.getEntityColor(i) or color
		end
	end,
    }

    local Loop = {
	Normal = function()
		local alive = entitylib.isAlive
		local localPosition = alive and entitylib.character.RootPart.Position
		for ent, nametag in Reference do
			local distance
			if alive and (DistanceCheck.Enabled or Distance.Enabled) then
				distance = (localPosition - ent.RootPart.Position).Magnitude
			end

			if DistanceCheck.Enabled then
				distance = distance or math.huge
				if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
					nametag.Visible = false
					continue
				end
			end

			local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
			nametag.Visible = headVis
			if not headVis then
				continue
			end

			if Distance.Enabled then
				local mag = alive and math.floor(distance) or 0
				if Sizes[ent] ~= mag then
					nametag.Text = string.format(Strings[ent], mag)
					local ize = getfontsize(
						removeTags(nametag.Text),
						nametag.TextSize,
						nametag.FontFace,
						Vector2.new(100000, 100000)
					)
					nametag.Size = UDim2.fromOffset(ize.X + 8, ize.Y + 7)
					Sizes[ent] = mag
				end
			end
			nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
		end
	end,
	Drawing = function()
		local alive = entitylib.isAlive
		local localPosition = alive and entitylib.character.RootPart.Position
		for ent, nametag in Reference do
			local distance
			if alive and (DistanceCheck.Enabled or Distance.Enabled) then
				distance = (localPosition - ent.RootPart.Position).Magnitude
			end

			if DistanceCheck.Enabled then
				distance = distance or math.huge
				if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
					nametag.Text.Visible = false
					nametag.BG.Visible = false
					continue
				end
			end

			local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
			nametag.Text.Visible = headVis
			nametag.BG.Visible = headVis
			if not headVis then
				continue
			end

			if Distance.Enabled then
				local mag = alive and math.floor(distance) or 0
				if Sizes[ent] ~= mag then
					nametag.Text.Text = string.format(Strings[ent], mag)
					nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
					Sizes[ent] = mag
				end
			end
			nametag.BG.Position = Vector2.new(headPos.X - (nametag.BG.Size.X / 2), headPos.Y - nametag.BG.Size.Y)
			nametag.Text.Position = nametag.BG.Position + Vector2.new(4, 3)
		end
	end,
    }

    NameTags = vape.Categories.Render:CreateModule({
	Name = 'NameTags',
	Function = function(callback)
		if callback then
			methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
			if Removed[methodused] then
				NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
			end
			if Added[methodused] then
				for _, v in entitylib.List do
					if Reference[v] then
						Removed[methodused](v)
					end
					Added[methodused](v)
				end
				NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
					if Reference[ent] then
						Removed[methodused](ent)
					end
					Added[methodused](ent)
				end))
			end
			if Updated[methodused] then
				NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
				for _, v in entitylib.List do
					Updated[methodused](v)
				end
			end
			if ColorFunc[methodused] then
				NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
					ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
				end))
			end
			if Loop[methodused] then
				NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
			end
		else
			if Removed[methodused] then
				for i in Reference do
					Removed[methodused](i)
				end
			end
		end
	end,
	Tooltip = 'Renders nametags on entities through walls'
    })
    Targets = NameTags:CreateTargets({
	Players = true,
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    FontOption = NameTags:CreateFont({
