-- BEGIN AETHER MODULE: render/NameTagSpoofer.lua --
run(function()
	local NameTagSpoofer
	local CustomNameBox
	local trackedElements = setmetatable({}, {__mode = 'k'})
	local trackedUsernames = setmetatable({}, {__mode = 'k'})
	local hiddenLabels = setmetatable({}, {__mode = 'k'})
	local watched = setmetatable({}, {__mode = 'k'})
	local applying = setmetatable({}, {__mode = 'k'})

	local function getCustomName()
		if CustomNameBox and type(CustomNameBox.Value) == "string" and CustomNameBox.Value ~= "" then
			return CustomNameBox.Value
		end
		return "Me"
	end

	local function containsLocalName(text)
		return type(text) == 'string' and (text:find(lplr.Name, 1, true) ~= nil
			or text:find(lplr.DisplayName, 1, true) ~= nil)
	end

	local function setText(element, value)
		if not element.Parent or element.Text == value then return end
		applying[element] = true
		element.Text = value
		applying[element] = nil
	end

	local applyObject
	local function watchText(element)
		if watched[element] then return end
		watched[element] = true
		NameTagSpoofer:Clean(element:GetPropertyChangedSignal('Text'):Connect(function()
			if NameTagSpoofer.Enabled and not applying[element] then applyObject(element) end
		end))
	end

	applyObject = function(element)
		if not element or not element.Parent then return end
		if element:IsA('TextLabel') and table.find({'PlayerName', 'EntityName', 'DisplayName'}, element.Name) then
			watchText(element)
			local original = trackedElements[element]
			if original then
				if containsLocalName(element.Text) then original.Text = element.Text end
				setText(element, getCustomName())
			elseif containsLocalName(element.Text) then
				trackedElements[element] = {Text = element.Text}
				setText(element, getCustomName())
			end
		elseif element:IsA('TextBox') and element.Name == 'PlayerUsername' then
			watchText(element)
			local original = trackedUsernames[element]
			if original then
				if containsLocalName(element.Text) then original.Text = element.Text end
				setText(element, '@'..getCustomName())
			elseif containsLocalName(element.Text) then
				trackedUsernames[element] = {Text = element.Text}
				setText(element, '@'..getCustomName())
			end
		elseif element:IsA('TextLabel') and element.Name == '@'
			and element.Parent and element.Parent.Name == 'PlayerUsername' then
			if hiddenLabels[element] == nil then hiddenLabels[element] = element.Visible end
			element.Visible = false
		end
	end

	local function processRoot(root)
		if not root then return end
		applyObject(root)
		for _, descendant in root:GetDescendants() do applyObject(descendant) end
	end

	local function attachCharacter(character)
		if not character then return end
		processRoot(character)
		NameTagSpoofer:Clean(character.DescendantAdded:Connect(applyObject))
	end

	local function restore()
		for element, original in trackedElements do
			if element.Parent then pcall(setText, element, original.Text) end
		end
		for element, original in trackedUsernames do
			if element.Parent then pcall(setText, element, original.Text) end
		end
		for element, visible in hiddenLabels do
			if element.Parent then pcall(function() element.Visible = visible end) end
		end
		table.clear(trackedElements)
		table.clear(trackedUsernames)
		table.clear(hiddenLabels)
		table.clear(watched)
		table.clear(applying)
	end

	NameTagSpoofer = vape.Categories.Render:CreateModule({
		Name = 'NameTagSpoofer',
		Function = function(callback)
			if callback then
				processRoot(lplr.PlayerGui)
				attachCharacter(lplr.Character)
				NameTagSpoofer:Clean(lplr.PlayerGui.DescendantAdded:Connect(applyObject))
				NameTagSpoofer:Clean(lplr.CharacterAdded:Connect(attachCharacter))
				NameTagSpoofer:Clean(restore)
			else
				restore()
			end
		end,
		Tooltip = 'Customize your name in various places'
	})

	CustomNameBox = NameTagSpoofer:CreateTextBox({
		Name = 'Custom Name',
		Default = 'Me',
		Placeholder = 'Enter name...',
		Function = function()
			if not NameTagSpoofer.Enabled then return end
			for element in trackedElements do if element.Parent then setText(element, getCustomName()) end end
			for element in trackedUsernames do if element.Parent then setText(element, '@'..getCustomName()) end end
		end
	})
end)
-- END AETHER MODULE: render/NameTagSpoofer.lua --

-- BEGIN AETHER MODULE: render/NoBob.lua --
run(function()
    local NoBob
    local oldPlayAnimation

    local function refreshViewmodel()
        pcall(function()
            bedwars.InventoryViewmodelController:handleStore(
                bedwars.Store:getState()
            )
        end)
    end

    NoBob = vape.Categories.Render:CreateModule({
        Name = 'NoBob',
        Function = function(callback)
            if callback then
                oldPlayAnimation = bedwars.ViewmodelController.playAnimation

                bedwars.ViewmodelController.playAnimation = function(self, animationType, ...)
                    if animationType == bedwars.AnimationType.FP_WALK then
                        return
                    end

                    return oldPlayAnimation(self, animationType, ...)
                end

                -- Rebuild the held-item viewmodel so an already-playing
                -- walking animation is cleared immediately.
                refreshViewmodel()
            else
                if oldPlayAnimation then
                    bedwars.ViewmodelController.playAnimation = oldPlayAnimation
                    oldPlayAnimation = nil
                end

                -- Restore the normal BedWars viewmodel state.
                refreshViewmodel()
            end
        end,
        Tooltip = 'Removes the sword bob animation while moving'
    })
end)
-- END AETHER MODULE: render/NoBob.lua --

-- BEGIN AETHER MODULE: render/OG4v4v4v4.lua --
run(function()
	local OG4v4v4v4
	local OldMaterials = {}
	local OldColors = {}
	local oldTexture = {}
	local oldColor = {}
	local deletedNumTeamMembers = {}

	local worldFolder = getWorldFolder()
	if not worldFolder then return end
	local blocks = worldFolder:FindFirstChild('Blocks')
	if not blocks then return end

	local function isValidWoolBlock(obj)
		if not obj:IsA("BasePart") then
			return false
		end
		if obj.Name ~= "wool_orange" and obj.Name ~= "wool_pink" then
			return false
		end
		local parent = obj.Parent
		if parent then
			if parent.Name == "Viewmodel" or parent.Parent and parent.Parent.Name == "Viewmodel" then
				return false
			end

			if parent:IsA("Accessory") or parent:IsA("Tool") then
				return false
			end

			local ancestor = parent
			while ancestor do
				if ancestor:IsA("Model") and playersService:GetPlayerFromCharacter(ancestor) then
					return false
				end
				ancestor = ancestor.Parent
			end
		end

		return true
	end

	local function removeNumTeamMembers(gui)
		if not gui then return end

		local topBarApp = gui:FindFirstChild("TopBarApp")
		if not topBarApp then return end

		local frame5 = topBarApp:FindFirstChild("5")
		if not frame5 then return end

		local frame4 = frame5:FindFirstChild("4")
		if not frame4 then return end

		for _, frameName in pairs({"2", "3", "4", "5"}) do
			local targetFrame = frame4:FindFirstChild(frameName)
			if targetFrame and targetFrame:IsA("Frame") then
				local numLabel = targetFrame:FindFirstChild("NumTeamMembers")
				if numLabel and numLabel:IsA("TextLabel") then
					deletedNumTeamMembers[numLabel] = {
						Parent = numLabel.Parent,
						Name = numLabel.Name,
						Text = numLabel.Text,
						Position = numLabel.Position,
						Size = numLabel.Size,
						Visible = numLabel.Visible
					}
					numLabel:Destroy()
				end
			end
		end
	end

	local function restoreNumTeamMembers()
		for label, data in pairs(deletedNumTeamMembers) do
			if data.Parent and data.Parent.Parent then
				local newLabel = Instance.new("TextLabel")
				newLabel.Name = data.Name
				newLabel.Text = data.Text
				newLabel.Position = data.Position
				newLabel.Size = data.Size
				newLabel.Visible = data.Visible
				newLabel.Parent = data.Parent
			end
		end
		table.clear(deletedNumTeamMembers)
	end

