-- BEGIN AETHER MODULE: render/Water.lua --
-- AETHER_MODULE_NAME: Water
-- Water: fills the void with real Roblox water, at exactly the height AntiFall puts its barrier.
--
-- Height comes from AntiFall's own barrier when that module is on, and is worked out the same way
-- (lowest block on the map, minus two) when it is not - so the surface always sits where the
-- barrier does, whether or not you use it.
--
-- Terrain mode is genuine Roblox water: waves, refraction, the lot. It is written locally, so it is
-- yours alone and never replicates. It follows you in slabs and clears the one behind you, because
-- filling a whole BedWars map at once is a lot of voxels for something you only ever see under your
-- feet. Part mode is the cheap version - one plane with the water material and Roblox's own water
-- texture on top - for anywhere terrain writes are unavailable.
run(function()
    local Water
    local Mode
    local Size
    local Depth
    local Waves
    local Color
    local part
    local filled
    local oldWater
    local fx        -- underwater screen effects (ColorCorrection / Blur / SunRays), Realistic mode only
    local oldFog    -- saved Lighting fog, put back the moment you surface
    local submerged -- currently below the water surface

    local function barrierHeight()
        if AntiFallPart and AntiFallPart.Parent then
            return AntiFallPart.Position.Y
        end
        local mag = math.huge
        pcall(function()
            for _, pos in bedwars.BlockController:getStore():getAllBlockPositions() do
                pos = pos * 3
                if pos.Y < mag and not getPlacedBlock(pos + Vector3.new(0, 3, 0)) then
                    mag = pos.Y
                end
            end
        end)
        if mag == math.huge then return nil end
        return mag - 2
    end

    local function clearTerrain()
        if not filled then return end
        pcall(function()
            workspace.Terrain:FillBlock(filled.CFrame, filled.Size, Enum.Material.Air)
        end)
        filled = nil
    end

    local function applyWaterLook()
        local terrain = workspace.Terrain
        if not oldWater then
            oldWater = {
                Color = terrain.WaterColor,
                Transparency = terrain.WaterTransparency,
                Reflectance = terrain.WaterReflectance,
                WaveSize = terrain.WaterWaveSize,
                WaveSpeed = terrain.WaterWaveSpeed
            }
        end
        terrain.WaterColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        terrain.WaterTransparency = math.clamp(1 - Color.Opacity, 0, 1)
        terrain.WaterWaveSize = Waves.Enabled and 0.15 or 0
        terrain.WaterWaveSpeed = Waves.Enabled and 12 or 0
    end

    local function restoreWaterLook()
        if not oldWater then return end
        local terrain = workspace.Terrain
        pcall(function()
            terrain.WaterColor = oldWater.Color
            terrain.WaterTransparency = oldWater.Transparency
            terrain.WaterReflectance = oldWater.Reflectance
            terrain.WaterWaveSize = oldWater.WaveSize
            terrain.WaterWaveSpeed = oldWater.WaveSpeed
        end)
        oldWater = nil
    end

    local function makePart(height)
        if part then
            part.Position = Vector3.new(0, height, 0)
            return
        end
        part = Instance.new('Part')
        part.Name = 'AetherWater'
        part.Size = Vector3.new(10000, Depth.Value, 10000)
        part.Position = Vector3.new(0, height, 0)
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Material = Enum.Material.Water
        part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
        part.Parent = workspace
        -- Roblox's own water surface texture on the top face, so Part mode reads as water rather
        -- than as a flat blue slab.
        local texture = Instance.new('Texture')
        texture.Name = 'WaterSurface'
        texture.Face = Enum.NormalId.Top
        texture.Texture = 'rbxasset://textures/water/normal_1.dds'
        texture.StudsPerTileU = 24
        texture.StudsPerTileV = 24
        texture.Transparency = 0.35
        texture.Parent = part
        pcall(function()
            bedwars.QueryUtil:setQueryIgnored(part, true)
        end)
    end

    local function removePart()
        if part then
            part:Destroy()
            part = nil
        end
    end

    ----------------------------------------------------------------------------
    -- Realistic mode. Terrain water, but glassy and reflective, and it comes alive only while you
    -- are actually in it: the look (fog, colour grade, god-rays, sway) and the buoyancy are applied
    -- when your eyes / body go under the surface and taken straight back off when you surface, so
    -- nothing here ever touches the world while you are stood on dry land.
    ----------------------------------------------------------------------------
    local FX_NAME = 'AetherWaterFX'

    local function applyRealisticLook()
        local terrain = workspace.Terrain
        if not oldWater then
            oldWater = {
                Color = terrain.WaterColor,
                Transparency = terrain.WaterTransparency,
                Reflectance = terrain.WaterReflectance,
                WaveSize = terrain.WaterWaveSize,
                WaveSpeed = terrain.WaterWaveSpeed
            }
        end
        terrain.WaterColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        terrain.WaterTransparency = math.clamp(1 - Color.Opacity, 0, 1)
        -- Glassy: reflect the sky and world off the surface, with livelier waves than the flat look.
		terrain.WaterReflectance = Waves.Enabled and 0.18 or 0.08
		terrain.WaterWaveSize = Waves.Enabled and 0.09 or 0.025
		terrain.WaterWaveSpeed = Waves.Enabled and 7 or 2
    end

    local function ensureFX()
        if fx then return end
        fx = {}
        local cc = Instance.new('ColorCorrectionEffect')
        cc.Name = FX_NAME
        cc.Enabled = false
        cc.Parent = lightingService
        fx.cc = cc
        local blur = Instance.new('BlurEffect')
        blur.Name = FX_NAME..'Blur'
        blur.Enabled = false
        blur.Size = 0
        blur.Parent = lightingService
        fx.blur = blur
        local rays = Instance.new('SunRaysEffect')
        rays.Name = FX_NAME..'Rays'
        rays.Enabled = false
        rays.Parent = lightingService
        fx.rays = rays
    end

    local function restoreFog()
        if not oldFog then return end
        pcall(function()
            lightingService.FogStart = oldFog.Start
            lightingService.FogEnd = oldFog.End
            lightingService.FogColor = oldFog.Color
        end)
        oldFog = nil
    end

    -- Came back up (or left Realistic mode): switch the look off and hand the fog back, but keep the
    -- effect instances around so diving straight back in does not churn them.
    local function surfaced()
        if not submerged then return end
        submerged = false
        restoreFog()
        if fx then
            pcall(function()
                fx.cc.Enabled = false
                fx.blur.Enabled = false
                fx.rays.Enabled = false
            end)
        end
    end

    local function removeFX()
        surfaced()
        if fx then
            for _, effect in fx do
                pcall(function() effect:Destroy() end)
            end
            fx = nil
        end
    end

    -- Called every frame while Realistic is on. surface is the top of the water slab.
    local function updateRealistic(surface)
        ensureFX()
        local cam = gameCamera
        local under = cam and cam.CFrame.Position.Y < surface

        if under then
            if not submerged then
                submerged = true
                if not oldFog then
                    oldFog = {Start = lightingService.FogStart, End = lightingService.FogEnd, Color = lightingService.FogColor}
                end
            end
            local col = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
            local sway = 0.5 + 0.5 * math.sin(tick() * 1.4)
            -- Fog closes in the deeper/less clear the water is, so it reads as real water rather
            -- than a blue filter.
            lightingService.FogColor = col
            lightingService.FogStart = 0
            lightingService.FogEnd = 55 + Color.Opacity * 55 + sway * 6
            fx.cc.Enabled = true
            fx.cc.TintColor = col:Lerp(Color3.new(1, 1, 1), 0.05 + 0.04 * sway)
            fx.cc.Brightness = -0.04
            fx.cc.Contrast = 0.12
            fx.cc.Saturation = -0.08
			-- Blur and animated sun rays made this mode both muddy-looking and one
			-- of the most expensive visual modules. Colour/fog provide depth without
			-- adding full-screen render passes.
			fx.blur.Enabled = false
			fx.rays.Enabled = false
        else
            surfaced()
        end

        -- Buoyancy: while your body is under the surface, water drags your speed and floats you back
        -- up, so falling into it feels like water instead of air.
        if entitylib.isAlive then
            local root = entitylib.character.RootPart
            if root and isnetworkowner(root) and root.Position.Y < surface then
                local vel = root.AssemblyLinearVelocity
                local lift = math.clamp(vel.Y * 0.6 + 6, -8, 10)
                root.AssemblyLinearVelocity = Vector3.new(vel.X * 0.85, lift, vel.Z * 0.85)
            end
        end
    end

    local function refresh()
        local height = barrierHeight()
        if not height then return end

        if Mode.Value == 'Part' then
            clearTerrain()
            restoreWaterLook()
            makePart(height)
            part.Size = Vector3.new(10000, Depth.Value, 10000)
            part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
            part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
            return
        end

        removePart()
        if Mode.Value == 'Realistic' then
            applyRealisticLook()
        else
            applyWaterLook()
        end

        local centre = Vector3.new(0, height, 0)
        if entitylib.isAlive then
            local root = entitylib.character.RootPart
            centre = Vector3.new(root.Position.X, height, root.Position.Z)
        end
        -- Voxels are 4 studs, so snap to that grid: an unsnapped fill leaves seams between slabs.
        centre = Vector3.new(math.floor(centre.X / 4) * 4, math.floor(centre.Y / 4) * 4, math.floor(centre.Z / 4) * 4)
        local size = Vector3.new(Size.Value, math.max(Depth.Value, 4), Size.Value)

        if filled and (filled.CFrame.Position - centre).Magnitude < (Size.Value * 0.25) and filled.Size == size then
            return
        end
        clearTerrain()
        local cframe = CFrame.new(centre)
        local ok = pcall(function()
            workspace.Terrain:FillBlock(cframe, size, Enum.Material.Water)
        end)
        if ok then
            filled = {CFrame = cframe, Size = size}
        else
            -- Terrain writes refused: fall back to the plane rather than showing nothing.
            makePart(height)
        end
    end

    Water = (vape.Categories.Visuals or vape.Categories.Render):CreateModule({
        Name = 'Water',
        Function = function(callback)
            if callback then
                repeat task.wait() until (store.matchState ~= 0 and store.map) or not Water.Enabled
                if not Water.Enabled then return end
                Water:Clean(function()
                    clearTerrain()
                    restoreWaterLook()
                    removePart()
                    removeFX()
                end)
                Water:Clean(task.spawn(function()
                    while Water.Enabled do
                        refresh()
                        task.wait(0.5)
                    end
                end))
                -- Realistic mode's look and buoyancy have to react the instant you break the surface,
                -- so they run every frame rather than on the half-second refresh. Idle for the other
                -- modes, and it reverts itself the frame you surface or switch mode away.
				local nextRealisticUpdate = 0
				Water:Clean(runService.Heartbeat:Connect(function()
					if not Water.Enabled or Mode.Value ~= 'Realistic' then
						surfaced()
						return
					end
					if tick() < nextRealisticUpdate then return end
					nextRealisticUpdate = tick() + 0.1
                    local height = barrierHeight()
                    if not height then return end
                    updateRealistic(height + math.max(Depth.Value, 4) / 2)
                end))
            else
                clearTerrain()
                restoreWaterLook()
                removePart()
                removeFX()
            end
        end,
        Tooltip = 'Fills the void with Roblox water at AntiFall\'s barrier height',
        ExtraText = function()
            return Mode.Value
        end
    })
    Mode = Water:CreateDropdown({
        Name = 'Mode',
        List = {'Terrain', 'Part', 'Realistic'},
        Default = 'Terrain',
        Tooltip = 'Terrain - real Roblox water\nPart - one cheap plane across the map\nRealistic - reflective water with underwater effects',
        Function = function()
            if Water.Enabled then
                clearTerrain()
                restoreWaterLook()
                removePart()
                removeFX()
                task.spawn(refresh)
            end
        end
    })
    Size = Water:CreateSlider({
        Name = 'Area',
        Min = 128,
        Max = 2048,
        Default = 768,
        Suffix = ' studs',
        Tooltip = 'How wide a patch of water to keep filled around you, in Terrain mode'
    })
    Depth = Water:CreateSlider({
        Name = 'Depth',
        Min = 4,
        Max = 60,
        Default = 12,
        Suffix = ' studs',
        Tooltip = 'How deep the water goes below the surface'
    })
    Waves = Water:CreateToggle({
        Name = 'Waves',
        Default = true,
        Tooltip = 'Animate the surface. Off gives you a still, flat sheet',
        Function = function()
            if Water.Enabled and Mode.Value == 'Terrain' then
                applyWaterLook()
            end
        end
    })
    Color = Water:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.7,
        Function = function()
            if not Water.Enabled then return end
            if Mode.Value == 'Terrain' then
                applyWaterLook()
            elseif part then
                part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
            end
        end
    })
end)
-- END AETHER MODULE: render/Water.lua --

-- BEGIN AETHER MODULE: utility/AntiEffect.lua --
run(function()
	local AntiEffect
	local Dizzy
	local Fear
	local Vignettes
	local oldvignettes
	
	AntiEffect = vape.Categories.Utility:CreateModule({
		Name = 'AntiEffect',
		Function = function(callback)
			if callback then
				if Dizzy.Enabled then
					runService:UnbindFromRenderStep('dizzy-status')
				end
	
				if Fear.Enabled then
					runService:UnbindFromRenderStep('werewolf-fear-status')
				end
	
				if Vignettes.Enabled then
					oldvignettes = bedwars.VignetteController.enableOnScreenEffects
					bedwars.VignetteController.enableOnScreenEffects = false
					bedwars.VignetteController:destroyAllVignettes()
				end
	
				local added = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(event)
					if event.entityInstance ~= lplr.Character then return end
	
					if Dizzy.Enabled and event.statusEffect == bedwars.StatusEffectMeta.DIZZY then
						runService:UnbindFromRenderStep('dizzy-status')
					end
	
					if Fear.Enabled and event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then
						runService:UnbindFromRenderStep('werewolf-fear-status')
					end
				end)
				AntiEffect:Clean(function()
					added:Destroy()
				end)
			else
				if oldvignettes ~= nil then
					bedwars.VignetteController.enableOnScreenEffects = oldvignettes
					oldvignettes = nil
				end
			end
		end,
		Tooltip = 'Throws away the parts of a debuff the game plays on your own client'
	})
	Dizzy = AntiEffect:CreateToggle({
		Name = 'Dizzy',
		Default = true,
		Tooltip = 'Stops the dizzy toad swinging your walk direction around'
	})
	Fear = AntiEffect:CreateToggle({
		Name = 'Werewolf fear',
		Default = true,
		Tooltip = 'Stops the werewolf tail walking you away from it'
	})
	Vignettes = AntiEffect:CreateToggle({
		Name = 'Vignettes',
		Function = function(callback)
			if AntiEffect.Enabled and callback then
				oldvignettes = bedwars.VignetteController.enableOnScreenEffects
				bedwars.VignetteController.enableOnScreenEffects = false
				bedwars.VignetteController:destroyAllVignettes()
			elseif AntiEffect.Enabled and oldvignettes ~= nil then
				bedwars.VignetteController.enableOnScreenEffects = oldvignettes
				oldvignettes = nil
			end
		end,
		Default = true,
		Tooltip = 'Clears the coloured screen border frozen, decay, soaked, and the rest put over your view'
	})
end)
-- END AETHER MODULE: utility/AntiEffect.lua --

-- BEGIN AETHER MODULE: utility/AntiLasso.lua --
run(function()
    local AntiLasso
    local Chance
    local Check
    local currentConnections = {}
    local currentCharacter
    local activeLasso
    local ignoredLasso
    local lassoVersion = 0
    local returnFilter = RaycastParams.new()
    local returnOverlap = OverlapParams.new()

    returnFilter.FilterType = Enum.RaycastFilterType.Exclude
    returnFilter.RespectCanCollide = true
    returnFilter.IgnoreWater = true
    returnOverlap.FilterType = Enum.RaycastFilterType.Exclude
    returnOverlap.RespectCanCollide = true

    local function disconnectCharacter()
        for _, connection in currentConnections do
            connection:Disconnect()
        end
        table.clear(currentConnections)
        currentCharacter = nil
    end

    local function isFinite(value)
        return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
    end

    local function isFiniteCFrame(value)
        if typeof(value) ~= 'CFrame' then return false end
        for _, component in {value:GetComponents()} do
            if not isFinite(component) then return false end
        end
        return true
    end

    -- What a lasso looks like on a character. The old check only ever accepted a direct child of
    -- the character holding a descendant named exactly 'Rope', which misses the constraint itself
    -- and anything the game renames between updates, so a lasso that carried no 'LassoHooked' tag
    -- was never seen at all.
    local function isLassoPart(inst)
        if inst:IsA('RopeConstraint') then return true end
        local name = inst.Name:lower()
        return name:find('lasso', 1, true) ~= nil or name:find('rope', 1, true) ~= nil
    end

    local function getLassoObject(character)
        for _, descendant in character:GetDescendants() do
            if isLassoPart(descendant) then
                return descendant
            end
        end
    end

    local function hasClearance(character, root, position)
        returnOverlap.FilterDescendantsInstances = {character, gameCamera}
        for _, part in workspace:GetPartBoundsInBox(CFrame.new(position), root.Size * Vector3.new(0.9, 1, 0.9), returnOverlap) do
            local queryIgnored = bedwars.QueryUtil.isQueryIgnored
            if part.CanCollide and not (type(queryIgnored) == 'function' and queryIgnored(bedwars.QueryUtil, part)) then
                return false
            end
        end
        return true
    end

    local function getSafeReturnCFrame(event)
        local character, root, saved = event.character, event.root, event.cframe
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not isFiniteCFrame(saved) or not root.Parent or not humanoid or humanoid.Health <= 0 then return end
        local position = saved.Position
        if position.Y <= workspace.FallenPartsDestroyHeight + 12 then return end

        returnFilter.FilterDescendantsInstances = {character, gameCamera}
        local ground = workspace:Raycast(position + Vector3.yAxis * 3, -Vector3.yAxis * 99, returnFilter)
        if ground and position.Y - ground.Position.Y >= 1 and hasClearance(character, root, position) then
            return saved
        end

        local offsets = {Vector3.zero}
        for radius = 3, 12, 3 do
            for _, direction in {
                Vector3.xAxis,
                -Vector3.xAxis,
                Vector3.zAxis,
                -Vector3.zAxis,
                Vector3.new(1, 0, 1).Unit,
                Vector3.new(1, 0, -1).Unit,
                Vector3.new(-1, 0, 1).Unit,
                Vector3.new(-1, 0, -1).Unit
            } do
                table.insert(offsets, direction * radius)
            end
        end

        local best, bestDistance
        for _, offset in offsets do
            local origin = position + offset + Vector3.yAxis * 12
            local result = workspace:Raycast(origin, -Vector3.yAxis * 72, returnFilter)
            if result and result.Instance.CanCollide then
                local candidate = Vector3.new(origin.X, result.Position.Y + humanoid.HipHeight + root.Size.Y / 2, origin.Z)
                local distance = (candidate - position).Magnitude
                if candidate.Y > workspace.FallenPartsDestroyHeight + 12 and hasClearance(character, root, candidate)
                    and (not bestDistance or distance < bestDistance)
                then
                    best, bestDistance = candidate, distance
                end
            end
        end
        return best and CFrame.new(best) * saved.Rotation or nil
    end

    local function clearLasso(event)
        if activeLasso ~= event then return end
        activeLasso = nil
        if event.root.Parent then
            event.root.Anchored = false
        end
    end

    local function returnPlayer(event, visualReleased)
        if activeLasso ~= event or event.returned or not AntiLasso.Enabled then return false end
        if collectionService:HasTag(event.character, 'LassoHooked') then return false end
        if not visualReleased and getLassoObject(event.character) then return false end
        local root = event.root
        local returnCFrame = getSafeReturnCFrame(event)
        if not returnCFrame or lplr.Character ~= event.character or not entitylib.isAlive or entitylib.character.RootPart ~= root then
            clearLasso(event)
            return true
        end
        event.returned = true
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.CFrame = returnCFrame
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        if activeLasso == event then
            activeLasso = nil
        end
        return true
    end

    local function waitForRelease(event)
        task.spawn(function()
            local visualReleasedAt
            while activeLasso == event and AntiLasso.Enabled and lplr.Character == event.character and event.root.Parent do
                local tagged = collectionService:HasTag(event.character, 'LassoHooked')
                local visual = getLassoObject(event.character)
                if not tagged and not visual then
                    returnPlayer(event)
                    return
                end
                if not tagged then
                    visualReleasedAt = visualReleasedAt or tick()
                    if tick() - visualReleasedAt >= 1 then
                        returnPlayer(event, true)
                        return
                    end
                else
                    visualReleasedAt = nil
                end
                task.wait(0.05)
            end
        end)
    end

    local function startLasso(character, nativeEvent)
        if not AntiLasso.Enabled or character ~= lplr.Character or ignoredLasso == character then return end
        if activeLasso and activeLasso.character == character then
            if not nativeEvent or not activeLasso.releaseSeen then return end
            clearLasso(activeLasso)
        end
        if Random.new(os.clock()):NextNumber(1, 100) > Chance.Value or Check.Enabled and not entitylib.EntityPosition({
            Range = 50,
            Part = 'RootPart',
            Players = true
        }) then
            if nativeEvent then ignoredLasso = character end
            return
        end
        local root = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not root or not humanoid or humanoid.Health <= 0 or not isFiniteCFrame(root.CFrame) then return end
        if activeLasso then clearLasso(activeLasso) end
        lassoVersion += 1
        local event = {
            cframe = root.CFrame,
            character = character,
            root = root,
            token = lassoVersion
        }
        activeLasso = event
        root.Anchored = true
        waitForRelease(event)
    end

    local function releaseLasso(character)
        if ignoredLasso == character then
            ignoredLasso = nil
            return
        end
        local event = activeLasso
        if not event or event.character ~= character then return end
        event.releaseSeen = true
        task.defer(function()
            local deadline = tick() + 1
            repeat
                if activeLasso ~= event or returnPlayer(event) then return end
                task.wait()
            until tick() >= deadline
            returnPlayer(event, true)
        end)
    end

    local function Added(character)
        local previousCharacter = currentCharacter
        disconnectCharacter()
        if previousCharacter ~= character then ignoredLasso = nil end
        if not AntiLasso.Enabled or not character or not character.Parent then return end
        if activeLasso then clearLasso(activeLasso) end
        currentCharacter = character
        -- DescendantAdded, not ChildAdded. The rope is built under the object the game parents to
        -- the character, so at the instant ChildAdded fired that object was still empty and the
        -- lasso went unnoticed every time - which, on a build that no longer tags the character,
        -- left the module with nothing to react to at all.
        table.insert(currentConnections, character.DescendantAdded:Connect(function(descendant)
            if isLassoPart(descendant) then
                startLasso(character)
            end
        end))
        table.insert(currentConnections, character.Destroying:Connect(function()
            if currentCharacter == character then
                disconnectCharacter()
            end
            if activeLasso and activeLasso.character == character then
                clearLasso(activeLasso)
            end
        end))
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if humanoid then
            table.insert(currentConnections, humanoid.Died:Connect(function()
                if activeLasso and activeLasso.character == character then
                    clearLasso(activeLasso)
                end
            end))
        end
        if collectionService:HasTag(character, 'LassoHooked') or getLassoObject(character) then
            startLasso(character, collectionService:HasTag(character, 'LassoHooked'))
        end
    end

    AntiLasso = vape.Categories.Utility:CreateModule({
        Name = 'AntiLasso',
        Function = function(callback)
            if callback then
                AntiLasso:Clean(collectionService:GetInstanceAddedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        startLasso(character, true)
                    end
                end))
                AntiLasso:Clean(collectionService:GetInstanceRemovedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        releaseLasso(character)
                    end
                end))
                AntiLasso:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
                    task.defer(function()
                        if AntiLasso.Enabled and ent and ent.Character then
                            Added(ent.Character)
                        end
                    end)
                end))
                AntiLasso:Clean(lplr.OnTeleport:Connect(function()
                    if activeLasso then clearLasso(activeLasso) end
                    ignoredLasso = nil
                    disconnectCharacter()
                end))
                if entitylib.isAlive then
                    Added(lplr.Character)
                end
            else
                lassoVersion += 1
                ignoredLasso = nil
                disconnectCharacter()
                if activeLasso then clearLasso(activeLasso) end
            end
        end,
        Tooltip = 'Prevents you from getting pulled by lasso projectile'
    })

    Chance = AntiLasso:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    Check = AntiLasso:CreateToggle({Name = 'Only when targeting'})
end)
-- END AETHER MODULE: utility/AntiLasso.lua --

-- BEGIN AETHER MODULE: utility/AntiSuffocate.lua --
run(function()
    local AntiSuffocate
    local Mode

    -- Burial check. Push mode needs the player fully buried (body plus the
    -- cells above and below) before nudging, but TP mode must also fire when
    -- only part of the body is inside a block - most importantly legs-only
    -- suffocation, where the body/head cells are still free.
    local function isSolidBlock(block)
		return block and block:IsA('BasePart') and block.CanCollide and block.CanQuery
			and block.Transparency < 1 and block.Size.Magnitude > 0
	end

    local function isSuffocating(root, mode)
        local body = getPlacedBlock(root.Position)
        local head = getPlacedBlock(root.Position + Vector3.new(0, 2, 0))
        local legs = getPlacedBlock(root.Position - Vector3.new(0, 2, 0))
		body, head, legs = isSolidBlock(body), isSolidBlock(head), isSolidBlock(legs)
        if mode == 'TP' then
            return (body or legs) and true or false
        end
        return (body and head and legs) and true or false
    end

    -- TP mode: pop straight up to the top of the block column we are stuck in so our
    -- feet rest on the highest ground with nothing above our head.
    local function teleportOut(root)
        local hip = entitylib.character.HipHeight or 2.5
        local base = root.Position
        for step = 1, 26 do
            local probe = base + Vector3.new(0, step, 0)
            local ground = getPlacedBlock(probe - Vector3.new(0, 2, 0))
            if isSolidBlock(ground) and not isSolidBlock(getPlacedBlock(probe)) and not isSolidBlock(getPlacedBlock(probe + Vector3.new(0, 2, 0))) then
                local topY = ground.Position.Y + ground.Size.Y / 2
                root.CFrame = CFrame.new(base.X, topY + hip + 0.1, base.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                return true
            end
        end
    end

    AntiSuffocate = vape.Categories.Utility:CreateModule({
	Name = 'AntiSuffocate',
	Function = function(call)
		if call then
			repeat
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					if isSuffocating(root, Mode.Value) then
						if Mode.Value == 'TP' then
							teleportOut(root)
						else
							root.CFrame += Vector3.new(0, 0.5, 0)
							if root.AssemblyLinearVelocity.Y < -1 then
								root.AssemblyLinearVelocity = Vector3.zero
							end
						end
					end
				end
				task.wait()
			until not AntiSuffocate.Enabled
		end
	end,
	Tooltip = 'Prevents you from suffocating in blocks',
    })
    Mode = AntiSuffocate:CreateDropdown({
	Name = 'Mode',
	List = {'Push', 'TP'},
	Default = 'Push',
	Tooltip = 'Push nudges you up while fully buried. TP jumps you to the top and also fires on partial burials'
    })
end)
-- END AETHER MODULE: utility/AntiSuffocate.lua --

-- BEGIN AETHER MODULE: utility/AutoBalloon.lua --
run(function()
    local AutoBalloon

    AutoBalloon = vape.Categories.Utility:CreateModule({
        Name = 'AutoBalloon',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoBalloon.Enabled)
                if not AutoBalloon.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        if entitylib.character.RootPart.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) < 3 then
                            local balloon = getItem('balloon')
                            if balloon then
                                for _ = 1, 3 do
                                    bedwars.BalloonController:inflateBalloon()
                                end
                            end
                            task.wait(0.1)
                        end
                    end
                    task.wait(0.1)
                until not AutoBalloon.Enabled
            end
        end,
        Tooltip = 'Inflates when you fall into the void'
    })
end)
-- END AETHER MODULE: utility/AutoBalloon.lua --

-- BEGIN AETHER MODULE: utility/AutoHonor.lua --
run(function()
    local AutoHonor
    local Delay

    -- BedWars lets you hand out two honors, so that cap stays - but it is a cap PER MATCH.
    local MAX_HONORS = 2
    local Honored = {}
    local honoring = false

    local function teamOf(plr)
        local ok, team = pcall(function()
            return plr:GetAttribute('Team')
        end)
        return ok and team or nil
    end

    local function honor()
        -- Re-entrancy guard: a final kill and the match ending can land in the same moment, and two
        -- overlapping passes used to spend both honors on the same player.
        if honoring or #Honored >= MAX_HONORS then return end
        honoring = true

        -- Candidates are collected by hand rather than sorting entitylib.List directly. That list
        -- also holds NPCs, monsters and drones, which have no .Player - and the old comparator
        -- indexed .Player on both sides without checking, so a single NPC anywhere in the game threw
        -- inside table.sort and took the entire honor down. That is the "sometimes it just doesn't
        -- work": nothing was broken about honoring, the list walk never got to it.
        local team = teamOf(lplr)
        local list = {}
        for _, ent in entitylib.List do
            local plr = ent.Player
            if plr and plr ~= lplr and plr.Parent and not table.find(Honored, plr) then
                table.insert(list, plr)
            end
        end

        -- Teammates first, keyed off a precomputed flag so the comparator is total and cannot
        -- error on a player whose team attribute disappears mid-sort.
        local mate = {}
        for _, plr in list do
            mate[plr] = team ~= nil and teamOf(plr) == team
        end
        table.sort(list, function(a, b)
            return mate[a] and not mate[b]
        end)

        -- The server refuses an honor sent in the same frame as the death that unlocked it, so
        -- settle first and wait out the delay BEFORE each attempt rather than after it.
        task.wait(0.2)
        for _, plr in list do
            if #Honored >= MAX_HONORS then break end
            if Delay.Value > 0 then
                task.wait(Delay.Value)
            end
            if plr.Parent and bedwars.HonorController then
                local sent = false
                for _ = 1, 3 do
                    sent = pcall(function()
                        bedwars.HonorController:honorPlayer(plr.UserId)
                    end)
                    if sent then break end
                    task.wait(0.15)
                end
                if sent then
                    table.insert(Honored, plr)
                end
            end
        end

        honoring = false
    end

    AutoHonor = vape.Categories.Utility:CreateModule({
        Name = 'AutoHonor',
        Function = function(callback)
            if callback then
                table.clear(Honored)
                honoring = false
                AutoHonor:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill and deathTable.entityInstance == lplr.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
                        task.spawn(honor)
                    end
                end))
                -- honor() waits internally, so it must not run ON the event thread: a yield inside a
                -- BindableEvent handler is what stopped the match-end honor from finishing.
                AutoHonor:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
                    task.spawn(honor)
                end))
                -- The two-honor cap is per match, so clear the record whenever a new one starts.
                -- Without this the module honored twice and then sat dead for the rest of the
                -- session, which looked exactly like it had stopped working.
                task.spawn(function()
                    local lastState = store.matchState
                    while AutoHonor.Enabled do
                        if store.matchState ~= lastState then
                            if store.matchState ~= 2 and lastState == 2 then
                                table.clear(Honored)
                            end
                            lastState = store.matchState
                        end
                        task.wait(1)
                    end
                end)
            end
        end,
        Tooltip = 'Honors two players when you are finally killed or the match ends'
    })

    Delay = AutoHonor:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 2,
        Decimal = 100,
        Suffix = 'seconds',
        Default = 0.1,
        Tooltip = 'Extra wait before each honor. Raise it if the server is still refusing them'
    })
end)
-- END AETHER MODULE: utility/AutoHonor.lua --

-- BEGIN AETHER MODULE: utility/AutoPearl.lua --
run(function()
    local AutoPearl
    local Legit
    local Back
    local Check
    local LandCheck
    local BackDelay
    local Limit

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Include
    local projectileRemote = {InvokeServer = function(self, ...) end}
    task.spawn(function()
	projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function firePearl(pos, spot, item)
	if Check.Enabled then
		for _, v in store.selfProjectiles do
			if v.Name == 'telepearl' then
				return
			end
		end
	end
	local hotbar, old = getHotbar(item.tool), store.hand

	switchItem(item.tool)
	if Legit.Enabled and hotbar then
		hotbarSwitch(hotbar)
	end

	local meta = bedwars.ProjectileMeta.telepearl
	local calc = prediction.SolveTrajectory(pos, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0)
	local landed = false

	if calc then
		local dir = CFrame.lookAt(pos, calc).LookVector * meta.launchVelocity
		local projectile = bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', pos, nil, dir, {drawDurationSeconds = 1})
		local res = projectileRemote:InvokeServer(
			item.tool,
			'telepearl',
			'telepearl',
			pos,
			pos,
			dir,
			httpService:GenerateGUID(true),
			{
                    drawDurationSeconds = 1,
                    shotId = httpService:GenerateGUID(false)
                },
			workspace:GetServerTimeNow() - 0.045
		)
		task.spawn(function()
			repeat
				task.wait()
			until not projectile or not projectile.Parent
			landed = true
		end)
		if res then
			pcall(function()
				res.Parent = replicatedStorage
			end)
		end
	end

	if Back.Enabled and LandCheck.Enabled then
		repeat
			task.wait()
		until landed
	end
	if Back.Enabled and old and old.tool then
		task.wait(BackDelay:GetRandomValue())
		switchItem(old.tool)
		if Legit.Enabled and getHotbar(old.tool) then
			hotbarSwitch(getHotbar(old.tool))
		end
	end
    end

    local function findNearGround(origin)
	for _, v in {Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do
		for i = 1, 24 do
			local ray = workspace:Raycast((origin.Position + (Vector3.yAxis * 3)) + (v * i), Vector3.new(0, -60, 0), rayCheck)
			if ray then
				return ray.Position
			end
		end
	end
	return nil
    end

    AutoPearl = vape.Categories.Utility:CreateModule({
	Name = 'AutoPearl',
	Function = function(callback)
		if callback then
			local check, lasty
			repeat
				if entitylib.isAlive and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == 'telepearl') then
					local root = entitylib.character.RootPart
					local pearl = getItem('telepearl')
					rayCheck.FilterDescendantsInstances = {store.map}
					rayCheck.CollisionGroup = root.CollisionGroup

					if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
						lasty = root.CFrame
					end

					if pearl and root.Velocity.Y < -100 and not workspace:Raycast(root.Position, Vector3.new(0, -200, 0), rayCheck) then
						if not check then
							check = true
							local ground = findNearGround(root.CFrame + Vector3.new(0, 40, 0)) or findNearGround(lasty and lasty + Vector3.new(0, 5, 0) or root.CFrame)
							if ground then
								firePearl(root.Position, ground, pearl)
							end
						end
					else
						check = false
					end
				end
				task.wait(0.1)
			until not AutoPearl.Enabled
		end
	end,
	Tooltip = 'Automatically throws a pearl onto nearby ground after\nfalling a certain distance'
    })

    Legit = AutoPearl:CreateToggle({
	Name = 'Legit Switch',
	Tooltip = 'Visualizes the switching clientside',
	Default = true
    })
    Back = AutoPearl:CreateToggle({
	Name = 'Switch back',
	Default = true,
	Function = function(callback)
		if BackDelay then
			BackDelay.Object.Visible = callback
		end
		if LandCheck then
			LandCheck.Object.Visible = callback
		end
	end,
	Tooltip = 'Switches back to the last slot before pearl'
    })
    LandCheck = AutoPearl:CreateToggle({
	Name = 'Only after landed',
	Tooltip = 'Only switches back after your pearl landed',
	Darker = true
    })
    Check = AutoPearl:CreateToggle({
	Name = 'Pearl check',
	Tooltip = 'Doesn\'t throw a pearl if you are already pearling',
	Default = true
    })
    BackDelay = AutoPearl:CreateTwoSlider({
	Name = 'Switch Back Delay',
	Min = 0,
	Max = 2,
	DefaultMin = 0.1,
	DefaultMax = 0.2,
	Darker = true
    })
    Limit = AutoPearl:CreateToggle({
	Name = 'Limit to item',
	Tooltip = 'Only throws pearl when holding a pearl'
    })
end)
-- END AETHER MODULE: utility/AutoPearl.lua --

-- BEGIN AETHER MODULE: utility/AutoPlay.lua --
run(function()
	local AutoPlay
	local Random
	
	local function joinQueue()
		if not bedwars.Store:getState().Game.customMatch and bedwars.Store:getState().Party.leader.userId == lplr.UserId and bedwars.Store:getState().Party.queueState == 0 then
			if Random.Enabled then
				local listofmodes = {}
				for i, v in bedwars.QueueMeta do
					if not v.disabled and not v.voiceChatOnly and not v.rankCategory then
						table.insert(listofmodes, i)
					end
				end
				bedwars.QueueController:joinQueue(listofmodes[math.random(1, #listofmodes)])
			else
				bedwars.QueueController:joinQueue(store.queueType)
			end
		end
	end
	
	AutoPlay = vape.Categories.Utility:CreateModule({
		Name = 'AutoPlay',
		Function = function(callback)
			if callback then
				AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
					if deathTable.finalKill and deathTable.entityInstance == lplr.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
						joinQueue()
					end
				end))
				AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(joinQueue))
			end
		end,
		Tooltip = 'Automatically queues after the match ends'
	})
	Random = AutoPlay:CreateToggle({
		Name = 'Random',
		Tooltip = 'Chooses a random mode'
	})
end)
-- END AETHER MODULE: utility/AutoPlay.lua --

-- BEGIN AETHER MODULE: utility/AutoRelease.lua --
run(function()
    local AutoRelease
    local Percentage
    local Delay

    local launchHook, last = nil, 0
    local charge = 0

    AutoRelease = vape.Categories.Utility:CreateModule({
	Name = 'AutoRelease',
	Function = function(call)
		if call then
			launchHook = bedwars.ProjectileLaunchHook:Add('AutoRelease', 20, function(nextLaunch, ...)
				local projmeta = select(2, ...)
				if projmeta and typeof(projmeta) == 'table' then
					charge = (projmeta.velocityMultiplier / 1) * 100
					last = os.clock() + 0.1
				end

				return nextLaunch(...)
			end)

			repeat
				if last > os.clock() and charge >= Percentage.Value then
					task.wait(Delay.Value)
					mouse1click()
					task.wait(0.2)
				end
				task.wait()
			until not AutoRelease.Enabled
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
        Tooltip = 'Automatically releases your projectile source when\nat certain charging percentage'
    })

    Percentage = AutoRelease:CreateSlider({
	Name = 'Percentage',
	Min = 0,
	Max = 100,
	Suffix = '%',
	Default = 100,
    })
    Delay = AutoRelease:CreateSlider({
	Name = 'Release delay',
	Min = 0,
	Max = 5,
	Default = 0.5,
	Decimal = 10,
	Suffix = function(val)
		return val <= 1 and 'sec' or 'secs'
	end,
    })
end)
-- END AETHER MODULE: utility/AutoRelease.lua --

-- BEGIN AETHER MODULE: utility/AutoShoot.lua --
run(function()
	local AutoShoot
	local Targets
	local Check
	local Projectiles
	local UseSophia
	local UseWhim
	local FireRate
	local SwitchDelay

	local fireDelays = {}
	local generation = 0
	local firing
	local projectileRemote
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude

	local function getTarget(origin)
		local facing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
		for _, target in entitylib.AllPosition({
			Origin = origin,
			Part = 'RootPart',
			Range = 22,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10,
			Sort = sortmethods.Distance
		}) do
			local delta = (target.RootPart.Position - origin) * Vector3.new(1, 0, 1)
			if facing.Magnitude == 0 or delta.Magnitude == 0 or facing.Unit:Dot(delta.Unit) >= math.cos(math.rad(60)) then return target end
		end
	end

	local function getDirection(origin, target, projectileMeta)
		local speed = projectileMeta.launchVelocity
		if type(speed) ~= 'number' or speed <= 0 then return end
		if not target then return gameCamera.CFrame.LookVector * speed end
		rayCheck.FilterDescendantsInstances = {lplr.Character, target.Character, gameCamera}
		local gravity = projectileMeta.gravitationalAcceleration or 196.2
		local solution = solveBedwarsProjectile(origin, speed, gravity, target, target.RootPart.Position, {
			RaycastParams = rayCheck,
			Lifetime = projectileMeta.lifetimeSec or 3
		})
		return solution and solution.Velocity or nil
	end

	local function fireOne(data, target, token)
		local item, ammo, projectile, source, projectileMeta = table.unpack(data)
		if token ~= generation or not AutoShoot.Enabled or not entitylib.isAlive or not item.tool or not item.tool.Parent then return false end
		local now = workspace:GetServerTimeNow()
		if (fireDelays[item.itemType] or 0) > now then return false end
		local slot = getHotbar(item.tool)
		if not slot or not hotbarSwitch(slot) then return false end
		task.wait(math.clamp(lplr:GetNetworkPing(), 0, 0.2))
		if token ~= generation or not AutoShoot.Enabled or not entitylib.isAlive then return false end

		local root = entitylib.character.RootPart
		local rootPosition = root.Position
		local velocity = getDirection(rootPosition, target, projectileMeta)
		if not velocity then return false end
		local shootPosition = projectileLaunchOrigin(rootPosition, velocity)
		-- Re-solve from the actual launch offset so close targets do not receive a visibly
		-- different local trajectory from the server request.
		velocity = getDirection(shootPosition, target, projectileMeta) or velocity
		local id = httpService:GenerateGUID(true)
		local draw = {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}
		local created = pcall(bedwars.ProjectileController.createLocalProjectile, bedwars.ProjectileController,
			projectileMeta, ammo, projectile, shootPosition, id, velocity, draw)
		if not created then return false end

		local called, result = pcall(projectileRemote.InvokeServer, projectileRemote,
			item.tool, ammo, projectile, shootPosition, rootPosition, velocity, id, draw,
			workspace:GetServerTimeNow() - 0.045)
		fireDelays[item.itemType] = workspace:GetServerTimeNow() + (source.fireDelaySec or 0) + FireRate:GetRandomValue()
		if not called then return false end
		store.lastProjectileFire = workspace:GetServerTimeNow()
		if target then
			targetinfo.Targets[target] = tick() + 1
			prediction.trackShot(target.RootPart)
		end
		local sounds = source.launchSound
		local sound = type(sounds) == 'table' and #sounds > 0 and sounds[math.random(1, #sounds)] or nil
		if sound then pcall(bedwars.SoundManager.playSound, bedwars.SoundManager, sound) end
		return result ~= false
	end

	local function shoot(token)
		if firing or token ~= generation or not entitylib.isAlive then return end
		firing = token
		local originalSlot = store.hand.tool and getHotbar(store.hand.tool) or nil
		local origin = entitylib.character.RootPart.Position
		local target = getTarget(origin)
		if not Check.Enabled or target then
			for _, data in getProjectiles(Projectiles.ListEnabled, UseSophia.Enabled, UseWhim.Enabled) do
				if token ~= generation or not AutoShoot.Enabled then break end
				local ok, fired = pcall(fireOne, data, target, token)
				if ok and fired then task.wait(SwitchDelay.Value) end
			end
		end
		if token == generation and originalSlot ~= nil then hotbarSwitch(originalSlot) end
		if firing == token then firing = nil end
	end

	AutoShoot = vape.Categories.Utility:CreateModule({
		Name = 'AutoShoot',
		Function = function(enabled)
			generation += 1
			firing = nil
			if not enabled then return end
			local token = generation
			local ok, remote = pcall(function() return bedwars.Client:Get(remotes.FireProjectile).instance end)
			if not ok or not remote or type(remote.InvokeServer) ~= 'function' then
				notif('AutoShoot', 'The projectile remote is unavailable.', 5, 'warning')
				AutoShoot:Toggle()
				return
			end
			projectileRemote = remote
			local lastSwing = bedwars.SwordController.lastSwing or 0
			AutoShoot:Clean(task.spawn(function()
				while AutoShoot.Enabled and token == generation do
					local swing = bedwars.SwordController.lastSwing or 0
					if swing > lastSwing and tick() - swing <= 0.25 then
						lastSwing = swing
						task.spawn(shoot, token)
					else
						lastSwing = math.max(lastSwing, swing)
					end
					task.wait(0.03)
				end
			end))
		end,
		Tooltip = 'Fires compatible projectiles once after each manual sword swing'
	})
	Targets = AutoShoot:CreateTargets({Players = true})
	Check = AutoShoot:CreateToggle({
		Name = 'Target check',
		Default = true,
		Function = function(callback)
			if Targets.Object then Targets.Object.Visible = callback end
		end
	})
	Projectiles = AutoShoot:CreateTextList({Name = 'Projectiles', Default = {'arrow', 'snowball'}})
	UseSophia = AutoShoot:CreateToggle({Name = 'Use sophia', Tooltip = 'Also shoots compatible Sophia frost projectiles'})
	UseWhim = AutoShoot:CreateToggle({Name = 'Use whim', Tooltip = 'Also shoots compatible Whim book projectiles'})
	FireRate = AutoShoot:CreateTwoSlider({Name = 'Fire Rate', Min = 0, Max = 1, DefaultMin = 0.05, DefaultMax = 0.12, Decimal = 100})
	SwitchDelay = AutoShoot:CreateSlider({Name = 'Switch Delay', Min = 0, Max = 1, Decimal = 100, Suffix = 'seconds', Default = 0.02})
end)
-- END AETHER MODULE: utility/AutoShoot.lua --

-- BEGIN AETHER MODULE: utility/AutoToxic.lua --
run(function()
    local AutoToxic
    local GG
    local Delay
    local TrollTriggers
    local trollCooldown = 0
    local Toggles, Lists, said, dead = {}, {}, {}

    -- Actually push a line to chat. Split out so both the message picker below and
    -- the match-end "gg" can share the Delay slider: when Delay > 0 the send is
    -- deferred that many seconds (the message is still chosen now, so the
    -- no-repeat logic is unaffected).
    local function doSend(text)
        if not text or text == '' then return end
        local wait = Delay and Delay.Value or 0
        local function push()
            if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                textChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(text)
            else
                replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, 'All')
            end
        end
        if wait > 0 then
            task.delay(wait, function() pcall(push) end)
        else
            push()
        end
    end

    local function sendMessage(name, obj, default)
        local tab = Lists[name].ListEnabled
        local custommsg = #tab > 0 and tab[math.random(1, #tab)] or default
        if not custommsg then return end
        if #tab > 1 and custommsg == said[name] then
            repeat
                task.wait()
                custommsg = tab[math.random(1, #tab)]
            until custommsg ~= said[name]
        end
        said[name] = custommsg

        custommsg = custommsg and custommsg:gsub('<obj>', obj or '') or ''
        doSend(custommsg)
    end

    AutoToxic = vape.Categories.Utility:CreateModule({
        Name = 'AutoToxic',
        Function = function(callback)
            if callback then
                AutoToxic:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable)
                    if Toggles.BedDestroyed.Enabled and bedTable.brokenBedTeam.id == lplr:GetAttribute('Team') then
                        sendMessage('BedDestroyed', (bedTable.player.DisplayName or bedTable.player.Name), 'how dare you >:( | <obj>')
                    elseif Toggles.Bed.Enabled and bedTable.player.UserId == lplr.UserId then
                        local team = bedwars.QueueMeta[store.queueType].teams[tonumber(bedTable.brokenBedTeam.id)]
                        sendMessage('Bed', team and team.displayName:lower() or 'white', 'nice bed lul | <obj>')
                    end
                end))
                AutoToxic:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill then
                        local killer = playersService:GetPlayerFromCharacter(deathTable.fromEntity)
                        local killed = playersService:GetPlayerFromCharacter(deathTable.entityInstance)
                        if not killed or not killer then return end
                        if killed == lplr then
                            if (not dead) and killer ~= lplr and Toggles.Death.Enabled then
                                dead = true
                                sendMessage('Death', (killer.DisplayName or killer.Name), 'my gaming chair subscription expired :( | <obj>')
                            end
                        elseif killer == lplr and Toggles.Kill.Enabled then
                            sendMessage('Kill', (killed.DisplayName or killed.Name), 'vxp on top | <obj>')
                        end
                    end
                end))
                AutoToxic:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winstuff)
                    if GG.Enabled then
                        doSend('gg')
                    end

                    local myTeam = bedwars.Store:getState().Game.myTeam
                    if myTeam and myTeam.id == winstuff.winningTeamId or lplr.Neutral then
                        if Toggles.Win.Enabled then
                            sendMessage('Win', nil, 'yall garbage')
                        end
                    end
                end))

                -- Troll: watch incoming chat and clap back when another player calls you
                -- a hacker/cheater (or any configured trigger phrase). A short cooldown
                -- stops it spamming when several people pile on at once.
                local function handleIncoming(speakerName, text, speakerUserId)
                    if not (Toggles.Troll and Toggles.Troll.Enabled) or not text or text == '' then return end
                    if speakerUserId and speakerUserId == lplr.UserId then return end
                    if speakerName and speakerName == lplr.Name then return end
                    if tick() < trollCooldown then return end
                    local lower = text:lower()
                    for _, phrase in TrollTriggers.ListEnabled do
                        if phrase ~= '' and lower:find(phrase:lower(), 1, true) then
                            trollCooldown = tick() + 6
                            task.spawn(sendMessage, 'Troll', speakerName, 'mad cause bad | <obj>')
                            break
                        end
                    end
                end

                if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                    AutoToxic:Clean(textChatService.MessageReceived:Connect(function(message)
                        local src = message.TextSource
                        handleIncoming(src and src.Name, message.Text, src and src.UserId)
                    end))
                else
                    AutoToxic:Clean(replicatedStorage.DefaultChatSystemChatEvents.OnMessageDoneFiltering.OnClientEvent:Connect(function(data)
                        if type(data) == 'table' then
                            handleIncoming(data.FromSpeaker, data.Message, nil)
                        end
                    end))
                end
            end
        end,
        Tooltip = 'Says a message after a certain action'
    })
    GG = AutoToxic:CreateToggle({
        Name = 'AutoGG',
        Default = true
    })
    Delay = AutoToxic:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 10,
        Default = 0,
        Decimal = 10,
        Suffix = 's',
        Tooltip = 'How long to wait after the triggering action before sending, 0 for instant'
    })
    for _, v in {'Kill', 'Death', 'Bed', 'BedDestroyed', 'Win'} do
        Toggles[v] = AutoToxic:CreateToggle({
            Name = v..' ',
            Function = function(callback)
                if Lists[v] then
                    Lists[v].Object.Visible = callback
                end
            end
        })
        Lists[v] = AutoToxic:CreateTextList({
            Name = v,
            Darker = true,
            Visible = false
        })
    end
    Toggles.Troll = AutoToxic:CreateToggle({
        Name = 'Troll ',
        Tooltip = 'Detects when someone calls you a hacker/cheater in chat and automatically replies',
        Function = function(callback)
            if TrollTriggers then TrollTriggers.Object.Visible = callback end
            if Lists.Troll then Lists.Troll.Object.Visible = callback end
        end
    })
    TrollTriggers = AutoToxic:CreateTextList({
        Name = 'Troll Triggers',
        Tooltip = 'Phrases said by others that trigger a reply (matched anywhere in their message)',
        Default = {'hacker', 'hacks', 'hacking', 'hax', 'cheater', 'cheating', 'cheat', 'exploiter', 'exploiting', 'aimbot'},
        Darker = true,
        Visible = false
    })
    Lists.Troll = AutoToxic:CreateTextList({
        Name = 'Troll Replies',
        Tooltip = 'Replies to send. <obj> is replaced with the accuser\'s name',
        Default = {'mad cause bad | <obj>', 'skill issue <obj>', 'cry about it <obj>', 'not my fault youre bad', 'imagine losing to a "hacker" lol'},
        Darker = true,
        Visible = false
    })
end)
-- END AETHER MODULE: utility/AutoToxic.lua --

-- BEGIN AETHER MODULE: utility/AutoVoidDrop.lua --
run(function()
    local AutoVoidDrop
    local OwlCheck
    local PearlCheck

    local pearlRay = RaycastParams.new()
    pearlRay.RespectCanCollide = true
    pearlRay.FilterType = Enum.RaycastFilterType.Exclude

    -- Where a telepearl we threw is going to put us. The arc is walked forward in short steps
    -- with a cast between each pair, so the first thing it would hit is the landing. Estimated,
    -- not exact - it only has to answer "is there ground at the end of this", which is the
    -- difference between saving the loot and throwing it into the void for nothing.
    local function pearlLandsOnGround(pearl, lowestpoint)
        local position = pearl.Position
        local velocity = pearl.AssemblyLinearVelocity
        -- A pearl carried by a controller rather than by physics reports no velocity, and there
        -- is nothing to project from. Unknown counts as "keep the loot".
        if velocity.Magnitude < 1 then return true end

        local meta = bedwars.ProjectileMeta.telepearl
        local gravity = (meta and meta.gravitationalAcceleration) or workspace.Gravity
        pearlRay.FilterDescendantsInstances = {lplr.Character, gameCamera, pearl}

        local step = 0.05
        for _ = 1, 120 do
            local nextPosition = position + (velocity * step)
            local result = workspace:Raycast(position, nextPosition - position, pearlRay)
            if result then
                return result.Position.Y > lowestpoint
            end
            if nextPosition.Y < lowestpoint then return false end
            position = nextPosition
            velocity -= Vector3.new(0, gravity * step, 0)
        end
        -- Still airborne after six seconds: no landing found, so it is not saving us.
        return false
    end

    local function pearlWillSave(lowestpoint)
        for _, projectile in store.selfProjectiles do
            if projectile.Parent and projectile.Name == 'telepearl' and pearlLandsOnGround(projectile, lowestpoint) then
                return true
            end
        end
        return false
    end

    AutoVoidDrop = vape.Categories.Utility:CreateModule({
        Name = 'AutoVoidDrop',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
                if not AutoVoidDrop.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        if root.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) <= 0 and not getItem('balloon') then
                            local saved = OwlCheck.Enabled and root:FindFirstChild('OwlLiftForce')
                                or (PearlCheck.Enabled and pearlWillSave(lowestpoint))
                            if not saved then
                                for _, item in {'iron', 'diamond', 'emerald', 'gold'} do
                                    item = getItem(item)
                                    if item then
                                        item = bedwars.Client:Get(remotes.DropItem):CallServer({
                                            item = item.tool,
                                            amount = item.amount
                                        })

                                        if item then
                                            item:SetAttribute('ClientDropTime', tick() + 100)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    task.wait(0.1)
                until not AutoVoidDrop.Enabled
            end
        end,
        Tooltip = 'Drops resources when you fall into the void'
    })
    OwlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Owl check',
        Default = true,
        Tooltip = 'Refuses to drop items if being picked up by an owl'
    })
    PearlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Pearl check',
        Default = true,
        Tooltip = 'Keeps your loot if a telepearl you threw is still in the air and looks like it lands on ground'
    })
end)
-- END AETHER MODULE: utility/AutoVoidDrop.lua --

-- BEGIN AETHER MODULE: utility/BackTrack.lua --
run(function()
    local BackTrack
    local Mode
    local Latency
    local Tick

    BackTrack = vape.Categories.Utility:CreateModule({
        Name = 'BackTrack',
        Function = function(callback)
            if callback then
                repeat
                    local ent = entitylib.EntityPosition({
                        Part = 'RootPart',
                        Range = 22,
                        Players = true,
                        Wallcheck = true,
                    })

                    if ent then
                        if Mode.Value == 'Manual' then
                            setfflag('TargetTimeDelayFacctorTenths', '50000')
                            task.wait(0.05 * Tick.Value)
                            setfflag('TargetTimeDelayFacctorTenths', '20')
                            task.wait(0.05 * Tick.Value)
                        else
                            setfflag('TargetTimeDelayFacctorTenths', tostring(math.floor(20 + (Latency:GetRandomValue() / 20))))
                            task.wait(1)
                        end
                    else
                        setfflag('TargetTimeDelayFacctorTenths', '20')
                    end
                    task.wait()
                until not BackTrack.Enabled
            end
        end,
        Tooltip = 'Lags targets at certain times to increase attack distance'
    })
    getgenv().Backtrack = BackTrack
    Latency = BackTrack:CreateTwoSlider({
        Name = 'Latency',
        Min = 1,
        Max = 500,
        DefaultMin = 50,
        DefaultMax = 120,
        Darker = true,
    })
    Tick = BackTrack:CreateSlider({
        Name = 'Ticks',
        Min = 1,
        Max = 20,
        Default = 5,
        Darker = true,
        Visible = false,
    })
    Mode = BackTrack:CreateDropdown({
        Name = 'Mode',
        List = { 'Manual', 'Lag Based' },
        Default = 'Manual',
        Function = function(val)
            if Latency and Tick then
                Latency.Object.Visible = val == 'Manual'
                Tick.Object.Visible = val == 'Lag Based'
            end
        end,
    })
end)
-- END AETHER MODULE: utility/BackTrack.lua --

-- BEGIN AETHER MODULE: utility/CheatDetector.lua --
run(function()
    -- CheatDetector
    --
    -- Everything here is measured through our own connection, which is the whole problem: what we
    -- see is a lagged, interpolated copy of what the server actually resolved. So every check is
    -- built the same way - a reading only counts when it is impossible rather than merely
    -- surprising, readings taken through bad conditions are thrown away instead of counted, and
    -- nobody is flagged until several independent readings of the same kind have stacked up.
    --
    -- Nothing here looks at what anybody is RUNNING. There is no module list, no remote name and
    -- no signature to keep up to date - every check reads position, timing and replicated state,
    -- which is all a cheat can never hide, because the whole point of a cheat is that the server
    -- and everyone else can see what it did.
    --
    -- One loop does all the polling. Each position-based check is a function fed the same
    -- once-per-tick snapshot of every player rather than its own thread walking the entity list,
    -- so the cost of the module is one pass over the players every tenth of a second no matter
    -- how many checks are ticked on.
    local CheatDetector
    local Toggles = {}

    -- Detections, in the order they are offered. A group with children is a heading: its own
    -- toggle gates the whole family, and the children pick which of them run.
    local GROUPS = {
        {Name = 'Impossible hits', Children = {'Killaura', 'SilentAim', 'HitBoxes', 'Reach'}},
        {Name = 'Blatant modules', Children = {'PlayerAttach', 'AntiDeath', 'Phase', 'Invisible', 'HighJump', 'Speed'}},
        {Name = 'Bypasses', Children = {'NoFallDamage', 'VoidFlight', 'ExtremeSpeed'}},
        {Name = 'AutoKit'},
        {Name = 'Crashers', Children = {'Animation', 'Remote'}},
        {Name = 'Breaker'},
        {Name = 'ProjectileAimbot and Aura'}
    }

    -- Off by default, and deliberately named so nobody leaves it on by accident. Every check below
    -- is written to read somebody else's replicated state, and the local player is normally exempt
    -- from all of them; this lifts that exemption so the detector measures us too. It changes who
    -- is looked at and nothing else - the checks still read behaviour, never which of our own
    -- modules happen to be on, so a flag here means the cheat was actually visible from outside.
    local DETECT_SELF = '[TEST] Detect self'

    -- How often every position-based check gets its sample.
    local POLL_INTERVAL = 0.1
    -- A strike older than this is forgotten. Long enough that a cheat running all match keeps
    -- stacking up, short enough that unrelated anomalies minutes apart never add together.
    local STRIKE_MEMORY = 45
    -- Nothing is measured through a connection worse than this. Above it, event timings and
    -- replicated positions are both fiction and every check would be reading noise. Our own
    -- behaviour is exempt: there is no network between us and our own character.
    local MAX_PING = 0.3
    -- A position step larger than this is streaming, a respawn or a real teleport, never movement.
    local TELEPORT_STEP = 100

    -- Speed. Sprint in this game is 20 studs/s and every legitimate way past that - a potion, a
    -- kit dash, a launch pad - is either a burst that decays within a second or announces itself
    -- through a status effect. So the limit is only a little over sprint, and what makes it safe
    -- is that it has to be HELD: the average has to stay over it across a continuous run of
    -- movement, which a dash, a pounce, a grapple or a knockback cannot do.
    local SPEED_LIMIT = 22
    local SPEED_WINDOW = 1.6
    -- No single sample above this is movement at all - it is a respawn, a streaming pop or a
    -- teleport that did not set the attribute. Counting one of those into a run is how a player
    -- who then simply sprints away gets flagged for it, so a sample this size ends the run.
    local SPEED_SANE = 60

    -- Reach. Every sword in the game swings 14.4 studs or less, so a hit landing past this is
    -- past the weapon whatever is being held. This is the one number that catches an aura built
    -- to fake its own position: the fake goes in the packet, but the body everyone else sees
    -- stays where it really is, and that is what gets measured here.
    local REACH_LIMIT = 15.5

    -- Killaura. No hand clicks faster than this, whatever the CPS cap says.
    local MIN_HUMAN_INTERVAL = 0.1
    -- An aura fires the instant the swing cooldown is up, every time, so the gaps between its
    -- hits stop varying. A hand saturating the same cooldown still scatters by tens of
    -- milliseconds, so the window is deliberately tighter than human jitter.
    local CADENCE_SAMPLES = 6
    local CADENCE_SPREAD = 0.03
    -- Sustained rate. A sword is on a cooldown near three tenths of a second, so even a hand
    -- that never misses and never stops cannot land four a second - which is where this sits,
    -- deliberately above the fastest legitimate weapon rather than at the pace of a fast mouse.
    local BURST_HITS, BURST_WINDOW = 10, 2.5
    -- Aura targeting: hitting this many different players inside the window means the aim moved
    -- between them instantly, which is the one signature clicking quickly cannot produce.
    local SWITCH_VICTIMS, SWITCH_WINDOW = 3, 1.2

    -- PlayerAttach. Riding somebody puts you inside arm's length of them and holds you there,
    -- with the separation barely moving, while the pair of you travel. Getting there is a jump
    -- no run can make.
    local ATTACH_RANGE = 3
    local ATTACH_SAMPLES = 10
    local ATTACH_TRAVEL = 6
    local ATTACH_JITTER = 1.2
    local ATTACH_JUMP = 12
    local ATTACH_RATE = 100

    -- AntiDeath. Parking the hitbox out of reach and bringing it back is a vertical step no fall
    -- produces: free fall tops out near 200 studs/s, so anything past this was set, not fallen.
    local VERTICAL_TELEPORT = 25
    local VERTICAL_RATE = 320
    local VERTICAL_REVERSALS, VERTICAL_MEMORY = 2, 3

    -- Crashers are floods, and the bar has to sit well above a player having a busy second -
    -- jumping while spamming a sword throws out a surprising number of both animations and
    -- replicated actions. These are per SECOND, not per three.
    local ANIMATION_FLOOD, ANIMATION_WINDOW = 45, 1
    local REMOTE_FLOOD, REMOTE_WINDOW = 45, 1

    -- How many readings of one kind before a player is flagged. Set per check rather than shared:
    -- a Reach reading is one clean measurement, a Phase reading is a guess about geometry we only
    -- half see, and they cannot sensibly share a threshold.
    local REQUIRED = {
        Killaura = 3,
        SilentAim = 4,
        HitBoxes = 4,
        Reach = 3,
        PlayerAttach = 2,
        AntiDeath = 2,
        Phase = 6,
        Invisible = 4,
        HighJump = 4,
        Speed = 3,
        NoFallDamage = 3,
        VoidFlight = 2,
        ExtremeSpeed = 2,
        AutoKit = 4,
        Animation = 3,
        Remote = 3,
        Breaker = 4,
        ProjectileAim = 4
    }

    local strikes = {}
    -- When each player last took a hit. Knockback throws people faster than they can run, so a
    -- speed sample taken just after one measures the hit, not the player.
    local lastHurt = {}

    local function enabled(name)
        local toggle = Toggles[name]
        return toggle ~= nil and toggle.Enabled == true
    end

    -- A child check runs only while its heading is on as well, so switching a family off switches
    -- off everything under it without disturbing which children were picked.
    local function checkEnabled(group, name)
        if not enabled(group) then return false end
        return group == name or enabled(name)
    end

    -- The one place the self exemption is decided. Checks ask this instead of comparing against
    -- lplr themselves, so the toggle reaches all of them at once and nothing is left half exempt.
    local function selfExcluded(plr)
        return plr == lplr and not enabled(DETECT_SELF)
    end

    -- entitylib keeps our own entity apart from the rest - entitylib.List is everyone but us - so a
    -- check that walks the list can never see the local player no matter what the guards say. This
    -- hands back that same list with our entity on the end while the toggle is on, which is what
    -- lets the polling checks read us without each of them knowing where our entity is kept.
    local function entities()
        if not enabled(DETECT_SELF) or not entitylib.isAlive or not entitylib.character then
            return entitylib.List
        end
        local list = table.clone(entitylib.List)
        table.insert(list, entitylib.character)
        return list
    end

    local function strikeCount(plr, reason)
        local perPlayer = strikes[plr]
        if not perPlayer then return 0 end
        local list = perPlayer[reason]
        if not list then return 0 end
        local now, count = tick(), 0
        for i = #list, 1, -1 do
            if now - list[i] > STRIKE_MEMORY then
                table.remove(list, i)
            else
                count += 1
            end
        end
        return count
    end

    local function Added(player, reason, detail)
        if not CheatersFlagged[player] then
            CheatersFlagged[player] = true
            whitelist.customtags[player.Name] = {{text = 'CHEATER', color = Color3.new(1, 0, 0)}}
            -- Say what was actually measured, not just which check fired. A flag you cannot
            -- sanity-check yourself is a flag you have to take on trust.
            notif('CheatDetector', `{player.Name} flagged for {reason:lower()}{detail and ' ('..detail..')' or ''}`, 10, 'alert')
        end
    end

    -- One reading is an oddity, several is a pattern. Nothing reaches Added until the pattern is
    -- there, at whatever count this particular check needs to be worth trusting.
    local function strike(plr, reason, label, detail)
        if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
        strikes[plr] = strikes[plr] or {}
        strikes[plr][reason] = strikes[plr][reason] or {}
        table.insert(strikes[plr][reason], tick())
        if strikeCount(plr, reason) >= (REQUIRED[reason] or 5) then
            Added(plr, label or reason, detail)
        end
    end

    local function ping()
        local value = 0
        pcall(function()
            value = lplr:GetNetworkPing()
        end)
        return value
    end

    -- Our own connection is the measuring instrument. When it is bad, every reading of somebody
    -- else is wrong in a direction that produces false positives, so we take none at all. Nothing
    -- sits between us and our own character, so measuring ourselves is always allowed.
    local function conditionsUsable(plr)
        if plr == lplr then return true end
        return ping() <= MAX_PING
    end

    local function recentlyTeleported(plr)
        return (workspace:GetServerTimeNow() - (plr:GetAttribute('LastTeleported') or 0)) <= 1
    end

    local function correctionContext(plr, char)
        if recentlyTeleported(plr) or not char then return true end
        for name, value in char:GetAttributes() do
            local lowered = tostring(name):lower()
            if value and (lowered:find('teleport') or lowered:find('servercorrect') or lowered:find('respawn') or lowered:find('launch')) then
                if type(value) ~= 'number' or math.abs(workspace:GetServerTimeNow() - value) < 2 then return true end
            end
        end
        local humanoid = char:FindFirstChildOfClass('Humanoid')
        return humanoid and table.find({Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.FallingDown, Enum.HumanoidStateType.GettingUp}, humanoid:GetState()) ~= nil
    end

    ------------------------------------------------------------------------
    -- Status effects.
    ------------------------------------------------------------------------
    -- Kits are the reason speed and jump checks need this. A kit that is MEANT to move you fast -
    -- a reaper's drift, a dash, a wind push - replicates a status attribute onto the character
    -- while it is doing it, so the sample is thrown away rather than counted. Matched on what the
    -- effect is called rather than on a list of kits, so a kit added next update is covered by
    -- the words it uses, and a kit renamed does not quietly become undetectable.
    local EFFECT_WORDS = {
        Movement = {'speed', 'dash', 'sprint', 'haste', 'boost', 'launch', 'grapple', 'balloon', 'wind', 'momentum', 'charge', 'rush', 'swift', 'leap', 'pounce', 'slide', 'drift', 'frenzy'},
        Vertical = {'jump', 'launch', 'bounce', 'pad', 'grapple', 'balloon', 'levitat', 'fly', 'wind', 'rocket', 'leap', 'pounce'},
        Invisible = {'invis', 'vanish', 'cloak', 'ghost'},
        Ability = {'ability', 'kit_', 'kitability', 'cooldown'}
    }

    -- One pass over a character's attributes per tick, producing every flag the checks want.
    -- Reading them separately meant walking the same attribute table three times a tick per
    -- player for answers that all come out of the same read.
    local function effectsOf(char)
        local flags = {}
        if not char then return flags end
        for name, value in char:GetAttributes() do
            if type(name) ~= 'string' or value == false or value == 0 then continue end
            local lowered = name:lower()
            for key, words in EFFECT_WORDS do
                if flags[key] then continue end
                for _, word in words do
                    if lowered:find(word, 1, true) then
                        flags[key] = true
                        break
                    end
                end
            end
        end
        return flags
    end

    local function weaponReach(plr)
        local inv = store.inventories[plr]
        local hand = inv and inv.hand
        -- The old check read hand.tool.Name, which is nil for anything the game hands over as a
        -- plain item rather than a Tool - so the reach fell back to the default for half the
        -- weapons in the game and flagged anyone holding a long one.
        local itemType = hand and (hand.itemType or (hand.tool and hand.tool.Name))
        local meta = itemType and bedwars.ItemMeta[itemType]
        local sword = meta and meta.sword
        return (sword and sword.attackRange or 14.4)
    end

    -- Lowest solid ground anywhere on the map, minus a margin. Below this is the void, and nothing
    -- alive belongs there. Recomputed on a timer rather than per sample: it walks every block on
    -- the map, and the floor of the world does not move between ticks.
    local voidCached, voidStamp = -300, 0
    local function voidLevel()
        local now = os.clock()
        if now - voidStamp < 5 then return voidCached end
        voidStamp = now
        local lowest = math.huge
        for _, v in store.blocks do
            local point = (v.Position.Y - (v.Size.Y / 2)) - 50
            if point < lowest then
                lowest = point
            end
        end
        voidCached = lowest < math.huge and lowest or -300
        return voidCached
    end

    -- What the game itself says a kit's movement is worth. Read out of the kit metadata rather
    -- than from a list of kit names: a kit added, renamed or rebalanced next update is covered by
    -- whatever its own meta says about itself, and there is nothing here to keep up to date. Any
    -- move-speed multiplier the meta declares raises that player's ceiling by the same
    -- proportion, so a kit whose whole point is moving fast is never flagged for moving fast.
    local kitCeilings = {}
    local function speedCeiling(plr)
        local kit = plr:GetAttribute('PlayingAsKits') or plr:GetAttribute('PlayingAsKit')
        if type(kit) ~= 'string' or kit == '' or kit == 'none' then return SPEED_LIMIT end
        local cached = kitCeilings[kit]
        if cached then return cached end

        local multiplier = 1
        pcall(function()
            local meta = bedwars.BedwarsKitMeta and bedwars.BedwarsKitMeta[kit]
            if type(meta) ~= 'table' then return end
            local function scan(tab, depth)
                for key, value in tab do
                    if type(value) == 'number' and type(key) == 'string' then
                        local lowered = key:lower()
                        -- Only a movement multiplier, never a raw number and never a speed that
                        -- belongs to something else the kit throws.
                        if lowered:find('speed') and (lowered:find('multiplier') or lowered:find('move')) then
                            multiplier = math.max(multiplier, value)
                        end
                    elseif type(value) == 'table' and depth < 3 then
                        scan(value, depth + 1)
                    end
                end
            end
            scan(meta, 1)
        end)

        local ceiling = SPEED_LIMIT * math.clamp(multiplier, 1, 2)
        kitCeilings[kit] = ceiling
        return ceiling
    end

    -- Rolling counter shared by every rate-based check: record an event, get back how many landed
    -- inside `window`.
    local function bumpRate(store_, key, window)
        local list = store_[key]
        if not list then
            list = {}
            store_[key] = list
        end
        local now = os.clock()
        table.insert(list, now)
        for i = #list, 1, -1 do
            if now - list[i] > window then
                table.remove(list, i)
            end
        end
        return #list
    end

    ------------------------------------------------------------------------
    -- Animation watch, shared.
    ------------------------------------------------------------------------
    -- Two checks want the same fact from different angles: the crasher check wants how OFTEN a
    -- player starts animations, and killaura's packet signal wants whether they started one at
    -- all. One hook per character answers both.
    local animationLast, animationRates, animationHooked = {}, {}, {}
    -- How many hits anywhere in the match arrived with a swing behind them. Until the game has
    -- proven to us that it replicates swings at all, "no swing behind that hit" means nothing,
    -- and the packet signal stays switched off rather than flagging the entire lobby.
    local animationBacked = 0

    local function watchAnimations(list)
        for _, rec in list do
            local plr = rec.Player
            if animationHooked[plr] == rec.Character then continue end
            local humanoid = rec.Character:FindFirstChildOfClass('Humanoid')
            local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
            if not animator then continue end
            animationHooked[plr] = rec.Character
            CheatDetector:Clean(animator.AnimationPlayed:Connect(function()
                animationLast[plr] = os.clock()
                if not checkEnabled('Crashers', 'Animation') then return end
                if CheatersFlagged[plr] then return end
                -- Landing/fall-state animations are restarted by the stock controller and by
                -- NoFallDamage's landed-state path. They are movement state, not an animation
                -- flood, and counting them made the Animation toggle accuse ordinary falls.
                local state = humanoid:GetState()
                if state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Landed
                    or math.abs((rec.RootPart and rec.RootPart.AssemblyLinearVelocity.Y) or 0) > 8 then return end
                if bumpRate(animationRates, plr, ANIMATION_WINDOW) >= ANIMATION_FLOOD then
                    animationRates[plr] = nil
                    strike(plr, 'Animation', 'animation spam', `{ANIMATION_FLOOD} animation starts inside {ANIMATION_WINDOW}s`)
                end
            end))
        end
    end

    -- Which heading each check belongs to, so a family can be switched off in one place.
    local CHECK_GROUP = {
        Killaura = 'Impossible hits',
        SilentAim = 'Impossible hits',
        HitBoxes = 'Impossible hits',
        Reach = 'Impossible hits',
        PlayerAttach = 'Blatant modules',
        AntiDeath = 'Blatant modules',
        Phase = 'Blatant modules',
        Invisible = 'Blatant modules',
        HighJump = 'Blatant modules',
        Speed = 'Blatant modules',
        NoFallDamage = 'Bypasses',
        VoidFlight = 'Bypasses',
        ExtremeSpeed = 'Bypasses',
        AutoKit = 'AutoKit',
        Animation = 'Crashers',
        Remote = 'Crashers',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }
    -- The checks whose toggle name is the heading itself.
    local CHECK_TOGGLE = {
        AutoKit = 'AutoKit',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }

    local function wanted(name)
        local group = CHECK_GROUP[name]
        return group ~= nil and checkEnabled(group, CHECK_TOGGLE[name] or name)
    end

    ------------------------------------------------------------------------
    -- Polling checks.
    ------------------------------------------------------------------------
    -- Each entry is a factory: it is called once when the module starts and hands back the
    -- function that runs against every snapshot, so all of a check's state is private to one
    -- run of the module and starts empty on the next.
    local Pollers = {}

    ------------------------------------------------------------------------
    -- Speed.
    ------------------------------------------------------------------------
    -- Not "how fast was that one step" - a knockback, a dash and a bad interpolation all answer
    -- that loudly. This measures a continuous run: distance actually covered over the time it
    -- took, with the run reset the moment anything makes a sample untrustworthy (a buff, a
    -- teleport, a hit taken, leaving the ground, or simply slowing down). What is left is speed
    -- that was HELD, which is the difference between a kit ability and a speed hack.
    Pollers.Speed = function()
        local tracks = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local track = tracks[plr]
                -- A respawn is a new character in the same player's name, and the position it
                -- starts at has nothing to do with the one the last one died at.
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Ceiling = speedCeiling(plr), Position = rec.Flat, Time = now, Distance = 0, Start = now, Samples = 0, Above = 0}
                    continue
                end
                local ceiling = track.Ceiling or SPEED_LIMIT

                local delta = now - track.Time
                local step = (rec.Flat - track.Position).Magnitude
                track.Position, track.Time = rec.Flat, now

                local usable = delta >= 0.05 and delta <= 0.5
                    and step <= TELEPORT_STEP
                    and (step / delta) <= SPEED_SANE
                    and not rec.Teleported
                    and not rec.Effects.Movement
                    and not rec.Hurt
                    and math.abs(rec.Velocity.Y) < 14
                    -- Sprint pace keeps a run alive, anything below it ends the run. That is
                    -- deliberately generous: a kit dash decays into a sprint rather than a stop,
                    -- so the sprinting that follows stays in the window and drags the average
                    -- back under the limit, while a hack that simply holds one speed does not.
                    and (step / delta) > (ceiling * 0.85)
                if not usable then
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    continue
                end

                track.Distance += step
                track.Samples += 1
                if (step / delta) > ceiling then
                    track.Above += 1
                end

                local span = now - track.Start
                if span >= SPEED_WINDOW and track.Samples >= 8 then
                    local average = track.Distance / span
                    local share = track.Above / track.Samples
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    -- Both, and the second one is what keeps kits out of this. A dash, a pounce or
                    -- a wind push is a spike that decays: most of the window sits at running pace
                    -- even when the average of it is dragged over the limit. A hack holds one
                    -- speed, so nearly every sample in its window is over on its own.
                    if average > ceiling and share >= 0.7 then
                        strike(plr, 'Speed', 'speeding', `{math.floor(average)} studs/s held for {math.floor(span * 10) / 10}s, ceiling {math.floor(ceiling)}`)
                    end
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Bypass behaviour.
    ------------------------------------------------------------------------
    -- These checks intentionally measure outcomes rather than known module signatures. A bypass
    -- can rename itself, but it still has to keep a player above the void, move them at an
    -- impossible pace, or suppress the health loss from a long unassisted fall.
    Pollers.ExtremeSpeed = function()
        local held = {}
        return function(now, list, delta)
            for _, rec in list do
                local plr = rec.Player
                if rec.Teleported or rec.Effects.Movement or rec.Hurt or not rec.Grounded then
                    held[plr] = nil
                    continue
                end
                local speed = (rec.Velocity * Vector3.new(1, 0, 1)).Magnitude
                if speed > 40 then
                    local entry = held[plr] or {Since = now, Peak = speed}
                    entry.Peak = math.max(entry.Peak, speed)
                    held[plr] = entry
                    if now - entry.Since >= 0.6 then
                        held[plr] = nil
                        strike(plr, 'ExtremeSpeed', 'anticheat bypass', `{math.floor(entry.Peak)} studs/s without a movement effect`)
                    end
                else
                    held[plr] = nil
                end
            end
        end
    end

    Pollers.VoidFlight = function()
        local since = {}
        return function(now, list)
            local floor = voidLevel()
            for _, rec in list do
                local plr = rec.Player
                -- A genuine void fall keeps descending. Only a body held/flying for three seconds
                -- below all playable ground is suspicious; this also fixes AntiDeath flagging the
                -- first samples of somebody simply falling out of the map.
                if rec.Position.Y < floor and rec.Velocity.Y > -35 and not rec.Teleported and not rec.Effects.Vertical then
                    since[plr] = since[plr] or now
                    if now - since[plr] >= 3 then
                        since[plr] = now
                        strike(plr, 'VoidFlight', 'anticheat bypass', 'remained mobile over the void for more than 3s')
                    end
                else
                    since[plr] = nil
                end
            end
        end
    end

    Pollers.NoFallDamage = function()
        local falls = {}
        return function(now, list)
            for _, rec in list do
                local plr = rec.Player
                local fall = falls[plr]
                if rec.Teleported or rec.Effects.Vertical or rec.Effects.Ability then
                    falls[plr] = nil
                    continue
                end
                if not rec.Grounded then
                    fall = fall or {Peak = rec.Position.Y, Lowest = rec.Position.Y, Health = rec.Health}
                    fall.Peak = math.max(fall.Peak, rec.Position.Y)
                    fall.Lowest = math.min(fall.Lowest, rec.Position.Y)
                    fall.Health = math.max(fall.Health, rec.Health)
                    falls[plr] = fall
                elseif fall then
                    local distance = fall.Peak - rec.Position.Y
                    -- BedWars starts meaningful fall damage well below this. The generous height
                    -- keeps slopes, replicated ground jitter and ordinary jumps out. Wait through
                    -- the server's damage-settle window before deciding health never changed.
                    if distance >= 32 then
                        fall.Landed = fall.Landed or now
                        if now - fall.Landed >= 0.8 then
                            if rec.Health >= fall.Health - 1 and not rec.Hurt then
                                strike(plr, 'NoFallDamage', 'no fall damage', `fell {math.floor(distance)} studs without losing health`)
                            end
                            falls[plr] = nil
                        end
                    else
                        falls[plr] = nil
                    end
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- PlayerAttach.
    ------------------------------------------------------------------------
    -- Two halves of the same behaviour, either of which is enough on its own. Getting there: a
    -- position step no run can make, landing on top of somebody. Staying there: held inside arm's
    -- length of one player while the pair actually travel, with the separation barely changing -
    -- two players who merely happen to be close bob around each other by whole studs.
    Pollers.PlayerAttach = function()
        local held, previous = {}, {}
        return function(now, list, delta)
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local last = previous[plr]
                -- Same player, different body: the step from where they died to where they
                -- respawned is not a step they took.
                local before = last and last.Character == rec.Character and last.Position or nil
                previous[plr] = {Character = rec.Character, Position = position}

                local nearest, nearestPlr = math.huge, nil
                for _, other in list do
                    if other.Player == plr then continue end
                    local separation = (position - other.Position).Magnitude
                    if separation < nearest then
                        nearest, nearestPlr = separation, other.Player
                    end
                end
                if not nearestPlr then
                    held[plr] = nil
                    continue
                end

                local step = before and (position - before).Magnitude or 0
                -- Rate, not raw distance: a poll stretched by a lag spike covers plenty of ground
                -- at a run, and calling that a teleport would flag whoever was standing nearby.
                local rate = delta > 0 and (step / delta) or 0
                if before and step > ATTACH_JUMP and rate > ATTACH_RATE and step <= TELEPORT_STEP and nearest <= ATTACH_RANGE * 2 and not rec.Teleported then
                    strike(plr, 'PlayerAttach', 'player attach', `{math.floor(step)} studs onto {nearestPlr.Name} in one step`)
                end

                if nearest > ATTACH_RANGE then
                    held[plr] = nil
                    continue
                end

                local entry = held[plr]
                if not entry or entry.Target ~= nearestPlr then
                    entry = {Target = nearestPlr, Count = 0, Travel = 0, Min = nearest, Max = nearest}
                    held[plr] = entry
                end
                entry.Count += 1
                entry.Travel += step
                entry.Min = math.min(entry.Min, nearest)
                entry.Max = math.max(entry.Max, nearest)
                if entry.Count >= ATTACH_SAMPLES and entry.Travel > ATTACH_TRAVEL and (entry.Max - entry.Min) < ATTACH_JITTER then
                    held[plr] = nil
                    strike(plr, 'PlayerAttach', 'player attach', `rode {nearestPlr.Name} at {math.floor(nearest * 10) / 10} studs`)
                end
            end
            for plr in held do
                if not seen[plr] then held[plr] = nil end
            end
            for plr in previous do
                if not seen[plr] then previous[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AntiDeath.
    ------------------------------------------------------------------------
    -- The hitbox taken somewhere nothing can reach it and brought straight back. This does not
    -- flag somebody merely for spending time below the map: it records impossible boundary
    -- crossings and requires repeated teleports to and from the void, which is what parking a
    -- hitbox out of a fight and restoring it looks like from outside.
    Pollers.AntiDeath = function()
        local tracks = {}
        return function(now, list, delta)
            local floor = voidLevel()
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local track = tracks[plr]
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Y = position.Y, Flat = rec.Flat, Below = position.Y < floor, Crossings = {}, Direction = 0, Reversals = {}}
                    continue
                end

                local rise = position.Y - track.Y
                local flatStep = (rec.Flat - track.Flat).Magnitude
                track.Y, track.Flat = position.Y, rec.Flat

                local below = position.Y < floor
                if rec.Teleported or delta <= 0 then
                    track.Below = below
                    continue
                end
                -- Straight up or straight down, faster than free fall, with the body barely
                -- moving sideways. Nothing physical does this. A normal void fall can cross the
                -- boundary once; AntiDeath has to cross it in both directions repeatedly.
                if math.abs(rise) < VERTICAL_TELEPORT or (math.abs(rise) / delta) < VERTICAL_RATE or flatStep > 15 then
                    track.Below = below
                    continue
                end

                if below ~= track.Below then
                    table.insert(track.Crossings, {Time = now, Below = below})
                    for i = #track.Crossings, 1, -1 do
                        if now - track.Crossings[i].Time > VERTICAL_MEMORY then
                            table.remove(track.Crossings, i)
                        end
                    end
                    local alternating = 0
                    for i = 2, #track.Crossings do
                        if track.Crossings[i].Below ~= track.Crossings[i - 1].Below then
                            alternating += 1
                        end
                    end
                    if alternating >= 3 then
                        table.clear(track.Crossings)
                        strike(plr, 'AntiDeath', 'anti death', 'repeatedly teleported to and from below the map')
                    end
                end
                track.Below = below

                local direction = rise > 0 and 1 or -1
                if track.Direction ~= 0 and direction ~= track.Direction then
                    table.insert(track.Reversals, now)
                end
                track.Direction = direction
                for i = #track.Reversals, 1, -1 do
                    if now - track.Reversals[i] > VERTICAL_MEMORY then
                        table.remove(track.Reversals, i)
                    end
                end
                if #track.Reversals >= VERTICAL_REVERSALS then
                    table.clear(track.Reversals)
                    track.Direction = 0
                    strike(plr, 'AntiDeath', 'anti death', `hitbox thrown {math.floor(math.abs(rise))} studs up and down`)
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Phase.
    ------------------------------------------------------------------------
    -- Standing inside solid geometry. Every part of this is arguable on its own - a body clips a
    -- block on a slope, streaming puts a block in late - so the reading needs the root buried in
    -- something solid across consecutive samples while the player is not being carried by
    -- anything, and it needs the most readings of any check before it flags. Sampled every third
    -- tick because it is the only check here that costs a spatial query.
    Pollers.Phase = function()
        local buried = {}
        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Exclude
        local skip = 0
        return function(now, list)
            skip += 1
            if skip % 3 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Movement then
                    buried[plr] = nil
                    continue
                end

                overlap.FilterDescendantsInstances = {rec.Character, lplr.Character, gameCamera}
                -- A box well inside the torso, so brushing a wall is not enough - the body has
                -- to be in the block.
                local parts = workspace:GetPartBoundsInBox(CFrame.new(rec.Position), Vector3.new(1, 1, 1), overlap)
                local solid = false
                for _, part in parts do
                    if part.CanCollide and part.Anchored then
                        solid = true
                        break
                    end
                end

                if solid then
                    buried[plr] = (buried[plr] or 0) + 1
                    if buried[plr] >= 4 then
                        buried[plr] = 0
                        strike(plr, 'Phase', 'phasing', 'stood inside a solid block')
                    end
                else
                    buried[plr] = nil
                end
            end
            for plr in buried do
                if not seen[plr] then buried[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Invisible.
    ------------------------------------------------------------------------
    -- Every limb fully transparent while the player is alive, moving and carrying no invisibility
    -- effect of their own. Movement is what separates this from a ragdoll or a death animation,
    -- and the status-effect check is what keeps the game's own invisibility potion out of it.
    Pollers.Invisible = function()
        local hidden = {}
        local skip = 0
        return function(now, list)
            -- Every fifth tick. Walking a character's whole descendant tree is the most expensive
            -- read in the module, and nobody turns invisible for a tenth of a second.
            skip += 1
            if skip % 5 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Effects.Invisible or rec.Velocity.Magnitude < 4 then
                    hidden[plr] = nil
                    continue
                end

                local visible, counted = false, 0
                for _, part in rec.Character:GetDescendants() do
                    if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                        counted += 1
                        if part.Transparency < 0.95 then
                            visible = true
                            break
                        end
                    end
                end

                -- No limbs found at all means the character has not streamed in, which is not
                -- the same thing as being invisible.
                if counted >= 4 and not visible then
                    hidden[plr] = (hidden[plr] or 0) + 1
                    if hidden[plr] >= 3 then
                        hidden[plr] = 0
                        strike(plr, 'Invisible', 'invisibility', 'moving with every limb hidden')
                    end
                else
                    hidden[plr] = nil
                end
            end
            for plr in hidden do
                if not seen[plr] then hidden[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- HighJump.
    ------------------------------------------------------------------------
    -- Rising further off one jump than the game's own jump power allows. Measured as a climb from
    -- a standing start rather than as an instantaneous velocity, because a launch pad or a
    -- knockback shows up in velocity and both of those are legitimate.
    Pollers.HighJump = function()
        local tracked = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Vertical or rec.Hurt then
                    tracked[plr] = nil
                    continue
                end

                local y = rec.Position.Y
                local entry = tracked[plr]
                if rec.Grounded then
                    tracked[plr] = {Base = y, Peak = y}
                elseif entry then
                    entry.Peak = math.max(entry.Peak, y)
                    -- Roblox's own jump tops out near 7 studs, and BedWars kits that go higher
                    -- all announce themselves through a status effect, which is excluded above.
                    -- 18 is far past anything left.
                    if (entry.Peak - entry.Base) > 18 then
                        tracked[plr] = nil
                        strike(plr, 'HighJump', 'high jump', `rose {math.floor(entry.Peak - entry.Base)} studs off one jump`)
                    end
                end
            end
            for plr in tracked do
                if not seen[plr] then tracked[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AutoKit.
    ------------------------------------------------------------------------
    -- A kit ability is a cooldown, and a script fires it the instant it is up - every time. What
    -- gives it away is not the speed but the regularity: the gaps between activations stop
    -- varying. A hand cannot hold an interval to within a tenth of a second five times running.
    Pollers.AutoKit = function()
        local activations, previous = {}, {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local active = rec.Effects.Ability
                local was = previous[plr]
                previous[plr] = active
                if not active or was then continue end

                -- Rising edge: the ability just went off.
                local times = activations[plr]
                if not times then
                    times = {}
                    activations[plr] = times
                end
                table.insert(times, now)
                if #times > 6 then
                    table.remove(times, 1)
                end
                if #times < 6 then continue end

                local shortest, longest = math.huge, 0
                for i = 2, #times do
                    local gap = times[i] - times[i - 1]
                    shortest = math.min(shortest, gap)
                    longest = math.max(longest, gap)
                end
                -- Five gaps that agree to within a tenth of a second, and none of them long
                -- enough to be somebody simply playing at a steady pace.
                if (longest - shortest) < 0.1 and longest < 30 then
                    table.clear(times)
                    strike(plr, 'AutoKit', 'automated kit use', `5 activations {math.floor(longest * 100) / 100}s apart`)
                end
            end
            for plr in activations do
                if not seen[plr] then
                    activations[plr] = nil
                    previous[plr] = nil
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Event-driven checks.
    ------------------------------------------------------------------------
    -- Same idea as the pollers: a factory called once at startup which puts its connections in
    -- place. Everything they need about a player is read at the moment of the event.
    local Events = {}

    ------------------------------------------------------------------------
    -- Killaura.
    ------------------------------------------------------------------------
    -- Four things an aura does that a hand does not, any one of which is a reading:
    --
    --   * hits closer together than anybody can click at all;
    --   * a cadence that does not vary, because the aura fires the moment the cooldown is up
    --     rather than whenever a finger happened to come down;
    --   * a run of hits held at a rate no hand sustains;
    --   * damage on several different people in the time it takes to turn to face one of them.
    --
    -- Plus the packet case: an aura that talks straight to the server does not swing anything,
    -- so the damage lands with no animation behind it. That one is only trusted once other
    -- players in the same match have proven that swings do reach us, so a game that simply does
    -- not replicate them cannot make the check flag everybody.
    Events.Killaura = function()
        local last, intervals, victims, hits, quiet = {}, {}, {}, {}, {}

        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Killaura') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity then return end

            local from = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not from or selfExcluded(from) or CheatersFlagged[from] then return end
            if not conditionsUsable(from) then return end

            local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            local now = os.clock()

            -- Was there a swing behind this hit?
            if (now - (animationLast[from] or 0)) <= 0.4 then
                animationBacked += 1
                quiet[from] = 0
            elseif animationBacked >= 5 then
                quiet[from] = (quiet[from] or 0) + 1
                if quiet[from] >= 6 then
                    quiet[from] = 0
                    strike(from, 'Killaura', 'using killaura', '6 hits with no swing behind them')
                end
            end

            -- Several different people inside the time it takes to turn around.
            if victim then
                local seen = victims[from]
                if not seen then
                    seen = {}
                    victims[from] = seen
                end
                seen[victim] = now
                local distinct = 0
                for plr, stamp in seen do
                    if now - stamp > SWITCH_WINDOW then
                        seen[plr] = nil
                    else
                        distinct += 1
                    end
                end
                if distinct >= SWITCH_VICTIMS then
                    table.clear(seen)
                    strike(from, 'Killaura', 'using killaura', `{distinct} different targets inside {SWITCH_WINDOW}s`)
                end
            end

            local previous = last[from]
            last[from] = now
            if not previous then return end

            local interval = now - previous
            -- Two events delivered in the same frame were batched by the network, not thrown that
            -- fast. Reading a batch as a zero interval is how a check like this flags people who
            -- are simply being replicated to us in bursts.
            if interval <= 0.008 then return end

            if interval < MIN_HUMAN_INTERVAL then
                strike(from, 'Killaura', 'using killaura', `hits {math.floor(interval * 1000)}ms apart`)
                return
            end

            -- Held rate. Not one fast hit - a run of them.
            if bumpRate(hits, from, BURST_WINDOW) >= BURST_HITS then
                hits[from] = nil
                strike(from, 'Killaura', 'using killaura', `{BURST_HITS} hits inside {BURST_WINDOW}s`)
            end

            -- Cadence. Only gaps short enough to be a weapon on cooldown are considered: a run of
            -- evenly spaced hits seconds apart is somebody trading, not a machine.
            local run = intervals[from]
            if not run then
                run = {}
                intervals[from] = run
            end
            if interval > 0.6 then
                table.clear(run)
                return
            end
            table.insert(run, interval)
            if #run > CADENCE_SAMPLES then
                table.remove(run, 1)
            end
            if #run < CADENCE_SAMPLES then return end

            local shortest, longest = math.huge, 0
            for _, value in run do
                shortest = math.min(shortest, value)
                longest = math.max(longest, value)
            end
            if (longest - shortest) <= CADENCE_SPREAD then
                table.clear(run)
                strike(from, 'Killaura', 'using killaura', `{CADENCE_SAMPLES} hits {math.floor(shortest * 1000)}ms apart to the millisecond`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Reach.
    ------------------------------------------------------------------------
    -- The measurement an aura cannot fake. It can put whatever position it likes in the packet it
    -- sends the server, but the body the rest of us see stays where the player really is, so the
    -- distance between the two characters at the moment damage lands is the honest one. Every
    -- sword in the game swings 14.4 studs or less; past 15.5 the hit came from somewhere the
    -- weapon does not reach.
    Events.Reach = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Reach') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local distance = (fromRoot.Position - toRoot.Position).Magnitude
            -- Ping converted into studs rather than added as seconds, and kept small: this is an
            -- allowance for our own view of two moving bodies, not for the weapon.
            local allowance = math.clamp(ping() * 20, 0, 3)
            local limit = math.max(weaponReach(attacker) + 1.1, REACH_LIMIT) + allowance

            if distance > limit then
                strike(attacker, 'Reach', 'using reach', `{math.floor(distance * 10) / 10} studs, limit {math.floor(limit * 10) / 10}`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- HitBoxes.
    ------------------------------------------------------------------------
    -- An expanded hitbox lives on the attacker's own client, so it is never visible from here
    -- directly. What it produces that a normal swing cannot is a hit landing while the attacker is
    -- facing well off the target: the swing resolved against a box far wider than the body. The
    -- distance has to be inside legitimate reach too, otherwise this is just Reach again and one
    -- swing would be counted twice.
    Events.HitBoxes = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('HitBoxes') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position)
            local distance = delta.Magnitude
            -- Point blank the angle means nothing - the bodies overlap and any heading hits - and
            -- past the weapon's own reach this is Reach's reading, not this one.
            if distance < 6 or distance > REACH_LIMIT then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            local toward = delta * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 or toward.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(toward.Unit), -1, 1)))
            -- 70 degrees off and still landing means the swing did not resolve against the body
            -- that is being drawn. Wide enough that our own interpolation of a strafing player
            -- cannot get there on its own.
            if angle > 70 then
                strike(attacker, 'HitBoxes', 'expanded hitboxes', `hit {math.floor(angle)} degrees off target`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- SilentAim.
    ------------------------------------------------------------------------
    -- The projectile equivalent: a shot that lands on someone the shooter was never pointing at.
    -- Only long shots are considered, because at close range the angle to a target is wide even
    -- when aimed honestly, and only non-melee damage, so a sword swing is never counted here.
    Events.SilentAim = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('SilentAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position) * Vector3.new(1, 0, 1)
            -- A thrown projectile arcs, and a short lob can leave at a heading well off the
            -- target quite legitimately. Distance is what makes the heading meaningful.
            if delta.Magnitude < 25 then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(delta.Unit), -1, 1)))
            if angle > 50 then
                strike(attacker, 'SilentAim', 'silent aim', `landed a shot {math.floor(angle)} degrees off their heading`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- ProjectileAimbot and Aura.
    ------------------------------------------------------------------------
    -- Aimbot is not one impossible shot, it is never missing. Landing projectile after projectile
    -- on live players at long range, faster than they can be aimed, is the thing no hand does.
    Events.ProjectileAim = function()
        local hits = {}
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('ProjectileAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            local victim = playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            -- Players only. A projectile stream into a mob or a bed is a different thing entirely.
            if not attacker or not victim or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end
            if (toRoot.Position - fromRoot.Position).Magnitude < 30 then return end

            -- Four long-range projectile hits on players inside six seconds. Bows are slow to
            -- draw, so this is well past what the weapon itself allows aimed by hand.
            if bumpRate(hits, attacker, 6) >= 4 then
                hits[attacker] = nil
                strike(attacker, 'ProjectileAim', 'projectile aimbot', '4 long-range projectile hits inside 6s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Breaker.
    ------------------------------------------------------------------------
    -- Blocks coming apart faster than a tool can swing, or coming apart from across the map. Both
    -- are read off the break event itself, which carries who did it and where.
    Events.Breaker = function()
        local rates = {}
        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            if not wanted('Breaker') then return end
            local plr = data.player
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if not conditionsUsable(plr) then return end

            local blockPosition = data.blockRef and data.blockRef.blockPosition
            if typeof(blockPosition) == 'Vector3' then
                local root
                for _, ent in entities() do
                    if ent.Player == plr then
                        root = ent.RootPart
                        break
                    end
                end
                if root and root.Parent then
                    local distance = (root.Position - (blockPosition * 3)).Magnitude
                    -- Block reach in this game is well under 30 studs even with every modifier.
                    if distance > 45 and not recentlyTeleported(plr) then
                        strike(plr, 'Breaker', 'block breaker', `broke a block {math.floor(distance)} studs away`)
                        return
                    end
                end
            end

            -- Twelve blocks inside two seconds. Flat out with the fastest tool in the game on the
            -- softest block is not close to this, and a burst that size cannot be a batch of
            -- replicated events either.
            if bumpRate(rates, plr, 2) >= 12 then
                rates[plr] = nil
                strike(plr, 'Breaker', 'block breaker', '12 blocks broken inside 2s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Crashers: Remote.
    ------------------------------------------------------------------------
    -- Another player's remote traffic is not visible from here, but its effect is: a crasher
    -- pushes replicated actions out at a rate the game itself never produces. Block places and
    -- breaks and damage events are all counted together, because a crasher does not care which
    -- remote it is hammering. The bar is per second and set well past a busy one: jumping around
    -- spamming a sword while building throws out a lot of events, and none of that is a crash.
    Events.Remote = function()
        local rates = {}

        local function count(plr)
            if not wanted('Remote') then return end
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if bumpRate(rates, plr, REMOTE_WINDOW) >= REMOTE_FLOOD then
                rates[plr] = nil
                strike(plr, 'Remote', 'remote spam', `{REMOTE_FLOOD} replicated actions inside {REMOTE_WINDOW}s`)
            end
        end

        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            count(data.player)
        end))
        CheatDetector:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(data)
            count(data and data.player)
        end))
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not damageTable.fromEntity then return end
            count(playersService:GetPlayerFromCharacter(damageTable.fromEntity))
        end))
    end

    -- One snapshot of everybody worth measuring, taken once per tick and handed to every polling
    -- check. Attributes, ground state and velocity are read here rather than inside each check,
    -- so a player is walked over once however many checks are on.
    local function snapshot(now)
        local list = {}
        for _, ent in entities() do
            local plr, root, char = ent.Player, ent.RootPart, ent.Character
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then continue end
            if not root or not root.Parent or not char then continue end
            if (ent.Health or 0) <= 0 then continue end

            local position = root.Position
            local effects = effectsOf(char)
            if tostring(store.queueType):lower():find('custom') then effects.Ability = true end
            table.insert(list, {
                Player = plr,
                Character = char,
                Root = root,
                Position = position,
                Flat = position * Vector3.new(1, 0, 1),
                Velocity = root.AssemblyLinearVelocity,
                Grounded = (ent.Humanoid and ent.Humanoid.FloorMaterial ~= Enum.Material.Air) or false,
                Effects = effects,
                Teleported = correctionContext(plr, char),
                Hurt = (now - (lastHurt[plr] or 0)) < 1.5,
                Health = ent.Health or (ent.Humanoid and ent.Humanoid.Health) or 0
            })
        end
        return list
    end

    CheatDetector = vape.Categories.Utility:CreateModule({
        Name = 'CheatDetector',
        Function = function(callback)
            if callback then
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
                voidStamp = 0

                -- Feeds the knockback suppression the speed and jump checks rely on.
                CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
                    local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
                    if victim then
                        lastHurt[victim] = tick()
                    end
                end))

                -- Every check is put in place, whichever toggles happen to be ticked right now,
                -- and each one asks whether it is wanted as it runs. Building only the ticked
                -- ones meant a detection switched on mid-match did nothing at all until the
                -- module was cycled by hand, which is most of what "half of these do not work"
                -- was. An unwanted check costs one table lookup a tick.
                for name, event in Events do
                    local ok, err = pcall(event)
                    if not ok then
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                    end
                end

                local running = {}
                for name, poller in Pollers do
                    local ok, fn = pcall(poller)
                    if ok and type(fn) == 'function' then
                        running[name] = fn
                    else
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(fn))
                    end
                end

                local last = tick()
                repeat
                    local now = tick()
                    local delta = now - last
                    last = now

                    -- The animation watch is what the crasher check counts and what killaura
                    -- asks whether a swing happened at all, so it runs for either of them.
                    local watching = wanted('Animation') or wanted('Killaura')
                    local polling = false
                    for name in running do
                        if wanted(name) then
                            polling = true
                            break
                        end
                    end

                    if watching or polling then
                        -- A character coming apart mid-read throws, and an unguarded throw here
                        -- ends the loop and the whole module with it.
                        local taken, list = pcall(snapshot, now)
                        if taken and #list > 0 then
                            if watching then
                                pcall(watchAnimations, list)
                            end
                            for name, fn in running do
                                if not wanted(name) then continue end
                                local ok, err = pcall(fn, now, list, delta)
                                if not ok then
                                    warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                                end
                            end
                        end
                    end

                    task.wait(POLL_INTERVAL)
                until not CheatDetector.Enabled
            else
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
            end
        end,
        Tooltip = 'Alerts for likely cheaters. Every detection needs several impossible readings, and ignores ones taken on a poor connection'
    })

    local GROUP_TOOLTIPS = {
        ['Impossible hits'] = 'Hits that cannot have been aimed or thrown by hand: killaura, silent aim, expanded hitboxes, reach past any weapon',
        ['Blatant modules'] = 'Movement and state nobody can produce by playing: attach, anti death, phase, invisibility, high jump, speed',
        ['Bypasses'] = 'Outcome-based checks for impossible movement, sustained void flight, and suppressed fall damage',
        ['AutoKit'] = 'Kit abilities fired on a fixed interval, the regularity no hand holds',
        ['Crashers'] = 'Floods meant to bury other clients - animations or replicated actions many times a second',
        ['Breaker'] = 'Blocks broken faster than a tool swings, or from across the map',
        ['ProjectileAimbot and Aura'] = 'Long-range projectiles landing on players faster than a bow can be drawn and aimed'
    }
    local CHILD_TOOLTIPS = {
        Killaura = 'Hit rate, an unvarying cadence, several targets at once, or damage with no swing behind it',
        SilentAim = 'Shots landing on someone the shooter was not pointing at',
        HitBoxes = 'Melee landing while facing well off the body being drawn',
        Reach = 'Hits landing past 15.5 studs, further than any sword in the game swings',
        PlayerAttach = 'Teleporting onto a player, or riding them with the gap between you barely moving',
        AntiDeath = 'Repeated impossible teleports to and from below the map, or rapid vertical reversals faster than gravity',
        Phase = 'The body stood inside solid geometry across consecutive samples',
        Invisible = 'Moving with every limb hidden and no invisibility effect of their own',
        HighJump = 'Rising far past jump power off one jump, with no launch or ability effect',
        Speed = 'Ground speed held past 22 studs/s - or past whatever the kit\'s own metadata says it is worth - with potions, dashes and knockback excluded',
        NoFallDamage = 'Falls over 32 studs that settle without health loss; teleports, kit abilities, launches and vertical effects are excluded',
        VoidFlight = 'A player held or moving below all playable ground for more than three seconds instead of naturally falling',
        ExtremeSpeed = 'Sustained movement over 40 studs/s without a kit movement effect, knockback, teleport, or launch',
        Animation = 'Animation starts many times a second, far past anything play produces',
        Remote = 'Replicated actions - places, breaks, hits - many times a second'
    }

    for _, group in GROUPS do
        Toggles[group.Name] = CheatDetector:CreateToggle({
            Name = group.Name,
            Default = true,
            Tooltip = GROUP_TOOLTIPS[group.Name],
            Function = function(callback)
                for _, child in (group.Children or {}) do
                    local toggle = Toggles[child]
                    if toggle and toggle.Object then
                        toggle.Object.Visible = callback
                    end
                end
            end
        })
        for _, child in (group.Children or {}) do
            Toggles[child] = CheatDetector:CreateToggle({
                Name = child,
                Default = true,
                Darker = true,
                Tooltip = CHILD_TOOLTIPS[child]
            })
        end
    end

    -- Last, and under everything else, because it is not a detection - it only changes who the
    -- detections above are allowed to look at. Takes effect immediately: the checks ask about it
    -- as they run rather than reading it once at startup, so there is no need to cycle the module.
    Toggles[DETECT_SELF] = CheatDetector:CreateToggle({
        Name = DETECT_SELF,
        Tooltip = 'Testing aid. Runs every enabled detection against you as well, on your behaviour alone - it never looks at which of your modules are on - and flags you like anyone else if one of them fires',
        Function = function()
            -- Readings taken either side of a change of mind about whether we count are not a
            -- pattern, so whichever way it just moved, our own history starts again from nothing.
            strikes[lplr] = nil
        end
    })
end)
-- END AETHER MODULE: utility/CheatDetector.lua --

-- BEGIN AETHER MODULE: utility/ClaimRewards.lua --
run(function()
    local ClaimRewards, CratesOnly, Notify
    local claimGeneration = 0

    local function rewardApi()
        local controller = bedwars.MilestonesController
        local rewards = bedwars.MilestoneRewards
        local state = bedwars.Store and bedwars.Store:getState()
        state = state and state.Bedwars
        if not controller or type(rewards) ~= 'table' or not state then return end
        return controller, rewards, state
    end

    ClaimRewards = vape.Categories.Utility:CreateModule({
        Name = 'ClaimRewards',
        Function = function(enabled)
            claimGeneration += 1
            if not enabled then return end
            local generation = claimGeneration
            task.spawn(function()
                while ClaimRewards.Enabled and claimGeneration == generation do
                    local controller, rewards, state = rewardApi()
                    if not controller then
                        notif('ClaimRewards', 'Milestone rewards are unavailable in this queue.', 5, 'warning')
                        ClaimRewards:Toggle()
                        break
                    end
                    local claimed = controller.milestoneRewardsClaimed or state.milestoneRewardsClaimed or {}
                    local level = state.playerLevel or 0
                    for _, reward in rewards do
                        if not ClaimRewards.Enabled or claimGeneration ~= generation then break end
                        if reward.levelRequirement <= level and not table.find(claimed, reward.id) and (not CratesOnly.Enabled or reward.instantClaim) then
						local remote = bedwars.Client and bedwars.Client:Get('ClaimMilestoneReward')
						local ok, result = false, nil
						if remote then ok, result = pcall(remote.CallServer, remote, reward.id) end
                            if ok and result then
                                table.insert(claimed, reward.id)
                                if Notify.Enabled then notif('ClaimRewards', `Claimed {reward.description or reward.id}`, 5) end
                            end
                            task.wait(1)
                        end
                    end
                    task.wait(5)
                end
            end)
        end,
        Tooltip = 'Claims unlocked level milestone rewards with the native reward remote.'
    })
    CratesOnly = ClaimRewards:CreateToggle({Name = 'Crates only', Tooltip = 'Only claim instant crate rewards.'})
    Notify = ClaimRewards:CreateToggle({Name = 'Notify', Default = true})
end)
-- END AETHER MODULE: utility/ClaimRewards.lua --

-- BEGIN AETHER MODULE: utility/CustomCursor.lua --
run(function()
	local UIS = game:GetService('UserInputService')
	local CustomCursor = {Enabled = false}
	local mouseDropdown = {Value = 'Arrow'}
	local mouseIcons = {
		['CS:GO'] = 'rbxassetid://14789879068',
		['Old Roblox Mouse'] = 'rbxassetid://13546344315',
		['dx9ware'] = 'rbxassetid://12233942144',
		['Aimbot'] = 'rbxassetid://8680062686',
		['Triangle'] = 'rbxassetid://14790304072',
		['Arrow'] = 'rbxassetid://14790316561'
	}
	local customMouseIcon = {Enabled = false}
	local customIcon = {Value = ''}
	local applyingCursor = false
	local function applyCursor()
		if not CustomCursor.Enabled or applyingCursor then return end
		local wanted = customMouseIcon.Enabled and 'rbxassetid://'..customIcon.Value or mouseIcons[mouseDropdown.Value]
		if UIS.MouseIcon ~= wanted then
			applyingCursor = true
			UIS.MouseIcon = wanted
			applyingCursor = false
		end
	end
	CustomCursor = vape.Categories.Utility:CreateModule({
		Name = 'CustomCursor',
		Tooltip = 'changes your cursor\'s image',
		Function = function(callback)
			if callback then
				applyCursor()
				CustomCursor:Clean(UIS:GetPropertyChangedSignal('MouseIcon'):Connect(applyCursor))
			else
				UIS.MouseIcon = ''
				task.wait()
				UIS.MouseIcon = ''
			end
		end
	})
	mouseDropdown = CustomCursor:CreateDropdown({
		Name = 'Mouse Icon',
		List = {
			'CS:GO',
			'Old Roblox Mouse',
			'dx9ware',
			'Aimbot',
			'Triangle',
			'Arrow'
		},
		Function = applyCursor
	})
	customMouseIcon = CustomCursor:CreateToggle({
		Name = 'Custom Icon',
		Function = applyCursor
	})
	customIcon = CustomCursor:CreateTextBox({
		Name = 'Custom Mouse Icon',
		TempText = 'Image ID (not decal)',
		Function = applyCursor
	})
end)
-- END AETHER MODULE: utility/CustomCursor.lua --

-- BEGIN AETHER MODULE: utility/EntityAnalyser.lua --
run(function()
    -- EntityAnalyser
    --
    -- Works out how good each player actually is from what they do in front of us, and nothing
    -- else. Every input below is something the game already hands every client: damage and death
    -- events, block placements and breaks, bed breaks, replicated inventories, replicated
    -- animations, character attributes and the positions of entities that are streamed in. There
    -- is no stat page, no leaderboard and no rank lookup anywhere in here, and kills and gear are
    -- two signals out of forty-odd - neither can carry a rating on its own.
    --
    -- Six categories are scored separately (Combat, Movement, GameSense, Objectives, Resources,
    -- Teamwork) and each is built the same way: a fixed list of named signals, each reporting a
    -- deviation from -1 (as bad as it gets) to +1 (as good as it gets) together with a confidence
    -- saying how much evidence is behind it. A signal we have never observed is still declared, at
    -- confidence zero - which is what makes incomplete data cost confidence instead of quietly
    -- reweighting whatever happened to survive. The overall skill is a confidence-weighted blend
    -- of the categories, re-weighted for the role the player is actually playing, so a Support or
    -- an Economy player is not marked down against a Fighter's yardstick.
    --
    -- Things that would make a number a lie are handled where they happen rather than averaged
    -- over: kills on AFK, trapped, out-geared or repeatedly-respawning players are discounted at
    -- the moment of the kill; fights taken against equal or better gear count for more; samples
    -- taken across a teleport or a streaming gap are thrown away instead of read as movement;
    -- time we could not see the player is not counted as time observed.
    --
    -- This module is a read-out. It never touches another module's settings. What it knows is
    -- published on getgenv().EntityAnalyser and vapeEvents.EntityAnalysed for anything that wants
    -- to act on it - Killaura's 'Target skilled' is the first consumer.
    local EntityAnalyser
    local SweatAt
    local SkilledAt
    local AboveAt
    local BeginnerBelow
    local NewBelow
    local MinConfidence
    local SampleRange
    local Labels
    local ShowScore
    local ShowRole
    local ShowConfidence
    local ShowSweat
    local ShowSkilled
    local ShowAbove
    local ShowAverage
    local ShowBeginner
    local ShowNew
    local ShowUnknown
    local Teammates
    local Notify

    ----------------------------------------------------------------------------
    -- Constants.
    ----------------------------------------------------------------------------
    local COMBO_WINDOW = 1.6      -- hits inside this gap are one combo
    local FIGHT_MEMORY = 6        -- still "in a fight" this long after a hit either way
    local ENGAGE_MEMORY = 14      -- an engagement stays resolvable this long after its last hit
    local ASSIST_WINDOW = 8       -- damage this recent counts toward someone else's kill
    local SWING_WINDOW = 0.28     -- a swing this soon before damage is the swing that landed
    local AFK_TIME = 12           -- no movement and no action for this long reads as AFK
    local TELEPORT_JUMP = 90      -- a position step bigger than this is lag, not movement
    local EVENT_LIMIT = 12        -- RecentEvents ring size
    local RESCORE_INTERVAL = 0.5  -- a profile is rebuilt at most this often
    local FAR_INTERVAL = 0.5      -- sampling period outside the near radius
    local AFK_INTERVAL = 2        -- sampling period for someone who is not doing anything
    local NEAR_INTERVAL = 0.1     -- combat sampling does not need the render frame rate
    local PROBE_INTERVAL = 0.1    -- terrain probe period for near players
    local PROBE_BUDGET = 4        -- terrain probes allowed per frame, across everyone
    local WORLD_INTERVAL = 0.5    -- bed/generator/roster snapshot rebuild period
    local HEAVY_INTERVAL = 0.5    -- period for the per-player checks that allocate
    local BED_NEAR = 30           -- "at a bed" radius
    local GEN_NEAR = 16           -- "at a generator" radius
    local THREAT_NEAR = 35        -- an enemy this close is a threat to have noticed
    local MATE_NEAR = 45          -- a teammate this close is one you could have helped
    local VOID_WINDOW = 4         -- knockback to void death has to land inside this
    local SEEN_TIMEOUT = 2        -- no sample for this long is a streaming gap, not idling

    local ratingColor = {
        Sweat = Color3.fromRGB(255, 105, 180),
        Skilled = Color3.fromRGB(85, 220, 130),
        ['Above Average'] = Color3.fromRGB(170, 225, 110),
        Average = Color3.fromRGB(235, 205, 90),
        Beginner = Color3.fromRGB(235, 95, 95),
        New = Color3.fromRGB(170, 115, 115),
        Unknown = Color3.fromRGB(150, 150, 158)
    }

    local ROLES = {'Rusher', 'Defender', 'Fighter', 'Support', 'Economy', 'ResourceControl'}
    local CATEGORIES = {'Combat', 'Movement', 'GameSense', 'Objectives', 'Resources', 'Teamwork'}

    -- How much each category counts toward the overall score, per role. A Defender who never
    -- rushes is not a worse player for it, so Objectives weighs less for them and the job they
    -- are actually doing weighs more. Mixed is the neutral profile everyone starts on.
    local ROLE_WEIGHTS = {
        Mixed           = {Combat = 1.00, Movement = 0.75, GameSense = 1.00, Objectives = 0.85, Resources = 0.55, Teamwork = 0.60},
        Rusher          = {Combat = 1.00, Movement = 0.95, GameSense = 0.85, Objectives = 1.20, Resources = 0.45, Teamwork = 0.50},
        Defender        = {Combat = 0.95, Movement = 0.70, GameSense = 1.20, Objectives = 0.70, Resources = 0.60, Teamwork = 0.90},
        Fighter         = {Combat = 1.30, Movement = 0.90, GameSense = 0.95, Objectives = 0.60, Resources = 0.40, Teamwork = 0.55},
        Support         = {Combat = 0.70, Movement = 0.70, GameSense = 1.05, Objectives = 0.65, Resources = 0.70, Teamwork = 1.35},
        Economy         = {Combat = 0.60, Movement = 0.70, GameSense = 0.95, Objectives = 0.70, Resources = 1.35, Teamwork = 0.85},
        ResourceControl = {Combat = 0.85, Movement = 0.75, GameSense = 1.10, Objectives = 0.75, Resources = 1.15, Teamwork = 0.90}
    }

    ----------------------------------------------------------------------------
    -- Rolling statistics.
    ----------------------------------------------------------------------------
    -- A mean that converges fast while there is little evidence and settles as more arrives, so an
    -- early read is usable and a late one is stable. `n` is the evidence weight behind it, which
    -- is what every count-based confidence term in the module is built from.
    local function meter(initial)
        return {v = initial or 0, n = 0}
    end

    local function observe(m, value, weight)
        weight = weight or 1
        if weight <= 0 or value ~= value then return end
        m.n = m.n + weight
        m.v = m.v + (value - m.v) * math.clamp(weight / math.min(m.n, 24), 0.04, 1)
    end

    -- Confidence a meter has earned. `full` is the observation weight at which the signal counts
    -- as properly evidenced; below that it is scaled down rather than dropped off a cliff.
    local function evidence(m, full)
        return math.clamp(m.n / (full or 8), 0, 1)
    end

    local function countConf(count, full)
        return math.clamp(count / (full or 6), 0, 1)
    end

    local function safeDiv(a, b)
        return b > 0 and (a / b) or 0
    end

    -- Maps a measurement onto the -1..+1 the blender wants, given the value a weak player produces
    -- and the value a strong one does. Used where both ends mean something - an accuracy of zero
    -- really is bad, not merely unremarkable.
    local function scale(value, low, high)
        if low == high then return 0 end
        return math.clamp((value - low) / (high - low), 0, 1) * 2 - 1
    end

    -- Counting signals where doing none of it is unremarkable rather than bad. Most players never
    -- break a bed; that is not a flaw, so zero has to land on neutral and not on -1.
    local function reward(value, good)
        if good <= 0 then return 0 end
        return math.clamp(value / good, 0, 1)
    end

    -- Signals where both extremes are wrong and the middle is right - target switching, time spent
    -- on a generator.
    local function bell(value, ideal, spread)
        if spread <= 0 then return 0 end
        return math.clamp(1 - (math.abs(value - ideal) / spread), -1, 1)
    end

    ----------------------------------------------------------------------------
    -- The blender.
    ----------------------------------------------------------------------------
    -- Every category is a bag of named signals. `total` accumulates the weight of every signal the
    -- category declares, `conf` the weight actually backed by evidence - so a category we can only
    -- half observe reports a middling confidence and a score pulled toward 50, rather than a
    -- confident-looking score assembled from whichever three signals happened to have data.
    local function blender()
        return {sum = 0, weight = 0, conf = 0, total = 0, named = {}}
    end

    local function signal(b, name, deviation, weight, confidence)
        weight = weight or 1
        confidence = math.clamp(confidence or 0, 0, 1)
        deviation = math.clamp(deviation or 0, -1, 1)
        b.total = b.total + weight
        b.conf = b.conf + weight * confidence
        local w = weight * confidence
        if w > 0 then
            b.sum = b.sum + deviation * w
            b.weight = b.weight + w
            b.named[name] = {Deviation = deviation, Confidence = confidence, Weight = weight}
        end
    end

    local function resolve(b)
        if b.total <= 0 then return 50, 0, b end
        local conf = b.conf / b.total
        if b.weight <= 0 then return 50, conf, b end
        local mean = b.sum / b.weight
        -- Low confidence holds the score near Average, so one well-evidenced signal in an
        -- otherwise unobserved category cannot swing it to an extreme.
        return math.clamp(50 + mean * 50 * (0.4 + 0.6 * conf), 0, 100), conf, b
    end

    ----------------------------------------------------------------------------
    -- State.
    ----------------------------------------------------------------------------
    local profiles, engagements, pendingVoid, tags, seen = {}, {}, {}, {}, {}
    local folder
    local running = false
    local probeBudget = 0
    local matchStart, bedsAtStart, lastMatchState = tick(), 0, -1

    -- Bed, generator and player positions are rebuilt a couple of times a second and shared by
    -- everyone, so the per-frame sampling never walks CollectionService or re-reads a position
    -- once per player per player.
    local world = {
        At = 0,
        Beds = {},
        Generators = {},
        Roster = {},
        Stage = 'Early',
        Elapsed = 0,
        TeamSize = 1
    }

    local function newProfile(plr)
        local now = tick()
        return {
            Player = plr,
            FirstSeen = now,
            LastSeen = now,
            LastSample = 0,
            LastProbe = 0,
            LastHeavy = 0,
            Observed = 0,       -- seconds we have actually had eyes on them
            Dirty = true,
            NextScore = 0,
            Cache = nil,
            Events = {},

            Combat = {
                Swings = 0, SwingHits = 0, SwingIds = {}, PendingSwing = 0, PendingSwingId = nil,
                Hits = 0, MeleeHits = 0,
                Projectiles = 0, ProjectileHits = 0,
                DamageDealt = 0, DamageTaken = 0,
                Kills = 0, Deaths = 0, FinalKills = 0,
                FightsWon = 0, FightsLost = 0,
                UphillFights = 0, UphillWins = 0,
                Combo = 0, BestCombo = 0, ComboCount = 0, ComboHits = 0,
                LastVictim = nil, LastHit = 0,
                LastHurt = 0, LastHurtBy = nil,
                FirstHits = 0, FirstHitChances = 0,
                VoidKills = 0,
                Switches = 0, SwitchSeen = {}, SwitchAt = 0,
                Reaction = meter(0),
                Strafe = meter(0),
                Tracking = meter(0),
                KillQuality = meter(1)
            },

            Movement = {
                Blocks = 0, BridgeRun = 0, BridgeTime = 0, BridgeAt = 0,
                Distance = 0, Pauses = 0, PauseAt = 0,
                Falls = 0, UnforcedFalls = 0, Saves = 0, Parkour = 0, Jumps = 0,
                Clutches = 0,
                KnockbackAt = 0, KnockbackFrom = nil,
                EdgeApproaches = 0, EdgeStops = 0, EdgeAt = 0,
                LastPos = nil, LastDir = nil, LastVel = nil,
                Ground = nil, OverVoid = false,
                FallFrom = nil, Airborne = false,
                BridgeSpeed = meter(0),
                Recovery = meter(0),
                Positioning = meter(0)
            },

            Sense = {
                Threats = 0, ThreatReactions = 0, ThreatFrom = nil, ThreatAt = 0, ThreatAnswered = false,
                BedAlerts = 0, BedResponses = 0, BedAlert = false, LastAlert = 0,
                Retreats = 0, RetreatFrom = nil, RetreatAt = 0,
                Chases = 0, PointlessChases = 0, ChaseAt = 0,
                SafeTime = 0, ExposedTime = 0,
                ToolSwaps = 0, LastHand = nil,
                LowHealthDeaths = 0, LowHealthEscapes = 0,
                SaveChanceAt = 0,
                BedResponseTime = meter(0)
            },

            Objectives = {
                BedApproaches = 0, BedApproachAt = 0,
                DefenceBroken = 0,
                Rushes = 0, RushWins = 0,
                Beds = 0,
                FinalKills = 0, Assists = 0, Escapes = 0,
                Pressure = 0,
                BedBreakTime = meter(0)
            },

            Resources = {
                GenTime = 0, GenAt = 0, GenVisits = 0,
                Iron = 0, Diamond = 0, Emerald = 0,
                IronSpent = 0, DiamondSpent = 0, EmeraldSpent = 0,
                Lost = 0, LostEvents = 0,
                Purchases = 0, Upgrades = 0,
                BestGear = 0,
                LastInventory = nil, InventoryAt = 0,
                Prepared = meter(0),
                GearTier = meter(0)
            },

            Teamwork = {
                Assists = 0,
                Saves = 0, SaveChances = 0, SaveAt = 0,
                Shared = 0,
                Defends = 0,
                PushWindow = 0,
                ControlTime = 0
            },

            Context = {
                Kit = nil, Team = nil,
                AFK = false,
                LastMove = now, LastAction = now,
                Alive = true, Respawns = 0, LastDeath = 0,
                Trapped = false,
                Lagged = 0, Samples = 0,
                Gaps = 0, GapTime = 0,
                Health = 1, Gear = 0, Armour = 0
            }
        }
    end

    local function profileFor(plr)
        if not plr then return nil end
        local record = profiles[plr]
        if not record then
            record = newProfile(plr)
            profiles[plr] = record
        end
        return record
    end

    -- Read path only, so asking about a player never allocates them a profile.
    local function peek(plr)
        return plr and profiles[plr] or nil
    end

    local function touch(record)
        record.Dirty = true
    end

    local function addEvent(record, kind, confidence, detail)
        local events = record.Events
        table.insert(events, {Type = kind, Time = tick(), Confidence = math.clamp(confidence or 1, 0, 1), Detail = detail})
        while #events > EVENT_LIMIT do
            table.remove(events, 1)
        end
        record.Dirty = true
    end

    ----------------------------------------------------------------------------
    -- Match context.
    ----------------------------------------------------------------------------
    local function teamOf(plr)
        if not plr then return nil end
        local team = plr:GetAttribute('Team')
        if team == nil and plr.Character then
            team = plr.Character:GetAttribute('Team')
        end
        return team
    end

    local function sameTeam(a, b)
        local ta, tb = teamOf(a), teamOf(b)
        return ta ~= nil and tb ~= nil and ta == tb
    end

    -- 0 = warmup, 1 = playing, 2 = over. Only a live match is worth judging anyone on, so the
    -- event handlers gate on this while the labels keep rendering whatever we already know.
    local function playing()
        return store.matchState == 1
    end

    local function bedPartOf(bed)
        return bed:IsA('BasePart') and bed or bed:FindFirstChildWhichIsA('BasePart')
    end

    local function refreshWorld(now)
        if now - world.At < WORLD_INTERVAL then return end
        world.At = now

        table.clear(world.Beds)
        local standing = 0
        for _, bed in collectionService:GetTagged('bed') do
            if bed.Parent then
                local part = bedPartOf(bed)
                if part then
                    standing = standing + 1
                    table.insert(world.Beds, {Position = part.Position, Object = bed})
                end
            end
        end

        table.clear(world.Generators)
        for _, gen in collectionService:GetTagged('Generator') do
            local part = gen:IsA('BasePart') and gen or gen:FindFirstChildWhichIsA('BasePart')
            if part then
                local id = tostring(gen:GetAttribute('Id') or ''):lower()
                table.insert(world.Generators, {
                    Position = part.Position,
                    Kind = id:find('emerald') and 'emerald' or id:find('diamond') and 'diamond' or 'iron'
                })
            end
        end

        -- One pass for the roster: positions, teams and the biggest team in the lobby, which is
        -- the only honest read on whether this is solos or squads. We are in it too, because we
        -- are a threat to stand on somebody's bed like anyone else.
        table.clear(world.Roster)
        local sizes, biggest = {}, 1
        local function addToRoster(plr, root)
            if not plr or not root or not root.Parent then return end
            local team = teamOf(plr)
            table.insert(world.Roster, {Player = plr, Position = root.Position, Team = team})
            if team ~= nil then
                sizes[team] = (sizes[team] or 0) + 1
                biggest = math.max(biggest, sizes[team])
            end
        end
        for _, ent in entitylib.List do
            addToRoster(ent.Player, ent.RootPart)
        end
        if entitylib.isAlive then
            addToRoster(lplr, entitylib.character.RootPart)
        end
        world.TeamSize = biggest

        -- Early / mid / late, from the clock and from how many beds are left. Rushing is worth far
        -- more in the first two minutes, and what counts as impressive gear moves with the match.
        local elapsed = now - matchStart
        local fraction = safeDiv(standing, math.max(bedsAtStart, standing, 1))
        world.Elapsed = elapsed
        if elapsed < 150 and fraction > 0.7 then
            world.Stage = 'Early'
        elseif elapsed > 480 or fraction < 0.35 then
            world.Stage = 'Late'
        else
            world.Stage = 'Mid'
        end
    end

    -- The bed belonging to this player's team, and the nearest bed that does not - the two things
    -- every objective, defence and positioning signal is measured against.
    local function bedsFor(plr, position)
        local team = teamOf(plr)
        local own, ownDist, enemy, enemyDist = nil, math.huge, nil, math.huge
        for _, bed in world.Beds do
            local mine = team ~= nil and bed.Object:GetAttribute('Team' .. team .. 'NoBreak') and true or false
            local dist = position and (bed.Position - position).Magnitude or math.huge
            if mine then
                -- Their own bed is theirs whether or not we were given a position to measure to.
                if own == nil or dist < ownDist then
                    own, ownDist = bed, dist
                end
            elseif dist < enemyDist then
                enemy, enemyDist = bed, dist
            end
        end
        return own, ownDist, enemy, enemyDist
    end

    local function nearestGenerator(position)
        local bestDist, bestKind = math.huge, nil
        for _, gen in world.Generators do
            local dist = (gen.Position - position).Magnitude
            if dist < bestDist then
                bestDist, bestKind = dist, gen.Kind
            end
        end
        return bestDist, bestKind
    end

    ----------------------------------------------------------------------------
    -- Gear, health and kits.
    ----------------------------------------------------------------------------
    local function inventoryOf(plr)
        return store.inventories[plr]
    end

    local function swordDamage(inv)
        local best = 0
        for _, item in (inv and inv.items or {}) do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.sword and (meta.sword.damage or 0) > best then
                best = meta.sword.damage
            end
        end
        return best
    end

    local function armourValue(inv)
        local total = 0
        for _, item in (inv and inv.armor or {}) do
            local meta = item and bedwars.ItemMeta[item.itemType]
            if meta and meta.armor then
                total = total + (meta.armor.damageReductionMultiplier or 0)
            end
        end
        return total
    end

    local function resourceCount(inv, kind)
        local total = 0
        for _, item in (inv and inv.items or {}) do
            if item.itemType == kind then
                total = total + (item.amount or 0)
            end
        end
        return total
    end

    -- One number for "how well equipped are they", weapon and armour together, so comparing two
    -- players' gear is a single subtraction. nil when their inventory has not replicated to us -
    -- which is a missing input, not a player with nothing.
    local function gearOf(plr)
        local inv = inventoryOf(plr)
        if not inv then return nil end
        return swordDamage(inv) + armourValue(inv) * 30
    end

    local function healthFraction(plr)
        local char = plr.Character
        if not char then return 1 end
        local health, maximum = char:GetAttribute('Health'), char:GetAttribute('MaxHealth')
        if not health or not maximum or maximum <= 0 then return 1 end
        return math.clamp(health / maximum, 0, 1)
    end

    local function kitOf(plr)
        return plr:GetAttribute('PlayingAsKits') or plr:GetAttribute('PlayingAsKit') or nil
    end

    -- Kits change what a signal is worth. A kit that hands out mobility makes bridging and parkour
    -- cheaper to look good at; a kit with a combat ability does the same for damage. These only
    -- soften the confidence of the affected signals, never the score itself, so a kit we do not
    -- recognise costs nobody anything.
    local KIT_MOVEMENT = {dasher = 0.7, angel = 0.65, void_dragon = 0.6, owl = 0.7, dragonslayer = 0.8, yuzi = 0.8, melody = 0.85, cyber = 0.8}
    local KIT_COMBAT = {barbarian = 0.8, vulcan = 0.75, ember = 0.8, ice_queen = 0.85, mage = 0.85, ranger = 0.85, pyro = 0.85}

    -- Status effects replicate as character attributes. Being trapped or frozen is not a skill
    -- failure, and killing somebody who is is not a skill success.
    local function statusTrapped(plr)
        local char = plr.Character
        if not char then return false end
        for name, value in char:GetAttributes() do
            if type(name) == 'string' and name:find('StatusEffect_') and value ~= false and value ~= 0 then
                local lowered = name:lower()
                if lowered:find('trap') or lowered:find('stun') or lowered:find('freeze') or lowered:find('root') or lowered:find('web') then
                    return true
                end
            end
        end
        return false
    end

    ----------------------------------------------------------------------------
    -- Data quality.
    ----------------------------------------------------------------------------
    local function localPing()
        local ping = 0
        pcall(function()
            ping = lplr:GetNetworkPing()
        end)
        return ping
    end

    -- Everything timing-sensitive - reaction time, first hits, aim tracking - is measured through
    -- our own connection, so our own ping is a hard ceiling on how far any of it can be trusted.
    local function timingConfidence()
        return math.clamp(1 - (localPing() / 0.35), 0.15, 1)
    end

    -- How much of what we think we know is actually ours to know. Time streamed out, samples
    -- thrown away as lag and a missing replicated inventory all land here, and all of them cost
    -- confidence rather than quietly changing the score.
    local function dataQuality(record)
        local context = record.Context
        local watched = math.max(record.Observed, 0.01)
        local coverage = math.clamp(watched / math.max(tick() - record.FirstSeen, watched), 0.2, 1)
        local clean = 1 - math.clamp(safeDiv(context.Lagged, math.max(context.Samples, 1)), 0, 0.6)
        return math.clamp(coverage * clean * (inventoryOf(record.Player) and 1 or 0.75), 0.1, 1)
    end

    -- A player nobody should be scored against. Returns 0..1, where 1 is somebody in a fair state
    -- to be fighting. This is the number that stops farming reading as skill.
    local function playerQuality(record)
        if not record then return 0.5 end
        local context = record.Context
        local quality = 1
        if context.AFK then
            quality = quality * 0.15
        end
        if context.Trapped then
            quality = quality * 0.4
        end
        -- Repeatedly respawning into the same fight. Every death inside the last minute makes the
        -- next one worth less to whoever takes it.
        local rate = safeDiv(context.Respawns, math.max((tick() - record.FirstSeen) / 60, 0.5))
        if rate > 1.5 then
            quality = quality * math.clamp(1 - (rate - 1.5) * 0.3, 0.3, 1)
        end
        if context.Health < 0.35 then
            quality = quality * 0.7
        end
        return math.clamp(quality, 0.05, 1)
    end

    ----------------------------------------------------------------------------
    -- Engagements.
    ----------------------------------------------------------------------------
    -- A fight is a pair of players trading damage. Tracking it as an object rather than as two
    -- separate hit counters is what makes first-hit rate, fight wins, escapes, assists and
    -- gear-relative performance answerable at all.
    local function engagementFor(attacker, victim)
        local key, flipped
        if attacker.UserId < victim.UserId then
            key, flipped = attacker.UserId .. ':' .. victim.UserId, false
        else
            key, flipped = victim.UserId .. ':' .. attacker.UserId, true
        end

        local now = tick()
        local fight = engagements[key]
        if fight and now - fight.Last > ENGAGE_MEMORY then
            engagements[key] = nil
            fight = nil
        end
        if not fight then
            fight = {
                A = flipped and victim or attacker,
                B = flipped and attacker or victim,
                Start = now,
                Opener = attacker,
                Damage = {},
                Counted = false,
                Resolved = false,
                -- Gear as it stood when the fight opened. The winner may well be holding the
                -- loser's kit by the time it ends, so reading it later would invert the signal.
                GearA = gearOf(flipped and victim or attacker),
                GearB = gearOf(flipped and attacker or victim)
            }
            engagements[key] = fight
        end
        fight.Last = now
        return fight
    end

    local function engagementsInvolving(plr, into)
        table.clear(into)
        for _, fight in engagements do
            if fight.A == plr or fight.B == plr then
                table.insert(into, fight)
            end
        end
        return into
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: swings.
    ----------------------------------------------------------------------------
    -- Swing animations replicate, so misses are countable - but only once we know which of a
    -- player's animations is their swing. The first animation id that keeps coinciding with their
    -- damage output becomes their swing id, and only then do misses start counting, so a kit
    -- ability is never mistaken for a whiffed hit. Until an id is confirmed nothing is scored.
    local function noteSwing(plr, animationId)
        local record = peek(plr)
        if not record then return end
        local combat = record.Combat
        local entry = combat.SwingIds[animationId]
        if not entry then
            entry = {Seen = 0, Hits = 0, Confirmed = false}
            combat.SwingIds[animationId] = entry
        end
        entry.Seen = entry.Seen + 1
        if entry.Confirmed then
            combat.Swings = combat.Swings + 1
        end
        combat.PendingSwing = tick()
        combat.PendingSwingId = animationId
        record.Context.LastAction = tick()
    end

    local function confirmSwing(record)
        local combat = record.Combat
        local id = combat.PendingSwingId
        if not id or tick() - combat.PendingSwing > SWING_WINDOW then return end
        local entry = combat.SwingIds[id]
        if not entry then return end
        entry.Hits = entry.Hits + 1
        if entry.Confirmed then
            combat.SwingHits = combat.SwingHits + 1
        elseif entry.Hits >= 3 and entry.Hits / math.max(entry.Seen, 1) > 0.3 then
            -- Recognised. Everything already seen for this id was a swing, so accuracy does not
            -- restart from zero the moment we work out what we have been watching.
            entry.Confirmed = true
            combat.Swings = combat.Swings + entry.Seen
            combat.SwingHits = combat.SwingHits + entry.Hits
        end
        combat.PendingSwingId = nil
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: damage.
    ----------------------------------------------------------------------------
    local function noteTargetSwitch(record, victim)
        local combat = record.Combat
        local now = tick()
        if now - combat.SwitchAt > FIGHT_MEMORY then
            table.clear(combat.SwitchSeen)
            combat.SwitchAt = now
        end
        if victim and not combat.SwitchSeen[victim] then
            combat.SwitchSeen[victim] = true
            local count = 0
            for _ in combat.SwitchSeen do
                count = count + 1
            end
            if count > 1 then
                combat.Switches = combat.Switches + 1
            end
        end
    end

    local fightScratch = {}

    local function onDamage(damageTable)
        if not running or not playing() then return end
        local amount = damageTable.damage or 0
        if amount <= 0 then return end

        local attacker = damageTable.fromEntity and playersService:GetPlayerFromCharacter(damageTable.fromEntity)
        local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
        if attacker == victim then return end
        if not attacker and not victim then return end

        local now = tick()
        local melee = damageTable.damageType == 0
        local attackerRecord = attacker and attacker ~= lplr and profileFor(attacker) or nil
        local victimRecord = victim and victim ~= lplr and profileFor(victim) or nil

        if victimRecord then
            local combat = victimRecord.Combat
            combat.DamageTaken = combat.DamageTaken + amount
            combat.LastHurt = now
            combat.LastHurtBy = attacker
            victimRecord.Context.LastAction = now
            -- Knockback is what actually kills people over a gap, so remember who applied it and
            -- whether the victim was over open air when it landed.
            local knockback = damageTable.knockbackMultiplier
            if knockback and not knockback.disabled and attacker then
                victimRecord.Movement.KnockbackAt = now
                victimRecord.Movement.KnockbackFrom = attacker
                if victimRecord.Movement.OverVoid then
                    pendingVoid[victim] = {From = attacker, At = now}
                end
            end
            touch(victimRecord)
        end

        -- The engagement is tracked from whichever side we can profile, including fights against
        -- us. A player who spends the whole match on the local player would otherwise finish it
        -- with no fight wins, no first hits and no gear-relative record at all - there is simply
        -- nobody to award the other half of each fight to.
        if attacker and victim then
            local fight = engagementFor(attacker, victim)
            fight.Damage[attacker] = (fight.Damage[attacker] or 0) + amount

            -- First hit. Only the opener gets the credit, and only once per fight, so a long
            -- scrap cannot inflate it.
            if not fight.Counted then
                fight.Counted = true
                if attackerRecord then
                    attackerRecord.Combat.FirstHitChances = attackerRecord.Combat.FirstHitChances + 1
                    if fight.Opener == attacker then
                        attackerRecord.Combat.FirstHits = attackerRecord.Combat.FirstHits + 1
                    end
                end
                if victimRecord then
                    victimRecord.Combat.FirstHitChances = victimRecord.Combat.FirstHitChances + 1
                end
            end
        end

        if not attackerRecord then return end
        local combat = attackerRecord.Combat
        combat.DamageDealt = combat.DamageDealt + amount
        combat.Hits = combat.Hits + 1
        attackerRecord.Context.LastAction = now
        if melee then
            combat.MeleeHits = combat.MeleeHits + 1
            confirmSwing(attackerRecord)
        else
            combat.ProjectileHits = combat.ProjectileHits + 1
        end

        -- Combo: hits that keep landing on the same person without a gap. Any pause or a change of
        -- victim ends it, so two people trading singles never adds up into one long combo.
        if combat.LastVictim == victim and now - combat.LastHit <= COMBO_WINDOW then
            combat.Combo = combat.Combo + 1
            combat.ComboHits = combat.ComboHits + 1
            if combat.Combo == 3 then
                combat.ComboCount = combat.ComboCount + 1
                addEvent(attackerRecord, 'Combo', 1, victim and victim.Name or nil)
            end
        else
            combat.Combo = 1
        end
        combat.BestCombo = math.max(combat.BestCombo, combat.Combo)
        combat.LastVictim, combat.LastHit = victim, now
        noteTargetSwitch(attackerRecord, victim)

        -- Reaction time: how quickly they answer being hit themselves.
        if combat.LastHurt > 0 and now - combat.LastHurt < 2 then
            observe(combat.Reaction, math.clamp(now - combat.LastHurt, 0.05, 2))
        end

        if not victim then
            touch(attackerRecord)
            return
        end

        -- Protecting a teammate: hitting somebody who is at that moment in a fight with one of
        -- your own. Rate limited so holding an angle on one attacker is one save, not thirty.
        if now - attackerRecord.Teamwork.SaveAt > 3 then
            for _, other in engagementsInvolving(victim, fightScratch) do
                local partner = other.A == victim and other.B or other.A
                if partner ~= attacker and sameTeam(partner, attacker) and now - other.Last <= FIGHT_MEMORY then
                    attackerRecord.Teamwork.Saves = attackerRecord.Teamwork.Saves + 1
                    attackerRecord.Teamwork.SaveAt = now
                    break
                end
            end
        end

        touch(attackerRecord)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: deaths.
    ----------------------------------------------------------------------------
    local function resolveEngagements(victim, killer)
        local now = tick()
        local fights = engagementsInvolving(victim, {})
        for _, fight in fights do
            local other = fight.A == victim and fight.B or fight.A
            local otherRecord = peek(other)

            if not fight.Resolved then
                fight.Resolved = true
                local victimRecord = peek(victim)
                if victimRecord then
                    victimRecord.Combat.FightsLost = victimRecord.Combat.FightsLost + 1
                end
                if otherRecord and (killer == other or (fight.Damage[other] or 0) > 0) then
                    otherRecord.Combat.FightsWon = otherRecord.Combat.FightsWon + 1
                    local mine = fight.A == other and fight.GearA or fight.GearB
                    local theirs = fight.A == other and fight.GearB or fight.GearA
                    -- Only counts as a fair test when we actually knew both loadouts.
                    if mine and theirs then
                        otherRecord.Combat.UphillFights = otherRecord.Combat.UphillFights + 1
                        if mine <= theirs + 1 then
                            otherRecord.Combat.UphillWins = otherRecord.Combat.UphillWins + 1
                            addEvent(otherRecord, 'UphillWin', 0.85, victim.Name)
                        end
                    end
                end
            end

            -- Anyone who did real damage inside the assist window and did not land the kill.
            if other ~= killer and (fight.Damage[other] or 0) > 0 and now - fight.Last <= ASSIST_WINDOW then
                if otherRecord and not sameTeam(other, victim) then
                    otherRecord.Objectives.Assists = otherRecord.Objectives.Assists + 1
                    otherRecord.Teamwork.Assists = otherRecord.Teamwork.Assists + 1
                    addEvent(otherRecord, 'Assist', 0.8, victim.Name)
                end
            end
        end
    end

    local function onDeath(deathTable)
        if not running then return end
        local killer = deathTable.fromEntity and playersService:GetPlayerFromCharacter(deathTable.fromEntity)
        local victim = deathTable.entityInstance and playersService:GetPlayerFromCharacter(deathTable.entityInstance)
        if not victim then return end

        local now = tick()
        local victimRecord = victim ~= lplr and profileFor(victim) or nil
        if victimRecord then
            local context = victimRecord.Context
            context.Alive = false
            context.Respawns = context.Respawns + 1
            context.LastDeath = now
            victimRecord.Combat.Deaths = victimRecord.Combat.Deaths + 1
            victimRecord.Combat.Combo = 0

            -- What the death cost them. The last inventory we saw is the best estimate, and it is
            -- the number that separates a careful player from one who dies holding forty iron.
            local inv = victimRecord.Resources.LastInventory
            if inv then
                local lost = inv.Iron + inv.Diamond * 4 + inv.Emerald * 8
                if lost > 0 then
                    victimRecord.Resources.Lost = victimRecord.Resources.Lost + lost
                    victimRecord.Resources.LostEvents = victimRecord.Resources.LostEvents + 1
                end
            end
            addEvent(victimRecord, deathTable.finalKill and 'Eliminated' or 'Death', 1, killer and killer.Name or nil)
        end

        -- Void kill: somebody knocked them out over open air and the death followed. Inferred, so
        -- it carries a confidence rather than being counted as a clean fact.
        local void = pendingVoid[victim]
        if void and now - void.At <= VOID_WINDOW then
            local voidRecord = peek(void.From)
            if voidRecord and not sameTeam(void.From, victim) then
                voidRecord.Combat.VoidKills = voidRecord.Combat.VoidKills + 1
                addEvent(voidRecord, 'VoidKnockback', 0.7, victim.Name)
            end
        end
        pendingVoid[victim] = nil

        if killer and killer ~= victim and killer ~= lplr and not sameTeam(killer, victim) then
            local killerRecord = profileFor(killer)
            killerRecord.Combat.Kills = killerRecord.Combat.Kills + 1
            killerRecord.Context.LastAction = now

            -- What was this kill actually worth? An AFK, trapped, out-geared or endlessly
            -- respawning victim is not evidence of skill, and the discount is applied here rather
            -- than by trying to unpick it from an aggregate later. Killing us is worth most of a
            -- real kill - we are demonstrably a live human - but we do not profile ourselves, so
            -- it cannot be checked the way everybody else's is.
            local quality = victimRecord and playerQuality(victimRecord) or (victim == lplr and 0.85 or 0.5)
            local killerGear, victimGear = gearOf(killer), gearOf(victim)
            if killerGear and victimGear and killerGear > victimGear + 20 then
                quality = quality * math.clamp(1 - (killerGear - victimGear - 20) / 80, 0.35, 1)
            end
            observe(killerRecord.Combat.KillQuality, quality)

            if deathTable.finalKill then
                killerRecord.Combat.FinalKills = killerRecord.Combat.FinalKills + 1
                killerRecord.Objectives.FinalKills = killerRecord.Objectives.FinalKills + 1
                addEvent(killerRecord, 'FinalKill', 1, victim.Name)
            else
                addEvent(killerRecord, 'Kill', 1, victim.Name)
            end
        end

        resolveEngagements(victim, killer)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: beds and blocks.
    ----------------------------------------------------------------------------
    -- One place to register "they have turned up at somebody else's bed", so the counters and the
    -- event trail agree however we came to notice. Standing near a bed is weak evidence of intent
    -- and only reads as a rush early on; taking its defence apart is neither, and the confidence
    -- carried by the event says which of the two it was.
    local function noteBedApproach(record, rushing, confidence)
        if record.Objectives.BedApproachAt ~= 0 then return end
        record.Objectives.BedApproachAt = tick()
        record.Objectives.BedApproaches = record.Objectives.BedApproaches + 1
        if rushing then
            record.Objectives.Rushes = record.Objectives.Rushes + 1
        end
        addEvent(record, 'BedApproach', confidence, world.Stage)
    end

    local function onBedBreak(bedTable)
        if not running then return end
        local breaker = bedTable.player
        if not breaker or breaker == lplr then return end
        local record = profileFor(breaker)
        record.Objectives.Beds = record.Objectives.Beds + 1
        record.Context.LastAction = tick()

        -- How long from turning up at that bed to taking it. Short is a clean break; a long one
        -- means they were fought off it and came back, which is a different story - and a better
        -- one, so it is credited as a rush that eventually worked either way.
        if record.Objectives.BedApproachAt > 0 then
            observe(record.Objectives.BedBreakTime, math.clamp(tick() - record.Objectives.BedApproachAt, 1, 120))
            record.Objectives.RushWins = record.Objectives.RushWins + 1
            record.Objectives.BedApproachAt = 0
        end

        addEvent(record, 'BedBreak', 1, world.Stage)
        -- Pressure created for teammates: a bed gone is a team that has to defend instead of push.
        for _, entry in world.Roster do
            if entry.Player ~= breaker and sameTeam(entry.Player, breaker) then
                local mate = peek(entry.Player)
                if mate then
                    mate.Objectives.Pressure = mate.Objectives.Pressure + 1
                    touch(mate)
                end
            end
        end
    end

    local function onPlaceBlock(data)
        if not running or not playing() then return end
        local plr = data.player
        if not plr or plr == lplr then return end
        local record = profileFor(plr)
        local movement, now = record.Movement, tick()
        movement.Blocks = movement.Blocks + 1
        record.Context.LastAction = now

        -- Bridging: blocks laid in an unbroken run. The rate over the run is the speed signal, and
        -- a run that keeps going is what tells bridging apart from panic placing.
        if now - movement.BridgeAt <= 1.2 then
            movement.BridgeRun = movement.BridgeRun + 1
            movement.BridgeTime = movement.BridgeTime + (now - movement.BridgeAt)
            if movement.BridgeRun >= 4 and movement.BridgeTime > 0 then
                observe(movement.BridgeSpeed, movement.BridgeRun / movement.BridgeTime, 0.5)
            end
        else
            movement.BridgeRun, movement.BridgeTime = 1, 0
        end
        movement.BridgeAt = now

        local position = data.blockRef and data.blockRef.blockPosition
        if not position then
            touch(record)
            return
        end
        position = position * 3

        -- A block dropped under their own feet while falling fast is a clutch, not a bridge.
        if movement.LastPos and movement.LastVel and position.Y < movement.LastPos.Y - 2 and movement.LastVel.Y < -35 then
            movement.Clutches = movement.Clutches + 1
            addEvent(record, 'BlockClutch', 0.75)
        end

        local own, ownDist, _, enemyDist = bedsFor(plr, position)
        if own and ownDist <= BED_NEAR then
            record.Teamwork.Defends = record.Teamwork.Defends + 1
            if record.Sense.BedAlert and record.Sense.LastAlert > 0 then
                record.Sense.BedResponses = record.Sense.BedResponses + 1
                observe(record.Sense.BedResponseTime, math.clamp(now - record.Sense.LastAlert, 0.5, 30))
                record.Sense.BedAlert = false
            end
        elseif enemyDist <= BED_NEAR then
            -- Blocks at somebody else's bed are a push being consolidated, not defence.
            record.Objectives.Pressure = record.Objectives.Pressure + 0.5
        end
        touch(record)
    end

    local function onBreakBlock(data)
        if not running or not playing() then return end
        local plr = data.player
        if not plr or plr == lplr then return end
        local position = data.blockRef and data.blockRef.blockPosition
        if not position then return end
        local record = profileFor(plr)
        record.Context.LastAction = tick()
        position = position * 3

        local _, _, _, enemyDist = bedsFor(plr, position)
        if enemyDist <= BED_NEAR then
            -- Defence broken: blocks coming off the shell around a bed that is not theirs. Digging
            -- into someone's base is a push at any stage of the match, not just an early rush.
            record.Objectives.DefenceBroken = record.Objectives.DefenceBroken + 1
            noteBedApproach(record, true, 0.85)
        end
        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: projectiles.
    ----------------------------------------------------------------------------
    -- Every projectile in the game replicates as a workspace child carrying the shooter's UserId,
    -- so launches are countable for everyone and not just for us. Hits come from the damage
    -- stream, and the two together are the only honest read on projectile accuracy.
    local function onProjectile(object)
        if not running then return end
        local shooter = object:GetAttribute('ProjectileShooter')
        if not shooter then return end
        local plr = playersService:GetPlayerByUserId(shooter)
        if not plr or plr == lplr then return end
        local record = peek(plr)
        if not record then return end
        record.Combat.Projectiles = record.Combat.Projectiles + 1
        record.Context.LastAction = tick()
        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Sampling.
    ----------------------------------------------------------------------------
    local function sampleEntity(ent, record, dt, near)
        local root = ent.RootPart
        if not root or not root.Parent then return end
        local now = tick()
        local movement, context = record.Movement, record.Context
        local position = root.Position
        local velocity = root.AssemblyLinearVelocity
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z)

        -- A streaming gap. Nothing measured across one means anything, so the movement history is
        -- dropped rather than read as a very fast trip across the map.
        if now - record.LastSeen > SEEN_TIMEOUT then
            context.Gaps = context.Gaps + 1
            context.GapTime = context.GapTime + (now - record.LastSeen)
            movement.LastPos, movement.LastDir, movement.LastVel = nil, nil, nil
        end
        record.LastSeen = now
        context.Samples = context.Samples + 1
        record.Observed = record.Observed + math.min(dt, 1)

        local previous = movement.LastPos
        if previous then
            local step = (position - previous).Magnitude
            if step > TELEPORT_JUMP then
                -- A teleport, a respawn or a lag spike, not movement.
                context.Lagged = context.Lagged + 1
                movement.LastPos, movement.LastDir, movement.LastVel = position, nil, velocity
                touch(record)
                return
            end
            movement.Distance = movement.Distance + step
            if step > 0.6 then
                context.LastMove = now
            end
        end

        local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
        local sampleWeight = math.min(dt * 4, 1)

        -- Strafing. Direction changes frame to frame while fighting, never while walking the map.
        if fighting and movement.LastDir and horizontal.Magnitude > 4 then
            local change = 1 - math.clamp(horizontal.Unit:Dot(movement.LastDir), -1, 1)
            observe(record.Combat.Strafe, math.clamp(change / 1.2, 0, 1), sampleWeight)
        end
        if horizontal.Magnitude > 1 then
            movement.LastDir = horizontal.Unit
        end

        -- Aim tracking. How well they keep facing whoever they are actually fighting.
        local opponent = record.Combat.LastVictim or record.Combat.LastHurtBy
        if fighting and opponent and opponent.Character then
            local theirRoot = opponent.Character:FindFirstChild('HumanoidRootPart')
            if theirRoot then
                local toward = (theirRoot.Position - position) * Vector3.new(1, 0, 1)
                local facing = root.CFrame.LookVector * Vector3.new(1, 0, 1)
                if toward.Magnitude > 1 and facing.Magnitude > 0.01 then
                    observe(record.Combat.Tracking, math.clamp(facing.Unit:Dot(toward.Unit), 0, 1), sampleWeight)
                end
            end
        end

        -- Pauses. Standing still mid-fight is hesitation; standing still out of one is not.
        if fighting and horizontal.Magnitude < 1.5 then
            if movement.PauseAt == 0 then
                movement.PauseAt = now
            elseif now - movement.PauseAt > 0.8 then
                movement.Pauses = movement.Pauses + 1
                movement.PauseAt = now
            end
        else
            movement.PauseAt = 0
        end

        -- Knockback recovery: how fast they get back to moving under their own power after a hit -
        -- the difference between eating a combo and walking out of one.
        if movement.KnockbackAt > 0 and now - movement.KnockbackAt < 3 then
            if horizontal.Magnitude > 12 and math.abs(velocity.Y) < 12 then
                observe(movement.Recovery, math.clamp(now - movement.KnockbackAt, 0.05, 3))
                movement.KnockbackAt = 0
            end
        end

        if ent.Jumping then
            movement.Jumps = movement.Jumps + 1
        end

        -- Falls. Falling after being hit is somebody else's doing; falling with nothing on the
        -- clock is their own, and a big drop they walk away from was a save.
        local wasAirborne = movement.Airborne
        movement.Airborne = velocity.Y < -12
        if movement.Airborne and not wasAirborne then
            movement.FallFrom = position
        elseif wasAirborne and not movement.Airborne and movement.FallFrom then
            local drop = movement.FallFrom.Y - position.Y
            if drop > 12 then
                movement.Falls = movement.Falls + 1
                if now - record.Combat.LastHurt > FIGHT_MEMORY then
                    movement.UnforcedFalls = movement.UnforcedFalls + 1
                    addEvent(record, 'UnforcedFall', 0.6)
                elseif drop > 25 then
                    movement.Saves = movement.Saves + 1
                end
            elseif drop > 4 then
                movement.Parkour = movement.Parkour + 1
            end
            movement.FallFrom = nil
        end

        movement.LastPos, movement.LastVel = position, velocity

        -- Generator camping and resource control. Time on a generator is economy; time on a
        -- diamond or emerald generator is map control, whoever owns it.
        local genDist, genKind = nearestGenerator(position)
        if genDist <= GEN_NEAR then
            record.Resources.GenTime = record.Resources.GenTime + dt
            if record.Resources.GenAt == 0 or now - record.Resources.GenAt > 5 then
                record.Resources.GenVisits = record.Resources.GenVisits + 1
            end
            record.Resources.GenAt = now
            if genKind == 'diamond' or genKind == 'emerald' then
                record.Teamwork.ControlTime = record.Teamwork.ControlTime + dt
            end
        end

        -- Positioning. Home ground is safe; deep in enemy territory with no teammate in reach is
        -- not. Kept as a running fraction so one bad push does not erase an hour of good sense,
        -- and one good stretch does not hide a habit of overextending.
        local plr = record.Player
        local own, ownDist, _, enemyDist = bedsFor(plr, position)
        local nearOwn = own ~= nil and ownDist <= BED_NEAR
        if nearOwn then
            record.Sense.SafeTime = record.Sense.SafeTime + dt
        end
        if enemyDist <= BED_NEAR * 2 then
            record.Sense.ExposedTime = record.Sense.ExposedTime + dt
            noteBedApproach(record, world.Stage == 'Early', 0.5)
        elseif record.Objectives.BedApproachAt ~= 0
            and enemyDist > BED_NEAR * 4
            and now - record.Objectives.BedApproachAt > 20
        then
            -- Broken off and gone. The next time they come back is a fresh approach, and the one
            -- they gave up on stays on the books as a rush that did not work.
            record.Objectives.BedApproachAt = 0
        end

        -- Teammate and enemy proximity, read off the shared roster rather than by walking the
        -- entity list once per player per frame.
        local mateNear, enemyNear = false, false
        for _, entry in world.Roster do
            if entry.Player ~= plr then
                if (entry.Position - position).Magnitude <= MATE_NEAR then
                    if entry.Team ~= nil and entry.Team == context.Team then
                        mateNear = true
                    else
                        enemyNear = true
                    end
                end
            end
        end
        if mateNear and enemyNear then
            record.Teamwork.PushWindow = record.Teamwork.PushWindow + dt
        end
        observe(movement.Positioning, (nearOwn or mateNear or not enemyNear) and 1 or 0, math.min(dt, 0.5))

        -- A teammate in trouble within reach is a chance to help. Whether they took it is answered
        -- by the damage they then put on whoever was doing it, over in onDamage.
        if near and now - record.Sense.SaveChanceAt > 3 then
            for _, entry in world.Roster do
                if entry.Player ~= plr and entry.Team ~= nil and entry.Team == context.Team then
                    local mate = peek(entry.Player)
                    if mate and now - mate.Combat.LastHurt <= 2 and (entry.Position - position).Magnitude <= MATE_NEAR then
                        record.Sense.SaveChanceAt = now
                        record.Teamwork.SaveChances = record.Teamwork.SaveChances + 1
                        break
                    end
                end
            end
        end

        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Terrain probes.
    ----------------------------------------------------------------------------
    -- Two rays: straight down, and down from a stride along the direction of travel. Between them
    -- they answer "are they over the void", "how far above the floor are they" and "are they
    -- walking at an edge", which is every terrain question the movement signals ask. Budgeted per
    -- frame so a full lobby can never turn edge awareness into a raycast storm.
    local probeParams = RaycastParams.new()
    probeParams.RespectCanCollide = true
    probeParams.FilterType = Enum.RaycastFilterType.Exclude
    local probeIgnore = {}

    local function probeGround(origin)
        probeParams.FilterDescendantsInstances = probeIgnore
        local hit = workspace:Raycast(origin, Vector3.new(0, -400, 0), probeParams)
        return hit and hit.Position.Y or nil
    end

    local function probeEntity(ent, record)
        if probeBudget <= 0 then return end
        local root = ent.RootPart
        if not root or not root.Parent then return end
        probeBudget = probeBudget - 1

        table.clear(probeIgnore)
        table.insert(probeIgnore, ent.Character)
        table.insert(probeIgnore, gameCamera)
        if AntiFallPart then
            table.insert(probeIgnore, AntiFallPart)
        end

        local movement = record.Movement
        local position = root.Position
        local ground = probeGround(position)
        movement.Ground = ground
        movement.OverVoid = ground == nil

        -- Edge awareness: is there floor a stride ahead of where they are heading? If not, and
        -- they slow or turn instead of walking off it, that is a read rather than luck.
        local direction = movement.LastDir
        if direction and ground then
            if probeGround(position + direction * 5) then
                if movement.EdgeAt > 0 and tick() - movement.EdgeAt < 1 then
                    movement.EdgeStops = movement.EdgeStops + 1
                    movement.EdgeAt = 0
                end
            else
                movement.EdgeApproaches = movement.EdgeApproaches + 1
                movement.EdgeAt = tick()
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Inventory deltas.
    ----------------------------------------------------------------------------
    -- Purchases, resource spend, tool preparation and gear progression all fall out of watching
    -- what the replicated inventory does between two looks at it.
    local function sampleInventory(record)
        local inv = inventoryOf(record.Player)
        if not inv then return end
        local now = tick()
        local resources = record.Resources
        if now - resources.InventoryAt < 1 then return end
        resources.InventoryAt = now

        local items = 0
        for _ in (inv.items or {}) do
            items = items + 1
        end
        local snapshot = {
            Iron = resourceCount(inv, 'iron'),
            Diamond = resourceCount(inv, 'diamond'),
            Emerald = resourceCount(inv, 'emerald'),
            Gear = swordDamage(inv) + armourValue(inv) * 30,
            Items = items
        }

        local previous = resources.LastInventory
        resources.LastInventory = snapshot
        record.Context.Gear = snapshot.Gear
        record.Context.Armour = armourValue(inv)
        if snapshot.Gear > resources.BestGear then
            resources.BestGear = snapshot.Gear
            observe(resources.GearTier, math.clamp(snapshot.Gear / 90, 0, 1))
        end

        -- Tool preparation: holding the right thing for what is about to happen. Swapping to a
        -- sword before contact, or to blocks over a gap, is reading a moment ahead.
        local hand = inv.hand
        local handType = hand and hand.itemType or nil
        if handType and handType ~= record.Sense.LastHand then
            record.Sense.LastHand = handType
            record.Sense.ToolSwaps = record.Sense.ToolSwaps + 1
            local meta = bedwars.ItemMeta[handType]
            if meta then
                local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
                local right = (fighting and meta.sword ~= nil) or (not fighting and record.Movement.OverVoid and meta.block ~= nil)
                observe(resources.Prepared, right and 1 or 0)
            end
        end

        if not previous then return end
        -- Resources going up is collection; going down is spending, and whether the item count
        -- went with them says whether it was bought for themselves or given away.
        resources.Iron = resources.Iron + math.max(snapshot.Iron - previous.Iron, 0)
        resources.Diamond = resources.Diamond + math.max(snapshot.Diamond - previous.Diamond, 0)
        resources.Emerald = resources.Emerald + math.max(snapshot.Emerald - previous.Emerald, 0)

        local ironSpent = math.max(previous.Iron - snapshot.Iron, 0)
        local diamondSpent = math.max(previous.Diamond - snapshot.Diamond, 0)
        local emeraldSpent = math.max(previous.Emerald - snapshot.Emerald, 0)
        resources.IronSpent = resources.IronSpent + ironSpent
        resources.DiamondSpent = resources.DiamondSpent + diamondSpent
        resources.EmeraldSpent = resources.EmeraldSpent + emeraldSpent

        local spent = ironSpent + diamondSpent + emeraldSpent
        if spent > 0 then
            record.Context.LastAction = now
            if snapshot.Items >= previous.Items then
                resources.Purchases = resources.Purchases + 1
                if snapshot.Gear > previous.Gear then
                    addEvent(record, 'Upgrade', 0.8)
                end
            else
                -- Resources gone and items gone with them: handed to a teammate, or spent at the
                -- upgrade shop. Both are contributions rather than losses, and we cannot tell
                -- which from here - so the event says how sure we are.
                resources.Upgrades = resources.Upgrades + 1
                record.Teamwork.Shared = record.Teamwork.Shared + 1
                addEvent(record, 'TeamSpend', 0.45)
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Context, threats and decisions.
    ----------------------------------------------------------------------------
    local function updateContext(record, ent)
        local plr = record.Player
        local context = record.Context
        local now = tick()
        context.Health = healthFraction(plr)
        context.Alive = ent ~= nil and ent.Health > 0

        -- The allocating reads are throttled; the cheap attribute reads above are not.
        if now - record.LastHeavy >= HEAVY_INTERVAL then
            record.LastHeavy = now
            context.Kit = kitOf(plr)
            context.Team = teamOf(plr)
            context.Trapped = statusTrapped(plr)
        end

        -- AFK is only decidable while we can actually see them: a streamed-out player is not
        -- standing still, we just are not looking. An AFK player is not playing badly, they are
        -- not playing, so this freezes the claim rather than grinding them toward New.
        local afk = context.Alive and (now - math.max(context.LastMove, context.LastAction)) > AFK_TIME
        if afk ~= context.AFK then
            context.AFK = afk
            addEvent(record, afk and 'AFK' or 'Active', 0.7)
        end
    end

    local function updateThreats(record, ent)
        local root = ent.RootPart
        if not root or not root.Parent then return end
        local plr = record.Player
        local position = root.Position
        local sense = record.Sense
        local now = tick()

        -- Threat awareness: an enemy inside striking distance. Whether they answered it - turned,
        -- moved off, or hit back - inside a couple of seconds is the read.
        local threat = nil
        for _, entry in world.Roster do
            if entry.Player ~= plr and not (entry.Team ~= nil and entry.Team == record.Context.Team) then
                if (entry.Position - position).Magnitude <= THREAT_NEAR then
                    threat = entry.Player
                    break
                end
            end
        end

        if threat and not sense.ThreatFrom then
            sense.ThreatFrom, sense.ThreatAt, sense.ThreatAnswered = threat, now, false
            sense.Threats = sense.Threats + 1
        elseif not threat then
            sense.ThreatFrom, sense.ThreatAnswered = nil, false
        end

        if sense.ThreatFrom and not sense.ThreatAnswered and now - sense.ThreatAt <= 2.5 then
            local moving = record.Movement.LastVel ~= nil
                and Vector3.new(record.Movement.LastVel.X, 0, record.Movement.LastVel.Z).Magnitude > 8
            if moving or now - record.Combat.LastHit <= 2.5 then
                sense.ThreatReactions = sense.ThreatReactions + 1
                sense.ThreatAnswered = true
            end
        end

        -- Bed under attack. Whether they turn up at all is the defence reaction; the block-place
        -- handler closes the loop when they get there and start walling it back up.
        local own = select(1, bedsFor(plr, position))
        if own then
            local underThreat = false
            for _, entry in world.Roster do
                if not (entry.Team ~= nil and entry.Team == record.Context.Team) then
                    if (entry.Position - own.Position).Magnitude <= BED_NEAR then
                        underThreat = true
                        break
                    end
                end
            end
            if underThreat and not sense.BedAlert then
                sense.BedAlert, sense.LastAlert = true, now
                sense.BedAlerts = sense.BedAlerts + 1
            elseif not underThreat and sense.BedAlert then
                if sense.LastAlert > 0 and (own.Position - position).Magnitude <= BED_NEAR then
                    sense.BedResponses = sense.BedResponses + 1
                    observe(sense.BedResponseTime, math.clamp(now - sense.LastAlert, 0.5, 30))
                end
                sense.BedAlert = false
            end
        end

        -- Retreating. Breaking off a losing fight and living is one of the clearest game-sense
        -- reads there is; dying on the spot at the same health is the other side of it.
        if now - record.Combat.LastHurt <= FIGHT_MEMORY and record.Context.Health < 0.35 then
            if not sense.RetreatFrom then
                sense.RetreatFrom, sense.RetreatAt = position, now
            end
        elseif sense.RetreatFrom then
            if now - sense.RetreatAt < 8 then
                if not record.Context.Alive then
                    sense.LowHealthDeaths = sense.LowHealthDeaths + 1
                elseif (position - sense.RetreatFrom).Magnitude > 40 then
                    sense.Retreats = sense.Retreats + 1
                    sense.LowHealthEscapes = sense.LowHealthEscapes + 1
                    record.Objectives.Escapes = record.Objectives.Escapes + 1
                    addEvent(record, 'Escape', 0.7)
                end
            end
            sense.RetreatFrom = nil
        end

        -- Chases. Running somebody down across the map, landing nothing, while the objective is
        -- somewhere else, is time nobody got anything out of.
        local victim = record.Combat.LastVictim
        local theirRoot = victim and victim.Character and victim.Character:FindFirstChild('HumanoidRootPart')
        if theirRoot and now - record.Combat.LastHit < 6 and (theirRoot.Position - position).Magnitude > 60 then
            if sense.ChaseAt == 0 then
                sense.ChaseAt = now
                sense.Chases = sense.Chases + 1
            elseif now - sense.ChaseAt > 6 then
                sense.PointlessChases = sense.PointlessChases + 1
                sense.ChaseAt = 0
            end
        else
            sense.ChaseAt = 0
        end
    end

    ----------------------------------------------------------------------------
    -- Category scoring.
    ----------------------------------------------------------------------------
    -- A note on confidence, because it is the whole design. Where absence means something - they
    -- have been on a generator for four minutes and have no diamonds - confidence comes from how
    -- long we watched, so a zero is a confident zero. Where absence means nothing - they have
    -- never fired an arrow, so we cannot say whether they can aim one - confidence comes from the
    -- count, and stays at zero until there is something to judge.
    local function watchConf(record, seconds)
        return math.clamp(record.Observed / (seconds or 90), 0, 1)
    end

    local function scoreCombat(record)
        local b = blender()
        local combat = record.Combat
        local timing = timingConfidence()
        local kitFactor = KIT_COMBAT[record.Context.Kit or ''] or 1
        local fights = combat.Kills + combat.Deaths
        local damage = combat.DamageDealt + combat.DamageTaken
        -- Kills against nobody are worth nothing. This multiplies every trade-shaped signal, and
        -- it is what keeps farming from reading as skill.
        local honesty = math.clamp(combat.KillQuality.v, 0.15, 1)

        signal(b, 'Trades',
            scale(safeDiv(combat.Kills - combat.Deaths, math.max(fights, 1)) * honesty, -0.6, 0.6),
            1.4, countConf(fights, 8))

        signal(b, 'Fight wins',
            scale(safeDiv(combat.FightsWon, combat.FightsWon + combat.FightsLost), 0.25, 0.75),
            1.2, countConf(combat.FightsWon + combat.FightsLost, 6))

        signal(b, 'Hit accuracy',
            scale(safeDiv(combat.SwingHits, combat.Swings), 0.3, 0.8),
            1.1, combat.Swings >= 8 and math.min(countConf(combat.Swings, 25), 0.55) or 0)

        signal(b, 'First hits',
            scale(safeDiv(combat.FirstHits, combat.FirstHitChances), 0.3, 0.75),
            1.0, countConf(combat.FirstHitChances, 6) * timing)

        signal(b, 'Combo consistency',
            scale(safeDiv(combat.ComboHits, math.max(combat.MeleeHits, 1)), 0.1, 0.5),
            1.0, countConf(combat.MeleeHits, 20))

        signal(b, 'Best combo',
            reward(combat.BestCombo - 2, 5),
            0.6, countConf(combat.MeleeHits, 20))

        signal(b, 'Damage traded',
            scale(safeDiv(combat.DamageDealt - combat.DamageTaken, math.max(damage, 1)), -0.4, 0.4),
            1.2, math.clamp(damage / 400, 0, 1))

        signal(b, 'Reaction time',
            -scale(combat.Reaction.v, 0.25, 1.1),
            0.9, evidence(combat.Reaction, 6) * timing)

        signal(b, 'Strafing',
            scale(combat.Strafe.v, 0.15, 0.65),
            0.8, evidence(combat.Strafe, 25) * kitFactor)

        signal(b, 'Aim tracking',
            scale(combat.Tracking.v, 0.45, 0.9),
            1.0, evidence(combat.Tracking, 25) * timing)

        signal(b, 'Target switching',
            bell(safeDiv(combat.Switches, math.max(fights, 1)), 0.8, 1.6),
            0.5, countConf(combat.Switches, 4))

        signal(b, 'Projectile accuracy',
            scale(safeDiv(combat.ProjectileHits, combat.Projectiles), 0.15, 0.6),
            0.9, combat.Projectiles >= 4 and countConf(combat.Projectiles, 12) or 0)

        signal(b, 'Void knockbacks',
            reward(combat.VoidKills, 3),
            0.6, watchConf(record, 120) * 0.7)

        signal(b, 'Against better gear',
            scale(safeDiv(combat.UphillWins, combat.UphillFights), 0.2, 0.7),
            1.3, countConf(combat.UphillFights, 5))

        return resolve(b)
    end

    local function scoreMovement(record)
        local b = blender()
        local movement = record.Movement
        local kitFactor = KIT_MOVEMENT[record.Context.Kit or ''] or 1

        signal(b, 'Bridging speed',
            scale(movement.BridgeSpeed.v, 1.2, 3.2),
            1.2, evidence(movement.BridgeSpeed, 5) * kitFactor)

        signal(b, 'Block efficiency',
            scale(safeDiv(movement.Distance, math.max(movement.Blocks, 1)), 1.5, 5),
            0.9, countConf(movement.Blocks, 25))

        signal(b, 'Hesitation',
            -scale(safeDiv(movement.Pauses, math.max(record.Observed / 60, 0.2)), 1, 8),
            0.7, watchConf(record, 90))

        signal(b, 'Unforced falls',
            -reward(movement.UnforcedFalls, 4),
            1.1, watchConf(record, 90))

        signal(b, 'Parkour',
            reward(movement.Parkour, 12),
            0.6, watchConf(record, 120) * kitFactor)

        signal(b, 'Pathing',
            scale(safeDiv(movement.Distance, math.max(record.Observed, 1)), 4, 13),
            0.7, watchConf(record, 60))

        signal(b, 'Edge awareness',
            scale(safeDiv(movement.EdgeStops, math.max(movement.EdgeApproaches, 1)), 0.2, 0.8),
            1.0, countConf(movement.EdgeApproaches, 8))

        signal(b, 'Combat positioning',
            scale(movement.Positioning.v, 0.35, 0.85),
            0.9, evidence(movement.Positioning, 20))

        signal(b, 'Knockback recovery',
            -scale(movement.Recovery.v, 0.3, 1.6),
            1.0, evidence(movement.Recovery, 5))

        signal(b, 'Block clutches',
            reward(movement.Clutches + movement.Saves, 4),
            1.1, watchConf(record, 120) * 0.8)

        return resolve(b)
    end

    local function scoreSense(record)
        local b = blender()
        local sense = record.Sense
        local exposure = sense.SafeTime + sense.ExposedTime

        signal(b, 'Threat awareness',
            scale(safeDiv(sense.ThreatReactions, math.max(sense.Threats, 1)), 0.3, 0.85),
            1.3, countConf(sense.Threats, 6))

        signal(b, 'Bed defence',
            scale(safeDiv(sense.BedResponses, math.max(sense.BedAlerts, 1)), 0.2, 0.8),
            1.2, countConf(sense.BedAlerts, 3))

        signal(b, 'Defence speed',
            -scale(sense.BedResponseTime.v, 3, 18),
            0.8, evidence(sense.BedResponseTime, 3))

        signal(b, 'Retreating',
            scale(safeDiv(sense.LowHealthEscapes, math.max(sense.LowHealthEscapes + sense.LowHealthDeaths, 1)), 0.2, 0.8),
            1.1, countConf(sense.LowHealthEscapes + sense.LowHealthDeaths, 4))

        signal(b, 'Fight selection',
            scale(safeDiv(record.Combat.FightsWon, math.max(record.Combat.FightsWon + record.Combat.FightsLost, 1)), 0.3, 0.9),
            1.0, countConf(record.Combat.FightsWon + record.Combat.FightsLost, 6))

        signal(b, 'Pointless chases',
            -scale(safeDiv(sense.PointlessChases, math.max(sense.Chases, 1)), 0.1, 0.7),
            0.8, countConf(sense.Chases, 4))

        signal(b, 'Safe positioning',
            scale(safeDiv(sense.SafeTime, math.max(exposure, 1)), 0.15, 0.6),
            0.6, math.clamp(exposure / 60, 0, 1))

        signal(b, 'Adapting tools',
            scale(record.Resources.Prepared.v, 0.3, 0.85),
            0.9, evidence(record.Resources.Prepared, 8))

        -- Adapting after failure: coming back at a bed they were pushed off, or changing the way
        -- in, rather than feeding the same approach until the match ends.
        signal(b, 'Adapting after failure',
            scale(safeDiv(record.Objectives.RushWins, math.max(record.Objectives.Rushes, 1)), 0.15, 0.7),
            1.0, countConf(record.Objectives.Rushes, 3))

        return resolve(b)
    end

    local function scoreObjectives(record)
        local b = blender()
        local objectives = record.Objectives
        local minutes = math.max(record.Observed / 60, 0.5)

        signal(b, 'Beds broken',
            reward(objectives.Beds, 2),
            1.5, watchConf(record, 150))

        signal(b, 'Bed approaches',
            scale(safeDiv(objectives.BedApproaches, minutes), 0.1, 1.2),
            0.9, watchConf(record, 120))

        signal(b, 'Rush success',
            scale(safeDiv(objectives.RushWins, math.max(objectives.Rushes, 1)), 0.1, 0.7),
            1.2, countConf(objectives.Rushes, 3))

        signal(b, 'Bed break speed',
            -scale(objectives.BedBreakTime.v, 8, 60),
            0.9, evidence(objectives.BedBreakTime, 2))

        signal(b, 'Defence broken',
            reward(objectives.DefenceBroken, 25),
            0.7, watchConf(record, 120))

        signal(b, 'Final kills',
            reward(objectives.FinalKills, 3),
            1.2, watchConf(record, 150))

        signal(b, 'Assists',
            reward(objectives.Assists, 5),
            0.7, watchConf(record, 120) * (world.TeamSize > 1 and 1 or 0))

        signal(b, 'Escapes',
            reward(objectives.Escapes, 3),
            0.6, watchConf(record, 120))

        signal(b, 'Pressure created',
            reward(objectives.Pressure, 4),
            0.8, watchConf(record, 120))

        return resolve(b)
    end

    local function scoreResources(record)
        local b = blender()
        local resources = record.Resources
        local minutes = math.max(record.Observed / 60, 0.3)
        -- Every resource read comes from the replicated inventory. Without it there is nothing
        -- here to say, and saying so is the point.
        local replicated = inventoryOf(record.Player) and 1 or 0

        signal(b, 'Generator time',
            bell(safeDiv(resources.GenTime, math.max(record.Observed, 1)), 0.25, 0.25),
            0.9, watchConf(record, 90))

        signal(b, 'Iron income',
            scale(safeDiv(resources.Iron, minutes), 4, 30),
            0.8, watchConf(record, 120) * replicated)

        signal(b, 'Diamond income',
            scale(safeDiv(resources.Diamond, minutes), 0.2, 2.5),
            1.0, watchConf(record, 150) * replicated)

        signal(b, 'Emerald income',
            scale(safeDiv(resources.Emerald, minutes), 0.05, 1.2),
            0.9, watchConf(record, 180) * replicated)

        signal(b, 'Spending',
            scale(safeDiv(resources.IronSpent + resources.DiamondSpent * 4 + resources.EmeraldSpent * 8,
                math.max(resources.Iron + resources.Diamond * 4 + resources.Emerald * 8, 1)), 0.25, 0.85),
            1.0, watchConf(record, 120) * replicated)

        signal(b, 'Resources lost on death',
            -scale(safeDiv(resources.Lost, math.max(resources.LostEvents, 1)), 5, 45),
            1.0, countConf(resources.LostEvents, 2))

        signal(b, 'Purchases',
            scale(safeDiv(resources.Purchases, minutes), 0.3, 3),
            0.7, watchConf(record, 120) * replicated)

        signal(b, 'Tool preparation',
            scale(resources.Prepared.v, 0.3, 0.85),
            0.8, evidence(resources.Prepared, 8))

        signal(b, 'Gear progression',
            scale(resources.GearTier.v, 0.15, 0.8),
            1.1, evidence(resources.GearTier, 3) * replicated)

        signal(b, 'Team upgrades',
            reward(resources.Upgrades, 3),
            0.7, watchConf(record, 150) * replicated * 0.5)

        return resolve(b)
    end

    local function scoreTeamwork(record)
        local b = blender()
        local team = record.Teamwork
        -- In a solo mode there is nobody to help. Rather than mark a solo player down for it, the
        -- whole category simply has no confidence and drops out of their overall score.
        local solo = world.TeamSize > 1 and 1 or 0
        local watched = watchConf(record, 120) * solo

        signal(b, 'Assists', reward(team.Assists, 4), 1.2, watched)

        signal(b, 'Protecting teammates',
            scale(safeDiv(team.Saves, math.max(team.SaveChances, 1)), 0.1, 0.6),
            1.1, countConf(team.SaveChances, 3) * solo)

        signal(b, 'Sharing resources', reward(team.Shared, 3), 0.8, watched * 0.6)

        signal(b, 'Defending', reward(team.Defends, 10), 1.0, watched)

        signal(b, 'Coordinated pushes',
            scale(safeDiv(team.PushWindow, math.max(record.Observed, 1)), 0.05, 0.4),
            1.0, watched)

        signal(b, 'Diamond and emerald control',
            scale(safeDiv(team.ControlTime, math.max(record.Observed, 1)), 0.03, 0.3),
            0.9, watchConf(record, 120))

        return resolve(b)
    end

    ----------------------------------------------------------------------------
    -- Roles.
    ----------------------------------------------------------------------------
    -- Each role is scored on its own evidence, and the winner has to be clearly ahead of the
    -- runner-up to be claimed. Anything else is Mixed, which is a real answer rather than a
    -- fallback: most players genuinely do a bit of everything.
    local function roleOf(record)
        local combat, sense = record.Combat, record.Sense
        local objectives, resources, team = record.Objectives, record.Resources, record.Teamwork
        local watched = math.max(record.Observed, 1)
        local minutes = math.max(watched / 60, 0.3)

        local scores = {
            Rusher = math.clamp(
                safeDiv(objectives.BedApproaches, minutes) * 0.5
                + objectives.Beds * 0.5
                + reward(objectives.DefenceBroken, 20) * 0.3
                + safeDiv(sense.ExposedTime, watched) * 0.6, 0, 2),
            Defender = math.clamp(
                safeDiv(sense.SafeTime, watched) * 1.1
                + reward(team.Defends, 10) * 0.6
                + safeDiv(sense.BedResponses, math.max(sense.BedAlerts, 1)) * 0.5, 0, 2),
            Fighter = math.clamp(
                safeDiv(combat.Kills + combat.FightsWon, minutes) * 0.35
                + reward(combat.DamageDealt, 400) * 0.4
                + reward(combat.MeleeHits, 40) * 0.3, 0, 2),
            Support = math.clamp(
                reward(team.Assists, 3) * 0.7
                + safeDiv(team.PushWindow, watched) * 0.9
                + reward(team.Shared, 4) * 0.25, 0, 2),
            Economy = math.clamp(
                safeDiv(resources.GenTime, watched) * 1.2
                + reward(resources.Purchases, 5) * 0.5
                + reward(resources.Iron, 60) * 0.4, 0, 2),
            ResourceControl = math.clamp(
                safeDiv(team.ControlTime, watched) * 1.6
                + reward(resources.Diamond + resources.Emerald * 2, 8) * 0.6, 0, 2)
        }

        local best, bestScore, second = 'Mixed', 0, 0
        for _, role in ROLES do
            local value = scores[role] or 0
            if value > bestScore then
                best, second, bestScore = role, bestScore, value
            elseif value > second then
                second = value
            end
        end

        if bestScore < 0.35 or bestScore < second * 1.35 then
            return 'Mixed', scores
        end
        return best, scores
    end

    ----------------------------------------------------------------------------
    -- Rating bands.
    ----------------------------------------------------------------------------
    -- Sliders can be dragged into any order. Read them back as a strictly descending set so a band
    -- can never swallow the one above it and every rating stays reachable.
    local function bands()
        local sweat = SweatAt.Value
        local skilled = math.min(SkilledAt.Value, sweat - 1)
        local above = math.min(AboveAt.Value, skilled - 1)
        local beginner = math.min(BeginnerBelow.Value, above - 1)
        return sweat, skilled, above, beginner, math.min(NewBelow.Value, beginner - 1)
    end

    local function ratingOf(score, confidence)
        if confidence < (MinConfidence.Value / 100) then return 'Unknown' end
        local sweat, skilled, above, beginner, fresh = bands()
        if score >= sweat then return 'Sweat' end
        if score >= skilled then return 'Skilled' end
        if score >= above then return 'Above Average' end
        if score > beginner then return 'Average' end
        if score > fresh then return 'Beginner' end
        return 'New'
    end

    ----------------------------------------------------------------------------
    -- Building the answer.
    ----------------------------------------------------------------------------
    local function blankAnalysis()
        return {
            OverallSkill = 0,
            Confidence = 0,
            Rating = 'Unknown',
            Role = 'Mixed',
            Categories = {
                Combat = 0,
                Movement = 0,
                GameSense = 0,
                Objectives = 0,
                Resources = 0,
                Teamwork = 0
            },
            Strengths = {},
            Weaknesses = {},
            RecentEvents = {}
        }
    end

    -- Strengths and weaknesses come from the named signals rather than the category totals, so the
    -- answer is "their bridging is quick" and not "movement: 71".
    local function highlights(blends)
        local pool = {}
        for _, entry in blends do
            for name, data in entry.named do
                if data.Confidence >= 0.35 and math.abs(data.Deviation) >= 0.3 then
                    table.insert(pool, {Name = name, Score = data.Deviation * data.Confidence * data.Weight})
                end
            end
        end
        table.sort(pool, function(a, b)
            return a.Score > b.Score
        end)

        local strengths, weaknesses = {}, {}
        for _, entry in pool do
            if entry.Score > 0.25 and #strengths < 4 then
                table.insert(strengths, entry.Name)
            end
        end
        for index = #pool, 1, -1 do
            if pool[index].Score < -0.25 and #weaknesses < 4 then
                table.insert(weaknesses, pool[index].Name)
            end
        end
        return strengths, weaknesses
    end

    local function round(value, places)
        local factor = 10 ^ (places or 1)
        return math.floor(value * factor + 0.5) / factor
    end

    local function rebuild(record)
        local now = tick()
        record.Dirty = false
        record.NextScore = now + RESCORE_INTERVAL

        local scores, confs, blends = {}, {}, {}
        scores.Combat, confs.Combat, blends[1] = scoreCombat(record)
        scores.Movement, confs.Movement, blends[2] = scoreMovement(record)
        scores.GameSense, confs.GameSense, blends[3] = scoreSense(record)
        scores.Objectives, confs.Objectives, blends[4] = scoreObjectives(record)
        scores.Resources, confs.Resources, blends[5] = scoreResources(record)
        scores.Teamwork, confs.Teamwork, blends[6] = scoreTeamwork(record)

        local role, roleScores = roleOf(record)
        local weights = ROLE_WEIGHTS[role] or ROLE_WEIGHTS.Mixed

        -- Overall is a confidence-weighted blend: a category we have barely observed cannot drag
        -- the answer around, and one we have watched thoroughly is what the answer is made of.
        local sum, weight, confSum, confWeight = 0, 0, 0, 0
        for _, name in CATEGORIES do
            local categoryWeight = weights[name]
            local w = categoryWeight * confs[name]
            sum = sum + scores[name] * w
            weight = weight + w
            confSum = confSum + confs[name] * categoryWeight
            confWeight = confWeight + categoryWeight
        end

        local quality = dataQuality(record)
        local confidence = math.clamp(safeDiv(confSum, confWeight) * quality, 0, 1)
        if record.Context.AFK then
            confidence = confidence * 0.6
        end
        -- Hold the overall toward Average by however much we do not know, so a thin read never
        -- comes out as a confident claim.
        local overall = math.clamp(50 + ((weight > 0 and (sum / weight) or 50) - 50) * (0.35 + 0.65 * confidence), 0, 100)
        local rating = ratingOf(overall, confidence)
        local strengths, weaknesses = highlights(blends)

        local events = {}
        for index = #record.Events, 1, -1 do
            local entry = record.Events[index]
            table.insert(events, {
                Type = entry.Type,
                Time = entry.Time,
                Age = now - entry.Time,
                Confidence = entry.Confidence,
                Detail = entry.Detail
            })
        end

        local analysis = {
            OverallSkill = round(overall, 1),
            Confidence = round(confidence, 3),
            Rating = rating,
            Role = role,
            Categories = {
                Combat = round(scores.Combat, 1),
                Movement = round(scores.Movement, 1),
                GameSense = round(scores.GameSense, 1),
                Objectives = round(scores.Objectives, 1),
                Resources = round(scores.Resources, 1),
                Teamwork = round(scores.Teamwork, 1)
            },
            Strengths = strengths,
            Weaknesses = weaknesses,
            RecentEvents = events,
            -- Past the shape the contract asks for, for anything that wants to go deeper.
            Player = record.Player,
            CategoryConfidence = confs,
            RoleScores = roleScores,
            Observed = round(record.Observed, 1),
            AFK = record.Context.AFK,
            DataQuality = round(quality, 3)
        }

        local previous = record.Cache
        record.Cache = analysis
        if not previous or previous.Rating ~= analysis.Rating or previous.Role ~= analysis.Role then
            vapeEvents.EntityAnalysed:Fire(record.Player, analysis)
            local wasHigh = previous ~= nil and (previous.Rating == 'Skilled' or previous.Rating == 'Sweat')
            local isHigh = analysis.Rating == 'Skilled' or analysis.Rating == 'Sweat'
            if Notify.Enabled and isHigh and not wasHigh then
                notif('EntityAnalyser', record.Player.Name .. ' is ' .. analysis.Rating .. ' (' .. math.floor(analysis.OverallSkill) .. ', ' .. analysis.Role .. ')', 4)
            end
        end
        return analysis
    end

    local function analysisFor(plr)
        local record = peek(plr)
        if not record then return blankAnalysis() end
        if not record.Cache then return rebuild(record) end
        -- Sampling marks a profile dirty constantly, so the throttle is what actually decides how
        -- often the maths runs. Twice a second is far faster than a rating can meaningfully move.
        if record.Dirty and tick() >= record.NextScore then return rebuild(record) end
        return record.Cache
    end

    ----------------------------------------------------------------------------
    -- Labels.
    ----------------------------------------------------------------------------
    local function removeTag(plr)
        local tag = tags[plr]
        if tag then
            tag:Destroy()
        end
        tags[plr] = nil
    end

    local function ratingShown(rating)
        if rating == 'Sweat' then return ShowSweat.Enabled end
        if rating == 'Skilled' then return ShowSkilled.Enabled end
        if rating == 'Above Average' then return ShowAbove.Enabled end
        if rating == 'Average' then return ShowAverage.Enabled end
        if rating == 'Beginner' then return ShowBeginner.Enabled end
        if rating == 'New' then return ShowNew.Enabled end
        return ShowUnknown.Enabled
    end

    local function updateTag(plr, ent, analysis)
        local adornee = ent.Head or ent.RootPart
        if not folder or not adornee or not adornee.Parent or not ratingShown(analysis.Rating) then
            removeTag(plr)
            return
        end

        local tag = tags[plr]
        if not tag or tag.Adornee ~= adornee or not tag.Parent then
            removeTag(plr)
            tag = Instance.new('BillboardGui')
            tag.Name = 'EntityAnalyser'
            tag.AlwaysOnTop = true
            tag.ClipsDescendants = false
            tag.Size = UDim2.fromOffset(260, 18)
            -- Above the +3 the other overhead tags use, so a nametag and a rating can be on
            -- together without covering each other.
            tag.StudsOffsetWorldSpace = Vector3.new(0, 4.4, 0)
            tag.Adornee = adornee
            tag.Parent = folder

            local label = Instance.new('TextLabel')
            label.Name = 'Label'
            label.Size = UDim2.fromScale(1, 1)
            label.BackgroundTransparency = 1
            label.Font = Enum.Font.GothamBold
            label.TextSize = 13
            label.TextStrokeTransparency = 0.4
            label.Parent = tag
            tags[plr] = tag
        end

        local label = tag:FindFirstChild('Label')
        if label then
            label.TextColor3 = ratingColor[analysis.Rating] or ratingColor.Unknown
            local text = '\u{25CF} ' .. analysis.Rating
            if ShowScore.Enabled and analysis.Rating ~= 'Unknown' then
                text = text .. ' ' .. math.floor(analysis.OverallSkill)
            end
            if ShowRole.Enabled and analysis.Role ~= 'Mixed' then
                text = text .. ' \u{00B7} ' .. analysis.Role
            end
            if ShowConfidence.Enabled then
                text = text .. ' \u{00B7} ' .. math.floor(analysis.Confidence * 100) .. '%'
            end
            if analysis.AFK then
                text = text .. ' \u{00B7} AFK'
            end
            label.Text = text
        end
    end

    local function clearTags()
        for plr in tags do
            removeTag(plr)
        end
        table.clear(tags)
    end

    ----------------------------------------------------------------------------
    -- The pass.
    ----------------------------------------------------------------------------
    local function step()
        -- Each player carries their own sample clock, so the pass itself needs no frame delta -
        -- a player read twice a second must be credited with half a second, not with one frame.
        local now = tick()
        probeBudget = PROBE_BUDGET

        if store.matchState ~= lastMatchState then
            if store.matchState == 1 then
                matchStart = now
                bedsAtStart = #collectionService:GetTagged('bed')
            end
            lastMatchState = store.matchState
        end
        refreshWorld(now)

        for key, fight in engagements do
            if now - fight.Last > ENGAGE_MEMORY then
                engagements[key] = nil
            end
        end

        local origin = entitylib.isAlive and entitylib.character.RootPart and entitylib.character.RootPart.Position or nil
        local nearRange = SampleRange.Value
        local labelsOn = Labels.Enabled

        table.clear(seen)
        for _, ent in entitylib.List do
            local plr = ent.Player
            if plr and plr ~= lplr then
                seen[plr] = true
                local record = profileFor(plr)
                local root = ent.RootPart
                local distance = (origin and root and root.Parent) and (root.Position - origin).Magnitude or math.huge
                local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
                local near = distance <= nearRange or fighting

                -- Adaptive: ten times a second for anyone near or fighting, twice a second for everyone
                -- else, and once every couple of seconds for somebody who is not doing anything -
                -- which is still often enough to notice the moment they start again.
                local interval = near and NEAR_INTERVAL or (record.Context.AFK and AFK_INTERVAL or FAR_INTERVAL)
                if now - record.LastSample >= interval then
                    local sampleDt = math.min(now - record.LastSample, 1)
                    record.LastSample = now
                    sampleEntity(ent, record, sampleDt, near)
                    updateContext(record, ent)
                    sampleInventory(record)
                    if near then
                        updateThreats(record, ent)
                        if now - record.LastProbe >= PROBE_INTERVAL then
                            record.LastProbe = now
                            probeEntity(ent, record)
                        end
                    end
                end

                -- Scored whether or not anything is being drawn: the labels are one consumer of
                -- this, the API and the notifications are others, and the rescore is throttled to
                -- twice a second regardless of how many of them are listening.
                local analysis = analysisFor(plr)
                if labelsOn and (Teammates.Enabled or not sameTeam(plr, lplr)) then
                    updateTag(plr, ent, analysis)
                else
                    removeTag(plr)
                end
            end
        end

        -- Anyone who has left the entity list - died, left, streamed out - loses their label but
        -- keeps their profile, so a rating survives a respawn instead of starting over.
        for plr in tags do
            if not seen[plr] then
                removeTag(plr)
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Public API.
    ----------------------------------------------------------------------------
    local api
    api = {
        Enabled = false,
        -- Always the full shape, even for a player we have never seen: an unknown player is a
        -- zeroed table rated 'Unknown', never nil. The table is rebuilt on each rescore, so treat
        -- what comes back as read-only and re-ask rather than holding onto it.
        Analyse = function(plr)
            if not running or typeof(plr) ~= 'Instance' or not plr:IsA('Player') then
                return blankAnalysis()
            end
            local ok, result = pcall(analysisFor, plr)
            return ok and result or blankAnalysis()
        end,
        GetAll = function()
            local all = {}
            if not running then return all end
            for plr in profiles do
                if plr.Parent then
                    all[plr] = api.Analyse(plr)
                end
            end
            return all
        end,
        Reset = function(plr)
            if plr then
                profiles[plr] = nil
                return
            end
            table.clear(profiles)
            table.clear(engagements)
            table.clear(pendingVoid)
        end,
        Ratings = {'New', 'Beginner', 'Average', 'Above Average', 'Skilled', 'Sweat'},
        Roles = ROLES
    }
    getgenv().EntityAnalyser = api

    EntityAnalyser = vape.Categories.Utility:CreateModule({
        Name = 'EntityAnalyser',
        Function = function(callback)
            running = callback
            api.Enabled = callback
            -- Anything whose UI depends on the analyser being up listens for this rather than
            -- reaching into this module - see Killaura's 'Target skilled'.
            vapeEvents.EntityAnalyserState:Fire(callback)

            if callback then
                matchStart, lastMatchState = tick(), -1
                bedsAtStart = #collectionService:GetTagged('bed')
                folder = Instance.new('Folder')
                folder.Name = 'EntityAnalyser'
                folder.Parent = vape.gui
                EntityAnalyser:Clean(folder)

                EntityAnalyser:Clean(vapeEvents.EntityDamageEvent.Event:Connect(onDamage))
                EntityAnalyser:Clean(vapeEvents.EntityDeathEvent.Event:Connect(onDeath))
                EntityAnalyser:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(onBedBreak))
                EntityAnalyser:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(onPlaceBlock))
                EntityAnalyser:Clean(vapeEvents.BreakBlockEvent.Event:Connect(onBreakBlock))
                EntityAnalyser:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
                    table.clear(engagements)
                    table.clear(pendingVoid)
                end))
                EntityAnalyser:Clean(entitylib.Events.AnimationPlayed:Connect(function(plr, track)
                    if not running or not plr or plr == lplr then return end
                    local animation = track and track.Animation
                    if animation then
                        noteSwing(plr, animation.AnimationId)
                    end
                end))
                EntityAnalyser:Clean(workspace.ChildAdded:Connect(function(object)
                    -- The shooter attribute is written a frame after the projectile is parented.
                    task.delay(0, function()
                        if object and object.Parent then
                            pcall(onProjectile, object)
                        end
                    end)
                end))
                -- A player leaving takes their profile with them, so a rejoin is judged fresh
                -- rather than inheriting somebody else's match.
                EntityAnalyser:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    profiles[plr] = nil
                    pendingVoid[plr] = nil
                    removeTag(plr)
                end))
                -- Everything above is event driven. This is the only loop, and all it does is the
                -- adaptive sampling and the label refresh - the two things that need a clock.
                local nextStep = 0
                EntityAnalyser:Clean(runService.Heartbeat:Connect(function()
                    if not running then return end
                    local now = tick()
                    if now < nextStep then return end
                    nextStep = now + NEAR_INTERVAL
                    pcall(step)
                end))
            else
                clearTags()
                table.clear(profiles)
                table.clear(engagements)
                table.clear(pendingVoid)
                folder = nil
            end
        end,
        Tooltip = 'Rates how well each player is playing and marks them overhead. Read-only, it never changes other modules'
    })

    SweatAt = EntityAnalyser:CreateSlider({
        Name = 'Sweat at',
        Min = 60,
        Max = 99,
        Default = 84,
        Tooltip = 'Score needed for the top rating. Getting here takes a spread of categories, sustained - no single thing carries anyone to it'
    })
    SkilledAt = EntityAnalyser:CreateSlider({
        Name = 'Skilled at',
        Min = 50,
        Max = 95,
        Default = 70,
        Tooltip = 'Score needed to count as skilled'
    })
    AboveAt = EntityAnalyser:CreateSlider({
        Name = 'Above average at',
        Min = 45,
        Max = 85,
        Default = 58,
        Tooltip = 'Score needed to be marked above average'
    })
    BeginnerBelow = EntityAnalyser:CreateSlider({
        Name = 'Beginner below',
        Min = 15,
        Max = 50,
        Default = 38,
        Tooltip = 'Score a player has to drop under to be marked a beginner'
    })
    NewBelow = EntityAnalyser:CreateSlider({
        Name = 'New below',
        Min = 2,
        Max = 40,
        Default = 22,
        Tooltip = 'Score a player has to drop under to be marked new. Bands are read top down'
    })
    MinConfidence = EntityAnalyser:CreateSlider({
        Name = 'Minimum confidence',
        Min = 0,
        Max = 90,
        Default = 15,
        Suffix = '%',
        Tooltip = 'How much of the rating must be evidenced before it commits. Below this everyone reads Unknown'
    })
    SampleRange = EntityAnalyser:CreateSlider({
        Name = 'Sample range',
        Min = 40,
        Max = 250,
        Default = 90,
        Suffix = ' studs',
        Tooltip = 'Inside this range players are read every frame, outside it twice a second'
    })
    Labels = EntityAnalyser:CreateToggle({
        Name = 'Labels',
        Default = true,
        Function = function(callback)
            for _, option in {ShowScore, ShowRole, ShowConfidence, ShowSweat, ShowSkilled, ShowAbove, ShowAverage, ShowBeginner, ShowNew, ShowUnknown} do
                if option and option.Object then
                    option.Object.Visible = callback
                end
            end
            if not callback then
                clearTags()
            end
        end,
        Tooltip = 'Show the rating above each player. Its own billboards, so it never clashes with ESP'
    })
    ShowScore = EntityAnalyser:CreateToggle({
        Name = 'Show score',
        Default = true,
        Darker = true,
        Tooltip = 'Put the 0-100 number next to the rating'
    })
    ShowRole = EntityAnalyser:CreateToggle({
        Name = 'Show role',
        Default = true,
        Darker = true,
        Tooltip = 'Also show the role they are playing - Rusher, Defender, Fighter, Support or Economy'
    })
    ShowConfidence = EntityAnalyser:CreateToggle({
        Name = 'Show confidence',
        Darker = true,
        Tooltip = 'Show how much of the rating is evidenced rather than assumed'
    })
    ShowSweat = EntityAnalyser:CreateToggle({Name = 'Label sweat', Default = true, Darker = true})
    ShowSkilled = EntityAnalyser:CreateToggle({Name = 'Label skilled', Default = true, Darker = true})
