-- BEGIN AETHER MODULE: utility/Legless.lua --
run(function()
	local Legless
	local Side
	local RemoveAccessories
	local originals = {}
	local legAttachments = {
		LeftAnkleAttachment = 'Left', LeftFootAttachment = 'Left', LeftKneeAttachment = 'Left',
		RightAnkleAttachment = 'Right', RightFootAttachment = 'Right', RightKneeAttachment = 'Right'
	}

	local function selected(name)
		return Side.Value == 'Both' or name:sub(1, #Side.Value) == Side.Value
	end

	local function hide(obj)
		if originals[obj] == nil then originals[obj] = obj.Transparency end
		obj.Transparency = 1
	end

	local function applyLegless(char)
		if not char then return end
		for _, obj in char:GetDescendants() do
			if obj:IsA('BasePart') and (selected(obj.Name) and obj.Name:find('Leg') or selected(obj.Name) and obj.Name:find('Foot')) then
				hide(obj)
			end
		end
		if RemoveAccessories.Enabled then
			for _, acc in char:GetChildren() do
				if acc:IsA('Accessory') then
					local handle = acc:FindFirstChild('Handle')
					if handle then
						for _, attachment in handle:GetChildren() do
							if attachment:IsA('Attachment') and legAttachments[attachment.Name] and selected(legAttachments[attachment.Name]) then
								hide(handle)
								for _, texture in handle:GetChildren() do
									if texture:IsA('Decal') or texture:IsA('Texture') then hide(texture) end
								end
								break
							end
						end
					end
				end
			end
		end
	end

	local function restoreLegs()
		for obj, value in originals do
			if obj.Parent then obj.Transparency = value end
		end
		table.clear(originals)
	end
	local function watchCharacter(char)
		applyLegless(char)
		if char then
			Legless:Clean(char.DescendantAdded:Connect(function()
				task.defer(applyLegless, char)
			end))
		end
	end

	Legless = vape.Categories.Utility:CreateModule({
		PerformanceModeBlacklisted = true,
		Name = 'Legless',
		Tooltip = 'Hides either or both legs',
		Function = function(callback)
			if callback then
				watchCharacter(lplr.Character)
				Legless:Clean(lplr.CharacterAdded:Connect(watchCharacter))
			else
				restoreLegs()
			end
		end
	})
	Side = Legless:CreateDropdown({
		Name = 'Legs',
		List = {'Both', 'Left', 'Right'},
		Function = function()
			if Legless.Enabled then restoreLegs(); applyLegless(lplr.Character) end
		end
	})
	RemoveAccessories = Legless:CreateToggle({
		Name = 'Remove Accessories',
		Function = function()
			if Legless.Enabled then restoreLegs(); applyLegless(lplr.Character) end
		end
	})
end)
-- END AETHER MODULE: utility/Legless.lua --

-- BEGIN AETHER MODULE: utility/MemoryFixer.lua --
run(function()
	local MemoryFixer
	local Sync
	local Interval
	local Notify
	local signals = {'Heartbeat', 'PostSimulation', 'PreAnimation', 'PreRender', 'PreSimulation', 'RenderStepped', 'Stepped'}
	
	local function clean()
		if not getconnections or not getfunctionhash or not isexecutorclosure then
			return 0
		end
	
		local removed, seen = 0, {}
		for _, v in signals do
			for _, connection in getconnections(runService[v]) do
				if connection.Function and not connection.ForeignState and isexecutorclosure(connection.Function) then
					local hash = v..getfunctionhash(connection.Function)
					if seen[hash] then
						connection:Disconnect()
						removed += 1
					else
						seen[hash] = true
					end
				end
			end
		end
	
		if Sync.Enabled then
			for _, event in bedwars.SyncEvents or {} do
				if typeof(event) == 'table' and typeof(event.entries) == 'table' then
					table.clear(seen)
					for i, entry in event.entries do
						local callback = entry.callbackInfo and entry.callbackInfo.callback
						if callback and isexecutorclosure(callback) then
							local hash = getfunctionhash(callback)
							if seen[hash] then
								event.entries[i] = nil
								event.isSorted = false
								removed += 1
							else
								seen[hash] = true
							end
						end
					end
				end
			end
		end
	
		return removed
	end
	
	MemoryFixer = vape.Categories.Utility:CreateModule({
		Name = 'MemoryFixer',
		Function = function(callback)
			if callback then
				task.spawn(function()
					repeat
						local removed = clean()
						if Notify.Enabled and removed > 0 then
							notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
						end
						task.wait(Interval.Value)
					until not MemoryFixer.Enabled
				end)
			end
		end,
		Tooltip = 'Drops the duplicate loops and listeners an older injection left connected'
	})
	Sync = MemoryFixer:CreateToggle({
		Name = 'Sync events',
		Default = true,
		Tooltip = 'Also prunes duplicate bedwars sync event listeners, the ones that survive a reinject'
	})
	Interval = MemoryFixer:CreateSlider({
		Name = 'Interval',
		Min = 5,
		Max = 300,
		Default = 30,
		Suffix = 'seconds'
	})
	Notify = MemoryFixer:CreateToggle({
		Name = 'Notify',
		Default = true,
		Tooltip = 'Tells you how many it dropped'
	})
	MemoryFixer:CreateButton({
		Name = 'Clean now',
		Function = function()
			local removed = clean()
			notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
		end
	})
end)
-- END AETHER MODULE: utility/MemoryFixer.lua --

-- BEGIN AETHER MODULE: utility/MP3Player.lua --
run(function()
    local MP3Player
    local Volume
    local Speed
    local Shuffle
    local Loop
    local AutoRefresh
    local PlayField
    local Playlist
    local ShowHUD
    local HUDProgress
    local HUDTime
    local HUDColor

    local SONGS = 'aetherv2/songs'
    local SPOTIFY = 'aetherv2/spotify'

    local sound
    local tracks, index = {}, 0
    local hudName, hudTime, hudBarFill, hudBackground
    local lastScan = 0
    local scanKey = ''
    -- When the current track was started, so the watchdog below can tell a song that has
    -- finished from one that has only just been asked to start.
    local lastPlay = 0

    -- Every filesystem call is optional: some executors ship none of them, and the module has to
    -- degrade to "no songs found" rather than erroring on load.
    local function fsList(path)
        local ok, res = pcall(function()
            if isfolder and not isfolder(path) then
                if makefolder then makefolder(path) end
                return {}
            end
            return listfiles and listfiles(path) or {}
        end)
        return ok and res or {}
    end

    local function isAudio(path)
        path = tostring(path):lower()
        return path:sub(-4) == '.mp3' or path:sub(-4) == '.wav' or path:sub(-4) == '.ogg'
    end

    local function fileName(path)
        local normalised = tostring(path):gsub('\\', '/')
        local name = normalised:match('([^/]+)$') or normalised
        return (name:gsub('%.[^%.]+$', ''))
    end

    local function scan(announce)
        local found = {}
        for _, file in fsList(SONGS) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        for _, file in fsList(SPOTIFY) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        table.sort(found, function(a, b)
            return a.Name:lower() < b.Name:lower()
        end)

        -- Playlist, when you have filled one in, is both the filter and the order.
        local wanted = Playlist and Playlist.ListEnabled or {}
        if #wanted > 0 then
            local ordered = {}
            for _, entry in wanted do
                local needle = entry:lower()
                for _, track in found do
                    if track.Name:lower():find(needle, 1, true) then
                        table.insert(ordered, track)
                        break
                    end
                end
            end
            if #ordered > 0 then
                found = ordered
            end
        end

        local key = ''
        for _, track in found do
            key = key .. track.Path .. ';'
        end
        local changed = key ~= scanKey
        scanKey = key
        tracks = found
        if changed and announce and MP3Player.Enabled then
            notif('MP3Player', #tracks > 0 and (#tracks .. ' song' .. (#tracks == 1 and '' or 's') .. ' loaded') or 'No songs in the songs folder yet', 3)
        end
        return changed
    end

    local function assetFor(path)
        local ok, asset = pcall(function()
            return getcustomasset(path)
        end)
        return ok and asset or nil
    end

    local function refreshHUD()
        if not hudName then return end
        local track = tracks[index]
        local colour = HUDColor and Color3.fromHSV(HUDColor.Hue, HUDColor.Sat, HUDColor.Value) or Color3.new(1, 1, 1)
        hudName.TextColor3 = colour
        hudName.Text = track and track.Name or 'No song loaded'
        if hudBackground then
            hudBackground.BackgroundTransparency = HUDColor and (1 - (HUDColor.Opacity * 0.65)) or 0.35
        end

        local length = sound and sound.TimeLength or 0
        local at = sound and sound.TimePosition or 0
        if hudTime then
            hudTime.Visible = HUDTime == nil or HUDTime.Enabled
            hudTime.TextColor3 = colour
            local function clock(t)
                t = math.max(math.floor(t), 0)
                return string.format('%d:%02d', t // 60, t % 60)
            end
            hudTime.Text = track and (clock(at) .. ' / ' .. clock(length)) or ''
        end
        if hudBarFill then
            hudBarFill.Parent.Visible = HUDProgress == nil or HUDProgress.Enabled
            hudBarFill.BackgroundColor3 = colour
            hudBarFill.Size = UDim2.fromScale(length > 0 and math.clamp(at / length, 0, 1) or 0, 1)
        end
    end

    local function stop()
        if sound then
            pcall(function()
                sound:Stop()
            end)
        end
    end

    -- Looping is the engine's job, not ours.
    --
    -- Repeating a song used to mean replaying it from the Ended handler, which is two
    -- problems at once: it leaves an audible gap at every repeat, and Ended is not
    -- something to depend on - a sound whose asset was still loading when Play ran can
    -- fire it immediately or never, and then the music just stops. Looped restarts the
    -- track inside the engine with no gap and no event involved.
    --
    -- Called on every play AND from the two toggles, so turning Loop on part way through a
    -- song loops that song rather than quietly waiting for the next one - which is what
    -- made the toggle look like it did nothing at all.
    local function applyLoop()
        if not (sound and Loop and Shuffle) then return end
        sound.Looped = Loop.Enabled and not Shuffle.Enabled
    end

    local function play(newIndex)
        if #tracks <= 0 then
            index = 0
            refreshHUD()
            return
        end
        -- Stamped before the asset is resolved, not after: a track the executor cannot load
        -- returns below, and leaving the stamp stale would have the watchdog walk the
        -- playlist several times a second complaining about each one.
        lastPlay = tick()
        index = ((newIndex - 1) % #tracks) + 1
        local track = tracks[index]
        local asset = track and assetFor(track.Path)
        if not asset then
            notif('MP3Player', 'Could not load ' .. (track and track.Name or 'that song'), 4, 'warning')
            return
        end
        if not sound then return end
        sound.SoundId = asset
        sound.Volume = Volume.Value / 100
        sound.PlaybackSpeed = Speed.Value
        sound.TimePosition = 0
        applyLoop()
        pcall(function()
            sound:Play()
        end)
        refreshHUD()
    end

    local function advance(step)
        if #tracks <= 0 then return end
        if Shuffle.Enabled and #tracks > 1 then
            local pick = index
            for _ = 1, 8 do
                pick = math.random(1, #tracks)
                if pick ~= index then break end
            end
            play(pick)
            return
        end
        play(index + step)
    end

    MP3Player = vape.Categories.Utility:CreateModule({
        Name = 'MP3Player',
        Function = function(callback)
            if callback then
                if not (listfiles and getcustomasset) then
                    notif('MP3Player', 'Your executor cannot read local files, so there is nothing to play', 6, 'warning')
                    return task.spawn(function()
                        if MP3Player.Enabled then MP3Player:Toggle() end
                    end)
                end
                if isfolder and makefolder then
                    if not isfolder(SONGS) then makefolder(SONGS) end
                end

                sound = Instance.new('Sound')
                sound.Name = 'AetherMP3'
                sound.Volume = Volume.Value / 100
                sound.PlaybackSpeed = Speed.Value
                sound.Parent = vape.gui
                MP3Player:Clean(sound)
                -- Only ever advances: a looping track never ends, because Looped keeps it
                -- going inside the engine.
                MP3Player:Clean(sound.Ended:Connect(function()
                    if not MP3Player.Enabled then return end
                    advance(1)
                end))

                -- Toggle() shows the HUD frame for any module with a Size, so put Show HUD back in
                -- charge of it now that the module is on.
                if MP3Player.Children then
                    MP3Player.Children.Visible = ShowHUD.Enabled
                end

                scan(true)
                if #tracks > 0 then
                    play(Shuffle.Enabled and math.random(1, #tracks) or 1)
                end

                MP3Player:Clean(task.spawn(function()
                    while MP3Player.Enabled do
                        if AutoRefresh.Enabled and tick() - lastScan > 3 then
                            lastScan = tick()
                            local changed = scan(true)
                            -- Nothing playing and songs have just appeared: start on them.
                            if changed and sound and not sound.IsPlaying and #tracks > 0 then
                                play(index > 0 and index or 1)
                            end
                        end
                        -- Backstop for a track that finished without Ended firing, which is
                        -- what left the playlist sitting in silence part way through. A
                        -- looping track is still playing, so this never touches it, and the
                        -- second since the last start keeps it off a song that is loading.
                        if sound and #tracks > 0 and sound.SoundId ~= '' and sound.IsLoaded
                            and not sound.IsPlaying and not sound.IsPaused
                            and (tick() - lastPlay) > 1 then
                            advance(1)
                        end
                        refreshHUD()
                        task.wait(0.2)
                    end
                end))
            else
                stop()
                sound = nil
                index = 0
                scanKey = ''
                refreshHUD()
            end
        end,
        Tooltip = 'Plays your own mp3 files from the aetherv2/songs folder, with a HUD and a live-refreshing playlist',
        Size = UDim2.fromOffset(236, 66),
        ExtraText = function()
            local track = tracks[index]
            return track and track.Name or nil
        end
    })

    -- HUD, built into the draggable frame the GUI hands us (same pattern AutoWin uses).
    if MP3Player.Children then
        local hud = MP3Player.Children
        if hud.Position == UDim2.new() then
            hud.Position = UDim2.fromOffset(16, 340)
        end
        hudBackground = Instance.new('Frame')
        hudBackground.Size = UDim2.fromScale(1, 1)
        hudBackground.BackgroundColor3 = Color3.new()
        hudBackground.BackgroundTransparency = 0.35
        hudBackground.BorderSizePixel = 0
        hudBackground.Parent = hud
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = hudBackground

        local title = Instance.new('TextLabel')
        title.Size = UDim2.new(1, -14, 0, 16)
        title.Position = UDim2.fromOffset(9, 5)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.GothamBold
        title.TextSize = 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(170, 170, 170)
        title.Text = 'MP3Player'
        title.Parent = hudBackground

        hudName = Instance.new('TextLabel')
        hudName.Size = UDim2.new(1, -18, 0, 18)
        hudName.Position = UDim2.fromOffset(9, 21)
        hudName.BackgroundTransparency = 1
        hudName.Font = Enum.Font.GothamMedium
        hudName.TextSize = 13
        hudName.TextXAlignment = Enum.TextXAlignment.Left
        hudName.TextTruncate = Enum.TextTruncate.AtEnd
        hudName.TextColor3 = Color3.new(1, 1, 1)
        hudName.Text = 'No song loaded'
        hudName.Parent = hudBackground

        hudTime = Instance.new('TextLabel')
        hudTime.Size = UDim2.new(1, -18, 0, 14)
        hudTime.Position = UDim2.fromOffset(-9, 5)
        hudTime.BackgroundTransparency = 1
        hudTime.Font = Enum.Font.Gotham
        hudTime.TextSize = 11
        hudTime.TextXAlignment = Enum.TextXAlignment.Right
        hudTime.TextColor3 = Color3.new(1, 1, 1)
        hudTime.Text = ''
        hudTime.Parent = hudBackground

        local bar = Instance.new('Frame')
        bar.Size = UDim2.new(1, -18, 0, 4)
        bar.Position = UDim2.fromOffset(9, 46)
        bar.BackgroundColor3 = Color3.fromRGB(70, 70, 70)
        bar.BorderSizePixel = 0
        bar.Parent = hudBackground
        local barCorner = Instance.new('UICorner')
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = bar

        hudBarFill = Instance.new('Frame')
        hudBarFill.Size = UDim2.fromScale(0, 1)
        hudBarFill.BackgroundColor3 = Color3.new(1, 1, 1)
        hudBarFill.BorderSizePixel = 0
        hudBarFill.Parent = bar
        local fillCorner = Instance.new('UICorner')
        fillCorner.CornerRadius = UDim.new(1, 0)
        fillCorner.Parent = hudBarFill
    end

    MP3Player:CreateButton({
        Name = 'Play / Pause',
        Function = function()
            if not sound then return end
            if sound.IsPlaying then
                sound:Pause()
            elseif sound.SoundId ~= '' then
                sound:Resume()
            else
                play(index > 0 and index or 1)
            end
        end,
        Tooltip = 'Pause or resume the current song'
    })
    MP3Player:CreateButton({
        Name = 'Next song',
        Function = function()
            advance(1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Previous song',
        Function = function()
            advance(-1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Refresh songs',
        Function = function()
            lastScan = tick()
            scan(true)
            refreshHUD()
        end,
        Tooltip = 'Re-read the songs folder right now'
    })
    Volume = MP3Player:CreateSlider({
        Name = 'Volume',
        Min = 0,
        Max = 100,
        Default = 40,
        Suffix = '%',
        Function = function(val)
            if sound then
                sound.Volume = val / 100
            end
        end
    })
    Speed = MP3Player:CreateSlider({
        Name = 'Speed',
        Min = 0.5,
        Max = 2,
        Default = 1,
        Decimal = 100,
        Suffix = 'x',
        Function = function(val)
            if sound then
                sound.PlaybackSpeed = val
            end
        end,
        Tooltip = 'Playback speed'
    })
    Shuffle = MP3Player:CreateToggle({
        Name = 'Shuffle',
        Function = applyLoop,
        Tooltip = 'Pick the next song at random instead of in order'
    })
    Loop = MP3Player:CreateToggle({
        Name = 'Loop song',
        Function = applyLoop,
        Tooltip = 'Repeat the current song instead of moving on'
    })
    AutoRefresh = MP3Player:CreateToggle({
        Name = 'Auto refresh',
        Default = true,
        Tooltip = 'Watch the songs folder and pick up new or deleted files while you play'
    })
    PlayField = MP3Player:CreateTextBox({
        Name = 'Play song',
        Placeholder = 'song name',
        -- TextBox hands us `enter`, not the text, and fires on every keystroke - so only act once
        -- the name has actually been submitted.
        Function = function(enter)
            if not enter then return end
            local val = PlayField and PlayField.Value or ''
            if val == '' then return end
            scan(false)
            local needle = val:lower()
            for i, track in tracks do
                if track.Name:lower():find(needle, 1, true) then
                    play(i)
                    return
                end
            end
            notif('MP3Player', 'No song matching "' .. val .. '"', 4, 'warning')
        end,
        Tooltip = 'Type part of a song name to jump straight to it'
    })
    Playlist = MP3Player:CreateTextList({
        Name = 'Playlist',
        Placeholder = 'song name',
        Function = function()
            scan(true)
        end,
        Tooltip = 'Leave empty to play everything in the folder. Add names and only those play, in the order you list them'
    })
    ShowHUD = MP3Player:CreateToggle({
        Name = 'Show HUD',
        Default = true,
        Tooltip = 'Show the now-playing panel. Drag it by its own frame to move it',
        Function = function(callback)
            pcall(function()
                HUDProgress.Object.Visible = callback
                HUDTime.Object.Visible = callback
                HUDColor.Object.Visible = callback
            end)
            if MP3Player.Children then
                MP3Player.Children.Visible = callback and MP3Player.Enabled
            end
        end
    })
    HUDProgress = MP3Player:CreateToggle({
        Name = 'Progress bar',
        Default = true,
        Darker = true,
        Tooltip = 'Show how far through the song you are'
    })
    HUDTime = MP3Player:CreateToggle({
        Name = 'Show time',
        Default = true,
        Darker = true,
        Tooltip = 'Show elapsed and total time'
    })
    HUDColor = MP3Player:CreateColorSlider({
        Name = 'HUD color',
        Darker = true,
        DefaultOpacity = 0.55,
        Function = refreshHUD
    })
end)
-- END AETHER MODULE: utility/MP3Player.lua --

-- BEGIN AETHER MODULE: utility/PickupRange.lua --
run(function()
    local PickupRange
    local Range
    local Network
    local Lower

    PickupRange = vape.Categories.Utility:CreateModule({
        Name = 'PickupRange',
        Function = function(callback)
            if callback then
                local items = collection('ItemDrop', PickupRange)
                repeat
                    if entitylib.isAlive then
                        local localPosition = entitylib.character.RootPart.Position
                        for _, v in items do
                            if tick() - (v:GetAttribute('ClientDropTime') or 0) < 2 then continue end
                            if isnetworkowner(v) and Network.Enabled and entitylib.character.Humanoid.Health > 0 then
                                v.CFrame = CFrame.new(localPosition - Vector3.new(0, 3, 0))
                            end

                            if (localPosition - v.Position).Magnitude <= Range.Value then
                                if Lower.Enabled and (localPosition.Y - v.Position.Y) < (entitylib.character.HipHeight - 1) then continue end
                                task.spawn(function()
                                    bedwars.Client:Get(remotes.PickupItem):CallServerAsync({
                                        itemDrop = v
                                    }):andThen(function(suc)
                                        if suc and bedwars.SoundList then
                                            bedwars.SoundManager:playSound(bedwars.SoundList.PICKUP_ITEM_DROP)
                                            local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
                                            if sound then
                                                bedwars.SoundManager:playSound(sound, {
                                                    position = v.Position,
                                                    volumeMultiplier = 0.9
                                                })
                                            end
                                        end
                                    end)
                                end)
                            end
                        end
                    end
                    task.wait(0.1)
                until not PickupRange.Enabled
            end
        end,
        Tooltip = 'Picks up items from a farther distance'
    })
    Range = PickupRange:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 10,
        Default = 10,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    Network = PickupRange:CreateToggle({
        Name = 'Network TP',
        Default = true
    })
    Lower = PickupRange:CreateToggle({Name = 'Feet Check'})
end)
-- END AETHER MODULE: utility/PickupRange.lua --

-- BEGIN AETHER MODULE: utility/Scaffold.lua --
run(function()
	local Scaffold
	local Count
	local Expand
	local Tower
	local Downwards
	local Diagonal
	local LimitItem
	local Mouse
	local BridgeWidth
	local KeepY
	local LevelBridge
	local JumpBridge
	local BlockPreference
	local RestoreSlot
	local FillColor
	local OutlineColor
	local adjacent, lastpos, label, visualBlock = {}, Vector3.zero
	local visualTween, visualPos
	local visualSpeed = 0.1
	local lockedY, restoreSlot, nextJump = nil, nil, 0

	for x = -3, 3, 3 do
		for y = -3, 3, 3 do
			for z = -3, 3, 3 do
				local vec = Vector3.new(x, y, z)
				if vec ~= Vector3.zero then
					table.insert(adjacent, vec)
				end
			end
		end
	end

	local function nearCorner(poscheck, pos)
		local startpos = poscheck - Vector3.new(3, 3, 3)
		local endpos = poscheck + Vector3.new(3, 3, 3)
		local check = poscheck + (pos - poscheck).Unit * 100
		return Vector3.new(math.clamp(check.X, startpos.X, endpos.X), math.clamp(check.Y, startpos.Y, endpos.Y), math.clamp(check.Z, startpos.Z, endpos.Z))
	end

	local function blockProximity(pos)
		local mag, returned = 60
		local tab = getBlocksInPoints(bedwars.BlockController:getBlockPosition(pos - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(pos + Vector3.new(21, 21, 21)))
		for _, v in tab do
			local blockpos = nearCorner(v, pos)
			local newmag = (pos - blockpos).Magnitude
			if newmag < mag then
				mag, returned = newmag, blockpos
			end
		end
		table.clear(tab)
		return returned
	end

	local function checkAdjacent(pos)
		for _, v in adjacent do
			if getPlacedBlock(pos + v) then
				return true
			end
		end
		return false
	end

	local function getScaffoldBlock()
		if store.hand.toolType == 'block' then
			return store.hand.tool.Name, store.hand.amount
		elseif (not LimitItem.Enabled) then
			local items = (store.inventory.inventory or {}).items or {}
			if BlockPreference.Value == 'Wool first' then
				local wool, amount = getWool()
				if wool then return wool, amount end
			end
			local chosen
			for _, item in items do
				local meta = bedwars.ItemMeta[item.itemType]
				if meta and meta.block and (not chosen or (BlockPreference.Value == 'Highest count' and (item.amount or 0) > (chosen.amount or 0))) then
					chosen = item
					if BlockPreference.Value == 'Nearest slot' then break end
				end
			end
			if chosen then return chosen.itemType, chosen.amount end
		end

		return nil, 0
	end

	local function clearVisuals()
		if visualTween then
			visualTween:Cancel()
			visualTween = nil
		end
		if visualBlock then
			visualBlock.Parent = nil
		end
		visualPos = nil
	end

	local function updateVisual(pos)
		if not visualBlock or not pos then return end

		local blockpos = bedwars.BlockController:getBlockPosition(pos) * 3
		if visualPos == blockpos then return end

		if visualTween then
			visualTween:Cancel()
			visualTween = nil
		end

		if visualBlock.Parent == gameCamera then
			visualTween = tweenService:Create(visualBlock, TweenInfo.new(visualSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = CFrame.new(blockpos)})
			visualTween:Play()
		else
			visualBlock.CFrame = CFrame.new(blockpos)
			visualBlock.Parent = gameCamera
		end
		visualPos = blockpos
	end

	Scaffold = vape.Categories.Utility:CreateModule({
		Name = 'Scaffold',
		Function = function(callback)
			if label then
				label.Visible = callback
			end

			if callback then
				lockedY, restoreSlot, nextJump = nil, nil, 0
				repeat
					if entitylib.isAlive then
						local wool, amount = getScaffoldBlock()

						if Mouse.Enabled then
							if not inputService:IsMouseButtonPressed(0) then
								wool = nil
							end
						end

						if label then
							amount = amount or 0
							label.Text = amount..' <font color="rgb(170, 170, 170)">(Scaffold)</font>'
							label.TextColor3 = Color3.fromHSV((amount / 128) / 2.8, 0.86, 1)
						end

						if wool then
							local root = entitylib.character.RootPart
							-- Only take a block slot when needed, and restore the original slot
							-- on disable. This keeps combat/inventory flow intact after bridging.
							if store.hand.toolType ~= 'block' then
								for slot, entry in store.inventory.hotbar or {} do
									if entry.item and entry.item.itemType == wool then
										restoreSlot = restoreSlot or store.inventory.hotbarSlot
										hotbarSwitch(slot - 1)
										break
									end
								end
							end
							if Tower.Enabled and inputService:IsKeyDown(Enum.KeyCode.Space) and (not inputService:GetFocusedTextBox()) then
								root.Velocity = Vector3.new(root.Velocity.X, 38, root.Velocity.Z)
							end
							if JumpBridge.Enabled and not Tower.Enabled and entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air and entitylib.character.Humanoid.MoveDirection.Magnitude > 0.05 and tick() >= nextJump then
								entitylib.character.Humanoid.Jump = true
								nextJump = tick() + 0.24
							end

							for i = Expand.Value, 1, -1 do
								local currentpos = roundPos(root.Position - Vector3.new(0, entitylib.character.HipHeight + (Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + entitylib.character.Humanoid.MoveDirection * (i * 3))
								local downwards = Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift)
								if (KeepY.Enabled or LevelBridge.Enabled) and not downwards then
									lockedY = lockedY or currentpos.Y
									currentpos = Vector3.new(currentpos.X, lockedY, currentpos.Z)
								else
									lockedY = currentpos.Y
								end
								if Diagonal.Enabled then
									if math.abs(math.round(math.deg(math.atan2(-entitylib.character.Humanoid.MoveDirection.X, -entitylib.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
										local dt = (lastpos - currentpos)
										if ((dt.X == 0 and dt.Z ~= 0) or (dt.X ~= 0 and dt.Z == 0)) and ((lastpos - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
											currentpos = lastpos
										end
									end
								end

								updateVisual(currentpos)
								local positions = {currentpos}
								if BridgeWidth.Value > 1 then
									local direction = entitylib.character.Humanoid.MoveDirection
									if direction.Magnitude < 0.05 then direction = root.CFrame.LookVector end
									local side = Vector3.new(-direction.Z, 0, direction.X)
									if side.Magnitude > 0 then
										side = side.Unit * 3
										for offset = 1, BridgeWidth.Value - 1 do
											table.insert(positions, currentpos + side * ((offset % 2 == 0 and -1 or 1) * math.ceil(offset / 2)))
										end
									end
								end
								for _, placepos in positions do
									local block, blockpos = getPlacedBlock(placepos)
									if not block then
										blockpos = checkAdjacent(blockpos * 3) and blockpos * 3 or blockProximity(placepos)
										if blockpos then Scaffold:Delay(0, function() bedwars.placeBlock(blockpos, wool, false) end) end
									end
								end
								lastpos = currentpos
							end
						end
					end
					task.wait(0.03)
				until not Scaffold.Enabled
				clearVisuals()
				if RestoreSlot.Enabled and restoreSlot ~= nil then hotbarSwitch(restoreSlot) end
				restoreSlot, lockedY = nil, nil
			end
		end,
		Tooltip = 'Helps you make bridges/scaffold walk.'
	})
	Expand = Scaffold:CreateSlider({
		Name = 'Expand',
		Min = 1,
		Max = 6
	})
	BridgeWidth = Scaffold:CreateSlider({
		Name = 'Bridge width', Min = 1, Max = 3, Default = 1,
		Tooltip = 'Places up to three blocks across while bridging'
	})
	KeepY = Scaffold:CreateToggle({Name = 'Keep Y', Default = true, Tooltip = 'Keeps a level bridge unless downwards mode is held'})
	LevelBridge = Scaffold:CreateToggle({Name = 'Level bridge', Default = false, Tooltip = 'Locks Scaffold to the starting bridge level'})
	JumpBridge = Scaffold:CreateToggle({Name = 'Jump bridge', Tooltip = 'Repeats natural jumps while moving on a bridge'})
	Tower = Scaffold:CreateToggle({
		Name = 'Tower',
		Default = true
	})
	Downwards = Scaffold:CreateToggle({
		Name = 'Downwards',
		Default = true
	})
	Diagonal = Scaffold:CreateToggle({
		Name = 'Diagonal',
		Default = true
	})
	LimitItem = Scaffold:CreateToggle({Name = 'Limit to items'})
	BlockPreference = Scaffold:CreateDropdown({
		Name = 'Block preference', List = {'Wool first', 'Nearest slot', 'Highest count'}, Default = 'Wool first',
		Tooltip = 'Chooses which inventory block Scaffold should use'
	})
	RestoreSlot = Scaffold:CreateToggle({Name = 'Restore slot', Default = true, Tooltip = 'Returns to the slot held before automatic block selection'})
	Mouse = Scaffold:CreateToggle({Name = 'Require mouse down'})
	Scaffold:CreateToggle({
		Name = 'Visual',
		Tooltip = 'Renders an overlay on the block about to be placed',
		Function = function(callback)
			FillColor.Object.Visible = callback
			OutlineColor.Object.Visible = callback
			if callback then
				visualBlock = Instance.new('Part')
				visualBlock.Size = Vector3.new(3, 3, 3)
				visualBlock.Anchored = true
				visualBlock.CanCollide = false
				visualBlock.CanQuery = false
				visualBlock.CanTouch = false
				visualBlock.CastShadow = false
				visualBlock.Transparency = 1
				local selection = Instance.new('SelectionBox')
				selection.Adornee = visualBlock
				selection.LineThickness = 0.04
				selection.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
				selection.Transparency = 1 - OutlineColor.Opacity
				selection.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
				selection.SurfaceTransparency = 1 - FillColor.Opacity
				selection.Parent = visualBlock
				bedwars.QueryUtil:setQueryIgnored(visualBlock, true)
			else
				clearVisuals()
				if visualBlock then visualBlock:Destroy() end
				visualBlock = nil
			end
		end
	})
	FillColor = Scaffold:CreateColorSlider({
		Name = 'Fill Color',
		DefaultSat = 0,
		DefaultOpacity = 0.4,
		Darker = true,
		Visible = false,
		Function = function(hue, sat, val, opacity)
			if visualBlock then
				visualBlock.SelectionBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val)
				visualBlock.SelectionBox.SurfaceTransparency = 1 - opacity
			end
		end
	})
	OutlineColor = Scaffold:CreateColorSlider({
		Name = 'Outline Color',
		DefaultValue = 0,
		Darker = true,
		Visible = false,
		Function = function(hue, sat, val, opacity)
			if visualBlock then
				visualBlock.SelectionBox.Color3 = Color3.fromHSV(hue, sat, val)
				visualBlock.SelectionBox.Transparency = 1 - opacity
			end
		end
	})
	Count = Scaffold:CreateToggle({
		Name = 'Block Count',
		Function = function(callback)
			if callback then
				label = Instance.new('TextLabel')
				label.Size = UDim2.fromOffset(100, 20)
				label.Position = UDim2.new(0.5, 6, 0.5, 60)
				label.BackgroundTransparency = 1
				label.AnchorPoint = Vector2.new(0.5, 0)
				label.Text = '0'
				label.TextColor3 = Color3.new(0, 1, 0)
				label.TextSize = 18
				label.RichText = true
				label.Font = Enum.Font.Arial
				label.Visible = Scaffold.Enabled
				label.Parent = vape.gui
			else
				label:Destroy()
				label = nil
			end
		end
	})
end)
-- END AETHER MODULE: utility/Scaffold.lua --

-- BEGIN AETHER MODULE: utility/StaffDetector.lua --
run(function()
    local StaffDetector
    local Mode
    local Clans
    local Party
    local Profile
    local Users
    local NotifyLeave
    local blacklistedclans = {'gg', 'gg2', 'DV', 'DV2'}
    local blacklisteduserids = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}
    local joined = {}
    -- Players that have been flagged as staff this session, so 'Notify on leave' can
    -- tell you the moment a detected mod leaves your game.
    local flagged = {}

    local function getRole(plr, id)
        local suc, res = pcall(function()
            return plr:GetRankInGroup(id)
        end)
        if not suc then
            notif('StaffDetector', res, 30, 'alert')
        end
        return suc and res or 0
    end

    local function staffFunction(plr, checktype)
        if not vape.Loaded then
            repeat task.wait() until vape.Loaded
        end

        notif('StaffDetector', 'Staff Detected ('..checktype..'): '..plr.Name..' ('..plr.UserId..')', 60, 'alert')
        whitelist.customtags[plr.Name] = {{text = 'GAME STAFF', color = Color3.new(1, 0, 0)}}
        flagged[plr.UserId] = {Name = plr.Name, Check = checktype}

        if Party.Enabled and not checktype:find('clan') then
            bedwars.PartyController:leaveParty()
        end

        if Mode.Value == 'Uninject' then
            task.spawn(function()
                vape:Uninject()
            end)
            game:GetService('StarterGui'):SetCore('SendNotification', {
                Title = 'StaffDetector',
                Text = 'Staff Detected ('..checktype..')\n'..plr.Name..' ('..plr.UserId..')',
                Duration = 60,
            })
        elseif Mode.Value == 'Requeue' then
            bedwars.QueueController:joinQueue(store.queueType)
        elseif Mode.Value == 'Profile' then
            vape.Save = function() end
            if vape.Profile ~= Profile.Value then
                vape:Load(true, Profile.Value)
            end
        elseif Mode.Value == 'AutoConfig' then
            local safe = {'AutoClicker', 'Reach', 'Sprint', 'HitFix', 'StaffDetector'}
            vape.Save = function() end
            for i, v in vape.Modules do
                if not (table.find(safe, i) or v.Category == 'Render') then
                    if v.Enabled then
                        v:Toggle()
                    end
                    v:SetBind('')
                end
            end
        end
    end

    local function checkFriends(list)
        for _, v in list do
            if joined[v] then
                return joined[v]
            end
        end
        return nil
    end

    local function checkJoin(plr, connection)
        if not plr:GetAttribute('Team') and plr:GetAttribute('Spectator') and not bedwars.Store:getState().Game.customMatch then
            connection:Disconnect()
            local tab, pages = {}, playersService:GetFriendsAsync(plr.UserId)
            for _ = 1, 200 do
                for _, v in pages:GetCurrentPage() do
                    table.insert(tab, v.Id)
                end
                if pages.IsFinished then break end
                pages:AdvanceToNextPageAsync()
            end

            local friend = checkFriends(tab)
            if not friend then
                staffFunction(plr, 'impossible_join')
                return true
            else
                notif('StaffDetector', string.format('Spectator %s joined from %s', plr.Name, friend), 20, 'warning')
            end
        end
    end

    local function playerAdded(plr)
        joined[plr.UserId] = plr.Name
        if plr == lplr then return end

        if table.find(blacklisteduserids, plr.UserId) or table.find(Users.ListEnabled, tostring(plr.UserId)) then
            staffFunction(plr, 'blacklisted_user')
        elseif getRole(plr, 5774246) >= 100 then
            staffFunction(plr, 'staff_role')
        else
            local connection
            connection = plr:GetAttributeChangedSignal('Spectator'):Connect(function()
                checkJoin(plr, connection)
            end)
            StaffDetector:Clean(connection)
            if checkJoin(plr, connection) then
                return
            end

            if not plr:GetAttribute('ClanTag') then
                plr:GetAttributeChangedSignal('ClanTag'):Wait()
            end

            if table.find(blacklistedclans, plr:GetAttribute('ClanTag')) and vape.Loaded and Clans.Enabled then
                connection:Disconnect()
                staffFunction(plr, 'blacklisted_clan_'..plr:GetAttribute('ClanTag'):lower())
            end
        end
    end

    StaffDetector = vape.Categories.Utility:CreateModule({
        Name = 'StaffDetector',
        Function = function(callback)
            if callback then
                table.clear(flagged)
                StaffDetector:Clean(playersService.PlayerAdded:Connect(playerAdded))
                StaffDetector:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    local info = flagged[plr.UserId]
                    if info and NotifyLeave.Enabled then
                        notif('StaffDetector', 'Flagged staff left ('..info.Check..'): '..info.Name..' ('..plr.UserId..')', 20, 'warning')
                    end
                    flagged[plr.UserId] = nil
                end))
                for _, v in playersService:GetPlayers() do
                    task.spawn(playerAdded, v)
                end
            else
                table.clear(joined)
                table.clear(flagged)
            end
        end,
        Tooltip = 'Detects people with a staff rank ingame'
    })
    Mode = StaffDetector:CreateDropdown({
        Name = 'Mode',
        List = {'Uninject', 'Profile', 'Requeue', 'AutoConfig', 'Notify'},
        Function = function(val)
            if Profile.Object then
                Profile.Object.Visible = val == 'Profile'
            end
        end
    })
    Clans = StaffDetector:CreateToggle({
        Name = 'Blacklist clans',
        Default = true
    })
    Party = StaffDetector:CreateToggle({
        Name = 'Leave party'
    })
    NotifyLeave = StaffDetector:CreateToggle({
        Name = 'Notify on leave',
        Tooltip = 'Notifies you when a flagged staff member leaves your game',
        Default = true
    })
    Profile = StaffDetector:CreateTextBox({
        Name = 'Profile',
        Default = 'default',
        Darker = true,
        Visible = false
    })
    Users = StaffDetector:CreateTextList({
        Name = 'Users',
        Placeholder = 'player (userid)'
    })
end)
-- END AETHER MODULE: utility/StaffDetector.lua --

